INSERT INTO cpath_situation (code, topic_code, sort_order, level, title_ja, title_vi, situation_vi, challenge_json, scenario_slug, seed_version) VALUES
  ('TRV-01', 'AIR', 1, 'N4', '空港のチェックイン', 'Làm thủ tục ở sân bay', 'Làm thủ tục lên máy bay và gửi hành lý.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"はい、パスポートをお{願|ねが}いします。","ja":"はい、パスポートをお願いします。","vi":"Vâng, cho tôi xin hộ chiếu ạ."},{"furigana":"はい、これです。{荷物|にもつ}はもう{受|う}け{取|と}りました。","ja":"はい、これです。荷物はもう受け取りました。","vi":"Vâng, đây ạ. Tôi đã nhận hành lý rồi."}],"line":2,"why_vi":"Nhân viên xin hộ chiếu nên Linh đưa ra (これです) rồi hỏi ghế; xin lại hộ chiếu là ngược vai, còn \'đã nhận hành lý\' là việc lúc đến nơi, không phải lúc làm thủ tục."},{"distractors":[{"furigana":"じゃ、{窓側|まどがわ}の{席|せき}はないんですね。","ja":"じゃ、窓側の席はないんですね。","vi":"Vậy là không còn ghế cạnh cửa sổ nhỉ."},{"furigana":"{後|うし}ろの{窓側|まどがわ}の{席|せき}をお{願|ねが}いします。","ja":"後ろの窓側の席をお願いします。","vi":"Cho tôi ghế cạnh cửa sổ ở phía sau ạ."}],"line":4,"why_vi":"Nhân viên báo chỉ còn một ghế ở phía trước (前方・一席) nên Linh nhận lời và nói số hành lý gửi; tưởng hết ghế cửa sổ là chưa nghe hiểu, còn xin ghế phía sau là đòi chỗ nhân viên không hề đề nghị."},{"distractors":[{"furigana":"どこで{量|はか}りますか。","ja":"どこで量りますか。","vi":"Cân ở đâu ạ?"},{"furigana":"ここが{搭乗口|とうじょうぐち}ですか。","ja":"ここが搭乗口ですか。","vi":"Đây là cửa lên máy bay ạ?"}],"line":6,"why_vi":"Hành lý đang được cân nên hỏi có quá cân không là tự nhiên; hỏi cân ở đâu là thừa vì nhân viên vừa bảo đặt lên đây (こちら), còn hỏi đây có phải cửa lên máy bay không là nhầm chỗ vì Linh đang ở quầy làm thủ tục."},{"distractors":[{"furigana":"よかった。じゃ、{追加|ついか}{料金|りょうきん}は{要|い}りませんね。","ja":"よかった。じゃ、追加料金は要りませんね。","vi":"May quá. Vậy là không mất phụ thu nhỉ."},{"furigana":"{分|わ}かりました。{二|に}キロ{足|た}りないんですね。","ja":"分かりました。二キロ足りないんですね。","vi":"Tôi hiểu rồi. Vậy là thiếu hai ký nhỉ."}],"line":8,"why_vi":"Hành lý quá 2 ký (超えております) và sẽ mất phụ thu; Linh đồng ý (分かりました) rồi hỏi cửa lên máy bay, còn nghĩ là không mất phí hay bị thiếu ký là hiểu sai."}]}', 'cpath-trv-01', '5f7a09dc7a13'),
  ('TRV-09', 'AIR', 2, 'N4', '搭乗口の確認', 'Xác nhận cổng lên máy bay', 'Ở cổng lên máy bay, hỏi giờ bắt đầu và xác nhận cổng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"すみません、{二時半|にじはん}に{着|つ}きました。","ja":"すみません、二時半に着きました。","vi":"Xin lỗi, tôi đã đến lúc hai giờ rưỡi ạ."},{"furigana":"すみません、ここで{待|ま}っていてください。","ja":"すみません、ここで待っていてください。","vi":"Xin lỗi, anh đợi ở đây nhé."}],"line":1,"why_vi":"Muốn biết giờ lên máy bay thì hỏi 何時から搭乗が始まりますか; nói mình đã đến hay bảo nhân viên đợi đều không phải câu hỏi."},{"distractors":[{"furigana":"では、{今|いま}すぐ{乗|の}ります。","ja":"では、今すぐ乗ります。","vi":"Vậy tôi lên máy bay ngay bây giờ ạ."},{"furigana":"{二時半|にじはん}までに{着|つ}きます。","ja":"二時半までに着きます。","vi":"Tôi sẽ đến trước hai giờ rưỡi."}],"line":3,"why_vi":"Đã biết giờ bắt đầu (二時半) thì hỏi tiếp cổng có đúng không; đòi lên ngay hay nói sẽ đến trước giờ đều không phải câu hỏi."},{"distractors":[{"furigana":"このゲートは{閉|し}まっていますか。","ja":"このゲートは閉まっていますか。","vi":"Cổng này có đóng không ạ?"},{"furigana":"{荷物|にもつ}を{預|あず}けたいです。","ja":"荷物を預けたいです。","vi":"Tôi muốn gửi hành lý ạ."}],"line":5,"why_vi":"Đã xác nhận cổng thì hỏi chỗ vệ sinh gần đây; hỏi cổng đóng hay gửi hành lý đều sai thời điểm (hành lý đã gửi lúc check-in)."},{"distractors":[{"furigana":"いいえ、{違|ちが}います。","ja":"いいえ、違います。","vi":"Không, không đúng ạ."},{"furigana":"{十五番|じゅうごばん}はどこですか。","ja":"十五番はどこですか。","vi":"Cổng số mười lăm ở đâu ạ?"}],"line":7,"why_vi":"Được chỉ đường rồi thì cảm ơn và nói sẽ quay lại; phủ nhận hay hỏi lại số cổng là sai (đã xác nhận 十五番)."}]}', 'cpath-trv-09', '5f7a09dc7a13'),
  ('TRV-10', 'AIR', 3, 'N4', '機内でお願い', 'Nhờ giúp trên máy bay', 'Trên máy bay, xin chăn và hỏi giờ hạ cánh.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{窓|まど}を{開|あ}けたいです。","ja":"窓を開けたいです。","vi":"Tôi muốn mở cửa sổ ạ."},{"furigana":"ここに{座|すわ}ってもいいですか。","ja":"ここに座ってもいいですか。","vi":"Tôi ngồi đây được không ạ?"}],"line":1,"why_vi":"Muốn xin thêm chăn thì hỏi 毛布をもう一枚もらえますか; đòi mở cửa hay bảo nhân viên ngồi xuống đều sai chỗ trên máy bay."},{"distractors":[{"furigana":"{毛布|もうふ}はありますか。","ja":"毛布はありますか。","vi":"Có chăn không ạ?"},{"furigana":"{席|せき}を{変|か}えたいです。","ja":"席を変えたいです。","vi":"Tôi muốn đổi ghế ạ."}],"line":4,"why_vi":"Đã nhận chăn thì chuyển sang hỏi giờ hạ cánh; hỏi lại chăn hay đòi đổi ghế đều không phải câu hỏi tiếp theo."},{"distractors":[{"furigana":"{到着|とうちゃく}は{二時|にじ}ですか。","ja":"到着は二時ですか。","vi":"Hạ cánh lúc hai giờ ạ?"},{"furigana":"もうすぐ{着|つ}きますね。","ja":"もうすぐ着きますね。","vi":"Sắp hạ cánh rồi nhỉ."}],"line":6,"why_vi":"Nhân viên vừa báo ba giờ hạ cánh nên Linh nhận xét chuyến bay lâu; hỏi lại giờ hay nói sắp hạ cánh là nghe sai."}]}', 'cpath-trv-10', '5f7a09dc7a13'),
  ('TRV-02', 'TRAIN', 1, 'N4', '電車の乗り換え', 'Đổi tàu', 'Hỏi nhân viên nhà ga cách đổi tàu để tới đích.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"すみません、{横浜|よこはま}へ{行|い}ってきました。","ja":"すみません、横浜へ行ってきました。","vi":"Xin lỗi, tôi đã đi Yokohama về rồi ạ."},{"furigana":"すみません、{横浜|よこはま}はどんな{町|まち}ですか。","ja":"すみません、横浜はどんな町ですか。","vi":"Xin lỗi, Yokohama là thành phố thế nào ạ?"}],"line":1,"why_vi":"Muốn được chỉ cách đổi tàu thì phải nói nơi mình muốn đến (〜へ行きたいんですが); kể đã đi về hay hỏi Yokohama là thành phố gì không giúp nhân viên chỉ đường."},{"distractors":[{"furigana":"じゃ、{乗|の}り{換|か}えなしで{行|い}けますね。","ja":"じゃ、乗り換えなしで行けますね。","vi":"Vậy là đi được mà không cần đổi tàu nhỉ."},{"furigana":"{横浜|よこはま}で{乗|の}り{換|か}えればいいですね。","ja":"横浜で乗り換えればいいですね。","vi":"Tôi đổi tàu ở Yokohama là được nhỉ."}],"line":3,"why_vi":"Nhân viên nói phải đổi tàu ở Shinagawa, nên hỏi tiếp tàu nào nhanh hơn là hợp lý; hiểu là không cần đổi tàu hay đổi ở Yokohama (điểm đến) là nghe sai."},{"distractors":[{"furigana":"じゃ、{各駅|かくえき}{停車|ていしゃ}のほうが{早|はや}いですね。","ja":"じゃ、各駅停車のほうが早いですね。","vi":"Vậy tàu thường nhanh hơn nhỉ."},{"furigana":"{二|に}{時間|じかん}も{早|はや}いんですか。","ja":"二時間も早いんですか。","vi":"Nhanh hơn tận hai tiếng ạ?"}],"line":5,"why_vi":"Tàu tốc hành tới sớm hơn khoảng 20 phút, nên hỏi có mất thêm phí không là bước tiếp theo; cho rằng tàu thường nhanh hơn hay nhanh hơn 2 tiếng là nghe sai."},{"distractors":[{"furigana":"じゃ、{特急|とっきゅう}{券|けん}は{要|い}りませんね。{何|なん}{番線|ばんせん}ですか。","ja":"じゃ、特急券は要りませんね。何番線ですか。","vi":"Vậy không cần vé tốc hành nhỉ. Ở đường ray số mấy ạ?"},{"furigana":"では{普通|ふつう}ので{大丈夫|だいじょうぶ}です。{特急|とっきゅう}{券|けん}はどこで{買|か}えますか。","ja":"では普通ので大丈夫です。特急券はどこで買えますか。","vi":"Vậy tàu thường cũng được ạ. Vé tốc hành mua ở đâu ạ?"}],"line":7,"why_vi":"Tàu tốc hành cần vé riêng nên Linh chọn tàu thường rồi hỏi đường ray; nói không cần vé tốc hành là nghe sai, còn chọn tàu thường mà hỏi mua vé tốc hành thì tự mâu thuẫn."}]}', 'cpath-trv-02', '5f7a09dc7a13'),
  ('TRV-11', 'TRAIN', 2, 'N4', '切符を買う', 'Mua vé tàu', 'Ở máy bán vé, nhờ nhân viên chỉ cách mua vé tới ga.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{切符|きっぷ}を{売|う}ってください。","ja":"切符を売ってください。","vi":"Bán cho tôi vé nhé."},{"furigana":"{電車|でんしゃ}は{何時|なんじ}に{来|き}ますか。","ja":"電車は何時に来ますか。","vi":"Tàu mấy giờ đến ạ?"}],"line":1,"why_vi":"Cần nhờ chỉ cách mua vé nên nói 買い方を教えてもらえますか; bảo bán cho mình vé hay hỏi giờ tàu đều chưa đúng bước đầu."},{"distractors":[{"furigana":"{往復|おうふく}でお{願|ねが}いします。","ja":"往復でお願いします。","vi":"Cho tôi vé khứ hồi ạ."},{"furigana":"いくらですか。","ja":"いくらですか。","vi":"Bao nhiêu tiền ạ?"}],"line":3,"why_vi":"Nhân viên hỏi điểm đến nên Linh trả lời 京都までです; nói mua vé khứ hồi hay hỏi giá trước khi chọn ga đều lạc nhịp."},{"distractors":[{"furigana":"どこまで{行|い}きますか。","ja":"どこまで行きますか。","vi":"Đi đến đâu ạ?"},{"furigana":"もう{払|はら}いました。","ja":"もう払いました。","vi":"Tôi trả tiền rồi ạ."}],"line":5,"why_vi":"Đã chọn ga thì hỏi giá vé là hợp lý; hỏi lại điểm đến hay nói đã trả tiền là sai."},{"distractors":[{"furigana":"{電車|でんしゃ}はいつ{出|で}ますか。","ja":"電車はいつ出ますか。","vi":"Tàu khi nào chạy ạ?"},{"furigana":"{両替|りょうがえ}できますか。","ja":"両替できますか。","vi":"Đổi tiền được không ạ?"}],"line":7,"why_vi":"Đã biết giá thì hỏi cách thanh toán; hỏi giờ tàu chạy hay đòi đổi tiền đều không phải bước tiếp theo."}]}', 'cpath-trv-11', '5f7a09dc7a13'),
  ('TRV-12', 'TRAIN', 3, 'N4', '終電を聞く', 'Hỏi chuyến tàu cuối', 'Hỏi nhân viên ga về chuyến tàu cuối về nhà.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{運賃|うんちん}はいくらですか。","ja":"運賃はいくらですか。","vi":"Giá vé bao nhiêu ạ?"},{"furigana":"{電車|でんしゃ}に{乗|の}り{遅|おく}れました。","ja":"電車に乗り遅れました。","vi":"Tôi lỡ tàu rồi ạ."}],"line":1,"why_vi":"Muốn biết chuyến cuối nên hỏi 終電は何時ですか; hỏi giá vé hay nói đã lỡ tàu đều sai việc."},{"distractors":[{"furigana":"{十一時|じゅういちじ}ですね。","ja":"十一時ですね。","vi":"Mười một giờ nhỉ."},{"furigana":"この{駅|えき}は{混|こ}みますか。","ja":"この駅は混みますか。","vi":"Ga này có đông không ạ?"}],"line":3,"why_vi":"Đã biết giờ cuối thì hỏi có đổi tàu không; hỏi lại giờ hay tò mò ga nào đông đều lạc đề."},{"distractors":[{"furigana":"{乗|の}り{換|か}えですね。","ja":"乗り換えですね。","vi":"Vậy là phải đổi tàu nhỉ."},{"furigana":"{切符|きっぷ}はどこで{買|か}いますか。","ja":"切符はどこで買いますか。","vi":"Vé mua ở đâu ạ?"}],"line":5,"why_vi":"Biết đi thẳng thì hỏi có kịp không; xác nhận phải đổi tàu hay hỏi mua vé ở đâu là hiểu sai."}]}', 'cpath-trv-12', '5f7a09dc7a13'),
  ('TRV-03', 'HOTEL', 1, 'N4', 'ホテルのチェックイン', 'Nhận phòng khách sạn', 'Nhận phòng và hỏi về bữa sáng, giờ trả phòng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{部屋|へや}を{予約|よやく}したいんですが。","ja":"部屋を予約したいんですが。","vi":"Tôi muốn đặt phòng ạ."},{"furigana":"チェックアウトをお{願|ねが}いします。","ja":"チェックアウトをお願いします。","vi":"Cho tôi trả phòng ạ."}],"line":1,"why_vi":"Khi nhận phòng đã đặt trước, câu mở đầu chuẩn là báo tên người đặt (予約した〜です); xin đặt phòng mới hay xin trả phòng là sai việc."},{"distractors":[{"furigana":"はい、お{待|ま}ちしておりました。","ja":"はい、お待ちしておりました。","vi":"Vâng, chúng tôi đã chờ ngài."},{"furigana":"はい。{朝食|ちょうしょく}は{付|つ}いていませんよね。","ja":"はい。朝食は付いていませんよね。","vi":"Vâng. Không kèm bữa sáng đúng không ạ?"}],"line":3,"why_vi":"Linh xác nhận (はい) rồi hỏi giờ ăn sáng; お待ちしておりました là câu nhân viên nói với khách, còn bảo không kèm bữa sáng thì mâu thuẫn với 朝食付き."},{"distractors":[{"furigana":"じゃ、{六|ろく}{時|じ}に{行|い}けばいいですね。","ja":"じゃ、六時に行けばいいですね。","vi":"Vậy tôi đến lúc sáu giờ là được nhỉ."},{"furigana":"レストランは{一階|いっかい}ですね。","ja":"レストランは一階ですね。","vi":"Nhà hàng ở tầng một nhỉ."}],"line":5,"why_vi":"Đã biết giờ và chỗ ăn sáng thì hỏi sang giờ trả phòng là hợp lý; đến lúc 6 giờ hay nghĩ nhà hàng ở tầng 1 là nghe sai 七時から・二階."},{"distractors":[{"furigana":"では、{十|じゅう}{時|じ}までに{出|で}ないといけませんね。","ja":"では、十時までに出ないといけませんね。","vi":"Vậy tôi phải ra khỏi phòng trước mười giờ nhỉ."},{"furigana":"{延長|えんちょう}はできないんですね。","ja":"延長はできないんですね。","vi":"Vậy là không gia hạn được nhỉ."}],"line":7,"why_vi":"Trả phòng lúc 11 giờ và khách sạn nhận gia hạn (延長も承ります); Linh chuyển sang nhờ giữ hành lý là hợp lý, còn hiểu là 10 giờ hay không gia hạn được là sai."}]}', 'cpath-trv-03', '5f7a09dc7a13'),
  ('TRV-13', 'HOTEL', 2, 'N4', 'チェックアウトとタクシー', 'Trả phòng và gọi taxi', 'Trả phòng, gửi hành lý và nhờ gọi taxi ra sân bay.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"チェックインをお{願|ねが}いします。","ja":"チェックインをお願いします。","vi":"Cho tôi nhận phòng ạ."},{"furigana":"{部屋|へや}を{予約|よやく}したいです。","ja":"部屋を予約したいです。","vi":"Tôi muốn đặt phòng ạ."}],"line":1,"why_vi":"Đến trả phòng thì nói チェックアウトをお願いします; xin nhận phòng hay đặt phòng mới đều sai việc."},{"distractors":[{"furigana":"{一泊|いっぱく}いくらですか。","ja":"一泊いくらですか。","vi":"Một đêm bao nhiêu ạ?"},{"furigana":"{私|わたし}の{名前|なまえ}はグエンです。","ja":"私の名前はグエンです。","vi":"Tên tôi là Nguyễn ạ."}],"line":3,"why_vi":"Lễ tân hỏi số phòng nên Linh báo 三百五号室; hỏi giá phòng hay nói tên mình đều không trả lời câu hỏi."},{"distractors":[{"furigana":"ミニバーを{使|つか}いました。","ja":"ミニバーを使いました。","vi":"Tôi có dùng minibar ạ."},{"furigana":"やっぱり{延泊|えんぱく}します。","ja":"やっぱり延泊します。","vi":"Thôi tôi ở thêm một đêm ạ."}],"line":5,"why_vi":"Đã xác nhận không dùng minibar thì chuyển sang nhờ gọi taxi; nói đã dùng minibar hay từ chối trả phòng đều mâu thuẫn."}]}', 'cpath-trv-13', '5f7a09dc7a13'),
  ('TRV-14', 'HOTEL', 3, 'N4', '部屋の設備を聞く', 'Hỏi về tiện nghi phòng', 'Hỏi wifi, nhờ bổ sung khăn và đồ trong phòng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"チェックアウトは{何時|なんじ}ですか。","ja":"チェックアウトは何時ですか。","vi":"Trả phòng mấy giờ ạ?"},{"furigana":"ベッドをもう{一|ひと}つください。","ja":"ベッドをもう一つください。","vi":"Cho tôi thêm một cái giường ạ."}],"line":1,"why_vi":"Cần mật khẩu wifi nên hỏi パスワードを教えてください; hỏi giờ trả phòng hay xin thêm giường đều sai việc."},{"distractors":[{"furigana":"パスワードは{何|なん}ですか。","ja":"パスワードは何ですか。","vi":"Mật khẩu là gì ạ?"},{"furigana":"{部屋|へや}はとてもきれいですね。","ja":"部屋はとてもきれいですね。","vi":"Phòng đẹp quá nhỉ."}],"line":3,"why_vi":"Đã nhận thẻ mật khẩu thì xin thêm khăn; hỏi lại mật khẩu hay khen phòng đẹp đều không phải việc đang làm."},{"distractors":[{"furigana":"タオルを{三枚|さんまい}ください。","ja":"タオルを三枚ください。","vi":"Cho tôi ba cái khăn ạ."},{"furigana":"レストランはどこですか。","ja":"レストランはどこですか。","vi":"Nhà hàng ở đâu ạ?"}],"line":5,"why_vi":"Đã nhờ thêm khăn thì hỏi đồ uống có miễn phí không; xin thêm khăn nữa hay hỏi nhà hàng đều lạc đề."}]}', 'cpath-trv-14', '5f7a09dc7a13'),
  ('TRV-04', 'FOOD', 1, 'N4', 'レストランで注文', 'Gọi món ở nhà hàng', 'Gọi món và hỏi về thành phần vì kiêng đồ ăn.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"いいえ、{予約|よやく}はしていません。","ja":"いいえ、予約はしていません。","vi":"Không, tôi không đặt bàn trước ạ."},{"furigana":"ごちそうさまでした。お{会計|かいけい}をお{願|ねが}いします。","ja":"ごちそうさまでした。お会計をお願いします。","vi":"Cảm ơn vì bữa ăn. Cho tôi tính tiền ạ."}],"line":2,"why_vi":"Nhân viên hỏi đã chọn món chưa, nên hỏi suất cơm gồm gì để chọn là hợp lý; trả lời chuyện đặt bàn là sai câu hỏi, còn xin tính tiền khi chưa ăn là sai thời điểm."},{"distractors":[{"furigana":"みそ{汁|しる}は{付|つ}かないんですね。","ja":"みそ汁は付かないんですね。","vi":"Vậy là không có canh miso nhỉ."},{"furigana":"{何|なん}でも{食|た}べられますから、{大丈夫|だいじょうぶ}です。","ja":"何でも食べられますから、大丈夫です。","vi":"Tôi ăn được mọi thứ nên không sao ạ."}],"line":4,"why_vi":"Linh kiêng đồ ăn nên cần hỏi món có thịt lợn không và giải thích mình không ăn được; nói \'ăn được mọi thứ\' là trái với việc đang kiêng ăn, còn nói không có canh miso là nghe sai (nhân viên vừa nói có みそ汁)."},{"distractors":[{"furigana":"じゃ、{豚肉|ぶたにく}なんですね。やめておきます。","ja":"じゃ、豚肉なんですね。やめておきます。","vi":"Vậy là thịt lợn nhỉ. Tôi thôi ạ."},{"furigana":"では、これをお{願|ねが}いします。{鶏肉|とりにく}を{豚肉|ぶたにく}に{変|か}えてください。","ja":"では、これをお願いします。鶏肉を豚肉に変えてください。","vi":"Vậy cho tôi món này. Đổi thịt gà sang thịt lợn giúp tôi."}],"line":6,"why_vi":"Món dùng thịt gà (鶏肉) nên Linh yên tâm gọi và hỏi thêm làm cay; hiểu nhầm là thịt lợn hay đòi đổi sang thịt lợn đều trái với việc Linh kiêng thịt lợn."}]}', 'cpath-trv-04', '5f7a09dc7a13'),
  ('TRV-15', 'FOOD', 2, 'N4', '電話で予約', 'Đặt bàn qua điện thoại', 'Gọi điện đặt bàn cho tối nay.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"いくらですか。","ja":"いくらですか。","vi":"Bao nhiêu tiền ạ?"},{"furigana":"{今|いま}、{店|みせ}に{着|つ}きました。","ja":"今、店に着きました。","vi":"Tôi vừa đến quán rồi ạ."}],"line":1,"why_vi":"Muốn đặt bàn thì nói rõ giờ 七時に予約したい; hỏi giá hay nói đã đến quán đều sai việc gọi điện đặt bàn."},{"distractors":[{"furigana":"{七時|しちじ}です。","ja":"七時です。","vi":"Bảy giờ ạ."},{"furigana":"{個室|こしつ}がいいです。","ja":"個室がいいです。","vi":"Tôi muốn phòng riêng ạ."}],"line":3,"why_vi":"Nhân viên hỏi số người nên Linh đáp 二人です; nói giờ hay xin phòng riêng đều không trả lời câu hỏi."},{"distractors":[{"furigana":"{三人|さんにん}です。","ja":"三人です。","vi":"Ba người ạ."},{"furigana":"やっぱりやめます。","ja":"やっぱりやめます。","vi":"Thôi, tôi không đặt nữa ạ."}],"line":5,"why_vi":"Được hỏi tên thì báo tên グエンです; hỏi lại số người hay từ chối đặt bàn đều sai."}]}', 'cpath-trv-15', '5f7a09dc7a13'),
  ('TRV-16', 'FOOD', 3, 'N4', '会計と割り勘', 'Tính tiền và chia đều', 'Sau bữa ăn, xin tính tiền và hỏi trả thẻ.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"メニューをください。","ja":"メニューをください。","vi":"Cho tôi thực đơn ạ."},{"furigana":"{今夜|こんや}{予約|よやく}できますか。","ja":"今夜予約できますか。","vi":"Tối nay đặt bàn được không ạ?"}],"line":1,"why_vi":"Ăn xong thì xin tính tiền お会計をお願いします; gọi thêm món hay hỏi đặt bàn đều sai thời điểm."},{"distractors":[{"furigana":"{現金|げんきん}でお{願|ねが}いします。","ja":"現金でお願いします。","vi":"Cho tôi trả tiền mặt ạ."},{"furigana":"{何時|なんじ}までですか。","ja":"何時までですか。","vi":"Mở đến mấy giờ ạ?"}],"line":3,"why_vi":"Biết tổng tiền thì hỏi có trả thẻ được không; trả luôn tiền mặt hay hỏi giờ đóng cửa đều không phải bước tiếp theo."},{"distractors":[{"furigana":"{全部|ぜんぶ}でいくらですか。","ja":"全部でいくらですか。","vi":"Tổng cộng bao nhiêu ạ?"},{"furigana":"{私|わたし}が{全部|ぜんぶ}{払|はら}います。","ja":"私が全部払います。","vi":"Tôi trả hết ạ."}],"line":5,"why_vi":"Đã xác nhận dùng thẻ được thì hỏi tính riêng cho hai người; hỏi lại tổng tiền hay bảo trả hết một mình là sai."}]}', 'cpath-trv-16', '5f7a09dc7a13'),
  ('TRV-06', 'TROUBLE', 1, 'N4', '道に迷ったとき', 'Khi bị lạc đường', 'Hỏi đường tới bảo tàng khi bản đồ không rõ.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"すみません、{美術館|びじゅつかん}の{地図|ちず}をあげましょうか。","ja":"すみません、美術館の地図をあげましょうか。","vi":"Xin lỗi, tôi đưa bác bản đồ bảo tàng nhé?"},{"furigana":"すみません、{美術館|びじゅつかん}は{何時|なんじ}まで{開|あ}いていますか。","ja":"すみません、美術館は何時まで開いていますか。","vi":"Xin lỗi, bảo tàng mở cửa đến mấy giờ ạ?"}],"line":1,"why_vi":"Linh bị lạc nên hỏi đường bằng どう行けばいいですか (người qua đường trả lời bằng cách chỉ đường); hỏi bảo tàng mở đến mấy giờ là sai việc vì Linh đang cần biết đường đi, còn đề nghị đưa bản đồ cho người khác là ngược vai."},{"distractors":[{"furigana":"{一|ひと}つ{目|め}の{信号|しんごう}を{右|みぎ}ですね。","ja":"一つ目の信号を右ですね。","vi":"Tới đèn thứ nhất thì rẽ phải nhỉ."},{"furigana":"じゃ、ここで{曲|ま}がればいいですね。","ja":"じゃ、ここで曲がればいいですね。","vi":"Vậy rẽ ngay ở đây là được nhỉ."}],"line":3,"why_vi":"Đã được chỉ đường (đi thẳng, đèn thứ hai rẽ trái) thì hỏi đi bộ mất bao lâu là hợp lý; xác nhận đèn thứ nhất rẽ phải hay rẽ ngay ở đây là nghe sai."},{"distractors":[{"furigana":"{一|いち}{時間|じかん}も{歩|ある}くんですか。","ja":"一時間も歩くんですか。","vi":"Phải đi bộ tận một tiếng ạ?"},{"furigana":"{時計|とけい}は{途中|とちゅう}にあるんですね。","ja":"時計は途中にあるんですね。","vi":"Đồng hồ nằm ở dọc đường đi nhỉ."}],"line":5,"why_vi":"Người qua đường nói khoảng 10 phút và cuối đường (突き当たり) có đồng hồ lớn làm mốc; Linh xác nhận mốc và cảm ơn là đúng, còn nghe thành 1 tiếng hay tưởng đồng hồ ở dọc đường (chứ không phải cuối đường) là hiểu sai."},{"distractors":[{"furigana":"そうですか。{今日|きょう}は{休館|きゅうかん}{日|び}なんですね。{残念|ざんねん}です。","ja":"そうですか。今日は休館日なんですね。残念です。","vi":"Vậy à. Hôm nay là ngày đóng cửa nhỉ. Tiếc quá."},{"furigana":"じゃ、{今日|きょう}は{開|あ}いているんですね。","ja":"じゃ、今日は開いているんですね。","vi":"Vậy là hôm nay có mở cửa nhỉ."}],"line":7,"why_vi":"休館日じゃないといいけど chỉ là mong hôm nay không đóng cửa (chưa chắc), nên Linh nói nên kiểm tra và cảm ơn; kết luận là hôm nay chắc chắn mở cửa hay chắc chắn đóng cửa đều hiểu sai (người qua đường chỉ mong, chưa chắc)."}]}', 'cpath-trv-06', '5f7a09dc7a13'),
  ('TRV-07', 'TROUBLE', 2, 'N3', '忘れ物をした', 'Để quên đồ', 'Báo mất túi trên tàu và làm thủ tục tìm đồ.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{電車|でんしゃ}で{鞄|かばん}を{拾|ひろ}ったんですが。","ja":"電車で鞄を拾ったんですが。","vi":"Tôi nhặt được một cái túi trên tàu ạ."},{"furigana":"{電車|でんしゃ}に{乗|の}り{遅|おく}れてしまったんですが。","ja":"電車に乗り遅れてしまったんですが。","vi":"Tôi lỡ bị trễ tàu mất rồi ạ."}],"line":1,"why_vi":"Linh để quên túi trên tàu nên báo bằng 忘れてしまったんですが; nói nhặt được túi hay bị lỡ tàu là sai sự việc."},{"distractors":[{"furigana":"{三|さん}{時間|じかん}ぐらい{乗|の}っていました。","ja":"三時間ぐらい乗っていました。","vi":"Tôi đã đi tàu khoảng ba tiếng."},{"furigana":"{山手線|やまのてせん}の{駅|えき}はどこですか。","ja":"山手線の駅はどこですか。","vi":"Ga tuyến Yamanote ở đâu ạ?"}],"line":3,"why_vi":"Nhân viên hỏi khoảng mấy giờ và tuyến nào nên phải nói giờ (三時ごろ) và tuyến; \'đi khoảng ba tiếng\' là nhầm 何時 với 何時間, còn hỏi ngược lại ga ở đâu là không trả lời."},{"distractors":[{"furigana":"はい、{大|おお}きさは{中|ちゅう}くらいです。","ja":"はい、大きさは中くらいです。","vi":"Vâng, kích cỡ trung bình ạ."},{"furigana":"リュックは{三千|さんぜん}{円|えん}ぐらいでした。","ja":"リュックは三千円ぐらいでした。","vi":"Cái ba lô giá khoảng ba nghìn yên ạ."}],"line":5,"why_vi":"Nhân viên hỏi bên trong có gì để nhận dạng (中身) nên Linh kể đồ trong túi; nói kích cỡ hay giá tiền của ba lô là tả cái túi, không trả lời câu hỏi về đồ bên trong."},{"distractors":[{"furigana":"じゃ、{鞄|かばん}はもう{見|み}つかったんですね。","ja":"じゃ、鞄はもう見つかったんですね。","vi":"Vậy là túi đã được tìm thấy rồi nhỉ."},{"furigana":"じゃ、{私|わたし}がお{調|しら}べしましょうか。","ja":"じゃ、私がお調べしましょうか。","vi":"Vậy để tôi tra giúp anh nhé?"}],"line":7,"why_vi":"Nhân viên sẽ tra và nhờ điền phiếu, nên Linh hỏi nếu tìm thấy sẽ được liên lạc thế nào; hiểu là đã tìm thấy túi hay đề nghị tự tra giúp nhân viên là sai tình huống và sai vai."}]}', 'cpath-trv-07', '5f7a09dc7a13'),
  ('TRV-08', 'TROUBLE', 3, 'N3', '体調が悪くなった', 'Bị mệt khi đang đi du lịch', 'Nhờ lễ tân khách sạn gọi giúp bác sĩ.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"すみません、{道|みち}がよく{分|わ}からなくて。","ja":"すみません、道がよく分からなくて。","vi":"Xin lỗi, tôi không rõ đường lắm ạ."},{"furigana":"すみません、{部屋|へや}が{少|すこ}し{狭|せま}くて。","ja":"すみません、部屋が少し狭くて。","vi":"Xin lỗi, phòng hơi chật ạ."}],"line":1,"why_vi":"Linh thấy mệt và cần nhờ gọi bác sĩ nên mở lời bằng 少し具合が悪くて (thấy khó chịu trong người); nói không rõ đường hay phàn nàn phòng chật là sai vấn đề."},{"distractors":[{"furigana":"はい、{大丈夫|だいじょうぶ}です。{何|なん}でもありません。","ja":"はい、大丈夫です。何でもありません。","vi":"Vâng, tôi không sao. Không có gì đâu ạ."},{"furigana":"{昨日|きのう}から、このホテルに{泊|と}まっています。","ja":"昨日から、このホテルに泊まっています。","vi":"Tôi ở khách sạn này từ hôm qua ạ."}],"line":3,"why_vi":"Lễ tân hỏi triệu chứng nên phải nói rõ bị sốt, đau đầu; bảo không sao là mâu thuẫn với việc vừa nói thấy khó chịu, còn nói ở khách sạn từ hôm qua là không trả lời câu hỏi."},{"distractors":[{"furigana":"{大丈夫|だいじょうぶ}です。もう{薬|くすり}を{飲|の}んで{治|なお}りました。","ja":"大丈夫です。もう薬を飲んで治りました。","vi":"Không sao ạ. Tôi uống thuốc rồi, khỏi rồi."},{"furigana":"じゃ、{病院|びょういん}はもう{調|しら}べましたか。","ja":"じゃ、病院はもう調べましたか。","vi":"Vậy chị đã tra bệnh viện chưa ạ?"}],"line":5,"why_vi":"Lễ tân đề nghị tra bệnh viện (〜ましょうか) nên Linh nhận lời và nói mình không rành tiếng Nhật; bảo đã khỏi là mâu thuẫn với triệu chứng vừa kể, còn hỏi \'đã tra chưa\' là hiểu nhầm lời đề nghị."},{"distractors":[{"furigana":"ありがとうございます。{日本語|にほんご}しか{通|つう}じないんですね。","ja":"ありがとうございます。日本語しか通じないんですね。","vi":"Cảm ơn chị. Vậy là chỉ dùng được tiếng Nhật thôi nhỉ."},{"furigana":"いいえ、{予約|よやく}はもうキャンセルしました。","ja":"いいえ、予約はもうキャンセルしました。","vi":"Không, tôi đã hủy hẹn rồi ạ."}],"line":7,"why_vi":"Lễ tân tìm được phòng khám nói tiếng Anh và đề nghị đặt hẹn; Linh cảm ơn (đồng ý) rồi hỏi bảo hiểm là hợp lý, còn hiểu là chỉ nói tiếng Nhật hay nói đã hủy hẹn (chưa hề đặt) là sai."}]}', 'cpath-trv-08', '5f7a09dc7a13'),
  ('TRV-05', 'SHOP', 1, 'N3', '買い物と免税', 'Mua sắm và miễn thuế', 'Mua quà lưu niệm và làm thủ tục miễn thuế.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"これ、{免税|めんぜい}{店|てん}で{買|か}いました。","ja":"これ、免税店で買いました。","vi":"Cái này tôi đã mua ở cửa hàng miễn thuế."},{"furigana":"これ、{交換|こうかん}できますか。","ja":"これ、交換できますか。","vi":"Cái này đổi được không ạ?"}],"line":1,"why_vi":"Linh đang định mua quà và muốn miễn thuế nên hỏi 免税になりますか; nói đã mua rồi hay hỏi đổi hàng (khi chưa mua) đều không đúng việc đang làm."},{"distractors":[{"furigana":"じゃ、{五|ご}{千|せん}{円|えん}{以下|いか}なら{免税|めんぜい}ですね。","ja":"じゃ、五千円以下なら免税ですね。","vi":"Vậy từ năm nghìn yên trở xuống thì được miễn thuế nhỉ."},{"furigana":"じゃ、{免税|めんぜい}には{五|ご}{千|せん}{円|えん}かかるんですね。","ja":"じゃ、免税には五千円かかるんですね。","vi":"Vậy là miễn thuế phải mất năm nghìn yên nhỉ."}],"line":3,"why_vi":"Miễn thuế khi mua từ 5.000 yên trở lên (以上) nên Linh hỏi tổng tiền hiện tại để biết đã đủ chưa; hiểu thành từ 5.000 yên trở xuống (以下) là sai nghĩa 以上, còn tưởng phải trả 5.000 yên phí miễn thuế là sai vì đó là mức mua tối thiểu."},{"distractors":[{"furigana":"じゃ、まだ{免税|めんぜい}にはなりませんね。","ja":"じゃ、まだ免税にはなりませんね。","vi":"Vậy là chưa được miễn thuế nhỉ."},{"furigana":"では{免税|めんぜい}でお{願|ねが}いします。{六百|ろっぴゃく}{二十|にじゅう}{円|えん}ですね。","ja":"では免税でお願いします。六百二十円ですね。","vi":"Vậy cho tôi miễn thuế ạ. Là sáu trăm hai mươi yên nhỉ."}],"line":5,"why_vi":"6.200 yên đã vượt mức 5.000 yên nên Linh xin miễn thuế và xác nhận cần hộ chiếu; cho rằng chưa đủ điều kiện hay nghe thành 620 yên là sai số tiền."},{"distractors":[{"furigana":"パスポートは{持|も}っていません。","ja":"パスポートは持っていません。","vi":"Tôi không mang hộ chiếu ạ."},{"furigana":"{現金|げんきん}でお{願|ねが}いします。","ja":"現金でお願いします。","vi":"Cho tôi trả bằng tiền mặt ạ."}],"line":7,"why_vi":"Nhân viên đã nhận hộ chiếu (お預かりいたします) và hỏi về cách gói, nên Linh trả lời cách gói; nói không có hộ chiếu là mâu thuẫn, còn nói cách thanh toán là trả lời sai câu hỏi."}]}', 'cpath-trv-05', '5f7a09dc7a13'),
  ('TRV-17', 'SHOP', 2, 'N4', '試着をする', 'Thử đồ', 'Muốn thử áo và xin cỡ khác.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"このシャツはいくらですか。","ja":"このシャツはいくらですか。","vi":"Cái áo này bao nhiêu ạ?"},{"furigana":"もっと{安|やす}くできますか。","ja":"もっと安くできますか。","vi":"Bớt được chút nữa không ạ?"}],"line":1,"why_vi":"Muốn thử áo thì hỏi 試着できますか; hỏi giá hay đòi giảm giá ngay đều chưa đúng bước đầu."},{"distractors":[{"furigana":"{大|おお}きすぎます。","ja":"大きすぎます。","vi":"To quá ạ."},{"furigana":"{色|いろ}がとてもきれいですね。","ja":"色がとてもきれいですね。","vi":"Màu đẹp quá nhỉ."}],"line":3,"why_vi":"Thử xong thấy chật thì xin cỡ lớn hơn; bảo áo quá rộng hay khen màu đều không đúng."},{"distractors":[{"furigana":"もう{一度|いちど}{試着|しちゃく}できますか。","ja":"もう一度試着できますか。","vi":"Tôi thử lại lần nữa được không ạ?"},{"furigana":"サイズは{何|なん}ですか。","ja":"サイズは何ですか。","vi":"Cỡ là bao nhiêu ạ?"}],"line":6,"why_vi":"Cỡ M vừa vặn nên Linh quyết định mua; đòi thử thêm hay hỏi lại cỡ đều không cần thiết."}]}', 'cpath-trv-17', '5f7a09dc7a13'),
  ('TRV-18', 'SHOP', 3, 'N4', '商品を交換する', 'Đổi hàng', 'Mua nhầm đồ, xin đổi màu khác.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{返品|へんぴん}できますか。","ja":"返品できますか。","vi":"Trả hàng được không ạ?"},{"furigana":"これをもう{一|ひと}つ{買|か}います。","ja":"これをもう一つ買います。","vi":"Tôi mua thêm một cái này ạ."}],"line":1,"why_vi":"Muốn đổi hàng thì nói rõ đã mua hôm qua 昨日買ったこれを交換できますか; nói muốn trả lại hay mua thêm đều sai việc."},{"distractors":[{"furigana":"レシートはありません。","ja":"レシートはありません。","vi":"Tôi không có hóa đơn ạ."},{"furigana":"いくらでしたか。","ja":"いくらでしたか。","vi":"Giá bao nhiêu ạ?"}],"line":3,"why_vi":"Được hỏi hóa đơn thì đưa ra (これです) rồi nói muốn đổi màu; nói mất hóa đơn hay hỏi giá đều sai."},{"distractors":[{"furigana":"{赤|あか}はありますか。","ja":"赤はありますか。","vi":"Có màu đỏ không ạ?"},{"furigana":"{違|ちが}うデザインにできますか。","ja":"違うデザインにできますか。","vi":"Đổi kiểu khác được không ạ?"}],"line":5,"why_vi":"Nhân viên báo có xanh và trắng nên Linh chọn màu xanh; đòi màu đỏ hay đổi cả kiểu đều sai vì chỉ có hai màu."}]}', 'cpath-trv-18', '5f7a09dc7a13'),
  ('DLY-01', 'HOME', 1, 'N4', '部屋を借りる', 'Thuê phòng', 'Xem phòng và hỏi về chi phí ban đầu.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{初期|しょき}{費用|ひよう}はもう{全部|ぜんぶ}{払|はら}いました。","ja":"初期費用はもう全部払いました。","vi":"Chi phí ban đầu tôi đã trả hết rồi ạ."},{"furigana":"{駅|えき}から{歩|ある}いて{何分|なんぷん}ですか。","ja":"駅から歩いて何分ですか。","vi":"Từ ga đi bộ mất mấy phút ạ?"}],"line":1,"why_vi":"Tình huống là hỏi chi phí ban đầu và nhân viên đáp bằng bảng chi phí (tiền thuê, cọc, tiền lễ, tổng khoảng 14 vạn), nên Lin phải hỏi tổng chi phí ban đầu; Lin đang xem phòng chưa thuê nên không thể đã trả hết, còn hỏi đi bộ từ ga mấy phút thì không khớp với câu trả lời về tiền."},{"distractors":[{"furigana":"{敷金|しききん}がないのは{助|たす}かります。{共益費|きょうえきひ}は{別|べつ}ですか。","ja":"敷金がないのは助かります。共益費は別ですか。","vi":"Không có tiền đặt cọc thì đỡ quá. Phí quản lý tính riêng ạ?"},{"furigana":"{礼金|れいきん}がないのは{助|たす}かります。{共益費|きょうえきひ}はもう{払|はら}いました。","ja":"礼金がないのは助かります。共益費はもう払いました。","vi":"Không có tiền lễ thì đỡ quá. Phí quản lý thì tôi trả rồi."}],"line":3,"why_vi":"Nhân viên nói không có tiền lễ (礼金) nhưng có cọc một tháng (敷金), nên Lin mừng vì không mất 礼金 rồi hỏi phí quản lý; nói \\"không có 敷金\\" là nghe nhầm 敷金 với 礼金, còn Lin chưa thuê nên không thể đã trả phí quản lý."},{"distractors":[{"furigana":"{共益費|きょうえきひ}は{毎月|まいつき}いくらですか。","ja":"共益費は毎月いくらですか。","vi":"Phí quản lý mỗi tháng bao nhiêu ạ?"},{"furigana":"{共益費|きょうえきひ}はかからないんですね。","ja":"共益費はかからないんですね。","vi":"Vậy là không mất phí quản lý nhỉ."}],"line":5,"why_vi":"Phí quản lý vừa được trả lời rõ (3.000 yên/tháng tính riêng), nên Lin chuyển sang hỏi phòng có nắng không; hỏi lại số tiền hay nói không mất phí đều trái với điều vừa nghe."},{"distractors":[{"furigana":"{北向|きたむ}きなので、{昼間|ひるま}は{暗|くら}いんですね。","ja":"北向きなので、昼間は暗いんですね。","vi":"Hướng bắc nên ban ngày tối nhỉ."},{"furigana":"{日当|ひあ}たりはいいですか。","ja":"日当たりはいいですか。","vi":"Phòng có nắng tốt không ạ?"}],"line":7,"why_vi":"Nhân viên vừa nói phòng hướng nam, ban ngày sáng, nên Lin hỏi sang chuyện tiếng ồn; câu \\"hướng bắc, tối\\" nói ngược lại, còn chuyện nắng thì vừa được trả lời xong."}]}', 'cpath-dly-01', 'd2c4b91916be'),
  ('DLY-02', 'HOME', 2, 'N4', 'ごみの分別', 'Phân loại rác', 'Hàng xóm chỉ cách phân loại rác cho người mới.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"ごみ{袋|ぶくろ}はどこで{買|か}えますか。","ja":"ごみ袋はどこで買えますか。","vi":"Túi rác mua ở đâu được ạ?"},{"furigana":"ごみの{出|だ}し{方|かた}は、もう{全部|ぜんぶ}{知|し}っています。","ja":"ごみの出し方は、もう全部知っています。","vi":"Cách đổ rác thì cháu biết hết rồi ạ."}],"line":1,"why_vi":"Hàng xóm đáp \\"それは資源ごみ\\" về cái lon, nên Lin phải hỏi lon rỗng thuộc loại rác nào; hỏi chỗ mua túi rác không khớp với câu trả lời đó, còn Lin là người mới đang được chỉ cách phân loại nên không thể nói mình đã biết hết."},{"distractors":[{"furigana":"{燃|も}えるごみと{一緒|いっしょ}に{出|だ}すんですね。","ja":"燃えるごみと一緒に出すんですね。","vi":"Vậy là đem ra cùng với rác cháy được nhỉ."},{"furigana":"じゃあ、{何曜日|なんようび}に{出|だ}すんですか。","ja":"じゃあ、何曜日に出すんですか。","vi":"Vậy đem ra vào thứ mấy ạ?"}],"line":3,"why_vi":"Hàng xóm vừa nói lon rỗng là rác tái chế, đem ra sáng thứ tư, nên Lin hỏi tiếp có phải rửa trước không; một câu nhầm thành rác cháy được, câu kia hỏi lại ngày đem rác vừa được trả lời."},{"distractors":[{"furigana":"{缶|かん}はつぶしてから{出|だ}すんですね。","ja":"缶はつぶしてから出すんですね。","vi":"Lon thì bóp bẹp rồi mới đem ra nhỉ."},{"furigana":"{空|あ}き{缶|かん}は{何|なに}ごみなんですか。","ja":"空き缶は何ごみなんですか。","vi":"Lon rỗng là rác loại gì ạ?"}],"line":5,"why_vi":"Hàng xóm vừa dặn tráng bên trong và đừng bóp bẹp, nên Lin chuyển sang hỏi cái ghế cũ; một câu hiểu ngược lời dặn \\"つぶさずに\\", câu kia hỏi lại loại rác của lon rỗng đã được trả lời (資源ごみ)."},{"distractors":[{"furigana":"{手続|てつづ}きは{要|い}らないんですね。{明日|あした}{出|だ}しておきます。","ja":"手続きは要らないんですね。明日出しておきます。","vi":"Không cần thủ tục nhỉ. Mai cháu đem ra luôn."},{"furigana":"じゃあ、{椅子|いす}も{水曜|すいよう}の{朝|あさ}に{出|だ}せばいいんですね。","ja":"じゃあ、椅子も水曜の朝に出せばいいんですね。","vi":"Vậy cái ghế cũng đem ra sáng thứ tư là được nhỉ."}],"line":7,"why_vi":"Ghế cũ là rác cồng kềnh, phải đăng ký với thành phố và mua tem, nên Lin xác nhận cần thủ tục rồi cảm ơn; hai câu kia bỏ qua thủ tục hoặc nhầm với lịch rác tái chế."}]}', 'cpath-dly-02', 'd2c4b91916be'),
  ('DLY-09', 'HOME', 3, 'N4', 'ゴミの分別を聞く', 'Hỏi cách phân loại rác', 'Hỏi hàng xóm về ngày đổ rác và cách phân loại.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"ゴミはどこに{置|お}きますか。","ja":"ゴミはどこに置きますか。","vi":"Rác để ở đâu ạ?"},{"furigana":"もうゴミを{出|だ}しました。","ja":"もうゴミを出しました。","vi":"Tôi đã đổ rác rồi ạ."}],"line":1,"why_vi":"Muốn biết cách đổ rác thì hỏi ゴミの出し方を教えてもらえますか; hỏi chỗ đổ rác cụ thể hay bảo đã đổ xong đều chưa đúng."},{"distractors":[{"furigana":"{何曜日|なんようび}ですか。","ja":"何曜日ですか。","vi":"Là thứ mấy ạ?"},{"furigana":"{燃|も}えるゴミだけあります。","ja":"燃えるゴミだけあります。","vi":"Chỉ có rác cháy được thôi ạ."}],"line":3,"why_vi":"Đã biết ngày đổ rác thì hỏi xử lý chai nhựa; hỏi lại ngày hay nói chỉ có rác cháy được đều lạc đề."},{"distractors":[{"furigana":"ラベルはどこで{買|か}いますか。","ja":"ラベルはどこで買いますか。","vi":"Nhãn mua ở đâu ạ?"},{"furigana":"{家|いえ}の{中|なか}はとてもきれいですね。","ja":"家の中はとてもきれいですね。","vi":"Trong nhà sạch sẽ quá nhỉ."}],"line":5,"why_vi":"Biết cách bỏ chai nhựa thì hỏi giờ đổ rác; hỏi chỗ mua nhãn hay khen nhà sạch đều không liên quan."}]}', 'cpath-dly-09', 'd2c4b91916be'),
  ('DLY-03', 'MARKET', 1, 'N4', 'スーパーで買い物', 'Đi siêu thị', 'Hỏi nhân viên về hạn dùng và hàng giảm giá.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"すみません、この{惣菜|そうざい}の{消費|しょうひ}{期限|きげん}は{明日|あした}までですよ。","ja":"すみません、この惣菜の消費期限は明日までですよ。","vi":"Xin lỗi, món ăn sẵn này hạn dùng đến ngày mai đấy."},{"furigana":"すみません、この{惣菜|そうざい}を{温|あたた}めてもらえますか。","ja":"すみません、この惣菜を温めてもらえますか。","vi":"Xin lỗi, anh hâm nóng món ăn sẵn này giúp tôi được không ạ?"}],"line":1,"why_vi":"Lin là khách muốn biết hạn dùng nên lịch sự hỏi \\"消費期限はいつまでですか\\" (nhân viên đáp về hạn dùng); một câu lại đi báo hạn dùng cho nhân viên, câu kia nhờ hâm nóng là sai mục đích hỏi."},{"distractors":[{"furigana":"{何日|なんにち}まで{食|た}べられますか。","ja":"何日まで食べられますか。","vi":"Ăn được đến ngày mấy ạ?"},{"furigana":"{朝|あさ}から{半額|はんがく}なんですね。","ja":"朝から半額なんですね。","vi":"Giảm nửa giá từ buổi sáng nhỉ."}],"line":3,"why_vi":"Nhân viên nói hạn dùng trong hôm nay và từ chiều tối giảm nửa giá, nên Lin hỏi cụ thể từ mấy giờ; hỏi ăn được đến ngày nào là bỏ qua \\"本日中\\", còn \\"giảm từ buổi sáng\\" là nghe nhầm \\"夕方\\"."},{"distractors":[{"furigana":"{分|わ}かりました。じゃあ、{明日|あした}の{朝|あさ}{七時|しちじ}にまた{来|き}ます。","ja":"分かりました。じゃあ、明日の朝七時にまた来ます。","vi":"Tôi hiểu rồi. Vậy bảy giờ sáng mai tôi quay lại."},{"furigana":"{分|わ}かりました。{今|いま}{買|か}えば{半額|はんがく}なんですね。","ja":"分かりました。今買えば半額なんですね。","vi":"Tôi hiểu rồi. Mua bây giờ là được nửa giá nhỉ."}],"line":5,"why_vi":"Đã biết sau bảy giờ tối mới dán tem giảm giá, Lin chuyển sang hỏi chỗ để sữa; sáng mai món đã hết hạn, còn bây giờ chưa đến giờ giảm nên mua ngay chưa được nửa giá."},{"distractors":[{"furigana":"いいえ、{牛乳|ぎゅうにゅう}はもう{買|か}いました。ありがとうございます。","ja":"いいえ、牛乳はもう買いました。ありがとうございます。","vi":"Không ạ, sữa thì tôi mua rồi. Cảm ơn anh."},{"furigana":"{入|い}り{口|ぐち}の{近|ちか}くですね。ありがとうございます。","ja":"入り口の近くですね。ありがとうございます。","vi":"Ở gần lối vào nhỉ. Cảm ơn anh."}],"line":7,"why_vi":"Nhân viên đề nghị dẫn đường (ご案内しましょうか), Lin lịch sự từ chối và cảm ơn; Lin vừa hỏi sữa ở đâu nên không thể đã mua sữa rồi, còn sữa ở khu tủ lạnh trong cùng chứ không gần lối vào."}]}', 'cpath-dly-03', 'd2c4b91916be'),
  ('DLY-10', 'MARKET', 2, 'N4', '野菜を買う', 'Mua rau', 'Ở chợ, hỏi giá và xin bớt.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{何時|なんじ}まで{開|あ}いていますか。","ja":"何時まで開いていますか。","vi":"Mở cửa đến mấy giờ ạ?"},{"furigana":"この{野菜|やさい}を{交換|こうかん}できますか。","ja":"この野菜を交換できますか。","vi":"Rau này đổi được không ạ?"}],"line":1,"why_vi":"Muốn mua rau thì hỏi giá 野菜はいくらですか; hỏi giờ đóng cửa hay xin đổi hàng đều sai việc."},{"distractors":[{"furigana":"{二百円|にひゃくえん}ですか。","ja":"二百円ですか。","vi":"Là hai trăm yên ạ?"},{"furigana":"{一袋|ひとふくろ}ください。","ja":"一袋ください。","vi":"Cho tôi một túi ạ."}],"line":3,"why_vi":"Biết giá thì hỏi rau có tươi không; hỏi lại giá hay nói mua luôn đều chưa cần."},{"distractors":[{"furigana":"この{野菜|やさい}はきれいですね。","ja":"この野菜はきれいですね。","vi":"Rau này đẹp nhỉ."},{"furigana":"どこで{作|つく}りましたか。","ja":"どこで作りましたか。","vi":"Trồng ở đâu ạ?"}],"line":5,"why_vi":"Người bán xác nhận rau tươi nên Linh mua hai túi và mặc cả; khen rau đẹp hay hỏi nguồn gốc xa xôi đều lạc nhịp."}]}', 'cpath-dly-10', 'd2c4b91916be'),
  ('DLY-11', 'MARKET', 3, 'N4', '魚を選ぶ', 'Chọn cá', 'Nhờ người bán chỉ cách chọn cá tươi.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{魚|さかな}はいくらですか。","ja":"魚はいくらですか。","vi":"Cá bao nhiêu tiền ạ?"},{"furigana":"{肉|にく}をください。","ja":"肉をください。","vi":"Cho tôi thịt ạ."}],"line":1,"why_vi":"Muốn chọn cá tươi thì hỏi 新鮮な魚はどれですか; hỏi giá trước hay bảo mua thịt đều sai việc."},{"distractors":[{"furigana":"{一番|いちばん}{大|おお}きいのはどれですか。","ja":"一番大きいのはどれですか。","vi":"Con to nhất là con nào ạ?"},{"furigana":"やっぱり{買|か}いません。","ja":"やっぱり買いません。","vi":"Thôi, tôi không mua ạ."}],"line":3,"why_vi":"Được giới thiệu cá thu thì đặt mua một con và nhờ lọc; đòi con to nhất hay từ chối mua đều mâu thuẫn."}]}', 'cpath-dly-11', 'd2c4b91916be'),
  ('DLY-07', 'SCHOOL', 1, 'N4', '学校に欠席の連絡', 'Báo nghỉ học', 'Gọi điện báo nghỉ và hỏi bài.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"おはようございます。{今日|きょう}の{授業|じゅぎょう}は{何時|なんじ}からですか。","ja":"おはようございます。今日の授業は何時からですか。","vi":"Chào cô ạ. Hôm nay mấy giờ bắt đầu học ạ?"},{"furigana":"おはようございます。{今日|きょう}は{元気|げんき}なので、{学校|がっこう}に{行|い}きます。","ja":"おはようございます。今日は元気なので、学校に行きます。","vi":"Chào cô ạ. Hôm nay em khỏe nên sẽ đến trường ạ."}],"line":1,"why_vi":"Gọi cho văn phòng trường thì trước hết chào rồi xưng năm học (二年 = năm hai) và tên mình, nên văn phòng mới hỏi \\"どうしましたか\\" để Lin nói việc cần báo; hỏi giờ học thì văn phòng phải trả lời giờ chứ không hỏi \\"có chuyện gì\\", còn nói hôm nay khỏe sẽ đến trường thì trái với mục đích gọi báo nghỉ."},{"distractors":[{"furigana":"バスが{来|こ}ないので、{今日|きょう}は{少|すこ}し{遅|おく}れて{行|い}きます。","ja":"バスが来ないので、今日は少し遅れて行きます。","vi":"Xe buýt không đến nên hôm nay em sẽ đến muộn một chút ạ."},{"furigana":"{熱|ねつ}があるので、{先生|せんせい}に{休|やす}んでいただきたいです。","ja":"熱があるので、先生に休んでいただきたいです。","vi":"Em bị sốt nên muốn thầy cô nghỉ ạ."}],"line":3,"why_vi":"\\"休ませていただきたい\\" là xin phép cho chính mình nghỉ vì bị sốt, nên văn phòng mới hỏi đã đi bệnh viện chưa và dặn mang giấy khám; báo đến muộn vì xe buýt thì không khớp với các câu đó, còn \\"休んでいただきたい\\" lại là mong thầy cô nghỉ."},{"distractors":[{"furigana":"{学校|がっこう}には{午後|ごご}から{行|い}く{予定|よてい}です。","ja":"学校には午後から行く予定です。","vi":"Em định chiều nay đến trường ạ."},{"furigana":"いいえ、{熱|ねつ}はもう{全然|ぜんぜん}ありません。","ja":"いいえ、熱はもう全然ありません。","vi":"Không ạ, em hết sốt hẳn rồi."}],"line":5,"why_vi":"Văn phòng hỏi đã đi bệnh viện chưa nên Lin đáp chiều nay sẽ đi; câu đến trường mâu thuẫn với việc xin nghỉ, câu hết sốt mâu thuẫn với lý do vừa nói."},{"distractors":[{"furigana":"はい。では、{今|いま}から{学校|がっこう}に{行|い}きます。","ja":"はい。では、今から学校に行きます。","vi":"Vâng ạ. Vậy bây giờ em đến trường ạ."},{"furigana":"いいえ、{病院|びょういん}には{行|い}かないので、{診断書|しんだんしょ}は{出|で}ません。","ja":"いいえ、病院には行かないので、診断書は出ません。","vi":"Không ạ, em không đi bệnh viện nên sẽ không có giấy khám."}],"line":7,"why_vi":"Lin vâng lời dặn mang giấy khám rồi hỏi tiếp về bài tập hôm nay; đến trường ngay là trái với việc xin nghỉ, còn nói không đi bệnh viện mâu thuẫn với dự định chiều nay."}]}', 'cpath-dly-07', 'd2c4b91916be'),
  ('DLY-15', 'SCHOOL', 2, 'N4', '宿題を聞く', 'Hỏi về bài tập', 'Hỏi giáo viên về hạn nộp bài tập.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{宿題|しゅくだい}は{何|なん}ページですか。","ja":"宿題は何ページですか。","vi":"Bài tập trang mấy ạ?"},{"furigana":"{休|やす}み{時間|じかん}は{何時|なんじ}ですか。","ja":"休み時間は何時ですか。","vi":"Giờ giải lao lúc mấy giờ ạ?"}],"line":1,"why_vi":"Muốn biết hạn nộp thì hỏi 締め切りはいつですか; hỏi nội dung bài tập hay giờ ra chơi đều chưa đúng."},{"distractors":[{"furigana":"いつまでですか。","ja":"いつまでですか。","vi":"Đến khi nào ạ?"},{"furigana":"{今日|きょう}{休|やす}んでもいいですか。","ja":"今日休んでもいいですか。","vi":"Hôm nay em nghỉ được không ạ?"}],"line":3,"why_vi":"Biết hạn nộp thì xác nhận cách nộp; hỏi lại hạn hay xin nghỉ học đều sai."}]}', 'cpath-dly-15', 'd2c4b91916be'),
  ('DLY-16', 'SCHOOL', 3, 'N4', '図書館で借りる', 'Mượn sách ở thư viện', 'Ở thư viện, hỏi thủ tục mượn sách.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"この{本|ほん}を{買|か}えますか。","ja":"この本を買えますか。","vi":"Quyển sách này bán được không ạ?"},{"furigana":"{図書館|としょかん}は{何時|なんじ}に{開|あ}きますか。","ja":"図書館は何時に開きますか。","vi":"Thư viện mấy giờ mở cửa ạ?"}],"line":1,"why_vi":"Muốn mượn sách thì nói 本を借りたいです; hỏi mua sách hay hỏi giờ mở cửa đều sai việc."},{"distractors":[{"furigana":"カードはありません。","ja":"カードはありません。","vi":"Tôi không có thẻ ạ."},{"furigana":"いくらかかりますか。","ja":"いくらかかりますか。","vi":"Mất bao nhiêu tiền ạ?"}],"line":3,"why_vi":"Được hỏi thẻ thì đưa ra; nói không có thẻ hay hỏi giá thuê đều sai."},{"distractors":[{"furigana":"{何週間|なんしゅうかん}{借|か}りられますか。","ja":"何週間借りられますか。","vi":"Mượn được mấy tuần ạ?"},{"furigana":"この{本|ほん}は{面白|おもしろ}いですね。","ja":"この本は面白いですね。","vi":"Sách này hay nhỉ."}],"line":5,"why_vi":"Biết hạn mượn thì hỏi chỗ trả sách; hỏi lại hạn mượn hay khen sách hay đều lạc đề."}]}', 'cpath-dly-16', 'd2c4b91916be'),
  ('DLY-04', 'PUBLIC', 1, 'N3', '銀行で手続き', 'Làm thủ tục ngân hàng', 'Chuyển khoản và hỏi về phí.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{口座|こうざ}を{新|あたら}しく{作|つく}りたいのですが。","ja":"口座を新しく作りたいのですが。","vi":"Tôi muốn mở tài khoản mới ạ."},{"furigana":"{両替|りょうがえ}をしたいのですが。","ja":"両替をしたいのですが。","vi":"Tôi muốn đổi tiền ạ."}],"line":1,"why_vi":"Lin đến ngân hàng để chuyển khoản nên nói \\"振込をしたいのですが\\" (nhân viên hỏi tiếp có chuyển sang ngân hàng khác không); mở tài khoản hay đổi tiền đều sai mục đích."},{"distractors":[{"furigana":"いいえ、{他|ほか}の{銀行|ぎんこう}の{口座|こうざ}です。","ja":"いいえ、他の銀行の口座です。","vi":"Không, là tài khoản ở ngân hàng khác ạ."},{"furigana":"はい。でも、{振込|ふりこみ}はやめておきます。","ja":"はい。でも、振込はやめておきます。","vi":"Vâng. Nhưng thôi, tôi không chuyển khoản nữa."}],"line":3,"why_vi":"Chuyển sang ngân hàng khác nên Lin đáp \\"vâng\\" rồi hỏi phí; nói \\"không\\" rồi lại bảo ngân hàng khác là tự mâu thuẫn, còn bỏ chuyển khoản ngay sau khi vừa xin làm là vô lý."},{"distractors":[{"furigana":"{窓口|まどぐち}のほうが{安|やす}いんですね。{窓口|まどぐち}でお{願|ねが}いします。","ja":"窓口のほうが安いんですね。窓口でお願いします。","vi":"Ở quầy rẻ hơn nhỉ. Cho tôi làm ở quầy."},{"furigana":"どちらも{同|おな}じ{金額|きんがく}なんですね。{分|わ}かりました。","ja":"どちらも同じ金額なんですね。分かりました。","vi":"Cả hai bên đều cùng số tiền nhỉ. Tôi hiểu rồi."}],"line":5,"why_vi":"Ở quầy 440 yên còn ở ATM chỉ 220 yên, nên Lin ngạc nhiên vì chênh lệch và hỏi làm ở ATM; hai câu kia hiểu sai là quầy rẻ hơn hoặc hai bên bằng nhau."},{"distractors":[{"furigana":"{通帳|つうちょう}は{要|い}らないんですね。よかったです。","ja":"通帳は要らないんですね。よかったです。","vi":"Không cần sổ ngân hàng nhỉ. May quá."},{"furigana":"{持|も}っていません。でも、ATMでお{願|ねが}いします。","ja":"持っていません。でも、ATMでお願いします。","vi":"Tôi không mang. Nhưng cho tôi làm ở ATM."}],"line":7,"why_vi":"ATM cần cả sổ và thẻ, Lin có mang nên nhờ hướng dẫn thao tác; nói không cần sổ là nghe sai, còn không mang mà vẫn đòi dùng ATM là vô lý."}]}', 'cpath-dly-04', 'd2c4b91916be'),
  ('DLY-06', 'PUBLIC', 2, 'N3', '宅配便の再配達', 'Nhận lại bưu kiện', 'Gọi tổng đài xin giao lại hàng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{荷物|にもつ}を{送|おく}りたいので、{家|いえ}まで{取|と}りに{来|き}ていただきたいのですが。","ja":"荷物を送りたいので、家まで取りに来ていただきたいのですが。","vi":"Tôi muốn gửi hàng nên nhờ anh đến tận nhà lấy ạ."},{"furigana":"{荷物|にもつ}はもう{受|う}け{取|と}ったので、{再|さい}{配達|はいたつ}は{要|い}りません。","ja":"荷物はもう受け取ったので、再配達は要りません。","vi":"Tôi nhận hàng rồi nên không cần giao lại nữa ạ."}],"line":1,"why_vi":"Lin vắng nhà nên nhận phiếu báo và gọi để xin giao lại; gửi hàng đi là sai mục đích, còn nói đã nhận hàng thì trái với tình huống."},{"distractors":[{"furigana":"はい、{名前|なまえ}はグエンです。","ja":"はい、名前はグエンです。","vi":"Vâng, tên tôi là Nguyễn ạ."},{"furigana":"{伝票|でんぴょう}{番号|ばんごう}を{教|おし}えていただけますか。","ja":"伝票番号を教えていただけますか。","vi":"Anh cho tôi biết mã vận đơn được không ạ?"}],"line":3,"why_vi":"Nhân viên hỏi mã vận đơn nên Lin đọc dãy số trên phiếu; nói tên là trả lời sai câu hỏi, còn hỏi ngược mã vận đơn là nhầm vai vì mã nằm trên phiếu Lin đang cầm."},{"distractors":[{"furigana":"{夜|よる}は{届|とど}けられないんですね。","ja":"夜は届けられないんですね。","vi":"Buổi tối không giao được nhỉ."},{"furigana":"{何日|なんにち}に{届|とど}けてもらえますか。","ja":"何日に届けてもらえますか。","vi":"Ngày nào thì anh giao được ạ?"}],"line":5,"why_vi":"Nhân viên nói giao được vào tối nay nên Lin hỏi khung giờ cụ thể; một câu hiểu ngược thành không giao buổi tối, câu kia hỏi lại ngày giao trong khi nhân viên vừa nói \\"本日\\"."},{"distractors":[{"furigana":"{八時|はちじ}から{十時|じゅうじ}の{間|あいだ}ですね。お{願|ねが}いします。","ja":"八時から十時の間ですね。お願いします。","vi":"Trong khoảng tám giờ đến mười giờ nhỉ. Nhờ anh ạ."},{"furigana":"{朝|あさ}の{七時|しちじ}から{九時|くじ}ですね。その{時間|じかん}なら{家|いえ}にいます。","ja":"朝の七時から九時ですね。その時間なら家にいます。","vi":"Từ bảy đến chín giờ sáng nhỉ. Giờ đó thì tôi có nhà."}],"line":7,"why_vi":"Khung giờ là 7–9 giờ tối nay và Lin có nhà nên đồng ý, nhờ bấm chuông; câu 8–10 giờ là nghe nhầm giờ, còn \\"7–9 giờ sáng\\" là sai vì nhân viên đã nói giao vào buổi tối hôm nay (本日の夜間)."}]}', 'cpath-dly-06', 'd2c4b91916be'),
  ('DLY-12', 'PUBLIC', 3, 'N3', '国際郵便を送る', 'Gửi bưu phẩm quốc tế', 'Ở bưu điện, hỏi cách gửi bưu phẩm về Việt Nam.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{切手|きって}はいくらですか。","ja":"切手はいくらですか。","vi":"Tem bao nhiêu tiền ạ?"},{"furigana":"{小包|こづつみ}を{受|う}け{取|と}りたいです。","ja":"小包を受け取りたいです。","vi":"Tôi muốn nhận bưu kiện ạ."}],"line":1,"why_vi":"Muốn gửi bưu kiện thì nói rõ nơi nhận; hỏi giá tem hay xin nhận bưu kiện đều sai việc."},{"distractors":[{"furigana":"{船便|ふなびん}はどうですか。","ja":"船便はどうですか。","vi":"Đường biển thì sao ạ?"},{"furigana":"{遅|おそ}くてもいいです。","ja":"遅くてもいいです。","vi":"Chậm cũng được ạ."}],"line":3,"why_vi":"Đã chọn đường hàng không thì hỏi thời gian; hỏi lại đường biển hay nói gửi chậm cũng được đều lạc nhịp."},{"distractors":[{"furigana":"{送料|そうりょう}はいくらですか。","ja":"送料はいくらですか。","vi":"Cước gửi bao nhiêu ạ?"},{"furigana":"{中身|なかみ}は{割|わ}れ{物|もの}です。","ja":"中身は割れ物です。","vi":"Bên trong là đồ dễ vỡ ạ."}],"line":5,"why_vi":"Biết thời gian gửi thì khai nội dung và hỏi tờ khai; hỏi giá cước hay nói gửi đồ dễ vỡ đều sai vì bên trong là quần áo."}]}', 'cpath-dly-12', 'd2c4b91916be'),
  ('DLY-05', 'HEALTH', 1, 'N3', '病院で診察', 'Khám bệnh', 'Mô tả triệu chứng và nhận đơn thuốc.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"おかげさまで{元気|げんき}です。{先生|せんせい}もお{元気|げんき}そうですね。","ja":"おかげさまで元気です。先生もお元気そうですね。","vi":"Nhờ trời tôi khỏe ạ. Bác sĩ trông cũng khỏe nhỉ."},{"furigana":"{先生|せんせい}はどうされましたか。{顔色|かおいろ}が{悪|わる}いですよ。","ja":"先生はどうされましたか。顔色が悪いですよ。","vi":"Còn bác sĩ thì bị sao vậy ạ? Sắc mặt bác sĩ không tốt đâu."}],"line":2,"why_vi":"Ở phòng khám, \\"どうされましたか\\" là hỏi bệnh nhân bị làm sao nên Lin phải kể triệu chứng; đáp như lời chào hỏi sức khỏe hay hỏi ngược bác sĩ đều sai."},{"distractors":[{"furigana":"はい、{薬|くすり}は{昨日|きのう}{飲|の}みました。","ja":"はい、薬は昨日飲みました。","vi":"Vâng, thuốc thì tôi uống hôm qua rồi."},{"furigana":"いいえ、{咳|せき}は{出|で}ていません。","ja":"いいえ、咳は出ていません。","vi":"Không, tôi không bị ho ạ."}],"line":4,"why_vi":"Bác sĩ hỏi đã đo nhiệt chưa nên Lin báo nhiệt độ đo buổi sáng; câu về thuốc trả lời sai câu hỏi, còn câu \\"không ho\\" mâu thuẫn với điều Lin vừa kể."},{"distractors":[{"furigana":"もう{治|なお}りましたから、{薬|くすり}は{要|い}りません。","ja":"もう治りましたから、薬は要りません。","vi":"Tôi khỏi rồi nên không cần thuốc ạ."},{"furigana":"{喉|のど}は{赤|あか}くないんですね。よかったです。","ja":"喉は赤くないんですね。よかったです。","vi":"Họng không đỏ nhỉ. May quá."}],"line":6,"why_vi":"Họng còn đỏ và ho chưa dứt nên Lin lịch sự xin thuốc để mau khỏi; nói đã khỏi là trái với triệu chứng, còn \\"họng không đỏ\\" là nghe nhầm vì bác sĩ vừa nói \\"少し赤いですね\\" (hơi đỏ)."},{"distractors":[{"furigana":"{眠|ねむ}くならない{薬|くすり}なんですね。{安心|あんしん}しました。","ja":"眠くならない薬なんですね。安心しました。","vi":"Là thuốc không gây buồn ngủ nhỉ. Tôi yên tâm rồi."},{"furigana":"{分|わ}かりました。{三日分|みっかぶん}ですね。","ja":"分かりました。三日分ですね。","vi":"Tôi hiểu rồi. Thuốc cho ba ngày nhỉ."}],"line":8,"why_vi":"Thuốc có thành phần gây buồn ngủ nên Lin hứa tránh lái xe; hai câu kia nghe nhầm là thuốc không gây buồn ngủ và nhầm số ngày (năm ngày chứ không phải ba)."}]}', 'cpath-dly-05', 'd2c4b91916be'),
  ('DLY-13', 'HEALTH', 2, 'N3', '診察を受ける', 'Khám bệnh', 'Ở phòng khám, kể triệu chứng đau đầu cho bác sĩ.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"おなかが{痛|いた}いです。","ja":"おなかが痛いです。","vi":"Tôi đau bụng ạ."},{"furigana":"{診察|しんさつ}は{何時|なんじ}までですか。","ja":"診察は何時までですか。","vi":"Khám đến mấy giờ ạ?"}],"line":1,"why_vi":"Đi khám thì kể triệu chứng chính là đau đầu; nói đau bụng hay hỏi giờ đóng cửa đều sai việc."},{"distractors":[{"furigana":"{熱|ねつ}はありません。","ja":"熱はありません。","vi":"Tôi không sốt ạ."},{"furigana":"{四十度|よんじゅうど}もあります。","ja":"四十度もあります。","vi":"Sốt tới bốn mươi độ ạ."}],"line":3,"why_vi":"Bác sĩ hỏi sốt thì Linh báo có sốt nhẹ và số đo; nói không sốt hay kêu quá sốt cao đều mâu thuẫn."},{"distractors":[{"furigana":"{咳|せき}は{出|で}ません。","ja":"咳は出ません。","vi":"Tôi không ho ạ."},{"furigana":"この{部屋|へや}はきれいですね。","ja":"この部屋はきれいですね。","vi":"Phòng này sạch nhỉ."}],"line":5,"why_vi":"Được hỏi họng và ho thì trả lời họng ổn nhưng hơi ho; nói không ho hay khen phòng khám đều không trả lời câu hỏi."}]}', 'cpath-dly-13', 'd2c4b91916be'),
  ('DLY-14', 'HEALTH', 3, 'N3', '薬局で薬をもらう', 'Mua thuốc ở hiệu thuốc', 'Cầm đơn thuốc ra hiệu thuốc hỏi cách uống.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{頭痛|ずつう}の{薬|くすり}はありますか。","ja":"頭痛の薬はありますか。","vi":"Có thuốc đau đầu không ạ?"},{"furigana":"{化粧品|けしょうひん}をください。","ja":"化粧品をください。","vi":"Cho tôi mỹ phẩm ạ."}],"line":1,"why_vi":"Có đơn thuốc thì đưa ra và xin lấy thuốc; hỏi mua thuốc không đơn hay xin tư vấn mỹ phẩm đều sai việc."},{"distractors":[{"furigana":"{保険証|ほけんしょう}はありません。","ja":"保険証はありません。","vi":"Tôi không có thẻ bảo hiểm ạ."},{"furigana":"{薬|くすり}はいくらですか。","ja":"薬はいくらですか。","vi":"Thuốc bao nhiêu tiền ạ?"}],"line":3,"why_vi":"Được hỏi thẻ bảo hiểm thì đưa ra; nói không có thẻ hay hỏi giá thuốc đều không đúng câu hỏi."},{"distractors":[{"furigana":"{何時|なんじ}に{飲|の}みますか。","ja":"何時に飲みますか。","vi":"Uống lúc mấy giờ ạ?"},{"furigana":"{一回|いっかい}だけですか。","ja":"一回だけですか。","vi":"Chỉ uống một lần thôi ạ?"}],"line":5,"why_vi":"Được hướng dẫn cách uống thì hỏi số ngày; hỏi lại giờ uống hay nói uống một lần đều sai."}]}', 'cpath-dly-14', 'd2c4b91916be'),
  ('DLY-08', 'SOCIAL', 1, 'N3', '近所付き合い', 'Chuyện hàng xóm', 'Xin lỗi hàng xóm vì tiếng ồn khi chuyển nhà.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{昨日|きのう}はお{宅|たく}の{引|ひ}っ{越|こ}しで{騒|さわ}がしかったですね。","ja":"昨日はお宅の引っ越しで騒がしかったですね。","vi":"Hôm qua nhà cô chuyển nhà ồn ào nhỉ."},{"furigana":"{昨日|きのう}は{引|ひ}っ{越|こ}しで{疲|つか}れたので、{今日|きょう}はゆっくり{休|やす}みます。","ja":"昨日は引っ越しで疲れたので、今日はゆっくり休みます。","vi":"Hôm qua chuyển nhà mệt quá nên hôm nay cháu nghỉ ngơi ạ."}],"line":1,"why_vi":"Chính Lin chuyển nhà gây ồn nên phải xin lỗi hàng xóm (hàng xóm đáp \\"お互い様\\"); một câu đổ cho nhà hàng xóm ồn, câu kia chỉ kể mình mệt mà không hề xin lỗi."},{"distractors":[{"furigana":"いえいえ、どういたしまして。","ja":"いえいえ、どういたしまして。","vi":"Dạ, không có gì đâu ạ."},{"furigana":"どうぞ{気|き}にしないでください。","ja":"どうぞ気にしないでください。","vi":"Cô đừng bận tâm ạ."}],"line":3,"why_vi":"Hàng xóm đã đáp \\"お互い様\\" nên Lin đưa món quà nhỏ \\"これ、少しですがどうぞ\\"; \\"どういたしまして\\" là đáp lời cảm ơn, còn bảo hàng xóm \\"đừng bận tâm\\" là nhầm vai vì Lin mới là người gây ồn."},{"distractors":[{"furigana":"ごみ{出|だ}しのことなど、また{教|おし}えてあげますね。","ja":"ごみ出しのことなど、また教えてあげますね。","vi":"Chuyện đổ rác các thứ, cháu sẽ chỉ thêm cho cô nhé."},{"furigana":"はい、それはとても{高|たか}かったんですよ。","ja":"はい、それはとても高かったんですよ。","vi":"Vâng, món đó đắt lắm đấy ạ."}],"line":5,"why_vi":"Là người mới đến, Lin khiêm tốn nhờ hàng xóm chỉ thêm chuyện đổ rác; \\"教えてあげます\\" là tự nhận mình chỉ cho người khác, còn khoe quà đắt thì trái phép lịch sự khi tặng quà."},{"distractors":[{"furigana":"{週|しゅう}に{一度|いちど}あるんですね。{大変|たいへん}ですね。","ja":"週に一度あるんですね。大変ですね。","vi":"Mỗi tuần họp một lần nhỉ. Vất vả quá."},{"furigana":"{集|あつ}まりは{月|つき}に{何回|なんかい}あるんですか。","ja":"集まりは月に何回あるんですか。","vi":"Buổi họp mỗi tháng có mấy lần ạ?"}],"line":7,"why_vi":"Hàng xóm vừa nói tổ dân phố họp mỗi tháng một lần nên Lin hỏi có nên tham gia không; một câu nghe nhầm thành mỗi tuần, câu kia hỏi lại số lần họp vừa được nói."}]}', 'cpath-dly-08', 'd2c4b91916be'),
  ('DLY-17', 'SOCIAL', 2, 'N3', '映画に誘う', 'Rủ đi xem phim', 'Rủ bạn đi xem phim vào cuối tuần.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{映画|えいが}のチケットはいくら？","ja":"映画のチケットはいくら？","vi":"Vé xem phim bao nhiêu?"},{"furigana":"{一人|ひとり}で{映画|えいが}に{行|い}くね。","ja":"一人で映画に行くね。","vi":"Mình đi xem phim một mình nhé."}],"line":1,"why_vi":"Muốn rủ bạn thì hỏi trước xem bạn có bận không; hỏi giá vé hay nói đi một mình đều sai việc."},{"distractors":[{"furigana":"{何時|なんじ}から{始|はじ}まる？","ja":"何時から始まる？","vi":"Bắt đầu lúc mấy giờ?"},{"furigana":"{一緒|いっしょ}に{勉強|べんきょう}しない？","ja":"一緒に勉強しない？","vi":"Học bài cùng mình không?"}],"line":3,"why_vi":"Bạn rảnh nên Linh rủ đi xem phim; hỏi giờ ngay hay rủ đi học bài đều chưa phải bước này."},{"distractors":[{"furigana":"{本当|ほんとう}に{暇|ひま}？","ja":"本当に暇？","vi":"Cậu rảnh thật chứ?"},{"furigana":"{日曜日|にちようび}はどう？","ja":"日曜日はどう？","vi":"Chủ nhật thì sao?"}],"line":5,"why_vi":"Bạn đồng ý thì Linh đề xuất giờ cụ thể; hỏi lại bạn có rảnh không hay đổi sang ngày khác đều thừa."}]}', 'cpath-dly-17', 'd2c4b91916be'),
  ('DLY-18', 'SOCIAL', 3, 'N3', '喫茶店に誘う', 'Rủ đi uống cà phê', 'Mời người quen đi uống cà phê sau giờ làm.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{昼休|ひるやす}みは{何時|なんじ}ですか。","ja":"昼休みは何時ですか。","vi":"Giờ nghỉ trưa là mấy giờ ạ?"},{"furigana":"{今日|きょう}は{忙|いそが}しいです。","ja":"今日は忙しいです。","vi":"Hôm nay tôi bận ạ."}],"line":1,"why_vi":"Muốn mời thì hỏi người kia có rảnh sau giờ làm không; hỏi giờ nghỉ trưa hay nói mình bận đều sai."},{"distractors":[{"furigana":"{夕食|ゆうしょく}を{食|た}べに{行|い}きませんか。","ja":"夕食を食べに行きませんか。","vi":"Đi ăn tối không ạ?"},{"furigana":"{買|か}い{物|もの}に{行|い}きませんか。","ja":"買い物に行きませんか。","vi":"Đi mua sắm không ạ?"}],"line":3,"why_vi":"Người kia rảnh thì Linh mời đi uống trà; mời ăn tối hay rủ đi mua sắm đều khác việc đang mời."},{"distractors":[{"furigana":"お{時間|じかん}{大丈夫|だいじょうぶ}ですか。","ja":"お時間大丈夫ですか。","vi":"Anh có rảnh không ạ?"},{"furigana":"{空港|くうこう}で{会|あ}いましょう。","ja":"空港で会いましょう。","vi":"Gặp nhau ở sân bay nhé ạ."}],"line":5,"why_vi":"Người kia đồng ý thì Linh chốt giờ và địa điểm; hỏi lại có rảnh không hay đổi địa điểm xa đều thừa."}]}', 'cpath-dly-18', 'd2c4b91916be'),
  ('DLY-19', 'TIME', 1, 'N5', '開店時間を聞く', 'Hỏi giờ mở cửa', 'Hỏi giờ mở cửa của bưu điện.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{郵便局|ゆうびんきょく}はどこですか。","ja":"郵便局はどこですか。","vi":"Bưu điện ở đâu ạ?"},{"furigana":"{送料|そうりょう}はいくらですか。","ja":"送料はいくらですか。","vi":"Cước gửi bao nhiêu ạ?"}],"line":1,"why_vi":"Muốn biết giờ mở cửa thì hỏi 何時に開きますか; hỏi địa chỉ hay giá gửi đồ đều sai việc."},{"distractors":[{"furigana":"{九時|くじ}に{開|あ}きますか。","ja":"九時に開きますか。","vi":"Chín giờ mở cửa ạ?"},{"furigana":"{手紙|てがみ}を{送|おく}りたいです。","ja":"手紙を送りたいです。","vi":"Tôi muốn gửi thư ạ."}],"line":3,"why_vi":"Biết giờ mở thì hỏi giờ đóng; hỏi lại giờ mở hay nói muốn gửi thư đều chưa cần."},{"distractors":[{"furigana":"{今日|きょう}は{何曜日|なんようび}ですか。","ja":"今日は何曜日ですか。","vi":"Hôm nay là thứ mấy ạ?"},{"furigana":"この{辺|へん}は{静|しず}かですね。","ja":"この辺は静かですね。","vi":"Khu này yên tĩnh nhỉ."}],"line":5,"why_vi":"Biết giờ đóng thì hỏi giờ hiện tại để ước lượng; hỏi ngày trong tuần hay khen chỗ đẹp đều lạc đề."}]}', 'cpath-dly-19', 'd2c4b91916be'),
  ('DLY-20', 'TIME', 2, 'N5', '待ち合わせの時間', 'Giờ hẹn gặp', 'Hẹn giờ gặp bạn để cùng đi chơi.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{何|なに}を{着|き}ていく？","ja":"何を着ていく？","vi":"Mặc gì đi?"},{"furigana":"{今日|きょう}、{会|あ}おう。","ja":"今日、会おう。","vi":"Hôm nay gặp nhau nhé."}],"line":1,"why_vi":"Muốn hẹn giờ thì hỏi mấy giờ gặp; hỏi mặc gì hay nói gặp hôm nay đều sai."},{"distractors":[{"furigana":"{十時|じゅうじ}でいいよ。","ja":"十時でいいよ。","vi":"Mười giờ được đấy."},{"furigana":"{九時|くじ}にしない？","ja":"九時にしない？","vi":"Chín giờ nhé?"}],"line":3,"why_vi":"Thấy mười giờ sớm quá thì Linh đề nghị mười một giờ; chấp nhận ngay hay đòi chín giờ đều mâu thuẫn."},{"distractors":[{"furigana":"{十一時|じゅういちじ}でいい？","ja":"十一時でいい？","vi":"Mười một giờ được chứ?"},{"furigana":"{私|わたし}の{家|いえ}で{会|あ}おう。","ja":"私の家で会おう。","vi":"Gặp nhau ở nhà mình nhé."}],"line":5,"why_vi":"Đã chốt giờ thì bàn địa điểm gặp; hỏi lại giờ hay nói gặp ở nhà bạn đều sai nhịp."}]}', 'cpath-dly-20', 'd2c4b91916be'),
  ('DLY-21', 'TIME', 3, 'N5', 'かかる時間を聞く', 'Hỏi thời gian đi lại', 'Hỏi đường và thời gian đi bộ tới ga.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{駅|えき}までいくらですか。","ja":"駅までいくらですか。","vi":"Ra ga bao nhiêu tiền ạ?"},{"furigana":"タクシーを{呼|よ}んでください。","ja":"タクシーを呼んでください。","vi":"Gọi taxi giúp tôi ạ."}],"line":1,"why_vi":"Muốn biết thời gian đi bộ thì hỏi どのくらいかかりますか; hỏi giá vé hay xin gọi taxi đều sai việc."},{"distractors":[{"furigana":"{何分|なんぷん}かかりますか。","ja":"何分かかりますか。","vi":"Mất bao nhiêu phút ạ?"},{"furigana":"もう{大丈夫|だいじょうぶ}です。","ja":"もう大丈夫です。","vi":"Không cần nữa ạ."}],"line":3,"why_vi":"Biết đi bộ mất mười lăm phút thì hỏi có xe buýt không; hỏi lại thời gian đi bộ hay nói không cần đều lạc nhịp."},{"distractors":[{"furigana":"バスはいくらですか。","ja":"バスはいくらですか。","vi":"Xe buýt bao nhiêu tiền ạ?"},{"furigana":"{車|くるま}で{行|い}きます。","ja":"車で行きます。","vi":"Tôi đi ô tô ạ."}],"line":5,"why_vi":"Có xe buýt thì hỏi tần suất chuyến; hỏi giá vé hay nói mình có ô tô đều không phải bước tiếp theo."}]}', 'cpath-dly-21', 'd2c4b91916be'),
  ('BRSE-04', 'PM', 1, 'N2', '進捗報告', 'Báo cáo tiến độ trong họp định kỳ', 'BrSE báo cáo tiến độ tuần, trong đó có một hạng mục đang chậm.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"それでは、{本日|ほんじつ}の{会議|かいぎ}はこれで{終|お}わりにいたします。","ja":"それでは、本日の会議はこれで終わりにいたします。","vi":"Vậy cuộc họp hôm nay xin kết thúc tại đây."},{"furigana":"それでは、{田中|たなか}{様|さま}から{今週|こんしゅう}の{進捗|しんちょく}をご{報告|ほうこく}いただけますか。","ja":"それでは、田中様から今週の進捗をご報告いただけますか。","vi":"Vậy xin anh Tanaka báo cáo tiến độ tuần này giúp."}],"line":1,"why_vi":"BrSE là người báo cáo tiến độ trong họp định kỳ nên mở đầu bằng ご報告いたします; tuyên bố kết thúc họp hay nhờ khách báo cáo tiến độ của đội mình đều sai vai."},{"distractors":[{"furigana":"{会員|かいいん}{登録|とうろく}{機能|きのう}の{進捗|しんちょく}は、{田中|たなか}{様|さま}のほうでご{確認|かくにん}いただけましたでしょうか。","ja":"会員登録機能の進捗は、田中様のほうでご確認いただけましたでしょうか。","vi":"Tiến độ chức năng đăng ký thành viên thì anh Tanaka đã xem giúp chưa ạ?"},{"furigana":"{会員|かいいん}{登録|とうろく}{機能|きのう}のテストを{担当|たんとう}していただけないでしょうか。","ja":"会員登録機能のテストを担当していただけないでしょうか。","vi":"Anh có thể phụ trách test chức năng đăng ký thành viên giúp được không ạ?"}],"line":2,"why_vi":"Báo cáo tiến độ cần nêu trạng thái hạng mục (xong đúng kế hoạch, đang chạy unit test); hỏi khách đã xem tiến độ chưa hay nhờ khách test đều đẩy việc sang khách, không phải là báo cáo."},{"distractors":[{"furigana":"{以上|いじょう}、{決済|けっさい}{機能|きのう}を{含|ふく}め、すべての{機能|きのう}が{予定|よてい}どおり{進|すす}んでおりますので、{今週|こんしゅう}は{遅|おく}れのある{項目|こうもく}はございません。","ja":"以上、決済機能を含め、すべての機能が予定どおり進んでおりますので、今週は遅れのある項目はございません。","vi":"Tóm lại, tất cả các chức năng, kể cả chức năng thanh toán, đều đang tiến triển đúng kế hoạch, nên tuần này không có hạng mục nào bị chậm."},{"furigana":"{一方|いっぽう}、{決済|けっさい}{機能|きのう}については、{田中|たなか}{様|さま}のご{確認|かくにん}が{遅|おそ}かったため、{進捗|しんちょく}が{遅|おく}れております。","ja":"一方、決済機能については、田中様のご確認が遅かったため、進捗が遅れております。","vi":"Ngược lại, chức năng thanh toán bị chậm tiến độ vì anh Tanaka xác nhận chậm."}],"line":3,"why_vi":"Sau tin tốt là hạng mục bị chậm: nêu khách quan nguyên nhân (xác nhận đặc tả API bên ngoài) và mức độ (khoảng 70%); nói mọi chức năng đều đúng kế hoạch là trái với tình huống có hạng mục chậm, còn đổ lỗi cho khách là thất lễ."},{"distractors":[{"furigana":"{全体|ぜんたい}のスケジュールへの{影響|えいきょう}については、こちらでは{判断|はんだん}いたしかねますので、{田中|たなか}{様|さま}のほうでご{判断|はんだん}いただけますでしょうか。","ja":"全体のスケジュールへの影響については、こちらでは判断いたしかねますので、田中様のほうでご判断いただけますでしょうか。","vi":"Về ảnh hưởng tới lịch trình tổng thể thì bên tôi không thể đánh giá được, nên anh Tanaka tự đánh giá giúp được không ạ?"},{"furigana":"いいえ、{決済|けっさい}{機能|きのう}は{昨日|きのう}の{時点|じてん}ですでに{完了|かんりょう}しておりますので、{全体|ぜんたい}のスケジュールへの{影響|えいきょう}はございません。","ja":"いいえ、決済機能は昨日の時点ですでに完了しておりますので、全体のスケジュールへの影響はございません。","vi":"Không, chức năng thanh toán đã hoàn thành từ hôm qua rồi, nên không có ảnh hưởng gì tới lịch trình tổng thể."}],"line":5,"why_vi":"Câu trả lời tốt nêu dự báo hiện tại (tuần sau bắt kịp) kèm rủi ro cụ thể (test kết nối API lỗi → chậm khoảng 2 ngày); đẩy việc đánh giá tiến độ của đội mình cho khách là sai vai, còn nói chức năng thanh toán đã xong thì mâu thuẫn với con số 70% vừa báo."},{"distractors":[{"furigana":"{承知|しょうち}いたしました。リスクがはっきりしても、ご{報告|ほうこく}は{不要|ふよう}ですね。","ja":"承知いたしました。リスクがはっきりしても、ご報告は不要ですね。","vi":"Tôi hiểu rồi. Vậy dù rủi ro đã rõ thì cũng không cần báo cáo nhỉ."},{"furigana":"{承知|しょうち}いたしました。では、プロジェクトが{終|お}わった{時点|じてん}でまとめてご{報告|ほうこく}いたします。","ja":"承知いたしました。では、プロジェクトが終わった時点でまとめてご報告いたします。","vi":"Tôi hiểu rồi. Vậy khi dự án kết thúc tôi sẽ báo cáo gộp một lần."}],"line":7,"why_vi":"Khách muốn được báo sớm nên BrSE hẹn một mốc cụ thể (thứ Tư) để kiểm tra và báo lại; \'không cần báo\' hay \'đợi dự án xong mới báo\' đều trái với yêu cầu báo sớm."}]}', 'cpath-brse-04', '80cfde997abf'),
  ('BRSE-05', 'PM', 2, 'N2', '納期遅延の報告と謝罪', 'Báo chậm bàn giao và xin lỗi', 'Test tích hợp phát sinh nhiều lỗi, BrSE phải báo lùi ngày bàn giao, nêu nguyên nhân và biện pháp.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{田中|たなか}{様|さま}、うれしいお{知|し}らせがございます。テストがすべて{予定|よてい}より{早|はや}く{終|お}わりました。","ja":"田中様、うれしいお知らせがございます。テストがすべて予定より早く終わりました。","vi":"Anh Tanaka, tôi có tin vui ạ. Toàn bộ phần test đã xong sớm hơn kế hoạch."},{"furigana":"{田中|たなか}{様|さま}、テストの{件|けん}ですが、{特|とく}にご{報告|ほうこく}することはございません。","ja":"田中様、テストの件ですが、特にご報告することはございません。","vi":"Anh Tanaka, về việc test thì không có gì đặc biệt cần báo cáo ạ."}],"line":1,"why_vi":"Sắp báo tin xấu (lùi ngày bàn giao) nên mở đầu bằng cụm đệm 大変申し上げにくいのですが; báo \'tin vui\' hay \'không có gì cần báo\' đều trái với tình huống."},{"distractors":[{"furigana":"{結合|けつごう}テストで{想定|そうてい}{以上|いじょう}の{不具合|ふぐあい}が{見|み}つかりましたが、{納品日|のうひんび}は{当初|とうしょ}の{予定|よてい}どおり{15日|じゅうごにち}で{問題|もんだい}ございません。","ja":"結合テストで想定以上の不具合が見つかりましたが、納品日は当初の予定どおり15日で問題ございません。","vi":"Test tích hợp phát hiện nhiều lỗi hơn dự kiến, nhưng ngày bàn giao vẫn là ngày 15 như kế hoạch ban đầu, không có vấn đề gì ạ."},{"furigana":"{結合|けつごう}テストは{問題|もんだい}なく{終|お}わりましたので、{納品日|のうひんび}を{当初|とうしょ}の{15日|じゅうごにち}から{12日|じゅうににち}に{早|はや}めさせていただけないでしょうか。","ja":"結合テストは問題なく終わりましたので、納品日を当初の15日から12日に早めさせていただけないでしょうか。","vi":"Test tích hợp đã xong, không có vấn đề gì, nên cho phép chúng tôi đẩy ngày bàn giao sớm lên, từ ngày 15 như ban đầu sang ngày 12 được không ạ?"}],"line":3,"why_vi":"Tình huống là phải lùi ngày bàn giao: nêu nguyên nhân (lỗi nhiều hơn dự kiến) và xin phép khách đổi từ ngày 15 sang ngày 18 (変更させていただけないでしょうか); nói vẫn giữ ngày 15 là trái với tình huống, còn báo test ổn rồi xin bàn giao sớm thì mâu thuẫn với lời mở đầu báo tin xấu."},{"distractors":[{"furigana":"{3日|みっか}ぐらいなら、{大|おお}きな{問題|もんだい}ではないと{思|おも}います。","ja":"3日ぐらいなら、大きな問題ではないと思います。","vi":"Chỉ khoảng 3 ngày thì tôi nghĩ không phải vấn đề lớn."},{"furigana":"ご{理解|りかい}いただき、{誠|まこと}にありがとうございます。","ja":"ご理解いただき、誠にありがとうございます。","vi":"Thành thật cảm ơn anh đã thông cảm."}],"line":5,"why_vi":"Khách đang khó xử nên trước hết phải xin lỗi chân thành (ご迷惑をおかけして…申し訳ございません); xem nhẹ 3 ngày chậm hay cảm ơn \'đã thông cảm\' khi khách chưa đồng ý đều sai."},{"distractors":[{"furigana":"{原因|げんいん}は、{仕様|しよう}{変更|へんこう}が{多|おお}すぎたことです。{今後|こんご}は、{仕様|しよう}{変更|へんこう}をしないようにお{願|ねが}いいたします。","ja":"原因は、仕様変更が多すぎたことです。今後は、仕様変更をしないようにお願いいたします。","vi":"Nguyên nhân là đặc tả thay đổi quá nhiều. Từ nay xin anh đừng thay đổi đặc tả nữa."},{"furigana":"{原因|げんいん}については、まだ{調査|ちょうさ}しておりませんのでわかりかねます。{今後|こんご}も{今|いま}までと{同|おな}じ{進|すす}め{方|かた}で、{特|とく}に{対策|たいさく}はとらない{予定|よてい}です。","ja":"原因については、まだ調査しておりませんのでわかりかねます。今後も今までと同じ進め方で、特に対策はとらない予定です。","vi":"Về nguyên nhân thì chúng tôi chưa điều tra nên chưa thể biết. Từ nay chúng tôi vẫn làm như trước giờ, không định áp dụng biện pháp gì."}],"line":6,"why_vi":"Sau lời xin lỗi cần nêu nguyên nhân phía mình và biện pháp phòng tái diễn cụ thể (checklist phạm vi ảnh hưởng); đổ lỗi cho khách hay không có biện pháp đều không thuyết phục."},{"distractors":[{"furigana":"はい、それでしたら、{15日|じゅうごにち}にすべての{機能|きのう}を{納品|のうひん}いたします。{18日|じゅうはちにち}まで{待|ま}つ{必要|ひつよう}はございません。","ja":"はい、それでしたら、15日にすべての機能を納品いたします。18日まで待つ必要はございません。","vi":"Vâng, vậy thì ngày 15 chúng tôi sẽ bàn giao toàn bộ chức năng. Không cần đợi tới ngày 18."},{"furigana":"はい、ログイン{機能|きのう}と{会員|かいいん}{管理|かんり}{機能|きのう}であれば、{15日|じゅうごにち}に{納品|のうひん}{可能|かのう}です。{残|のこ}りの{機能|きのう}は、{来月|らいげつ}{以降|いこう}に{納品|のうひん}いたします。","ja":"はい、ログイン機能と会員管理機能であれば、15日に納品可能です。残りの機能は、来月以降に納品いたします。","vi":"Vâng, nếu là chức năng đăng nhập và quản lý thành viên thì ngày 15 có thể bàn giao. Phần còn lại sẽ bàn giao từ tháng sau trở đi."}],"line":8,"why_vi":"Đưa ra phương án cụ thể: phần làm kịp bàn giao ngày 15, phần còn lại ngày 18 như đã xin; nói bàn giao hết ngày 15 thì mâu thuẫn với lý do xin lùi, còn đẩy sang tháng sau thì sai với ngày 18 đã đề nghị."},{"distractors":[{"furigana":"かしこまりました。では、{週|しゅう}に{一度|いちど}、{金曜日|きんようび}にまとめてご{報告|ほうこく}いたします。","ja":"かしこまりました。では、週に一度、金曜日にまとめてご報告いたします。","vi":"Vâng. Vậy mỗi tuần một lần, vào thứ Sáu tôi sẽ báo cáo gộp."},{"furigana":"かしこまりました。{修正|しゅうせい}が{全部|ぜんぶ}{終|お}わるまでは、ご{報告|ほうこく}を{控|ひか}えさせていただきます。","ja":"かしこまりました。修正が全部終わるまでは、ご報告を控えさせていただきます。","vi":"Vâng. Cho tới khi sửa xong hết, chúng tôi xin phép chưa báo cáo."}],"line":10,"why_vi":"Khách yêu cầu chia sẻ hằng ngày nên hẹn báo cáo mỗi chiều qua email; báo mỗi tuần một lần hay đợi sửa xong mới báo đều không đúng yêu cầu."}]}', 'cpath-brse-05', '80cfde997abf'),
  ('BRSE-08', 'PM', 3, 'N3', '会議の日程調整', 'Sắp xếp lịch họp', 'BrSE đề xuất lịch họp review, có tính tới chênh lệch múi giờ Nhật - Việt.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{来週|らいしゅう}、{要件|ようけん}{定義|ていぎ}のレビュー{会議|かいぎ}をします。{月曜|げつよう}の{朝|あさ}9{時|じ}に{来|き}てください。","ja":"来週、要件定義のレビュー会議をします。月曜の朝9時に来てください。","vi":"Tuần sau sẽ họp review định nghĩa yêu cầu. Anh hãy đến lúc 9 giờ sáng thứ Hai."},{"furigana":"{来週|らいしゅう}の{要件|ようけん}{定義|ていぎ}のレビュー{会議|かいぎ}は、{中止|ちゅうし}にさせていただきたいのですが。","ja":"来週の要件定義のレビュー会議は、中止にさせていただきたいのですが。","vi":"Tôi muốn xin hủy buổi họp review định nghĩa yêu cầu tuần sau."}],"line":1,"why_vi":"Muốn xin lịch họp thì nêu mục đích và hỏi lịch của khách (ご都合はいかがでしょうか); tự ấn định giờ bắt khách đến là thất lễ, còn xin hủy họp thì trái với tình huống."},{"distractors":[{"furigana":"ありがとうございます。では、{水曜日|すいようび}の14{時|じ}からはいかがでしょうか。1{時間|じかん}ほどを{予定|よてい}しております。","ja":"ありがとうございます。では、水曜日の14時からはいかがでしょうか。1時間ほどを予定しております。","vi":"Cảm ơn anh. Vậy từ 14 giờ thứ Tư có được không ạ? Dự kiến khoảng 1 tiếng."},{"furigana":"ありがとうございます。では、{火曜日|かようび}の{午前|ごぜん}10{時|じ}からはいかがでしょうか。1{時間|じかん}ほどを{予定|よてい}しております。","ja":"ありがとうございます。では、火曜日の午前10時からはいかがでしょうか。1時間ほどを予定しております。","vi":"Cảm ơn anh. Vậy từ 10 giờ sáng thứ Ba có được không ạ? Dự kiến khoảng 1 tiếng."}],"line":3,"why_vi":"Khách chỉ rảnh chiều thứ Ba và chiều thứ Năm, nên đề xuất 15 giờ thứ Năm là hợp; thứ Tư không có trong lịch khách, còn 10 giờ sáng thứ Ba thì không phải buổi chiều."},{"distractors":[{"furigana":"{日本|にほん}{時間|じかん}の15{時|じ}ですと、ベトナムは17{時|じ}になりますので、{開発|かいはつ}チームも{参加|さんか}できます。","ja":"日本時間の15時ですと、ベトナムは17時になりますので、開発チームも参加できます。","vi":"15 giờ giờ Nhật là 17 giờ ở Việt Nam, nên đội phát triển cũng tham gia được."},{"furigana":"{日本|にほん}{時間|じかん}の15{時|じ}ですと、ベトナムも{同|おな}じ15{時|じ}ですので、{開発|かいはつ}チームも{参加|さんか}できます。","ja":"日本時間の15時ですと、ベトナムも同じ15時ですので、開発チームも参加できます。","vi":"15 giờ giờ Nhật thì ở Việt Nam cũng là 15 giờ, nên đội phát triển cũng tham gia được."}],"line":5,"why_vi":"Giờ Việt Nam chậm hơn giờ Nhật 2 tiếng nên 15 giờ Nhật là 13 giờ Việt Nam, đội phát triển dự được; \'17 giờ\' hay \'cũng là 15 giờ\' đều tính sai múi giờ."},{"distractors":[{"furigana":"{後|のち}ほど、{火曜日|かようび}の{会議|かいぎ}のURLと{資料|しりょう}をお{送|おく}りいたします。","ja":"後ほど、火曜日の会議のURLと資料をお送りいたします。","vi":"Lát nữa tôi sẽ gửi anh link và tài liệu cho cuộc họp thứ Ba."},{"furigana":"では、{会議|かいぎ}のURLと{資料|しりょう}は、{田中|たなか}{様|さま}のほうでご{準備|じゅんび}いただけますでしょうか。","ja":"では、会議のURLと資料は、田中様のほうでご準備いただけますでしょうか。","vi":"Vậy anh Tanaka có thể chuẩn bị giúp link họp và tài liệu được không ạ?"}],"line":6,"why_vi":"Chốt lịch xong thì hẹn gửi link họp và tài liệu; \'thứ Ba\' sai với lịch thứ Năm vừa chốt, còn nhờ khách tự chuẩn bị link họp và tài liệu thì sai vai, vì chính BrSE là người xin lịch họp."},{"distractors":[{"furigana":"かしこまりました。{会議|かいぎ}が{終|お}わってからお{送|おく}りいたします。","ja":"かしこまりました。会議が終わってからお送りいたします。","vi":"Vâng. Họp xong tôi sẽ gửi anh."},{"furigana":"{申|もう}し{訳|わけ}ございません。{資料|しりょう}は{当日|とうじつ}までお{見|み}せできません。","ja":"申し訳ございません。資料は当日までお見せできません。","vi":"Xin lỗi anh, tài liệu thì phải đến hôm họp mới cho anh xem được."}],"line":8,"why_vi":"Khách muốn nhận tài liệu trước nên BrSE nhận lời và hẹn gửi trước một ngày; gửi sau buổi họp hay từ chối cho xem trước đều không đáp ứng yêu cầu."}]}', 'cpath-brse-08', '80cfde997abf'),
  ('BRSE-10', 'PM', 4, 'N2', '会議のまとめ', 'Chốt nội dung cuối buổi họp', 'Cuối buổi họp, BrSE nhắc lại các quyết định và hẹn gửi biên bản.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"まず、{本日|ほんじつ}の{会議|かいぎ}の{目的|もくてき}をご{説明|せつめい}いたします。","ja":"まず、本日の会議の目的をご説明いたします。","vi":"Trước tiên, tôi xin giải thích mục đích của cuộc họp hôm nay."},{"furigana":"{最後|さいご}に、{本日|ほんじつ}は{何|なに}も{決|き}まらなかったので、{確認|かくにん}することはございません。","ja":"最後に、本日は何も決まらなかったので、確認することはございません。","vi":"Cuối cùng, hôm nay không quyết định được gì nên không có gì cần xác nhận."}],"line":1,"why_vi":"Cuối buổi họp, BrSE chủ động xác nhận lại các nội dung đã quyết định; giải thích mục đích họp là việc của đầu buổi, còn nói \'không quyết định gì\' thì trái với tình huống."},{"distractors":[{"furigana":"{一点目|いってんめ}、アカウントのロックは30{分|ぷん}{後|ご}に{自動|じどう}で{解除|かいじょ}しますか。{二点目|にてんめ}、CSV{出力|しゅつりょく}{機能|きのう}の{見積|みつ}もりは、どなたが{提出|ていしゅつ}しますか。","ja":"一点目、アカウントのロックは30分後に自動で解除しますか。二点目、CSV出力機能の見積もりは、どなたが提出しますか。","vi":"Thứ nhất, tài khoản bị khóa có tự mở sau 30 phút không? Thứ hai, ai sẽ gửi bản ước tính chức năng xuất CSV?"},{"furigana":"{本日|ほんじつ}の{決定|けってい}{事項|じこう}は、{資料|しりょう}に{書|か}いてありますので、{各自|かくじ}でお{読|よ}みください。","ja":"本日の決定事項は、資料に書いてありますので、各自でお読みください。","vi":"Các nội dung quyết định hôm nay đã ghi trong tài liệu, mọi người tự đọc nhé."}],"line":2,"why_vi":"Xác nhận là nêu từng điểm đã chốt kèm ai làm, khi nào (thứ nhất…, thứ hai…); đặt câu hỏi như thể chưa quyết, hay bảo mọi người tự đọc tài liệu, đều không phải là xác nhận lại."},{"distractors":[{"furigana":"{議事録|ぎじろく}は{作成|さくせい}いたしませんので、{各自|かくじ}でメモをお{願|ねが}いいたします。","ja":"議事録は作成いたしませんので、各自でメモをお願いいたします。","vi":"Chúng tôi sẽ không soạn biên bản, xin mọi người tự ghi chép."},{"furigana":"{議事録|ぎじろく}は{来月|らいげつ}の{会議|かいぎ}のときにお{見|み}せいたします。","ja":"議事録は来月の会議のときにお見せいたします。","vi":"Biên bản họp thì đến buổi họp tháng sau tôi sẽ cho anh xem."}],"line":4,"why_vi":"Chốt xong thì hẹn soạn và chia sẻ biên bản ngay trong hôm nay, mời khách chỉ ra nếu có sai lệch; không soạn biên bản hay đợi tới tháng sau đều không phù hợp."},{"distractors":[{"furigana":"{本日|ほんじつ}はお{忙|いそが}しいところ、お{時間|じかん}をいただきありがとうございます。では、{会議|かいぎ}を{始|はじ}めます。","ja":"本日はお忙しいところ、お時間をいただきありがとうございます。では、会議を始めます。","vi":"Cảm ơn anh hôm nay đã dành thời gian dù bận. Vậy chúng ta bắt đầu cuộc họp."},{"furigana":"お{疲|つか}れ。{今日|きょう}はこれで{終|お}わりね。","ja":"お疲れ。今日はこれで終わりね。","vi":"Vất vả rồi. Hôm nay đến đây là xong nhé."}],"line":6,"why_vi":"Kết thúc họp với khách thì cảm ơn đã dành thời gian bằng thể quá khứ lịch sự (ありがとうございました); câu \'bắt đầu họp\' sai thời điểm, còn お疲れ。…ね là thân mật, không dùng với khách."}]}', 'cpath-brse-10', '80cfde997abf'),
  ('BRSE-01', 'COM', 1, 'N3', '初対面の挨拶', 'Chào hỏi lần đầu gặp khách hàng', 'Buổi kick-off dự án, BrSE lần đầu gặp khách hàng và trao danh thiếp.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"お{久|ひさ}しぶりです。VJソリューションズのグエンです。{前回|ぜんかい}は{大変|たいへん}お{世話|せわ}になりました。","ja":"お久しぶりです。VJソリューションズのグエンです。前回は大変お世話になりました。","vi":"Lâu rồi không gặp anh. Tôi là Nguyễn của VJ Solutions. Lần trước anh đã giúp đỡ tôi rất nhiều."},{"furigana":"やあ、グエンだよ。このプロジェクトでブリッジSEをやるから、よろしくね。","ja":"やあ、グエンだよ。このプロジェクトでブリッジSEをやるから、よろしくね。","vi":"Chào, mình là Nguyễn đây. Mình sẽ làm BrSE cho dự án này, nhờ cậy nhé."}],"line":1,"why_vi":"Lần đầu gặp khách nên mở đầu bằng 初めまして và tự giới thiệu khiêm nhường (と申します・いたします); câu \'lâu rồi không gặp\' sai tình huống, còn nói trống không thì thất lễ với khách."},{"distractors":[{"furigana":"こちら、{私|わたし}の{名刺|めいし}です。では、これで{失礼|しつれい}いたします。","ja":"こちら、私の名刺です。では、これで失礼いたします。","vi":"Đây là danh thiếp của tôi. Vậy tôi xin phép về trước."},{"furigana":"ご{丁寧|ていねい}にありがとうございます。こちらこそよろしくお{願|ねが}いします。","ja":"ご丁寧にありがとうございます。こちらこそよろしくお願いします。","vi":"Cảm ơn anh đã chu đáo. Tôi cũng mong được hợp tác."}],"line":2,"why_vi":"Tự giới thiệu xong thì trao danh thiếp và nói よろしくお願いいたします; cảm ơn \'sự chu đáo\' là câu của người nhận danh thiếp, còn xin về ngay thì vô lý khi buổi kick-off mới bắt đầu."},{"distractors":[{"furigana":"はい、{日本語|にほんご}がとても{上手|じょうず}です。{毎日|まいにち}{日本人|にほんじん}と{話|はな}していますから。","ja":"はい、日本語がとても上手です。毎日日本人と話していますから。","vi":"Vâng, tiếng Nhật của tôi rất giỏi. Vì ngày nào tôi cũng nói chuyện với người Nhật."},{"furigana":"{田中|たなか}{様|さま}は{日本|にほん}のどちらのご{出身|しゅっしん}ですか。ミライテックの{本社|ほんしゃ}は{東京|とうきょう}でしょうか。","ja":"田中様は日本のどちらのご出身ですか。ミライテックの本社は東京でしょうか。","vi":"Anh Tanaka quê ở vùng nào của Nhật ạ? Trụ sở Miraitech ở Tokyo phải không ạ?"}],"line":5,"why_vi":"Được khen thì đáp khiêm tốn (まだまだ勉強中です) rồi kể kinh nghiệm làm với khách Nhật; tự khen mình giỏi là thiếu khiêm tốn, còn hỏi ngược lại khách là né câu hỏi."},{"distractors":[{"furigana":"はい、ダナンにございます。ただ、{私|わたし}はこのプロジェクトには{参加|さんか}いたしません。","ja":"はい、ダナンにございます。ただ、私はこのプロジェクトには参加いたしません。","vi":"Vâng, ở Đà Nẵng ạ. Tuy nhiên tôi sẽ không tham gia dự án này."},{"furigana":"はい、ダナンにあるそうです。{詳|くわ}しいことは{私|わたし}もよく{知|し}りません。","ja":"はい、ダナンにあるそうです。詳しいことは私もよく知りません。","vi":"Vâng, nghe nói là ở Đà Nẵng. Chi tiết thì tôi cũng không rõ lắm."}],"line":7,"why_vi":"BrSE xác nhận đội ở Đà Nẵng và nhận vai trò đầu mối, khớp với câu tiếp theo của khách; nói \'nghe nói\' hay \'không tham gia dự án\' mâu thuẫn với việc vừa tự giới thiệu là BrSE phụ trách."},{"distractors":[{"furigana":"いいえ、ご{連絡|れんらく}は{開発|かいはつ}チームに{直接|ちょくせつ}お{願|ねが}いいたします。","ja":"いいえ、ご連絡は開発チームに直接お願いいたします。","vi":"Không, xin anh liên lạc trực tiếp với đội phát triển."},{"furigana":"はい。ただ、{連絡|れんらく}は{月|つき}に{一回|いっかい}だけにしていただけますか。","ja":"はい。ただ、連絡は月に一回だけにしていただけますか。","vi":"Vâng. Nhưng anh có thể chỉ liên lạc mỗi tháng một lần được không?"}],"line":9,"why_vi":"Khách xác nhận sẽ liên lạc qua Nguyễn nên BrSE đồng ý và mời liên hệ bất cứ lúc nào; đẩy sang đội phát triển hay giới hạn mỗi tháng một lần đi ngược vai trò đầu mối vừa nhận."}]}', 'cpath-brse-01', '80cfde997abf'),
  ('BRSE-02', 'COM', 2, 'N2', '電話の取り次ぎ', 'Nghe điện thoại khi người được tìm vắng mặt', 'Khách hàng gọi tìm PM nhưng PM đang họp, BrSE nhận lời nhắn.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"もしもし、ミライテックの{田中|たなか}{様|さま}でいらっしゃいますか。グエンです。","ja":"もしもし、ミライテックの田中様でいらっしゃいますか。グエンです。","vi":"Alô, có phải anh Tanaka của Miraitech không ạ? Tôi là Nguyễn."},{"furigana":"はい、VJソリューションズです。ファムはただいま{会議中|かいぎちゅう}でございます。","ja":"はい、VJソリューションズです。ファムはただいま会議中でございます。","vi":"Vâng, VJ Solutions đây ạ. Anh Phạm hiện đang họp."}],"line":1,"why_vi":"Nhận cuộc gọi công việc thì cảm ơn trước rồi xưng tên công ty và tên mình bằng でございます; hỏi \'có phải anh Tanaka không\' là câu của người gọi, còn chưa biết ai gọi, gọi tìm ai mà đã báo PM đang họp thì vô lý."},{"distractors":[{"furigana":"{初|はじ}めまして。どちらの{会社|かいしゃ}の{方|かた}でしょうか。","ja":"初めまして。どちらの会社の方でしょうか。","vi":"Rất hân hạnh được làm quen với anh. Anh là người của công ty nào ạ?"},{"furigana":"いえいえ、お{世話|せわ}なんてしておりませんよ。","ja":"いえいえ、お世話なんてしておりませんよ。","vi":"Không không, tôi có giúp đỡ gì anh đâu ạ."}],"line":3,"why_vi":"いつもお世話になっております là câu chào cố định trong công việc, đáp lại bằng こちらこそ… là chuẩn; chào \'lần đầu\' khi khách vừa xưng công ty, hay phủ nhận theo nghĩa đen, đều sai."},{"distractors":[{"furigana":"はい、ファムさんはいらっしゃいます。ただいまお{呼|よ}びしますので、{少々|しょうしょう}お{待|ま}ちください。","ja":"はい、ファムさんはいらっしゃいます。ただいまお呼びしますので、少々お待ちください。","vi":"Vâng, anh Phạm có ở đây ạ. Tôi gọi anh ấy ngay, xin anh chờ một chút."},{"furigana":"{申|もう}し{訳|わけ}ございません。ファムは{先月|せんげつ}、{退職|たいしょく}いたしました。","ja":"申し訳ございません。ファムは先月、退職いたしました。","vi":"Thành thật xin lỗi, anh Phạm đã nghỉ việc từ tháng trước."}],"line":5,"why_vi":"PM đang họp nên báo vắng mặt kèm giờ dự kiến xong; với khách bên ngoài phải gọi đồng nghiệp mình không kính ngữ (ファム, không phải ファムさんはいらっしゃいます), và không được nói sai tình trạng của PM."},{"distractors":[{"furigana":"ファムの{会議|かいぎ}は{何時|なんじ}に{終|お}わるか、ご{存|ぞん}じですか。","ja":"ファムの会議は何時に終わるか、ご存じですか。","vi":"Anh có biết cuộc họp của anh Phạm mấy giờ kết thúc không?"},{"furigana":"それでは、ファムの{会議|かいぎ}が{終|お}わるまで、お{電話|でんわ}はご{遠慮|えんりょ}いただけますか。","ja":"それでは、ファムの会議が終わるまで、お電話はご遠慮いただけますか。","vi":"Vậy xin anh đừng gọi điện cho tới khi cuộc họp của anh Phạm kết thúc."}],"line":6,"why_vi":"Người được tìm vắng thì chủ động đề nghị nhắn họ gọi lại (折り返し…申し伝えましょうか); hỏi khách giờ họp xong là vô lý vì mình vừa nói 11 giờ, còn bảo khách đừng gọi thì thất lễ."},{"distractors":[{"furigana":"かしこまりました。{来週|らいしゅう}のリリースの{件|けん}ですね。{念|ねん}のため、お{電話|でんわ}{番号|ばんごう}をお{伺|うかが}いしてもよろしいでしょうか。","ja":"かしこまりました。来週のリリースの件ですね。念のため、お電話番号をお伺いしてもよろしいでしょうか。","vi":"Tôi hiểu rồi. Về đợt release tuần sau ạ. Để chắc chắn, cho tôi xin số điện thoại của anh được không?"},{"furigana":"かしこまりました。{来週|らいしゅう}の{会議|かいぎ}の{件|けん}ですね。お{急|いそ}ぎではないようですので、ファムには{後日|ごじつ}メールで{伝|つた}えておきます。","ja":"かしこまりました。来週の会議の件ですね。お急ぎではないようですので、ファムには後日メールで伝えておきます。","vi":"Tôi hiểu rồi. Về cuộc họp tuần sau ạ. Có vẻ anh không gấp nên hôm khác tôi sẽ nhắn anh Phạm qua email."}],"line":8,"why_vi":"Nhắc lại đúng nội dung lời nhắn (release ngày mai) rồi xin số điện thoại để PM gọi lại; nghe nhầm thành \'tuần sau\' hay \'cuộc họp\', hoặc để hôm khác mới nhắn, đều sai với điều khách vừa nhờ."},{"distractors":[{"furigana":"03-1243-5678ですね。かしこまりました。{会議|かいぎ}が{終|お}わり{次第|しだい}、ファムから{折|お}り{返|かえ}しお{電話|でんわ}いたします。","ja":"03-1243-5678ですね。かしこまりました。会議が終わり次第、ファムから折り返しお電話いたします。","vi":"Số 03-1243-5678 ạ. Tôi hiểu rồi. Họp xong anh Phạm sẽ gọi lại cho anh ngay."},{"furigana":"03-1234-5678ですね。では、{田中|たなか}{様|さま}のほうからもう{一度|いちど}ファムにお{電話|でんわ}ください。","ja":"03-1234-5678ですね。では、田中様のほうからもう一度ファムにお電話ください。","vi":"Số 03-1234-5678 ạ. Vậy xin anh Tanaka gọi lại cho anh Phạm thêm lần nữa."}],"line":10,"why_vi":"Đọc lại chính xác số điện thoại (03-1234-5678) và tên khách, cho biết mình là người nhận lời nhắn; đọc sai số (1243) thì PM không gọi lại được, còn bắt khách tự gọi lại thì trái với đề nghị gọi lại vừa đưa ra."},{"distractors":[{"furigana":"お{待|ま}たせいたしました。","ja":"お待たせいたしました。","vi":"Xin lỗi đã để anh phải chờ."},{"furigana":"かしこまりました。{少々|しょうしょう}お{待|ま}ちください。","ja":"かしこまりました。少々お待ちください。","vi":"Vâng, xin anh chờ một chút."}],"line":12,"why_vi":"Kết thúc cuộc gọi công việc dùng 失礼いたします; \'xin lỗi đã để chờ\' hay \'xin chờ một chút\' là câu dùng giữa cuộc gọi, không phải câu chào trước khi cúp máy."}]}', 'cpath-brse-02', '80cfde997abf'),
  ('BRSE-09', 'COM', 3, 'N3', 'お客様への依頼', 'Nhờ khách hàng hỗ trợ', 'Sắp tới test tích hợp nhưng khách chưa cấp tài khoản test, BrSE nhờ khách chuẩn bị.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{田中|たなか}{様|さま}、{先日|せんじつ}はテスト{用|よう}のアカウントを{発行|はっこう}していただき、ありがとうございました。","ja":"田中様、先日はテスト用のアカウントを発行していただき、ありがとうございました。","vi":"Anh Tanaka, cảm ơn anh hôm trước đã cấp tài khoản test cho chúng tôi."},{"furigana":"{田中|たなか}{様|さま}、{何|なに}かお{困|こま}りのことはございますか。","ja":"田中様、何かお困りのことはございますか。","vi":"Anh Tanaka, anh có đang gặp khó khăn gì không ạ?"}],"line":1,"why_vi":"BrSE cần nhờ khách nên mở lời bằng 一つお願いがあるのですが; cảm ơn vì đã cấp tài khoản test là sai vì khách chưa cấp, còn hỏi khách có khó khăn gì thì không phải là lời nhờ."},{"distractors":[{"furigana":"{来週|らいしゅう}から{結合|けつごう}テストを{始|はじ}める{予定|よてい}です。テスト{用|よう}のアカウントはすでに{十分|じゅうぶん}にございますので、ご{安心|あんしん}ください。","ja":"来週から結合テストを始める予定です。テスト用のアカウントはすでに十分にございますので、ご安心ください。","vi":"Tuần sau chúng tôi dự định bắt đầu test tích hợp. Tài khoản test thì đã có đủ rồi, anh cứ yên tâm ạ."},{"furigana":"{結合|けつごう}テストは{先月|せんげつ}すべて{終|お}わりました。{何|なに}かご{質問|しつもん}はございますか。","ja":"結合テストは先月すべて終わりました。何かご質問はございますか。","vi":"Test tích hợp đã xong toàn bộ từ tháng trước. Anh có câu hỏi gì không ạ?"}],"line":3,"why_vi":"Trình bày bối cảnh của lời nhờ: tuần sau test tích hợp mà chưa có tài khoản test; nói tài khoản đã đủ hay test đã xong từ tháng trước thì mâu thuẫn với việc đang muốn nhờ."},{"distractors":[{"furigana":"お{忙|いそが}しいところ{恐縮|きょうしゅく}ですが、{来月末|らいげつまつ}までに5{名分|めいぶん}{発行|はっこう}していただくことは{可能|かのう}でしょうか。","ja":"お忙しいところ恐縮ですが、来月末までに5名分発行していただくことは可能でしょうか。","vi":"Biết anh đang bận, nhưng trước cuối tháng sau anh có thể cấp giúp 5 tài khoản được không ạ?"},{"furigana":"{今|いま}すぐアカウントを{作|つく}ってください。{今日中|きょうじゅう}じゃないと{困|こま}ります。","ja":"今すぐアカウントを作ってください。今日中じゃないと困ります。","vi":"Anh tạo tài khoản ngay đi. Không xong trong hôm nay thì tôi khó xử lắm."}],"line":4,"why_vi":"Lời nhờ lịch sự kèm hạn và số lượng cụ thể, trước khi test bắt đầu (trước thứ Sáu, 5 tài khoản); hạn cuối tháng sau thì quá muộn so với test tuần sau, còn ra lệnh gấp gáp thì thất lễ với khách."},{"distractors":[{"furigana":"{忘|わす}れていたんですか。{困|こま}りますね、{次|つぎ}は{気|き}をつけてください。","ja":"忘れていたんですか。困りますね、次は気をつけてください。","vi":"Anh quên à? Phiền quá, lần sau anh chú ý giùm nhé."},{"furigana":"いえ、{急|いそ}ぎませんので、{来月|らいげつ}でも{大丈夫|だいじょうぶ}です。","ja":"いえ、急ぎませんので、来月でも大丈夫です。","vi":"Không, không gấp đâu, tháng sau cũng được ạ."}],"line":6,"why_vi":"Khách nhận làm trong hôm nay nên cảm ơn và nói お手数をおかけしますが…; trách khách quên là thất lễ, còn bảo \'tháng sau cũng được\' mâu thuẫn với hạn thứ Sáu vừa nhờ."}]}', 'cpath-brse-09', '80cfde997abf'),
  ('BRSE-03', 'REQ', 1, 'N2', '仕様の確認', 'Xác nhận điểm chưa rõ trong đặc tả', 'BrSE phát hiện tài liệu đặc tả thiếu thông tin và hỏi lại khách hàng.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{田中|たなか}{様|さま}、{仕様書|しようしょ}はすべて{確認|かくにん}いたしました。{特|とく}に{問題|もんだい}はございません。","ja":"田中様、仕様書はすべて確認いたしました。特に問題はございません。","vi":"Anh Tanaka, tôi đã kiểm tra toàn bộ đặc tả. Không có vấn đề gì đặc biệt ạ."},{"furigana":"{田中|たなか}さん、{仕様書|しようしょ}のことでちょっと{聞|き}きたいんだけど、{今|いま}いい？","ja":"田中さん、仕様書のことでちょっと聞きたいんだけど、今いい？","vi":"Anh Tanaka ơi, tôi muốn hỏi chút về đặc tả, giờ rảnh không?"}],"line":1,"why_vi":"BrSE phát hiện đặc tả thiếu nên xin phép khách bằng kính ngữ để hỏi (確認させていただきたいのですが…よろしいでしょうか); báo \'không có vấn đề\' trái với tình huống, còn nói kiểu thân mật (タメ口) với khách thì thất lễ."},{"distractors":[{"furigana":"{画面|がめん}{設計書|せっけいしょ}の3ページ{目|め}、ログイン{画面|がめん}についてです。パスワードを5{回|かい}{間違|まちが}えるとアカウントをロックする{件|けん}は、すでに{実装|じっそう}が{完了|かんりょう}しております。","ja":"画面設計書の3ページ目、ログイン画面についてです。パスワードを5回間違えるとアカウントをロックする件は、すでに実装が完了しております。","vi":"Về màn hình đăng nhập ở trang 3 tài liệu thiết kế màn hình. Phần khóa tài khoản khi nhập sai mật khẩu 5 lần thì chúng tôi đã triển khai xong rồi ạ."},{"furigana":"{画面|がめん}{設計書|せっけいしょ}がまだ{届|とど}いておりません。お{送|おく}りいただけますでしょうか。","ja":"画面設計書がまだ届いておりません。お送りいただけますでしょうか。","vi":"Tài liệu thiết kế màn hình vẫn chưa tới tay tôi. Anh có thể gửi giúp được không ạ?"}],"line":3,"why_vi":"Cần chỉ rõ vị trí (trang 3, màn hình đăng nhập) và điểm còn thiếu (cách mở khóa); báo đã làm xong thì không nêu được câu hỏi, còn nói chưa nhận tài liệu thì mâu thuẫn với việc vừa đọc đặc tả."},{"distractors":[{"furigana":"では、{解除|かいじょ}{方法|ほうほう}はこちらで{自由|じゆう}に{決|き}めて{実装|じっそう}いたしますので、{決|き}まった{内容|ないよう}のご{報告|ほうこく}は{特|とく}にいたしません。","ja":"では、解除方法はこちらで自由に決めて実装いたしますので、決まった内容のご報告は特にいたしません。","vi":"Vậy cách mở khóa chúng tôi sẽ tự quyết định rồi triển khai, quyết định thế nào thì chúng tôi cũng không báo lại."},{"furigana":"では、アカウントをロックするまでの{回数|かいすう}は{何回|なんかい}にすればよろしいでしょうか。","ja":"では、アカウントをロックするまでの回数は何回にすればよろしいでしょうか。","vi":"Vậy số lần nhập sai trước khi khóa tài khoản nên đặt là bao nhiêu lần ạ?"}],"line":5,"why_vi":"Khi đặc tả thiếu, BrSE đưa ra các phương án (tự động/thủ công) để khách chọn; tự quyết mà không báo lại thì bỏ qua bước xác nhận với khách, còn hỏi số lần nhập sai thì thừa vì tài liệu đã ghi 5 lần, điểm còn thiếu là cách mở khóa."},{"distractors":[{"furigana":"{承知|しょうち}いたしました。3{分|ぷん}{後|ご}の{自動|じどう}{解除|かいじょ}のみを{実装|じっそう}する、ということでよろしいでしょうか。","ja":"承知いたしました。3分後の自動解除のみを実装する、ということでよろしいでしょうか。","vi":"Tôi hiểu rồi. Vậy là chỉ triển khai tự động mở khóa sau 3 phút, đúng không ạ?"},{"furigana":"{承知|しょうち}いたしました。{管理者|かんりしゃ}による{解除|かいじょ}は{不要|ふよう}、ということでよろしいでしょうか。","ja":"承知いたしました。管理者による解除は不要、ということでよろしいでしょうか。","vi":"Tôi hiểu rồi. Vậy là không cần chức năng quản trị viên mở khóa, đúng không ạ?"}],"line":7,"why_vi":"Nhắc lại chính xác cả hai yêu cầu (tự mở sau 30 phút + quản trị viên mở thủ công) để chốt; \'3 phút, chỉ tự động\' hay \'không cần quản trị viên\' đều tóm tắt sai lời khách."},{"distractors":[{"furigana":"ありがとうございます。では、{今回|こんかい}の{内容|ないよう}はもう{確認|かくにん}できましたので、{記録|きろく}は{特|とく}に{残|のこ}さずに{進|すす}めます。","ja":"ありがとうございます。では、今回の内容はもう確認できましたので、記録は特に残さずに進めます。","vi":"Cảm ơn anh. Nội dung lần này đã xác nhận xong rồi, nên chúng tôi sẽ tiến hành mà không cần ghi lại gì."},{"furigana":"{申|もう}し{訳|わけ}ございません。もう{一度|いちど}{最初|さいしょ}からご{説明|せつめい}いただけますか。","ja":"申し訳ございません。もう一度最初からご説明いただけますか。","vi":"Xin lỗi anh, anh có thể giải thích lại từ đầu được không?"}],"line":9,"why_vi":"Chốt xong thì cảm ơn và ghi vào bảng Q&A gửi khách để tránh hiểu sai; bảo không ghi lại hay xin giải thích lại từ đầu đều đi ngược việc vừa xác nhận xong."}]}', 'cpath-brse-03', '80cfde997abf'),
  ('BRSE-07', 'REQ', 2, 'N2', '仕様変更の依頼への対応', 'Xử lý yêu cầu thay đổi đặc tả', 'Khách hàng muốn thêm chức năng ngoài phạm vi, BrSE làm rõ yêu cầu và đề nghị ước tính công số.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"PDF{出力|しゅつりょく}{機能|きのう}の{追加|ついか}ですね。{対象|たいしょう}となる{画面|がめん}を{教|おし}えていただけますか。","ja":"PDF出力機能の追加ですね。対象となる画面を教えていただけますか。","vi":"Thêm chức năng xuất PDF ạ. Anh cho tôi biết màn hình cần xuất được không?"},{"furigana":"CSV{出力|しゅつりょく}{機能|きのう}の{追加|ついか}ですね。{承知|しょうち}いたしました。{追加|ついか}{費用|ひよう}なしで、{本日中|ほんじつちゅう}に{対応|たいおう}いたします。","ja":"CSV出力機能の追加ですね。承知いたしました。追加費用なしで、本日中に対応いたします。","vi":"Thêm chức năng xuất CSV ạ. Tôi hiểu rồi. Chúng tôi sẽ làm xong trong hôm nay mà không tính thêm chi phí."}],"line":2,"why_vi":"Nhận yêu cầu thay đổi thì nhắc lại đúng (xuất CSV) và hỏi rõ màn hình, trường dữ liệu; nhầm thành PDF, hay hứa làm xong trong hôm nay mà không tính thêm phí khi chưa rõ phạm vi, đều sai."},{"distractors":[{"furigana":"{承知|しょうち}いたしました。{現在|げんざい}の{開発|かいはつ}{範囲内|はんいない}の{作業|さぎょう}となりますので、{追加|ついか}の{見積|みつ}もりは{不要|ふよう}です。このまま{今回|こんかい}のリリースに{含|ふく}めます。","ja":"承知いたしました。現在の開発範囲内の作業となりますので、追加の見積もりは不要です。このまま今回のリリースに含めます。","vi":"Tôi hiểu rồi. Đây là công việc trong phạm vi phát triển hiện tại nên không cần ước tính thêm. Chúng tôi sẽ đưa luôn vào đợt release lần này."},{"furigana":"{申|もう}し{訳|わけ}ございませんが、{現在|げんざい}の{開発|かいはつ}{範囲外|はんいがい}の{作業|さぎょう}となりますので、{今回|こんかい}のご{依頼|いらい}は{一切|いっさい}お{受|う}けできません。","ja":"申し訳ございませんが、現在の開発範囲外の作業となりますので、今回のご依頼は一切お受けできません。","vi":"Thành thật xin lỗi, đây là công việc ngoài phạm vi phát triển hiện tại nên chúng tôi tuyệt đối không nhận yêu cầu lần này."}],"line":4,"why_vi":"Yêu cầu nằm ngoài phạm vi nên BrSE nói rõ điều đó và xin ước tính công số, ảnh hưởng lịch trình; coi là trong phạm vi thì sai sự thật, còn từ chối thẳng thì cứng nhắc với khách."},{"distractors":[{"furigana":"おそらく{半日|はんにち}ほどで{終|お}わると{思|おも}いますので、{見積|みつ}もりは{省略|しょうりゃく}して{本日|ほんじつ}から{着手|ちゃくしゅ}させていただきます。リリースにもそのまま{含|ふく}めます。","ja":"おそらく半日ほどで終わると思いますので、見積もりは省略して本日から着手させていただきます。リリースにもそのまま含めます。","vi":"Chắc khoảng nửa ngày là xong, nên chúng tôi xin bỏ qua bước ước tính và bắt tay vào làm từ hôm nay. Sẽ đưa luôn vào đợt release."},{"furigana":"{見積|みつ}もりは、{田中|たなか}{様|さま}のほうで{作成|さくせい}していただけますでしょうか。{弊社|へいしゃ}では{工数|こうすう}を{出|だ}すのが{難|むずか}しいので。","ja":"見積もりは、田中様のほうで作成していただけますでしょうか。弊社では工数を出すのが難しいので。","vi":"Bản ước tính thì anh Tanaka có thể soạn giúp được không ạ? Vì bên chúng tôi khó tính được công số."}],"line":6,"why_vi":"Chưa thể trả lời ngay nên hẹn trao đổi với đội và gửi ước tính trong ngày mai, kèm bàn việc đưa vào đợt release nào; đoán bừa \'nửa ngày\' rồi tự ý làm luôn, hay bắt khách tự ước tính công số, đều sai."}]}', 'cpath-brse-07', '80cfde997abf'),
  ('BRSE-15', 'REQ', 3, 'N2', '要件の確認', 'Xác nhận yêu cầu', 'Họp với khách hàng Nhật để làm rõ yêu cầu mới.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{見積|みつ}もりはいくらですか。","ja":"見積もりはいくらですか。","vi":"Báo giá bao nhiêu ạ?"},{"furigana":"{障害|しょうがい}が{発生|はっせい}しました。","ja":"障害が発生しました。","vi":"Đã xảy ra sự cố ạ."}],"line":1,"why_vi":"Muốn trao đổi yêu cầu mới thì nói rõ chủ đề; hỏi giá hay báo lỗi đều sai việc."},{"distractors":[{"furigana":"{会議|かいぎ}は{何時|なんじ}からですか。","ja":"会議は何時からですか。","vi":"Cuộc họp bắt đầu lúc mấy giờ ạ?"},{"furigana":"オフィスは{広|ひろ}いですね。","ja":"オフィスは広いですね。","vi":"Văn phòng rộng thật nhỉ."}],"line":3,"why_vi":"Khách hỏi lại nội dung thì nêu câu hỏi cụ thể về độ ưu tiên; hỏi giờ họp hay khen văn phòng đều lạc đề."},{"distractors":[{"furigana":"{優先度|ゆうせんど}は{低|ひく}いですか。","ja":"優先度は低いですか。","vi":"Độ ưu tiên có thấp không ạ?"},{"furigana":"この{機能|きのう}は{対応|たいおう}できません。","ja":"この機能は対応できません。","vi":"Chức năng này tôi không làm được ạ."}],"line":5,"why_vi":"Biết tính năng được ưu tiên cao thì xin tài liệu đặc tả kèm hạn; hỏi lại độ ưu tiên hay từ chối nhận việc đều không phải bước tiếp theo."}]}', 'cpath-brse-15', '80cfde997abf'),
  ('BRSE-11', 'DEV', 1, 'N2', 'コードレビューの指摘対応', 'Tiếp nhận góp ý code review', 'Trưởng nhóm kỹ thuật phía khách hàng review pull request và góp ý, developer tiếp nhận và hẹn sửa.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{指摘|してき}は{必要|ひつよう}ありません。そのままマージしてください。","ja":"指摘は必要ありません。そのままマージしてください。","vi":"Không cần góp ý đâu. Anh cứ merge luôn đi."},{"furigana":"すみません、まだプルリクエストを{作成|さくせい}しておりません。","ja":"すみません、まだプルリクエストを作成しておりません。","vi":"Xin lỗi, tôi vẫn chưa tạo pull request."}],"line":2,"why_vi":"Khách đã review và có góp ý nên cảm ơn rồi mời khách nói tiếp; từ chối nghe góp ý là thiếu chuyên nghiệp, còn nói chưa tạo PR thì mâu thuẫn với việc khách vừa xem nó."},{"distractors":[{"furigana":"ご{指摘|してき}ありがとうございます。では、{例外|れいがい}が{発生|はっせい}したら{画面|がめん}にエラー{内容|ないよう}をそのまま{表示|ひょうじ}するよう{修正|しゅうせい}いたします。","ja":"ご指摘ありがとうございます。では、例外が発生したら画面にエラー内容をそのまま表示するよう修正いたします。","vi":"Cảm ơn anh đã chỉ ra. Vậy tôi sẽ sửa để khi phát sinh ngoại lệ thì hiển thị nguyên nội dung lỗi lên màn hình."},{"furigana":"ログは{出力|しゅつりょく}されていますよ。{田中|たなか}{様|さま}の{確認|かくにん}が{間違|まちが}っていると{思|おも}います。","ja":"ログは出力されていますよ。田中様の確認が間違っていると思います。","vi":"Log có được ghi ra mà. Tôi nghĩ anh Tanaka kiểm tra sai rồi."}],"line":4,"why_vi":"Nhận góp ý thì cảm ơn và nói rõ cách sửa (ghi log trong phần xử lý ngoại lệ); hiển thị nguyên lỗi lên màn hình không phải là ghi log (lại còn lộ thông tin), còn cãi rằng khách kiểm tra sai là thiếu thiện chí."},{"distractors":[{"furigana":"おっしゃるとおりです。では、ほかの{画面|がめん}にも{同|おな}じ{入力|にゅうりょく}チェックをコピーしておきます。","ja":"おっしゃるとおりです。では、ほかの画面にも同じ入力チェックをコピーしておきます。","vi":"Anh nói đúng ạ. Vậy tôi sẽ copy cùng đoạn kiểm tra đầu vào sang các màn hình khác nữa."},{"furigana":"おっしゃるとおりです。{共通|きょうつう}のバリデーションクラスを{作成|さくせい}します。ただ、{既存|きそん}の3{画面|がめん}はそのままにして、{今後|こんご}の{新|あたら}しい{画面|がめん}だけで{使|つか}います。","ja":"おっしゃるとおりです。共通のバリデーションクラスを作成します。ただ、既存の3画面はそのままにして、今後の新しい画面だけで使います。","vi":"Anh nói đúng ạ. Tôi sẽ tạo một class validation dùng chung. Nhưng 3 màn hình hiện có thì để nguyên, class đó chỉ dùng cho các màn hình mới sau này."}],"line":6,"why_vi":"Đồng ý gom phần kiểm tra đầu vào của cả 3 màn hình vào class validation dùng chung và chạy test hồi quy cho các màn hình cũ; copy thêm là ngược góp ý, còn tạo class chung mà để nguyên 3 màn hình thì đoạn trùng lặp vẫn còn."},{"distractors":[{"furigana":"{承知|しょうち}いたしました。{修正|しゅうせい}が{終|お}わったら、{再|さい}レビューなしでマージいたします。","ja":"承知いたしました。修正が終わったら、再レビューなしでマージいたします。","vi":"Vâng. Sửa xong tôi sẽ merge luôn mà không cần review lại."},{"furigana":"{承知|しょうち}いたしました。{修正|しゅうせい}は{来年|らいねん}のリリースのときにまとめて{行|おこな}います。","ja":"承知いたしました。修正は来年のリリースのときにまとめて行います。","vi":"Vâng. Việc sửa thì tôi sẽ gom lại làm một lượt vào đợt release năm sau."}],"line":8,"why_vi":"Khách dặn sửa xong thì xin review lại, nên hẹn sửa trong hôm nay và gửi yêu cầu re-review; merge không qua review hay hoãn tới năm sau đều trái với yêu cầu."}]}', 'cpath-brse-11', '80cfde997abf'),
  ('BRSE-16', 'DEV', 2, 'N2', '進捗報告', 'Báo cáo tiến độ', 'Báo cáo tiến độ phát triển cho PM.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{給料|きゅうりょう}はいつ{上|あ}がりますか。","ja":"給料はいつ上がりますか。","vi":"Khi nào tăng lương ạ?"},{"furigana":"バグを{報告|ほうこく}します。","ja":"バグを報告します。","vi":"Tôi báo cáo lỗi ạ."}],"line":1,"why_vi":"Muốn báo cáo tiến độ thì mở lời rõ ràng; hỏi lương hay báo lỗi đều sai việc."},{"distractors":[{"furigana":"まだ{何|なに}もしていません。","ja":"まだ何もしていません。","vi":"Tôi chưa làm gì cả ạ."},{"furigana":"ファムさんはどうですか。","ja":"ファムさんはどうですか。","vi":"Anh Phạm thì sao ạ?"}],"line":3,"why_vi":"PM mời báo cáo thì nêu việc đã hoàn thành; nói chưa bắt đầu hay hỏi ngược PM đều sai."},{"distractors":[{"furigana":"{明日|あした}、{休|やす}みたいです。","ja":"明日、休みたいです。","vi":"Ngày mai tôi muốn nghỉ ạ."},{"furigana":"{別|べつ}の{機能|きのう}を{作|つく}りたいです。","ja":"別の機能を作りたいです。","vi":"Tôi muốn làm chức năng khác ạ."}],"line":5,"why_vi":"PM hỏi việc tiếp theo thì nêu kế hoạch kết nối API; nói nghỉ phép hay đổi đề tài đều lạc nhịp."}]}', 'cpath-brse-16', '80cfde997abf'),
  ('BRSE-17', 'DEV', 3, 'N2', '開発環境を確認する', 'Xác nhận môi trường phát triển', 'Hỏi khách hàng về môi trường kết nối API.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"この{作業|さぎょう}はいくらですか。","ja":"この作業はいくらですか。","vi":"Việc này bao nhiêu tiền ạ?"},{"furigana":"{実装|じっそう}が{終|お}わりました。","ja":"実装が終わりました。","vi":"Đã xong phần lập trình ạ."}],"line":1,"why_vi":"Cần thông tin kết nối thì hỏi trực tiếp; hỏi giá hay báo tiến độ đều sai việc."},{"distractors":[{"furigana":"URLをもう{一度|いちど}{送|お}ってください。","ja":"URLをもう一度送ってください。","vi":"Gửi lại URL giúp tôi ạ."},{"furigana":"メールが{分|わ}かりやすいですね。","ja":"メールが分かりやすいですね。","vi":"Email dễ hiểu nhỉ."}],"line":3,"why_vi":"Đã có URL thì hỏi tiếp khóa xác thực; hỏi lại URL hay khen email đẹp đều lạc đề."}]}', 'cpath-brse-17', '80cfde997abf'),
  ('BRSE-12', 'TEST', 1, 'N2', 'テスト結果の報告', 'Báo cáo kết quả kiểm thử', 'Kết thúc đợt test tích hợp, BrSE báo cáo số liệu và kế hoạch xử lý các case không đạt.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{結合|けつごう}テストの{結果|けっか}を{教|おし}えていただけますか。","ja":"結合テストの結果を教えていただけますか。","vi":"Anh cho tôi biết kết quả test tích hợp được không?"},{"furigana":"{結合|けつごう}テストはこれから{始|はじ}める{予定|よてい}です。","ja":"結合テストはこれから始める予定です。","vi":"Test tích hợp thì dự kiến sắp bắt đầu."}],"line":1,"why_vi":"Đợt test tích hợp đã kết thúc và BrSE là người báo cáo, nên mở đầu bằng 結果をご報告いたします; hỏi khách kết quả hay nói test sắp bắt đầu đều sai với tình huống."},{"distractors":[{"furigana":"テストケース{全|ぜん}420{件|けん}のうち412{件|けん}を{消化|しょうか}し、{合格|ごうかく}は398{件|けん}、{不合格|ふごうかく}は24{件|けん}でした。","ja":"テストケース全420件のうち412件を消化し、合格は398件、不合格は24件でした。","vi":"Trong tổng số 420 test case, đã thực hiện 412 case, đạt 398 case và không đạt 24 case."},{"furigana":"テストケースの{数|かず}はまだ{数|かぞ}えておりませんが、だいたい{合格|ごうかく}しました。","ja":"テストケースの数はまだ数えておりませんが、だいたい合格しました。","vi":"Số test case thì chúng tôi chưa đếm, nhưng đại khái là đạt."}],"line":2,"why_vi":"Báo cáo cần số liệu khớp nhau: thực hiện 412/420, đạt 398 + không đạt 14 = 412, còn 8 case chưa chạy; 398 + 24 vượt quá 412 case đã chạy nên số liệu sai, còn báo \'đại khái là đạt\' thì không có số liệu."},{"distractors":[{"furigana":"{残|のこ}りの8{件|けん}は{外部|がいぶ}システムとの{接続|せつぞく}が{必要|ひつよう}なケースですが、{時間|じかん}がございませんので、{今回|こんかい}は{実施|じっし}しない{予定|よてい}です。","ja":"残りの8件は外部システムとの接続が必要なケースですが、時間がございませんので、今回は実施しない予定です。","vi":"8 case còn lại là các case cần kết nối với hệ thống bên ngoài, nhưng vì không có thời gian nên lần này chúng tôi định không thực hiện."},{"furigana":"{残|のこ}りの8{件|けん}は、すべて{不合格|ふごうかく}のケースでして、{修正|しゅうせい}の{予定|よてい}もまだ{立|た}っておりません。","ja":"残りの8件は、すべて不合格のケースでして、修正の予定もまだ立っておりません。","vi":"8 case còn lại đều là case không đạt, và vẫn chưa có kế hoạch sửa."}],"line":4,"why_vi":"8 case còn lại là case chưa chạy được vì cần môi trường của đối tác, nên giải thích lý do và khi nào sẽ chạy; bỏ không chạy vì hết thời gian là không chấp nhận được, còn gọi chúng là \'không đạt\' thì nhầm với 14 case kia."},{"distractors":[{"furigana":"{重大度|じゅうだいど}「{高|こう}」が2{件|けん}、「{中|ちゅう}」が5{件|けん}、「{低|てい}」が10{件|けん}です。「{高|こう}」の2{件|けん}は{明日|あした}までに{修正|しゅうせい}し、{再|さい}テストいたします。","ja":"重大度「高」が2件、「中」が5件、「低」が10件です。「高」の2件は明日までに修正し、再テストいたします。","vi":"Mức độ nghiêm trọng \'cao\' 2 case, \'trung bình\' 5 case, \'thấp\' 10 case. 2 case mức \'cao\' sẽ được sửa và test lại trước ngày mai."},{"furigana":"{重大度|じゅうだいど}「{高|こう}」が7{件|けん}、「{中|ちゅう}」が5{件|けん}、「{低|てい}」が2{件|けん}です。まず「{低|てい}」の2{件|けん}を{修正|しゅうせい}し、「{高|こう}」の7{件|けん}は{来月|らいげつ}に{対応|たいおう}いたします。","ja":"重大度「高」が7件、「中」が5件、「低」が2件です。まず「低」の2件を修正し、「高」の7件は来月に対応いたします。","vi":"Mức độ nghiêm trọng \'cao\' 7 case, \'trung bình\' 5 case, \'thấp\' 2 case. Trước tiên chúng tôi sửa 2 case mức \'thấp\', còn 7 case mức \'cao\' thì tháng sau mới xử lý."}],"line":6,"why_vi":"Chi tiết phải cộng đúng 14 (2 + 5 + 7) và ưu tiên sửa, test lại các lỗi mức \'cao\'; 2 + 5 + 10 không khớp với 14, còn sửa lỗi nhẹ trước rồi để lỗi mức \'cao\' sang tháng sau là sai thứ tự ưu tiên."},{"distractors":[{"furigana":"かしこまりました。ただ、エビデンスは{社内|しゃない}{資料|しりょう}ですので、お{送|おく}りできません。","ja":"かしこまりました。ただ、エビデンスは社内資料ですので、お送りできません。","vi":"Vâng. Nhưng bằng chứng test là tài liệu nội bộ nên chúng tôi không thể gửi anh."},{"furigana":"かしこまりました。{報告書|ほうこくしょ}だけ{先|さき}にお{送|おく}りし、エビデンスは{作成|さくせい}いたしません。","ja":"かしこまりました。報告書だけ先にお送りし、エビデンスは作成いたしません。","vi":"Vâng. Tôi sẽ gửi trước báo cáo, còn bằng chứng test thì sẽ không soạn."}],"line":8,"why_vi":"Khách yêu cầu gửi kèm bằng chứng nên BrSE hẹn gửi cả báo cáo lẫn evidence trong hôm nay; từ chối gửi hay bỏ phần evidence đều không đáp ứng yêu cầu."}]}', 'cpath-brse-12', '80cfde997abf'),
  ('BRSE-18', 'TEST', 2, 'N2', 'テスト結果の報告', 'Báo cáo kết quả kiểm thử', 'Báo cáo kết quả kiểm thử tích hợp cho PM.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{今日|きょう}は{早退|そうたい}できますか。","ja":"今日は早退できますか。","vi":"Hôm nay tôi về sớm được không ạ?"},{"furigana":"{単体|たんたい}テストを{始|はじ}めます。","ja":"単体テストを始めます。","vi":"Tôi bắt đầu kiểm thử đơn vị ạ."}],"line":1,"why_vi":"Muốn báo cáo kết quả test thì nói rõ chủ đề; hỏi nghỉ phép hay báo lỗi đều sai việc."},{"distractors":[{"furigana":"まだテストしていません。","ja":"まだテストしていません。","vi":"Tôi chưa chạy kiểm thử ạ."},{"furigana":"ファムさんはどう{思|おも}いますか。","ja":"ファムさんはどう思いますか。","vi":"Anh Phạm nghĩ sao ạ?"}],"line":3,"why_vi":"PM hỏi kết quả thì báo số ca đạt/không đạt; nói chưa chạy test hay hỏi ngược PM đều sai."},{"distractors":[{"furigana":"{二件|にけん}とも{無視|むし}しました。","ja":"二件とも無視しました。","vi":"Tôi bỏ qua cả hai ca ạ."},{"furigana":"{全部|ぜんぶ}{合格|ごうかく}でよかったです。","ja":"全部合格でよかったです。","vi":"May là tất cả đều đạt ạ."}],"line":5,"why_vi":"Được hỏi nguyên nhân thì báo trạng thái từng ca lỗi; nói bỏ qua hai ca hay khen kết quả đều không đúng."}]}', 'cpath-brse-18', '80cfde997abf'),
  ('BRSE-19', 'TEST', 3, 'N2', 'テストケースの確認', 'Xác nhận ca kiểm thử', 'Hỏi khách hàng xác nhận danh sách ca kiểm thử.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"テストケースは{完璧|かんぺき}です。","ja":"テストケースは完璧です。","vi":"Danh sách ca kiểm thử hoàn hảo rồi ạ."},{"furigana":"この{作業|さぎょう}の{費用|ひよう}はいくらですか。","ja":"この作業の費用はいくらですか。","vi":"Chi phí việc này bao nhiêu ạ?"}],"line":1,"why_vi":"Muốn khách rà soát thì nhờ xác nhận danh sách; tự khen danh sách đầy đủ hay hỏi giá đều sai việc."},{"distractors":[{"furigana":"いつまでに{返事|へんじ}をくれますか。","ja":"いつまでに返事をくれますか。","vi":"Bao giờ anh trả lời ạ?"},{"furigana":"{確認|かくにん}が{速|はや}いですね。","ja":"確認が速いですね。","vi":"Anh xác nhận nhanh nhỉ."}],"line":3,"why_vi":"Khách nhận lời xem thì hỏi còn thiếu hạng mục nào không; hỏi giờ trả kết quả hay khen khách nhanh đều lạc đề."}]}', 'cpath-brse-19', '80cfde997abf'),
  ('BRSE-06', 'BUG', 1, 'N2', '不具合の問い合わせ対応', 'Tiếp nhận báo lỗi từ khách hàng', 'Khách hàng phát hiện lỗi trên môi trường staging, BrSE hỏi bước tái hiện và hẹn thời gian phản hồi.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"そうですか。こちらの{環境|かんきょう}では{問題|もんだい}ないので、{田中|たなか}{様|さま}のパソコンの{問題|もんだい}だと{思|おも}います。","ja":"そうですか。こちらの環境では問題ないので、田中様のパソコンの問題だと思います。","vi":"Vậy à. Môi trường bên tôi không có vấn đề nên tôi nghĩ là do máy tính của anh Tanaka."},{"furigana":"ご{報告|ほうこく}ありがとうございます。では、{本番|ほんばん}{環境|かんきょう}にそのままリリースしてもよろしいでしょうか。","ja":"ご報告ありがとうございます。では、本番環境にそのままリリースしてもよろしいでしょうか。","vi":"Cảm ơn anh đã báo. Vậy chúng tôi release nguyên như vậy lên production có được không ạ?"}],"line":2,"why_vi":"Nhận báo lỗi thì cảm ơn rồi hỏi các bước tái hiện để điều tra; đổ cho máy của khách khi chưa kiểm tra hay đòi release luôn khi đang có lỗi đều sai."},{"distractors":[{"furigana":"{長音|ちょうおん}を{含|ふく}まない{場合|ばあい}ですね。では、{長音|ちょうおん}を{含|ふく}むキーワードは{問題|もんだい}ないということでしょうか。","ja":"長音を含まない場合ですね。では、長音を含むキーワードは問題ないということでしょうか。","vi":"Trường hợp không chứa trường âm ạ. Vậy từ khóa có trường âm thì không có vấn đề, đúng không ạ?"},{"furigana":"{承知|しょうち}いたしました。では、{商品名|しょうひんめい}から{長音|ちょうおん}{記号|きごう}をすべて{削除|さくじょ}していただけますか。","ja":"承知いたしました。では、商品名から長音記号をすべて削除していただけますか。","vi":"Tôi hiểu rồi. Vậy anh có thể xóa hết dấu trường âm khỏi tên sản phẩm được không?"}],"line":4,"why_vi":"Nhắc lại điều kiện gây lỗi (có trường âm) và hỏi thêm các điều kiện khác để khoanh vùng; hiểu ngược điều kiện hay bắt khách xóa dấu ー khỏi dữ liệu thì không xử lý đúng lỗi."},{"distractors":[{"furigana":"{承知|しょうち}いたしました。では、{問題|もんだい}はないようですので、このまま{様子|ようす}を{見|み}ます。","ja":"承知いたしました。では、問題はないようですので、このまま様子を見ます。","vi":"Tôi hiểu rồi. Vậy có vẻ không có vấn đề gì nên chúng tôi cứ để nguyên và theo dõi."},{"furigana":"{承知|しょうち}いたしました。{調査|ちょうさ}はいたしますが、いつご{連絡|れんらく}できるかはお{約束|やくそく}できません。","ja":"承知いたしました。調査はいたしますが、いつご連絡できるかはお約束できません。","vi":"Tôi hiểu rồi. Chúng tôi sẽ điều tra, nhưng không thể hứa khi nào liên lạc lại được."}],"line":6,"why_vi":"Đã khoanh vùng xong thì nhờ đội điều tra ngay và hẹn mốc giờ cụ thể (trước 17 giờ) để báo nguyên nhân, hướng xử lý; bỏ qua lỗi hay không hẹn thời gian đều khiến khách lo lắng."},{"distractors":[{"furigana":"{原因|げんいん}はまだわかっておりませんが、{本番|ほんばん}リリースは{確実|かくじつ}に1か{月|げつ}ほど{延期|えんき}になりますので、ご{了承|りょうしょう}ください。","ja":"原因はまだわかっておりませんが、本番リリースは確実に1か月ほど延期になりますので、ご了承ください。","vi":"Nguyên nhân thì chưa rõ, nhưng release production chắc chắn sẽ bị hoãn khoảng 1 tháng, mong anh thông cảm."},{"furigana":"はい、{多少|たしょう}の{影響|えいきょう}はあるかもしれませんが、{詳|くわ}しいことは{開発|かいはつ}チームに{直接|ちょくせつ}お{問|と}い{合|あ}わせいただけますか。","ja":"はい、多少の影響はあるかもしれませんが、詳しいことは開発チームに直接お問い合わせいただけますか。","vi":"Vâng, có thể sẽ có chút ảnh hưởng, nhưng chi tiết xin anh hỏi trực tiếp đội phát triển giúp."}],"line":8,"why_vi":"Khi chưa rõ nguyên nhân thì không khẳng định bừa: hẹn báo cả việc có ảnh hưởng hay không khi xác định được nguyên nhân và lịch sự xin khách chờ; khẳng định \'chắc chắn hoãn 1 tháng\' khi chưa rõ nguyên nhân, hay đẩy khách sang hỏi thẳng đội phát triển, đều sai vai trò BrSE."}]}', 'cpath-brse-06', '80cfde997abf'),
  ('BRSE-20', 'BUG', 2, 'N2', '障害の報告', 'Báo cáo sự cố', 'Báo sự cố cho khách hàng và hỏi thông tin.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"システムは{安定|あんてい}しています。","ja":"システムは安定しています。","vi":"Hệ thống đang ổn định ạ."},{"furigana":"{今日|きょう}の{天気|てんき}はどうですか。","ja":"今日の天気はどうですか。","vi":"Thời tiết hôm nay thế nào ạ?"}],"line":1,"why_vi":"Xảy ra sự cố thì báo ngay và nêu rõ môi trường; khen hệ thống ổn định hay hỏi việc khác đều sai việc."},{"distractors":[{"furigana":"{分|わ}かりません。","ja":"分かりません。","vi":"Tôi không biết ạ."},{"furigana":"もう{直|なお}りました。","ja":"もう直りました。","vi":"Đã xử lý xong rồi ạ."}],"line":3,"why_vi":"Khách hỏi thời điểm thì báo giờ bắt đầu và tình trạng điều tra; nói không biết gì hay khoe đã xử lý xong đều sai."},{"distractors":[{"furigana":"{影響|えいきょう}はありません。","ja":"影響はありません。","vi":"Không ảnh hưởng gì ạ."},{"furigana":"お{客様|きゃくさま}はどう{思|おも}いますか。","ja":"お客様はどう思いますか。","vi":"Anh nghĩ sao ạ?"}],"line":5,"why_vi":"Được hỏi phạm vi ảnh hưởng thì nêu chức năng bị ảnh hưởng và hướng xử lý; nói không ảnh hưởng gì hay hỏi lại khách đều mâu thuẫn."}]}', 'cpath-brse-20', '80cfde997abf'),
  ('BRSE-21', 'BUG', 3, 'N2', '修正完了の報告', 'Báo cáo hoàn tất sửa lỗi', 'Báo đã sửa xong lỗi và xin xác nhận lại.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"まだ{修正中|しゅうせいちゅう}です。","ja":"まだ修正中です。","vi":"Vẫn đang sửa ạ."},{"furigana":"ファムさんはすごいですね。","ja":"ファムさんはすごいですね。","vi":"Anh Phạm giỏi quá nhỉ."}],"line":1,"why_vi":"Muốn báo cáo hoàn tất thì nói rõ việc đã xong; báo đang làm dở hay khen PM đều sai việc."},{"distractors":[{"furigana":"{分|わ}からないです。","ja":"分からないです。","vi":"Tôi không rõ ạ."},{"furigana":"どうしたらいいですか。","ja":"どうしたらいいですか。","vi":"Tôi phải làm sao ạ?"}],"line":3,"why_vi":"PM hỏi nguy cơ tái phát thì khẳng định không còn và nêu bằng chứng kiểm thử; nói không chắc hay hỏi lại PM đều sai."},{"distractors":[{"furigana":"できません。","ja":"できません。","vi":"Tôi không làm được ạ."},{"furigana":"{今日|きょう}は{休|やす}みたいです。","ja":"今日は休みたいです。","vi":"Hôm nay tôi muốn nghỉ ạ."}],"line":5,"why_vi":"PM giao triển khai thì nhận lời và nêu thời điểm; từ chối làm hay hỏi nghỉ phép đều sai."}]}', 'cpath-brse-21', '80cfde997abf'),
  ('BRSE-13', 'OPS', 1, 'N2', '本番障害の一次報告', 'Báo cáo sơ bộ sự cố production', 'Production gặp sự cố sau đợt release buổi sáng, BrSE gọi báo khách ngay và xin phê duyệt rollback.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{田中|たなか}{様|さま}、{急|いそ}ぎではないのですが、{来週|らいしゅう}の{定例|ていれい}{会議|かいぎ}でご{報告|ほうこく}したいことがございます。","ja":"田中様、急ぎではないのですが、来週の定例会議でご報告したいことがございます。","vi":"Anh Tanaka, không gấp lắm nhưng tôi có việc muốn báo cáo trong buổi họp định kỳ tuần sau."},{"furigana":"{田中|たなか}{様|さま}、{本日|ほんじつ}のリリースは{問題|もんだい}なく{完了|かんりょう}いたしました。ご{協力|きょうりょく}ありがとうございました。","ja":"田中様、本日のリリースは問題なく完了いたしました。ご協力ありがとうございました。","vi":"Anh Tanaka, đợt release hôm nay đã hoàn tất không có vấn đề gì. Cảm ơn anh đã hợp tác."}],"line":1,"why_vi":"Sự cố production phải báo ngay (至急ご報告いたします) kèm thời điểm và hiện tượng; hẹn báo ở họp tuần sau hay báo \'release suôn sẻ\' đều là che giấu sự cố."},{"distractors":[{"furigana":"{現時点|げんじてん}で、ユーザーへの{影響|えいきょう}はまったくございません。","ja":"現時点で、ユーザーへの影響はまったくございません。","vi":"Hiện tại hoàn toàn không có ảnh hưởng gì tới người dùng."},{"furigana":"えっと、3{割|わり}ぐらいかな。よくわかんないけど。","ja":"えっと、3割ぐらいかな。よくわかんないけど。","vi":"Ờ, chắc khoảng 30%. Tôi cũng không rõ lắm."}],"line":3,"why_vi":"Khách hỏi mức ảnh hưởng nên trả lời bằng số liệu hiện có (khoảng 30% lượt thanh toán bị lỗi) với kính ngữ; nói \'không ảnh hưởng gì\' là sai sự thật, còn trả lời trống không, mơ hồ thì không phù hợp khi báo sự cố."},{"distractors":[{"furigana":"{原因|げんいん}はユーザーの{使|つか}い{方|かた}の{問題|もんだい}ですので、こちらでは{対応|たいおう}いたしません。","ja":"原因はユーザーの使い方の問題ですので、こちらでは対応いたしません。","vi":"Nguyên nhân là do người dùng sử dụng sai nên bên chúng tôi sẽ không xử lý."},{"furigana":"{原因|げんいん}はすでに{判明|はんめい}しており、{今朝|けさ}のリリースで{更新|こうしん}した{設定|せってい}ファイルを{修正|しゅうせい}して、すべて{解決|かいけつ}いたしました。","ja":"原因はすでに判明しており、今朝のリリースで更新した設定ファイルを修正して、すべて解決いたしました。","vi":"Nguyên nhân đã được xác định: chúng tôi đã sửa file cấu hình cập nhật trong đợt release sáng nay và mọi thứ đã được giải quyết xong."}],"line":4,"why_vi":"Nguyên nhân chưa xác định nên nói \'đang điều tra\' kèm giả thuyết khả năng cao (file cấu hình của đợt release sáng nay); đổ cho người dùng hay báo \'đã giải quyết xong\' khi lỗi vẫn đang xảy ra đều sai."},{"distractors":[{"furigana":"{戻|もど}すことは{可能|かのう}ですが、リスクがございますので、{原因|げんいん}が{判明|はんめい}するまでは{何|なに}もせずに{様子|ようす}を{見|み}る{予定|よてい}です。","ja":"戻すことは可能ですが、リスクがございますので、原因が判明するまでは何もせずに様子を見る予定です。","vi":"Quay lại thì được, nhưng vì có rủi ro nên chúng tôi định chưa làm gì, chỉ theo dõi cho tới khi xác định được nguyên nhân."},{"furigana":"{実|じつ}は、{田中|たなか}{様|さま}のご{承認|しょうにん}をいただく{前|まえ}に、すでにリリース{前|まえ}の{状態|じょうたい}に{戻|もど}しておきました。","ja":"実は、田中様のご承認をいただく前に、すでにリリース前の状態に戻しておきました。","vi":"Thật ra, chúng tôi đã đưa về trạng thái trước release rồi, trước cả khi xin phê duyệt của anh Tanaka."}],"line":6,"why_vi":"Xác nhận có thể quay lại ngay, nêu rõ biện pháp tạm thời và thời hạn (trong 30 phút) rồi xin khách phê duyệt rollback; để nguyên chờ tìm ra nguyên nhân khi lỗi vẫn đang xảy ra, hay tự ý rollback trước khi xin phép, đều trái với quy trình xử lý sự cố."},{"distractors":[{"furigana":"{承知|しょうち}いたしました。{戻|もど}したあとのご{連絡|れんらく}は{特|とく}にいたしませんので、ご{了承|りょうしょう}ください。","ja":"承知いたしました。戻したあとのご連絡は特にいたしませんので、ご了承ください。","vi":"Vâng. Sau khi quay lại chúng tôi sẽ không liên lạc gì thêm, mong anh thông cảm."},{"furigana":"{承知|しょうち}いたしました。では、まず{原因|げんいん}と{再発|さいはつ}{防止|ぼうし}{策|さく}を{話|はな}し{合|あ}う{会議|かいぎ}を{来週|らいしゅう}{開|ひら}き、その{結果|けっか}を{見|み}てから{戻|もど}す{作業|さぎょう}を{始|はじ}めます。","ja":"承知いたしました。では、まず原因と再発防止策を話し合う会議を来週開き、その結果を見てから戻す作業を始めます。","vi":"Vâng. Vậy trước tiên chúng tôi sẽ họp bàn về nguyên nhân và biện pháp phòng tái phát vào tuần sau, xem kết quả rồi mới bắt đầu quay lại bản cũ."}],"line":8,"why_vi":"Được phê duyệt thì tiến hành ngay, hẹn báo khi khôi phục xong và báo hướng xử lý triệt để khi rõ nguyên nhân; không liên lạc lại hay đợi họp tuần sau mới làm đều sai với yêu cầu \'tiến hành ngay\'."}]}', 'cpath-brse-13', '80cfde997abf'),
  ('BRSE-14', 'OPS', 2, 'N2', 'リリース前の最終確認', 'Xác nhận lần cuối trước release', 'Trước ngày release, BrSE xác nhận lịch làm việc, thời gian dừng dịch vụ và phương án rollback với khách.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"{昨日|きのう}のリリースの{結果|けっか}をご{報告|ほうこく}いたします。","ja":"昨日のリリースの結果をご報告いたします。","vi":"Tôi xin báo cáo kết quả đợt release hôm qua."},{"furigana":"{明日|あした}のリリースは{準備|じゅんび}ができていないので、{中止|ちゅうし}にいたします。","ja":"明日のリリースは準備ができていないので、中止にいたします。","vi":"Đợt release ngày mai chưa chuẩn bị xong nên chúng tôi sẽ hủy."}],"line":1,"why_vi":"Trước ngày release, BrSE mở đầu buổi xác nhận cuối cùng (最終確認をさせていただきます); báo kết quả release \'hôm qua\' sai thời điểm, còn tự tuyên bố hủy thì trái với tình huống."},{"distractors":[{"furigana":"リリース{手順書|てじゅんしょ}はまだ{作成|さくせい}しておりませんので、{作業|さぎょう}の{時間|じかん}も{決|き}まっておりません。","ja":"リリース手順書はまだ作成しておりませんので、作業の時間も決まっておりません。","vi":"Tài liệu thao tác release chúng tôi chưa soạn nên thời gian làm cũng chưa quyết định."},{"furigana":"リリース{手順書|てじゅんしょ}は{昨日|きのう}お{送|おく}りしたとおりで、{作業|さぎょう}は{本日|ほんじつ}の22{時|じ}から24{時|じ}を{予定|よてい}しております。","ja":"リリース手順書は昨日お送りしたとおりで、作業は本日の22時から24時を予定しております。","vi":"Tài liệu thao tác release như đã gửi hôm qua, dự kiến làm từ 22 giờ đến 24 giờ hôm nay."}],"line":2,"why_vi":"Xác nhận lần cuối thì nhắc tài liệu đã gửi và khung giờ làm 22–24 giờ ngày mai; nói chưa soạn tài liệu là không thể ở bước chốt, còn \'hôm nay\' thì sai vì đợt release là ngày mai."},{"distractors":[{"furigana":"いいえ、{作業中|さぎょうちゅう}もサービスは{止|と}まりませんので、ユーザーへのお{知|し}らせなど、{特|とく}にご{対応|たいおう}いただくことはございません。","ja":"いいえ、作業中もサービスは止まりませんので、ユーザーへのお知らせなど、特にご対応いただくことはございません。","vi":"Không, trong lúc làm dịch vụ cũng không dừng, nên anh không cần làm gì cả, kể cả thông báo cho người dùng."},{"furigana":"はい、22{時|じ}から{約|やく}1{時間|じかん}、サービスを{停止|ていし}いたします。ただ、ユーザーへのお{知|し}らせは{必要|ひつよう}ございません。","ja":"はい、22時から約1時間、サービスを停止いたします。ただ、ユーザーへのお知らせは必要ございません。","vi":"Vâng, dịch vụ sẽ dừng khoảng 1 tiếng từ 22 giờ. Nhưng không cần thông báo cho người dùng."}],"line":4,"why_vi":"Tình huống có thời gian dừng dịch vụ (khoảng 1 tiếng từ 22 giờ) nên phải báo rõ và nhờ khách đăng thông báo trước cho người dùng; nói \'không dừng\' là sai với tình huống, còn dừng mà không báo thì người dùng bị ảnh hưởng bất ngờ."},{"distractors":[{"furigana":"{万|まん}が{一|いち}{問題|もんだい}が{発生|はっせい}した{場合|ばあい}は、{翌朝|よくあさ}まで{様子|ようす}を{見|み}て、{元|もと}のバージョンには{戻|もど}しません。","ja":"万が一問題が発生した場合は、翌朝まで様子を見て、元のバージョンには戻しません。","vi":"Nếu chẳng may có vấn đề, chúng tôi sẽ theo dõi đến sáng hôm sau và không quay về phiên bản cũ."},{"furigana":"{万|まん}が{一|いち}{問題|もんだい}が{発生|はっせい}した{場合|ばあい}は、{切|き}り{戻|もど}し{手順|てじゅん}に{従|したが}って{元|もと}のバージョンに{戻|もど}します。{判断|はんだん}の{期限|きげん}は21{時|じ}とさせていただきます。","ja":"万が一問題が発生した場合は、切り戻し手順に従って元のバージョンに戻します。判断の期限は21時とさせていただきます。","vi":"Nếu chẳng may có vấn đề, chúng tôi sẽ quay về phiên bản cũ theo quy trình rollback. Thời hạn ra quyết định là 21 giờ."}],"line":6,"why_vi":"Phương án rollback phải có hạn quyết định nằm trong khung làm việc 22–24 giờ (23 giờ 30) để kịp quay về bản cũ; không rollback mà chờ tới sáng là bỏ mặc sự cố, còn hạn 21 giờ thì rơi vào trước cả giờ bắt đầu làm (22 giờ) nên vô lý."},{"distractors":[{"furigana":"かしこまりました。ですが、{夜中|よなか}にご{連絡|れんらく}するのは{失礼|しつれい}ですので、{何|なに}があっても{翌朝|よくあさ}にいたします。","ja":"かしこまりました。ですが、夜中にご連絡するのは失礼ですので、何があっても翌朝にいたします。","vi":"Vâng. Nhưng liên lạc lúc nửa đêm thì thất lễ, nên dù có chuyện gì tôi cũng sẽ liên lạc vào sáng hôm sau."},{"furigana":"{了解|りょうかい}。{何|なに}かあったら{電話|でんわ}するね。{終|お}わったら{連絡|れんらく}するよ。","ja":"了解。何かあったら電話するね。終わったら連絡するよ。","vi":"Rõ. Có gì tôi gọi nhé. Xong tôi báo cho."}],"line":8,"why_vi":"Nhận lời bằng かしこまりました và hẹn báo kết quả qua email sau khi xong; tự ý dời liên lạc sang sáng hôm sau trái với lời khách dặn, còn nói trống không (了解…ね/よ) thì không hợp với khách hàng."}]}', 'cpath-brse-14', '80cfde997abf'),
  ('BRSE-22', 'OPS', 3, 'N2', 'リリースの報告', 'Báo cáo phát hành', 'Thông báo đã phát hành phiên bản mới cho khách hàng.', '{"learnerSpeaker":"グエン","turns":[{"distractors":[{"furigana":"サーバーが{落|お}ちました。","ja":"サーバーが落ちました。","vi":"Máy chủ bị sập ạ."},{"furigana":"この{作業|さぎょう}の{料金|りょうきん}はいくらですか。","ja":"この作業の料金はいくらですか。","vi":"Phí việc này bao nhiêu ạ?"}],"line":1,"why_vi":"Muốn báo cáo phát hành thì nói rõ phiên bản mới đã xong; báo hệ thống sập hay hỏi giá đều sai việc."},{"distractors":[{"furigana":"{確認|かくにん}していません。","ja":"確認していません。","vi":"Tôi chưa kiểm tra ạ."},{"furigana":"{田中|たなか}さんは{安心|あんしん}してください。","ja":"田中さんは安心してください。","vi":"Anh Tanaka cứ yên tâm ạ."}],"line":3,"why_vi":"Khách hỏi vận hành thì khẳng định hệ thống ổn, có giám sát chứng minh; nói không kiểm tra hay khen khách đều sai."},{"distractors":[{"furigana":"バックアップはまだです。","ja":"バックアップはまだです。","vi":"Vẫn chưa sao lưu ạ."},{"furigana":"{必要|ひつよう}ですか。","ja":"必要ですか。","vi":"Có cần thiết không ạ?"}],"line":5,"why_vi":"Được hỏi sao lưu thì xác nhận đã làm trước khi phát hành; nói chưa sao lưu hay hỏi lại khách đều mâu thuẫn."}]}', 'cpath-brse-22', '80cfde997abf'),
  ('WRK-01', 'OFFICE-GREETING', 1, 'N3', '朝のあいさつ', 'Chào buổi sáng', 'Chào đồng nghiệp khi vừa đến công ty.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"こんばんは。","ja":"こんばんは。","vi":"Chào buổi tối."},{"furigana":"さようなら。","ja":"さようなら。","vi":"Tạm biệt."}],"line":1,"why_vi":"Đến công ty buổi sáng thì chào buổi sáng; chào buổi tối hay chào tạm biệt đều sai thời điểm."},{"distractors":[{"furigana":"{寝坊|ねぼう}しました。","ja":"寝坊しました。","vi":"Tôi ngủ quên ạ."},{"furigana":"{電車|でんしゃ}が{混|こ}んでいました。","ja":"電車が混んでいました。","vi":"Tàu đông quá ạ."}],"line":3,"why_vi":"Đồng nghiệp khen đến sớm thì nói mình dậy sớm; nói ngủ quên hay phàn nàn kẹt xe đều mâu thuẫn."},{"distractors":[{"furigana":"もう{会議|かいぎ}を{始|はじ}めましょう。","ja":"もう会議を始めましょう。","vi":"Bắt đầu họp ngay thôi ạ."},{"furigana":"{今日|きょう}は{帰|かえ}ります。","ja":"今日は帰ります。","vi":"Hôm nay tôi về ạ."}],"line":5,"why_vi":"Còn thời gian thì nói đi uống cà phê; bảo bắt đầu họp ngay hay đi về đều sai bối cảnh."}]}', 'cpath-wrk-01', '7a8f7e1bcd88'),
  ('WRK-02', 'OFFICE-GREETING', 2, 'N3', '自己紹介', 'Tự giới thiệu', 'Giới thiệu bản thân với đồng nghiệp mới.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{給料|きゅうりょう}はいくらですか。","ja":"給料はいくらですか。","vi":"Lương bao nhiêu ạ?"},{"furigana":"この{会社|かいしゃ}は{大|おお}きいですね。","ja":"この会社は大きいですね。","vi":"Công ty này to nhỉ."}],"line":1,"why_vi":"Mới đến thì chào và tự giới thiệu tên; hỏi lương hay khen công ty đều sai việc chào hỏi."},{"distractors":[{"furigana":"{大学|だいがく}を{出|で}たばかりです。","ja":"大学を出たばかりです。","vi":"Tôi vừa tốt nghiệp đại học ạ."},{"furigana":"{先輩|せんぱい}は{何部|なにぶ}ですか。","ja":"先輩は何部ですか。","vi":"Anh ở bộ phận nào ạ?"}],"line":3,"why_vi":"Được hỏi nơi làm cũ thì nói chuyển từ bộ phận kinh doanh; nói mới tốt nghiệp hay hỏi lại đồng nghiệp đều sai."}]}', 'cpath-wrk-02', '7a8f7e1bcd88'),
  ('WRK-03', 'OFFICE-GREETING', 3, 'N3', '退社のあいさつ', 'Chào khi ra về', 'Chào sếp khi xong việc ra về.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"おはようございます。","ja":"おはようございます。","vi":"Chào buổi sáng ạ."},{"furigana":"{会議|かいぎ}に{行|い}ってきます。","ja":"会議に行ってきます。","vi":"Em đi họp đây ạ."}],"line":1,"why_vi":"Xong việc ra về thì chào xin phép về trước; chào buổi sáng hay báo đi họp đều sai thời điểm."},{"distractors":[{"furigana":"{今日|きょう}はできません。","ja":"今日はできません。","vi":"Hôm nay em không làm được ạ."},{"furigana":"{何時|なんじ}に{帰|かえ}りますか。","ja":"何時に帰りますか。","vi":"Mấy giờ về ạ?"}],"line":3,"why_vi":"Sếp dặn xem tài liệu thì nhận lời; từ chối hay hỏi lại giờ về đều sai."},{"distractors":[{"furigana":"{会議|かいぎ}は{何時|なんじ}ですか。","ja":"会議は何時ですか。","vi":"Họp mấy giờ ạ?"},{"furigana":"{明日|あした}は{休|やす}みたいです。","ja":"明日は休みたいです。","vi":"Ngày mai em muốn nghỉ ạ."}],"line":5,"why_vi":"Sếp báo giờ họp thì hứa không đến muộn; hỏi lại giờ họp hay nói muốn nghỉ đều sai nhịp."}]}', 'cpath-wrk-03', '7a8f7e1bcd88'),
  ('WRK-07', 'OFFICE-LEAVE', 1, 'N3', '有給の申請', 'Xin nghỉ phép', 'Xin sếp nghỉ phép có lương.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{金曜日|きんようび}は{休|やす}みます。","ja":"金曜日は休みます。","vi":"Thứ Sáu em nghỉ ạ."},{"furigana":"{風邪|かぜ}を{引|ひ}きました。","ja":"風邪を引きました。","vi":"Em bị cảm ạ."}],"line":1,"why_vi":"Muốn xin nghỉ thì hỏi sếp có được không; tự ý nghỉ hay báo ốm giả đều sai."},{"distractors":[{"furigana":"{遊|あそ}びに{行|い}きます。","ja":"遊びに行きます。","vi":"Em đi chơi ạ."},{"furigana":"{秘密|ひみつ}です。","ja":"秘密です。","vi":"Bí mật ạ."}],"line":3,"why_vi":"Sếp hỏi lý do thì nói về quê vì việc gia đình; nói đi chơi hay không nói lý do đều không thuyết phục."},{"distractors":[{"furigana":"{引|ひ}き{継|つ}ぎは{必要|ひつよう}ありません。","ja":"引き継ぎは必要ありません。","vi":"Không cần bàn giao đâu ạ."},{"furigana":"{誰|だれ}に{引|ひ}き{継|つ}げばいいですか。","ja":"誰に引き継げばいいですか。","vi":"Bàn giao cho ai ạ?"}],"line":5,"why_vi":"Sếp dặn bàn giao thì nhận lời và nêu người nhận bàn giao; nói không cần bàn giao hay từ chối đều sai."}]}', 'cpath-wrk-07', '7a8f7e1bcd88'),
  ('WRK-08', 'OFFICE-LEAVE', 2, 'N3', '早退のお願い', 'Xin về sớm', 'Xin sếp về sớm vì có việc gấp.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"もう{帰|かえ}ります。","ja":"もう帰ります。","vi":"Em về luôn đây ạ."},{"furigana":"{明日|あした}も{休|やす}みます。","ja":"明日も休みます。","vi":"Ngày mai em cũng nghỉ ạ."}],"line":1,"why_vi":"Muốn về sớm thì xin phép sếp rõ giờ; tự ý ra về hay xin nghỉ cả ngày đều sai."},{"distractors":[{"furigana":"{買|か}い{物|もの}に{行|い}きます。","ja":"買い物に行きます。","vi":"Em đi mua sắm ạ."},{"furigana":"{友達|ともだち}と{遊|あそ}びます。","ja":"友達と遊びます。","vi":"Em đi chơi với bạn ạ."}],"line":3,"why_vi":"Sếp hỏi lý do thì nói con ốm phải đi đón; nói đi mua sắm hay kể chuyện vui đều không phù hợp."},{"distractors":[{"furigana":"{仕事|しごと}はやりません。","ja":"仕事はやりません。","vi":"Em không làm việc nữa ạ."},{"furigana":"{本当|ほんとう}にいいですか。","ja":"本当にいいですか。","vi":"Thật sự được chứ ạ?"}],"line":5,"why_vi":"Được sếp cho về thì cảm ơn và hứa làm việc còn lại; nói bỏ hết việc hay hỏi lại sếp đều sai."}]}', 'cpath-wrk-08', '7a8f7e1bcd88'),
  ('WRK-09', 'OFFICE-LEAVE', 3, 'N3', '病欠の連絡', 'Báo nghỉ ốm', 'Gọi điện báo sếp xin nghỉ ốm.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{給料|きゅうりょう}の{話|はなし}があります。","ja":"給料の話があります。","vi":"Em có chuyện lương ạ."},{"furigana":"{今日|きょう}の{仕事|しごと}は{終|お}わりました。","ja":"今日の仕事は終わりました。","vi":"Việc hôm nay đã xong ạ."}],"line":1,"why_vi":"Gọi điện thì xưng tên trước; hỏi ngay chuyện lương hay báo công việc đều sai lúc này."},{"distractors":[{"furigana":"{今日|きょう}は{遅刻|ちこく}します。","ja":"今日は遅刻します。","vi":"Hôm nay em đến muộn ạ."},{"furigana":"{旅行|りょこう}に{行|い}きたいです。","ja":"旅行に行きたいです。","vi":"Em muốn đi du lịch ạ."}],"line":3,"why_vi":"Sếp hỏi thì nói bị sốt và xin nghỉ; nói đi chơi hay báo đến muộn đều sai."},{"distractors":[{"furigana":"{病院|びょういん}には{行|い}きません。","ja":"病院には行きません。","vi":"Em không đi bệnh viện ạ."},{"furigana":"{連絡|れんらく}はしません。","ja":"連絡はしません。","vi":"Em không liên lạc đâu ạ."}],"line":5,"why_vi":"Được hỏi đi bệnh viện thì nói sẽ đi và hẹn liên lạc lại; nói không đi bệnh viện hay từ chối liên lạc đều chưa tốt."}]}', 'cpath-wrk-09', '7a8f7e1bcd88'),
  ('WRK-10', 'OFFICE-PHONE', 1, 'N3', '電話を取る', 'Nhận điện thoại', 'Nhận điện thoại của đối tác tìm người phụ trách.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"もしもし、リンです。","ja":"もしもし、リンです。","vi":"Alo, tôi là Linh ạ."},{"furigana":"どちら{様|さま}ですか。","ja":"どちら様ですか。","vi":"Ai vậy ạ?"}],"line":1,"why_vi":"Nghe điện thoại công ty thì xưng tên công ty; trả lời là nhà riêng hay chào kiểu bạn bè đều sai."},{"distractors":[{"furigana":"{何|なん}のご{用件|ようけん}ですか。","ja":"何のご用件ですか。","vi":"Có việc gì ạ?"},{"furigana":"{田中|たなか}は{今|いま}いません。","ja":"田中は今いません。","vi":"Tanaka hiện không có ạ."}],"line":3,"why_vi":"Khách xin gặp đồng nghiệp thì chuyển máy; hỏi lý do khách hay báo đồng nghiệp vắng ngay đều chưa đúng."},{"distractors":[{"furigana":"{田中|たなか}は{退職|たいしょく}しました。","ja":"田中は退職しました。","vi":"Tanaka đã nghỉ việc ạ."},{"furigana":"{切|き}ります。","ja":"切ります。","vi":"Tôi cúp máy đây."}],"line":5,"why_vi":"Sau khi kiểm tra thấy đồng nghiệp vắng thì xin lỗi và báo; nói đồng nghiệp nghỉ việc hay cúp máy đều sai."}]}', 'cpath-wrk-10', '7a8f7e1bcd88'),
  ('WRK-11', 'OFFICE-PHONE', 2, 'N3', '伝言を受ける', 'Nhận lời nhắn', 'Nhận lời nhắn cho đồng nghiệp vắng mặt.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"はい、もしもし。","ja":"はい、もしもし。","vi":"Vâng, alo."},{"furigana":"{商品|しょうひん}はいくらですか。","ja":"商品はいくらですか。","vi":"Sản phẩm bao nhiêu tiền ạ?"}],"line":1,"why_vi":"Trả lời điện thoại công ty thì xưng tên công ty; chào kiểu cá nhân hay hỏi giá đều sai."},{"distractors":[{"furigana":"{伝言|でんごん}はできません。","ja":"伝言はできません。","vi":"Tôi không chuyển lời nhắn được ạ."},{"furigana":"{田中|たなか}に{直接|ちょくせつ}{聞|き}いてください。","ja":"田中に直接聞いてください。","vi":"Anh hỏi trực tiếp Tanaka đi ạ."}],"line":3,"why_vi":"Khách nhờ chuyển lời nhắn thì nhận lời; từ chối hay hỏi khách có việc gì đều sai."},{"distractors":[{"furigana":"{内容|ないよう}を{忘|わす}れました。","ja":"内容を忘れました。","vi":"Tôi quên nội dung ạ."},{"furigana":"{復唱|ふくしょう}はしません。","ja":"復唱はしません。","vi":"Tôi không nhắc lại đâu ạ."}],"line":5,"why_vi":"Đã ghi lời nhắn thì nhắc lại để xác nhận; nói quên nội dung hay từ chối xác nhận đều không chuyên nghiệp."}]}', 'cpath-wrk-11', '7a8f7e1bcd88'),
  ('WRK-12', 'OFFICE-PHONE', 3, 'N3', '電話をかける', 'Gọi điện cho khách', 'Gọi điện cho khách để xác nhận lịch hẹn.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"もしもし。","ja":"もしもし。","vi":"Alo."},{"furigana":"{明日|あした}の{会議|かいぎ}はやめましょう。","ja":"明日の会議はやめましょう。","vi":"Hủy cuộc họp ngày mai đi ạ."}],"line":1,"why_vi":"Gọi điện cho khách thì xưng tên công ty và tên mình; chỉ nói \\"alo\\" hay hỏi lương đều sai."},{"distractors":[{"furigana":"{今日|きょう}はいい{天気|てんき}ですね。","ja":"今日はいい天気ですね。","vi":"Hôm nay trời đẹp nhỉ."},{"furigana":"お{元気|げんき}ですか。","ja":"お元気ですか。","vi":"Anh khỏe không ạ?"}],"line":3,"why_vi":"Khách nhận ra mình thì nêu mục đích cuộc gọi; khen khách hay hỏi thời tiết đều lạc đề."},{"distractors":[{"furigana":"{会議|かいぎ}をキャンセルします。","ja":"会議をキャンセルします。","vi":"Tôi hủy cuộc họp ạ."},{"furigana":"{会議室|かいぎしつ}の{料金|りょうきん}はいくらですか。","ja":"会議室の料金はいくらですか。","vi":"Phí phòng họp bao nhiêu ạ?"}],"line":5,"why_vi":"Đã nêu việc thì đề nghị đổi giờ cụ thể; đòi hủy cuộc họp hay hỏi giá đều sai mục đích."}]}', 'cpath-wrk-12', '7a8f7e1bcd88'),
  ('WRK-16', 'FACTORY-SAFETY', 1, 'N3', '保護具の着用', 'Đeo đồ bảo hộ', 'Tổ trưởng nhắc nhở đeo đồ bảo hộ trước khi vào xưởng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{昼休|ひるやす}みは{何時|なんじ}ですか。","ja":"昼休みは何時ですか。","vi":"Nghỉ trưa mấy giờ ạ?"},{"furigana":"{給料|きゅうりょう}はいつもらえますか。","ja":"給料はいつもらえますか。","vi":"Bao giờ lĩnh lương ạ?"}],"line":1,"why_vi":"Trước khi vào xưởng thì hỏi cần chuẩn bị gì; hỏi giờ nghỉ trưa hay hỏi lương đều sai lúc này."},{"distractors":[{"furigana":"ヘルメットはどこですか。","ja":"ヘルメットはどこですか。","vi":"Mũ bảo hộ ở đâu ạ?"},{"furigana":"{手袋|てぶくろ}はいりません。","ja":"手袋はいりません。","vi":"Không cần găng tay đâu ạ."}],"line":3,"why_vi":"Được nhắc đeo mũ và giày thì hỏi thêm có cần găng tay không; hỏi lại mũ hay từ chối đeo đều sai."},{"distractors":[{"furigana":"{面倒|めんどう}くさいです。","ja":"面倒くさいです。","vi":"Phiền quá ạ."},{"furigana":"{今日|きょう}は{着用|ちゃくよう}しません。","ja":"今日は着用しません。","vi":"Hôm nay em không đeo đâu ạ."}],"line":5,"why_vi":"Được giải thích xong thì đồng ý đeo ngay; cãi lại hay bỏ ra ngoài đều sai."}]}', 'cpath-wrk-16', '7a8f7e1bcd88'),
  ('WRK-17', 'FACTORY-SAFETY', 2, 'N3', '火気の注意', 'Chú ý nguồn lửa', 'Đàn anh nhắc nhở không dùng lửa gần khu dễ cháy.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"タバコを{吸|す}います。","ja":"タバコを吸います。","vi":"Em hút thuốc đây ạ."},{"furigana":"{今日|きょう}は{何時|なんじ}に{帰|かえ}れますか。","ja":"今日は何時に帰れますか。","vi":"Hôm nay mấy giờ về ạ?"}],"line":1,"why_vi":"Muốn hút thuốc thì hỏi có được hút ở đây không; tự ý hút hay hỏi giờ nghỉ đều sai."},{"distractors":[{"furigana":"ここで{大丈夫|だいじょうぶ}ですよ。","ja":"ここで大丈夫ですよ。","vi":"Ở đây được mà ạ."},{"furigana":"{少|すこ}しだけ{吸|す}います。","ja":"少しだけ吸います。","vi":"Em hút chút thôi ạ."}],"line":3,"why_vi":"Bị nhắc không được hút ở đây thì hỏi chỗ được hút; cãi là hút được hay tiếp tục hút đều sai."},{"distractors":[{"furigana":"{本当|ほんとう}に{吸|す}っていいですか。","ja":"本当に吸っていいですか。","vi":"Thật sự được hút chứ ạ?"},{"furigana":"もうやめます。","ja":"もうやめます。","vi":"Thôi, em không hút nữa ạ."}],"line":5,"why_vi":"Biết có khu hút thuốc thì hỏi vị trí; hỏi lại có được hút không hay bỏ đi đều thừa."}]}', 'cpath-wrk-17', '7a8f7e1bcd88'),
  ('WRK-18', 'FACTORY-SAFETY', 3, 'N3', '避難訓練', 'Diễn tập sơ tán', 'Tổ trưởng thông báo diễn tập sơ tán.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今日|きょう}は{残業|ざんぎょう}ですか。","ja":"今日は残業ですか。","vi":"Hôm nay có tăng ca không ạ?"},{"furigana":"{給料|きゅうりょう}は{上|あ}がりますか。","ja":"給料は上がりますか。","vi":"Lương có tăng không ạ?"}],"line":1,"why_vi":"Muốn biết có diễn tập không thì hỏi trực tiếp; hỏi giờ nghỉ hay lương đều sai."},{"distractors":[{"furigana":"{何時|なんじ}からですか。","ja":"何時からですか。","vi":"Từ mấy giờ ạ?"},{"furigana":"{何|なに}を{着|き}ますか。","ja":"何を着ますか。","vi":"Mặc gì ạ?"}],"line":3,"why_vi":"Biết có diễn tập thì hỏi nơi tập trung; hỏi lại giờ hay hỏi mặc gì đều sai."},{"distractors":[{"furigana":"{広場|ひろば}はどこですか。","ja":"広場はどこですか。","vi":"Quảng trường ở đâu ạ?"},{"furigana":"お{弁当|べんとう}はありますか。","ja":"お弁当はありますか。","vi":"Có cơm hộp không ạ?"}],"line":5,"why_vi":"Biết chỗ tập trung thì hỏi lối thoát hiểm; hỏi lại chỗ tập trung hay hỏi đồ ăn đều lạc đề."}]}', 'cpath-wrk-18', '7a8f7e1bcd88'),
  ('WRK-19', 'FACTORY-SHIFT', 1, 'N3', 'シフトの確認', 'Xác nhận ca làm', 'Hỏi tổ trưởng về ca làm tuần tới.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{来週|らいしゅう}、{休|やす}みたいです。","ja":"来週、休みたいです。","vi":"Tuần sau em muốn nghỉ ạ."},{"furigana":"{給料|きゅうりょう}はいくらですか。","ja":"給料はいくらですか。","vi":"Lương bao nhiêu ạ?"}],"line":1,"why_vi":"Muốn biết ca làm thì nói xác nhận ca; hỏi lương hay xin nghỉ luôn đều sai."},{"distractors":[{"furigana":"{夜勤|やきん}ですね。","ja":"夜勤ですね。","vi":"Ca đêm nhỉ ạ."},{"furigana":"{休|やす}みはいつですか。","ja":"休みはいつですか。","vi":"Nghỉ khi nào ạ?"}],"line":3,"why_vi":"Biết làm ca đêm thì hỏi giờ cụ thể; hỏi lại làm ca gì hay hỏi ngày nghỉ đều sai nhịp."},{"distractors":[{"furigana":"{何時|なんじ}まで{働|はたら}きますか。","ja":"何時まで働きますか。","vi":"Làm đến mấy giờ ạ?"},{"furigana":"{夜食|やしょく}は{出|で}ますか。","ja":"夜食は出ますか。","vi":"Có ăn khuya không ạ?"}],"line":5,"why_vi":"Biết giờ làm thì hỏi giờ nghỉ; hỏi lại giờ làm hay hỏi đồ ăn khuya đều không phải bước tiếp theo."}]}', 'cpath-wrk-19', '7a8f7e1bcd88'),
  ('WRK-20', 'FACTORY-SHIFT', 2, 'N3', '夜勤の引き継ぎ', 'Bàn giao ca đêm', 'Bàn giao công việc cho đồng nghiệp ca đêm.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今日|きょう}は{疲|つか}れました。","ja":"今日は疲れました。","vi":"Hôm nay mệt quá ạ."},{"furigana":"{夜勤|やきん}の{手当|てあて}はいくらですか。","ja":"夜勤の手当はいくらですか。","vi":"Phụ cấp ca đêm bao nhiêu ạ?"}],"line":1,"why_vi":"Bàn giao ca thì chào và nhờ đồng nghiệp; phàn nàn mệt hay hỏi lương đều sai."},{"distractors":[{"furigana":"{特|とく}にありません。","ja":"特にありません。","vi":"Không có gì đặc biệt ạ."},{"furigana":"{昨日|きのう}のテレビは{面白|おもしろ}かったです。","ja":"昨日のテレビは面白かったです。","vi":"Tivi hôm qua hay lắm ạ."}],"line":3,"why_vi":"Được hỏi bàn giao thì báo máy có vấn đề; nói không có gì hay kể chuyện riêng đều không bàn giao thực chất."},{"distractors":[{"furigana":"{三番|さんばん}の{機械|きかい}は{大丈夫|だいじょうぶ}ですか。","ja":"三番の機械は大丈夫ですか。","vi":"Máy số ba ổn chứ ạ?"},{"furigana":"じゃ、{帰|かえ}ります。","ja":"じゃ、帰ります。","vi":"Vậy em về đây ạ."}],"line":5,"why_vi":"Bàn giao thêm thì nhắc nguyên liệu sắp hết; hỏi lại máy hay nói đi về ngay đều chưa đầy đủ."}]}', 'cpath-wrk-20', '7a8f7e1bcd88'),
  ('WRK-21', 'FACTORY-SHIFT', 3, 'N3', '残業のお願い', 'Xin tăng ca', 'Quản đốc đề nghị tăng ca để kịp tiến độ.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{工場長|こうじょうちょう}、{給料|きゅうりょう}の{話|はなし}ですか。","ja":"工場長、給料の話ですか。","vi":"Thưa quản đốc, chuyện lương ạ?"},{"furigana":"{今日|きょう}はいい{天気|てんき}ですね。","ja":"今日はいい天気ですね。","vi":"Hôm nay trời đẹp nhỉ."}],"line":1,"why_vi":"Được quản đốc gọi thì thưa lại; hỏi lương hay khen nhà máy đều sai."},{"distractors":[{"furigana":"できません。","ja":"できません。","vi":"Em không tăng ca được ạ."},{"furigana":"{明日|あした}は{休|やす}みたいです。","ja":"明日は休みたいです。","vi":"Ngày mai em muốn nghỉ ạ."}],"line":3,"why_vi":"Được đề nghị tăng ca thì đồng ý và hỏi giờ; từ chối ngay hay hỏi ngày nghỉ đều sai."},{"distractors":[{"furigana":"{三十分|さんじゅっぷん}だけですか。","ja":"三十分だけですか。","vi":"Chỉ ba mươi phút thôi ạ?"},{"furigana":"{残業代|ざんぎょうだい}はいりません。","ja":"残業代はいりません。","vi":"Em không cần tiền tăng ca đâu ạ."}],"line":5,"why_vi":"Biết giờ tăng ca thì hỏi chế độ trả tiền; hỏi lại giờ hay từ chối trả tiền đều lạc nhịp."}]}', 'cpath-wrk-21', '7a8f7e1bcd88'),
  ('WRK-28', 'FACTORY-5S', 1, 'N3', '整理整頓の指示', 'Chỉ thị sắp xếp gọn gàng', 'Tổ trưởng nhắc nhở dọn dẹp sau giờ làm.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今日|きょう}は{何時|なんじ}に{帰|かえ}れますか。","ja":"今日は何時に帰れますか。","vi":"Hôm nay mấy giờ được về ạ?"},{"furigana":"{給料|きゅうりょう}は{上|あ}がりましたか。","ja":"給料は上がりましたか。","vi":"Lương đã tăng chưa ạ?"}],"line":1,"why_vi":"Muốn biết việc cần làm thì hỏi trực tiếp; hỏi giờ về hay lương đều sai."},{"distractors":[{"furigana":"{工具|こうぐ}はどこですか。","ja":"工具はどこですか。","vi":"Dụng cụ ở đâu ạ?"},{"furigana":"{片付|かたづ}けません。","ja":"片付けません。","vi":"Em không dọn đâu ạ."}],"line":3,"why_vi":"Được giao dọn dụng cụ thì hỏi đồ không cần xử lý sao; hỏi lại dụng cụ hay từ chối dọn đều sai."},{"distractors":[{"furigana":"{廃棄物|はいきぶつ}はどこに{置|お}きますか。","ja":"廃棄物はどこに置きますか。","vi":"Phế liệu để ở đâu ạ?"},{"furigana":"もう{全部|ぜんぶ}{終|お}わりました。","ja":"もう全部終わりました。","vi":"Em làm xong hết rồi ạ."}],"line":5,"why_vi":"Biết cách xử lý đồ bỏ thì hỏi có dọn vệ sinh không; hỏi lại đồ bỏ hay bảo xong rồi đều sai nhịp."}]}', 'cpath-wrk-28', '7a8f7e1bcd88'),
  ('WRK-29', 'FACTORY-5S', 2, 'N3', '掃除当番', 'Trực nhật vệ sinh', 'Hỏi đồng nghiệp về lịch trực vệ sinh.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今週|こんしゅう}の{休|やす}みはいつですか。","ja":"今週の休みはいつですか。","vi":"Tuần này nghỉ khi nào ạ?"},{"furigana":"ボーナスはいつですか。","ja":"ボーナスはいつですか。","vi":"Khi nào có thưởng ạ?"}],"line":1,"why_vi":"Muốn biết ai trực vệ sinh thì hỏi trực tiếp; hỏi lương hay giờ nghỉ đều sai."},{"distractors":[{"furigana":"{本当|ほんとう}に{私|わたし}たちですか。","ja":"本当に私たちですか。","vi":"Thật là chúng ta ạ?"},{"furigana":"{掃除|そうじ}はしたくないです。","ja":"掃除はしたくないです。","vi":"Em không muốn dọn vệ sinh ạ."}],"line":3,"why_vi":"Biết mình trực vệ sinh thì hỏi thời gian; hỏi lại ai trực hay từ chối trực đều sai."},{"distractors":[{"furigana":"{何分間|なんぷんかん}ですか。","ja":"何分間ですか。","vi":"Bao nhiêu phút ạ?"},{"furigana":"ほうきはありますか。","ja":"ほうきはありますか。","vi":"Có chổi không ạ?"}],"line":5,"why_vi":"Biết thời gian thì hỏi khu vực phụ trách; hỏi lại thời gian hay hỏi đồ dùng đều lạc đề."}]}', 'cpath-wrk-29', '7a8f7e1bcd88'),
  ('WRK-30', 'FACTORY-5S', 3, 'N3', '5Sの確認', 'Kiểm tra 5S', 'Đàn anh kiểm tra việc thực hiện 5S.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"もう{完璧|かんぺき}です。","ja":"もう完璧です。","vi":"Hoàn hảo rồi ạ."},{"furigana":"{点検|てんけん}は{必要|ひつよう}ありません。","ja":"点検は必要ありません。","vi":"Không cần kiểm tra đâu ạ."}],"line":1,"why_vi":"Muốn được kiểm tra thì nhờ đàn anh; tự khen mình giỏi hay hỏi lương đều sai."},{"distractors":[{"furigana":"まだ{戻|もど}していません。","ja":"まだ戻していません。","vi":"Em chưa để về ạ."},{"furigana":"{先輩|せんぱい}が{確認|かくにん}してください。","ja":"先輩が確認してください。","vi":"Anh tự kiểm tra đi ạ."}],"line":3,"why_vi":"Được hỏi dụng cụ thì xác nhận đã để về chỗ cũ; nói chưa dọn hay hỏi lại đàn anh đều sai."},{"distractors":[{"furigana":"{箱|はこ}を{置|お}いています。","ja":"箱を置いています。","vi":"Em có để hộp ạ."},{"furigana":"{分|わ}かりません。","ja":"分かりません。","vi":"Em không biết ạ."}],"line":5,"why_vi":"Được hỏi lối đi thì xác nhận không để đồ và sạch sẽ; nói có để đồ hay không biết đều mâu thuẫn."}]}', 'cpath-wrk-30', '7a8f7e1bcd88'),
  ('WRK-31', 'SERVICE-RECEPTION', 1, 'N3', 'ご来店のお客様', 'Đón khách đến cửa hàng', 'Nhân viên chào và hỏi nhu cầu của khách.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今日|きょう}は{何時|なんじ}に{閉|し}まりますか。","ja":"今日は何時に閉まりますか。","vi":"Hôm nay mấy giờ đóng cửa ạ?"},{"furigana":"ここで{働|はたら}きたいです。","ja":"ここで働きたいです。","vi":"Em muốn làm việc ở đây ạ."}],"line":1,"why_vi":"Vào cửa hàng thì hỏi có sản phẩm gợi ý không; hỏi giờ đóng cửa hay xin nghỉ đều sai."},{"distractors":[{"furigana":"{何|なに}も{探|さが}していません。","ja":"何も探していません。","vi":"Em không tìm gì ạ."},{"furigana":"この{店|みせ}は{高|たか}いですか。","ja":"この店は高いですか。","vi":"Cửa hàng này có đắt không ạ?"}],"line":3,"why_vi":"Được hỏi tìm gì thì nói đang tìm quà; nói chỉ xem chơi hay hỏi giá chung đều không trả lời đúng."},{"distractors":[{"furigana":"すぐ{買|か}います。","ja":"すぐ買います。","vi":"Em mua ngay ạ."},{"furigana":"もう{帰|かえ}ります。","ja":"もう帰ります。","vi":"Em về đây ạ."}],"line":5,"why_vi":"Được giới thiệu thì xin xem thử; đòi mua ngay hay bỏ đi đều chưa đúng bước."}]}', 'cpath-wrk-31', '7a8f7e1bcd88'),
  ('WRK-32', 'SERVICE-RECEPTION', 2, 'N3', '商品を探す', 'Tìm sản phẩm', 'Hỏi nhân viên vị trí sản phẩm cần tìm.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{傘|かさ}はいくらですか。","ja":"傘はいくらですか。","vi":"Ô giá bao nhiêu ạ?"},{"furigana":"ここで{働|はたら}けますか。","ja":"ここで働けますか。","vi":"Em làm việc ở đây được không ạ?"}],"line":1,"why_vi":"Muốn tìm quầy bán ô thì hỏi vị trí; hỏi giá ô hay xin việc đều sai."},{"distractors":[{"furigana":"{傘|かさ}の{売|う}り{場|ば}は{三階|さんがい}ですか。","ja":"傘の売り場は三階ですか。","vi":"Quầy bán ô ở tầng ba ạ?"},{"furigana":"{昼|ひる}ごはんはどこで{食|た}べますか。","ja":"昼ごはんはどこで食べますか。","vi":"Ăn trưa ở đâu ạ?"}],"line":3,"why_vi":"Biết chỗ bán ô thì hỏi thang cuốn để đi; hỏi lại chỗ bán ô hay hỏi giờ ăn đều sai."},{"distractors":[{"furigana":"{遠|とお}いですね。","ja":"遠いですね。","vi":"Xa quá nhỉ ạ."},{"furigana":"{分|わ}かりました。{行|い}きます。","ja":"分かりました。行きます。","vi":"Hiểu rồi. Em đi đây ạ."}],"line":5,"why_vi":"Được chỉ đường thì cảm ơn; phàn nàn xa hay bỏ đi không nói đều sai."}]}', 'cpath-wrk-32', '7a8f7e1bcd88'),
  ('WRK-33', 'SERVICE-RECEPTION', 3, 'N3', '試着のお願い', 'Xin thử đồ', 'Xin nhân viên cho thử quần áo.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"この{服|ふく}はいくらですか。","ja":"この服はいくらですか。","vi":"Bộ này bao nhiêu tiền ạ?"},{"furigana":"{安|やす}くしてください。","ja":"安くしてください。","vi":"Giảm giá cho em ạ."}],"line":1,"why_vi":"Muốn thử đồ thì nói thẳng; hỏi giá hay đòi giảm giá đều sai."},{"distractors":[{"furigana":"{試着室|しちゃくしつ}はどこですか。","ja":"試着室はどこですか。","vi":"Phòng thử ở đâu ạ?"},{"furigana":"{試着|しちゃく}しません。","ja":"試着しません。","vi":"Em không thử đâu ạ."}],"line":3,"why_vi":"Được chỉ phòng thử thì hỏi trường hợp không vừa có đổi được không; hỏi lại chỗ thử hay từ chối đều sai."},{"distractors":[{"furigana":"{本当|ほんとう}に{交換|こうかん}できますか。","ja":"本当に交換できますか。","vi":"Thật sự đổi được ạ?"},{"furigana":"いくらで{買|か}えますか。","ja":"いくらで買えますか。","vi":"Mua bao nhiêu ạ?"}],"line":5,"why_vi":"Biết đổi được thì hỏi màu khác; hỏi lại việc đổi hay hỏi giá lại đều lạc nhịp."}]}', 'cpath-wrk-33', '7a8f7e1bcd88'),
  ('WRK-34', 'SERVICE-PRODUCT', 1, 'N3', '新商品の紹介', 'Giới thiệu sản phẩm mới', 'Nhân viên giới thiệu sản phẩm mới cho khách.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"セールはいつですか。","ja":"セールはいつですか。","vi":"Khi nào có khuyến mãi ạ?"},{"furigana":"この{店|みせ}は{古|ふる}いですね。","ja":"この店は古いですね。","vi":"Cửa hàng này cũ nhỉ."}],"line":1,"why_vi":"Muốn biết sản phẩm mới thì hỏi trực tiếp; hỏi giờ đóng cửa hay giá đều sai."},{"distractors":[{"furigana":"いくらですか。","ja":"いくらですか。","vi":"Bao nhiêu tiền ạ?"},{"furigana":"{店員|てんいん}さんは{親切|しんせつ}ですね。","ja":"店員さんは親切ですね。","vi":"Nhân viên tốt bụng nhỉ."}],"line":3,"why_vi":"Được giới thiệu sản phẩm thì hỏi đặc điểm; hỏi giá ngay hay khen cửa hàng đều lạc đề."},{"distractors":[{"furigana":"{特徴|とくちょう}をもう{一度|いちど}{教|おし}えてください。","ja":"特徴をもう一度教えてください。","vi":"Nói lại đặc điểm lần nữa ạ."},{"furigana":"すぐ{買|か}います。","ja":"すぐ買います。","vi":"Em mua ngay ạ."}],"line":5,"why_vi":"Biết đặc điểm thì hỏi cách dùng có đơn giản không; hỏi lại đặc điểm hay đòi mua ngay đều sai nhịp."}]}', 'cpath-wrk-34', '7a8f7e1bcd88'),
  ('WRK-35', 'SERVICE-PRODUCT', 2, 'N3', '価格の確認', 'Hỏi giá', 'Hỏi giá và chương trình giảm giá.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"これは{何色|なにいろ}ですか。","ja":"これは何色ですか。","vi":"Cái này màu gì ạ?"},{"furigana":"これは{高|たか}いですね。","ja":"これは高いですね。","vi":"Cái này đắt nhỉ."}],"line":1,"why_vi":"Muốn biết giá thì hỏi trực tiếp; hỏi màu hay khen đều sai."},{"distractors":[{"furigana":"{何円|なんえん}ですか。","ja":"何円ですか。","vi":"Bao nhiêu yên ạ?"},{"furigana":"{千円|せんえん}にしてください。","ja":"千円にしてください。","vi":"Cho em một nghìn yên đi ạ."}],"line":3,"why_vi":"Biết giá thì hỏi có giảm giá không; hỏi lại giá hay mặc cả ngay đều sai nhịp."},{"distractors":[{"furigana":"{会員|かいいん}になりません。","ja":"会員になりません。","vi":"Em không làm hội viên đâu ạ."},{"furigana":"{全部|ぜんぶ}でいくらですか。","ja":"全部でいくらですか。","vi":"Tổng cộng bao nhiêu ạ?"}],"line":5,"why_vi":"Biết có giảm giá cho hội viên thì hỏi cách làm thẻ; từ chối làm thẻ hay hỏi giá lại đều sai."}]}', 'cpath-wrk-35', '7a8f7e1bcd88'),
  ('WRK-36', 'SERVICE-PRODUCT', 3, 'N3', '使い方の説明', 'Hướng dẫn cách dùng', 'Nhờ nhân viên hướng dẫn cách dùng sản phẩm.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"この{製品|せいひん}はいくらですか。","ja":"この製品はいくらですか。","vi":"Sản phẩm này bao nhiêu ạ?"},{"furigana":"{自分|じぶん}でやってみます。","ja":"自分でやってみます。","vi":"Em tự thử ạ."}],"line":1,"why_vi":"Muốn biết cách dùng thì nhờ hướng dẫn; hỏi giá hay tự ý dùng đều sai."},{"distractors":[{"furigana":"もう{一度|いちど}{言|い}ってください。","ja":"もう一度言ってください。","vi":"Nói lại lần nữa ạ."},{"furigana":"{難|むずか}しそうです。やめます。","ja":"難しそうです。やめます。","vi":"Khó quá, em bỏ ạ."}],"line":3,"why_vi":"Nghe bước đầu thì hỏi bước tiếp; hỏi lại bước đầu hay bỏ cuộc đều sai."},{"distractors":[{"furigana":"ボタンはどこですか。","ja":"ボタンはどこですか。","vi":"Nút ở đâu ạ?"},{"furigana":"もう{返品|へんぴん}したいです。","ja":"もう返品したいです。","vi":"Em muốn trả hàng rồi ạ."}],"line":5,"why_vi":"Biết cách dùng thì hỏi sách hướng dẫn; hỏi lại nút hay đòi trả hàng đều lạc nhịp."}]}', 'cpath-wrk-36', '7a8f7e1bcd88'),
  ('WRK-37', 'SERVICE-PAYMENT', 1, 'N3', '支払い方法', 'Phương thức thanh toán', 'Hỏi phương thức thanh toán khi mua hàng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"トイレはどこですか。","ja":"トイレはどこですか。","vi":"Nhà vệ sinh ở đâu ạ?"},{"furigana":"{今日|きょう}は{何時|なんじ}に{閉|し}まりますか。","ja":"今日は何時に閉まりますか。","vi":"Hôm nay mấy giờ đóng cửa ạ?"}],"line":1,"why_vi":"Muốn thanh toán thì nói rõ; hỏi giờ đóng cửa hay xin việc đều sai."},{"distractors":[{"furigana":"{分|わ}かりません。","ja":"分かりません。","vi":"Em không biết ạ."},{"furigana":"{分割払|ぶんかつばら}いにします。","ja":"分割払いにします。","vi":"Em trả góp ạ."}],"line":3,"why_vi":"Được hỏi cách thanh toán thì chọn trả thẻ; nói không biết hay đòi trả góp ngay đều sai."},{"distractors":[{"furigana":"{暗証番号|あんしょうばんごう}を{忘|わす}れました。","ja":"暗証番号を忘れました。","vi":"Em quên mã PIN ạ."},{"furigana":"{現金|げんきん}にします。","ja":"現金にします。","vi":"Em trả tiền mặt ạ."}],"line":5,"why_vi":"Được yêu cầu nhập mã thì hỏi trả một lần có được không; từ chối nhập mã hay hỏi lại phương thức đều sai."}]}', 'cpath-wrk-37', '7a8f7e1bcd88'),
  ('WRK-38', 'SERVICE-PAYMENT', 2, 'N3', '領収書のお願い', 'Xin biên lai', 'Xin biên lai sau khi thanh toán.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"お{釣|つ}りはいくらですか。","ja":"お釣りはいくらですか。","vi":"Tiền thừa bao nhiêu ạ?"},{"furigana":"{袋|ふくろ}はいりません。","ja":"袋はいりません。","vi":"Em không cần túi ạ."}],"line":1,"why_vi":"Muốn biên lai thì xin trực tiếp; hỏi giờ đóng cửa hay giá đều sai."},{"distractors":[{"furigana":"{私|わたし}の{名前|なまえ}でお{願|ねが}いします。","ja":"私の名前でお願いします。","vi":"Ghi tên em ạ."},{"furigana":"{宛名|あてな}はいりません。","ja":"宛名はいりません。","vi":"Không cần người nhận ạ."}],"line":3,"why_vi":"Được hỏi người nhận thì nói ghi tên công ty; ghi tên mình hay không ghi đều sai."},{"distractors":[{"furigana":"{宛名|あてな}を{変|か}えてください。","ja":"宛名を変えてください。","vi":"Đổi người nhận đi ạ."},{"furigana":"もう{結構|けっこう}です。","ja":"もう結構です。","vi":"Thôi được rồi ạ."}],"line":5,"why_vi":"Đã xin biên lai thì hỏi thêm hóa đơn; hỏi lại người nhận hay từ chối nhận đều sai nhịp."}]}', 'cpath-wrk-38', '7a8f7e1bcd88'),
  ('WRK-39', 'SERVICE-PAYMENT', 3, 'N3', 'クーポンの利用', 'Dùng phiếu ưu đãi', 'Hỏi dùng phiếu ưu đãi khi thanh toán.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{安|やす}くしてください。","ja":"安くしてください。","vi":"Giảm giá cho em ạ."},{"furigana":"お{店|みせ}は{何時|なんじ}までですか。","ja":"お店は何時までですか。","vi":"Cửa hàng mở đến mấy giờ ạ?"}],"line":1,"why_vi":"Có phiếu thì hỏi dùng được không; tự ý trừ tiền hay hỏi giờ nghỉ đều sai."},{"distractors":[{"furigana":"{本当|ほんとう}に{使|つか}えますか。","ja":"本当に使えますか。","vi":"Thật dùng được ạ?"},{"furigana":"{無料|むりょう}にしてください。","ja":"無料にしてください。","vi":"Cho em miễn phí ạ."}],"line":3,"why_vi":"Biết dùng được thì hỏi giảm bao nhiêu phần trăm; hỏi lại có dùng được không hay đòi miễn phí đều sai."},{"distractors":[{"furigana":"{何|なん}パーセントですか。","ja":"何パーセントですか。","vi":"Bao nhiêu phần trăm ạ?"},{"furigana":"このクーポンはいりません。","ja":"このクーポンはいりません。","vi":"Em không cần phiếu này ạ."}],"line":5,"why_vi":"Biết mức giảm thì hỏi có dùng chung với thẻ điểm không; hỏi lại phần trăm hay bỏ phiếu đều sai nhịp."}]}', 'cpath-wrk-39', '7a8f7e1bcd88'),
  ('WRK-43', 'SERVICE-BOOKING', 1, 'N3', '部屋の予約', 'Đặt phòng', 'Đặt phòng khách sạn qua quầy lễ tân.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{朝食|ちょうしょく}は{何時|なんじ}ですか。","ja":"朝食は何時ですか。","vi":"Bữa sáng mấy giờ ạ?"},{"furigana":"ここで{働|はたら}きたいです。","ja":"ここで働きたいです。","vi":"Em muốn làm ở đây ạ."}],"line":1,"why_vi":"Muốn đặt phòng thì nói thẳng; hỏi ăn gì hay xin việc đều sai."},{"distractors":[{"furigana":"{一|いっ}か{月|げつ}{泊|と}まります。","ja":"一か月泊まります。","vi":"Em ở một tháng ạ."},{"furigana":"{全部|ぜんぶ}でいくらですか。","ja":"全部でいくらですか。","vi":"Tổng cộng bao nhiêu ạ?"}],"line":3,"why_vi":"Được hỏi số đêm thì trả lời và hỏi loại phòng; nói ở lâu hay hỏi giá ngay đều sai nhịp."},{"distractors":[{"furigana":"{本当|ほんとう}に{空|あ}いていますか。","ja":"本当に空いていますか。","vi":"Thật còn phòng ạ?"},{"furigana":"{無料|むりょう}にしてください。","ja":"無料にしてください。","vi":"Cho em miễn phí ạ."}],"line":5,"why_vi":"Biết còn phòng thì hỏi giá một đêm; hỏi lại có phòng không hay đòi miễn phí đều sai."}]}', 'cpath-wrk-43', '7a8f7e1bcd88'),
  ('WRK-44', 'SERVICE-BOOKING', 2, 'N3', 'チェックイン', 'Nhận phòng', 'Làm thủ tục nhận phòng tại khách sạn.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{朝食|ちょうしょく}は{何時|なんじ}からですか。","ja":"朝食は何時からですか。","vi":"Bữa sáng từ mấy giờ ạ?"},{"furigana":"このホテルは{古|ふる}いですか。","ja":"このホテルは古いですか。","vi":"Khách sạn này cũ không ạ?"}],"line":1,"why_vi":"Muốn nhận phòng thì nói rõ; hỏi ăn sáng hay giá đều sai."},{"distractors":[{"furigana":"{名前|なまえ}を{忘|わす}れました。","ja":"名前を忘れました。","vi":"Em quên tên ạ."},{"furigana":"{予約|よやく}していません。","ja":"予約していません。","vi":"Em chưa đặt phòng ạ."}],"line":3,"why_vi":"Được hỏi tên thì nói tên và đã đặt phòng; nói không nhớ tên hay chưa đặt đều sai."},{"distractors":[{"furigana":"{名前|なまえ}をもう{一度|いちど}{言|い}いますか。","ja":"名前をもう一度言いますか。","vi":"Em nói lại tên ạ?"},{"furigana":"{今|いま}すぐ{部屋|へや}に{入|はい}りたいです。","ja":"今すぐ部屋に入りたいです。","vi":"Em muốn vào phòng ngay ạ."}],"line":5,"why_vi":"Đã khai tên thì hỏi nhận chìa khóa ở đâu; hỏi lại tên hay đòi vào phòng ngay đều sai nhịp."}]}', 'cpath-wrk-44', '7a8f7e1bcd88'),
  ('WRK-45', 'SERVICE-BOOKING', 3, 'N3', '料金の確認', 'Hỏi phí', 'Hỏi phí lưu trú và các khoản kèm theo.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今日|きょう}の{夕食|ゆうしょく}は{何|なん}ですか。","ja":"今日の夕食は何ですか。","vi":"Bữa tối nay là gì ạ?"},{"furigana":"このホテルはきれいですね。","ja":"このホテルはきれいですね。","vi":"Khách sạn này đẹp nhỉ."}],"line":1,"why_vi":"Muốn biết phí thì hỏi trực tiếp; hỏi ăn gì hay khen khách sạn đều sai."},{"distractors":[{"furigana":"{一泊|いっぱく}いくらですか。","ja":"一泊いくらですか。","vi":"Một đêm bao nhiêu ạ?"},{"furigana":"{安|やす}くしてください。","ja":"安くしてください。","vi":"Giảm giá cho em ạ."}],"line":3,"why_vi":"Biết phí thì hỏi đã gồm bữa sáng chưa; hỏi lại phí hay đòi giảm giá đều sai nhịp."},{"distractors":[{"furigana":"{朝食|ちょうしょく}はどこで{食|た}べますか。","ja":"朝食はどこで食べますか。","vi":"Ăn sáng ở đâu ạ?"},{"furigana":"{午後|ごご}まで{泊|と}まりたいです。","ja":"午後まで泊まりたいです。","vi":"Em muốn ở đến chiều ạ."}],"line":5,"why_vi":"Biết bữa sáng tính riêng thì hỏi giờ trả phòng; hỏi lại bữa sáng hay đòi trả phòng muộn đều sai."}]}', 'cpath-wrk-45', '7a8f7e1bcd88'),
  ('WRK-04', 'OFFICE-REPORT', 1, 'N2', '進捗報告', 'Báo cáo tiến độ', 'Báo cáo tiến độ công việc cho sếp.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{明日|あした}、{休暇|きゅうか}を{取|と}れますか。","ja":"明日、休暇を取れますか。","vi":"Ngày mai em xin nghỉ được không ạ?"},{"furigana":"{部長|ぶちょう}はお{元気|げんき}ですか。","ja":"部長はお元気ですか。","vi":"Trưởng phòng khỏe không ạ?"}],"line":1,"why_vi":"Muốn báo cáo thì mở đầu nêu chủ đề; hỏi nghỉ phép hay khen sếp đều sai việc."},{"distractors":[{"furigana":"まだ{何|なに}もしていません。","ja":"まだ何もしていません。","vi":"Em chưa làm gì cả ạ."},{"furigana":"{部長|ぶちょう}の{意見|いけん}はどうですか。","ja":"部長の意見はどうですか。","vi":"Trưởng phòng thấy sao ạ?"}],"line":3,"why_vi":"Sếp mời báo cáo thì nêu mức hoàn thành; nói chưa bắt đầu hay hỏi ngược sếp đều sai."},{"distractors":[{"furigana":"{間|ま}に{合|あ}いません。","ja":"間に合いません。","vi":"Không kịp ạ."},{"furigana":"{締|し}め{切|き}りを{延|の}ばしてください。","ja":"締め切りを延ばしてください。","vi":"Xin gia hạn thời hạn ạ."}],"line":5,"why_vi":"Sếp hỏi hạn thì cam kết nộp ngày mai; nói không kịp hay đòi gia hạn đều mâu thuẫn với tiến độ bảy mươi phần trăm."}]}', 'cpath-wrk-04', '7a8f7e1bcd88'),
  ('WRK-05', 'OFFICE-REPORT', 2, 'N2', 'トラブルの報告', 'Báo cáo sự cố', 'Báo cáo trục trặc trong công việc cho sếp.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{部長|ぶちょう}、ランチに{行|い}きませんか。","ja":"部長、ランチに行きませんか。","vi":"Trưởng phòng, đi ăn trưa không ạ?"},{"furigana":"{今日|きょう}はいい{天気|てんき}ですね。","ja":"今日はいい天気ですね。","vi":"Hôm nay trời đẹp nhỉ."}],"line":1,"why_vi":"Có việc cần báo thì mở lời xin báo cáo; nói chuyện riêng hay khen sếp đều sai."},{"distractors":[{"furigana":"{問題|もんだい}はありません。","ja":"問題はありません。","vi":"Không có vấn đề gì ạ."},{"furigana":"{今日|きょう}は{体調|たいちょう}が{悪|わる}いです。","ja":"今日は体調が悪いです。","vi":"Hôm nay em không khỏe ạ."}],"line":3,"why_vi":"Sếp hỏi thì nêu sự cố là phản hồi bị chậm; nói mọi việc ổn hay báo nghỉ ốm đều sai."},{"distractors":[{"furigana":"{分|わ}かりません。","ja":"分かりません。","vi":"Em không biết ạ."},{"furigana":"{相手|あいて}のせいです。","ja":"相手のせいです。","vi":"Là do đối tác ạ."}],"line":5,"why_vi":"Sếp hỏi nguyên nhân thì giải thích người phụ trách vắng mặt; nói không rõ nguyên nhân hay đổ lỗi cho khách đều chưa tốt."}]}', 'cpath-wrk-05', '7a8f7e1bcd88'),
  ('WRK-06', 'OFFICE-REPORT', 3, 'N2', '結果報告', 'Báo cáo kết quả', 'Báo cáo kết quả công việc đã hoàn thành.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{作業|さぎょう}はまだ{途中|とちゅう}です。","ja":"作業はまだ途中です。","vi":"Việc vẫn đang làm dở ạ."},{"furigana":"{今日|きょう}は{早退|そうたい}したいです。","ja":"今日は早退したいです。","vi":"Hôm nay em muốn về sớm ạ."}],"line":1,"why_vi":"Muốn báo cáo hoàn tất thì nói rõ việc đã xong; báo đang làm dở hay xin nghỉ đều sai."},{"distractors":[{"furigana":"{少|すこ}しミスがありました。","ja":"少しミスがありました。","vi":"Có chút sai sót ạ."},{"furigana":"まだ{完成|かんせい}していません。","ja":"まだ完成していません。","vi":"Vẫn chưa hoàn thành ạ."}],"line":3,"why_vi":"Sếp hỏi kết quả thì khẳng định ổn và đưa báo cáo; nói có sai sót hay chưa làm xong đều mâu thuẫn."},{"distractors":[{"furigana":"{確認|かくにん}していません。","ja":"確認していません。","vi":"Em chưa kiểm tra ạ."},{"furigana":"{部長|ぶちょう}が{直|なお}しましたか。","ja":"部長が直しましたか。","vi":"Trưởng phòng đã sửa ạ?"}],"line":5,"why_vi":"Sếp khen số liệu khớp thì nói đã kiểm tra kỹ; nói chưa kiểm tra hay hỏi lại sếp đều sai."}]}', 'cpath-wrk-06', '7a8f7e1bcd88'),
  ('WRK-13', 'OFFICE-MEETING', 1, 'N2', '会議の準備', 'Chuẩn bị họp', 'Chuẩn bị phòng họp và tài liệu.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"まだ{準備|じゅんび}していません。","ja":"まだ準備していません。","vi":"Em chưa chuẩn bị ạ."},{"furigana":"{会議|かいぎ}に{出|で}たくないです。","ja":"会議に出たくないです。","vi":"Em không muốn dự họp ạ."}],"line":1,"why_vi":"Muốn báo cáo chuẩn bị xong thì nói rõ; báo chưa chuẩn bị hay xin nghỉ đều sai."},{"distractors":[{"furigana":"まだ{印刷|いんさつ}していません。","ja":"まだ印刷していません。","vi":"Em chưa in ạ."},{"furigana":"{五部|ごぶ}だけです。","ja":"五部だけです。","vi":"Chỉ có năm bộ ạ."}],"line":3,"why_vi":"Sếp hỏi tài liệu thì báo đã in đủ số; nói in thiếu hay chưa in đều mâu thuẫn với việc đã chuẩn bị xong."},{"distractors":[{"furigana":"{確認|かくにん}していません。","ja":"確認していません。","vi":"Em chưa kiểm tra ạ."},{"furigana":"{壊|こわ}れています。","ja":"壊れています。","vi":"Máy hỏng rồi ạ."}],"line":5,"why_vi":"Sếp hỏi máy chiếu thì xác nhận hoạt động tốt; nói chưa kiểm tra hay máy hỏng đều sai."}]}', 'cpath-wrk-13', '7a8f7e1bcd88'),
  ('WRK-14', 'OFFICE-MEETING', 2, 'N2', '会議で意見を言う', 'Phát biểu trong họp', 'Nêu ý kiến về kế hoạch trong cuộc họp.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"この{計画|けいかく}は{完璧|かんぺき}です。","ja":"この計画は完璧です。","vi":"Kế hoạch này hoàn hảo ạ."},{"furigana":"{会議室|かいぎしつ}は{広|ひろ}いですね。","ja":"会議室は広いですね。","vi":"Phòng họp rộng nhỉ."}],"line":1,"why_vi":"Muốn phát biểu thì xin phép nêu ý kiến; tự ý nói to hay khen phòng họp đều sai."},{"distractors":[{"furigana":"{特|とく}に{意見|いけん}はありません。","ja":"特に意見はありません。","vi":"Em không có ý kiến gì ạ."},{"furigana":"とてもいい{計画|けいかく}です。","ja":"とてもいい計画です。","vi":"Kế hoạch rất hay ạ."}],"line":3,"why_vi":"Được mời nói thì nêu vấn đề ngân sách thiếu; khen kế hoạch hay nói không ý kiến đều không phát biểu thực chất."},{"distractors":[{"furigana":"{分|わ}かりません。","ja":"分かりません。","vi":"Em không biết ạ."},{"furigana":"{一円|いちえん}も{要|い}りません。","ja":"一円も要りません。","vi":"Không cần đồng nào ạ."}],"line":5,"why_vi":"Sếp hỏi con số cụ thể thì nêu số tiền cần thêm; nói không biết hay đưa con số vô lý đều không thuyết phục."}]}', 'cpath-wrk-14', '7a8f7e1bcd88'),
  ('WRK-15', 'OFFICE-MEETING', 3, 'N2', '議事録の確認', 'Xác nhận biên bản họp', 'Nhờ đồng nghiệp kiểm tra biên bản họp.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{議事録|ぎじろく}はまだです。","ja":"議事録はまだです。","vi":"Biên bản vẫn chưa xong ạ."},{"furigana":"{会議室|かいぎしつ}を{予約|よやく}しました。","ja":"会議室を予約しました。","vi":"Em đã đặt phòng họp ạ."}],"line":1,"why_vi":"Muốn báo cáo thì nói đã soạn xong biên bản; báo chưa làm hay nói việc khác đều sai."},{"distractors":[{"furigana":"{見|み}ないでください。","ja":"見ないでください。","vi":"Đừng xem ạ."},{"furigana":"{大丈夫|だいじょうぶ}です。","ja":"大丈夫です。","vi":"Không cần đâu ạ."}],"line":3,"why_vi":"Đồng nghiệp muốn xem thì đồng ý và nhờ báo lỗi chính tả; từ chối cho xem hay bảo tự mình xem là đủ đều sai."},{"distractors":[{"furigana":"{問題|もんだい}ありません。","ja":"問題ありません。","vi":"Không có vấn đề gì ạ."},{"furigana":"{自分|じぶん}で{直|なお}してください。","ja":"自分で直してください。","vi":"Anh tự sửa đi ạ."}],"line":5,"why_vi":"Được góp ý thì nhận lời viết lại; phủ nhận lỗi hay bảo đồng nghiệp tự sửa đều chưa tốt."}]}', 'cpath-wrk-15', '7a8f7e1bcd88'),
  ('WRK-22', 'FACTORY-INSTRUCTION', 1, 'N2', '作業手順の確認', 'Xác nhận quy trình', 'Hỏi đàn anh về quy trình lắp ráp.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{自分|じぶん}でやります。","ja":"自分でやります。","vi":"Em tự làm ạ."},{"furigana":"この{仕事|しごと}の{給料|きゅうりょう}はいくらですか。","ja":"この仕事の給料はいくらですか。","vi":"Việc này lương bao nhiêu ạ?"}],"line":1,"why_vi":"Muốn học quy trình thì nhờ chỉ dẫn; tự ý làm hay hỏi lương đều sai."},{"distractors":[{"furigana":"もう{一度|いちど}{言|い}ってください。","ja":"もう一度言ってください。","vi":"Nói lại lần nữa ạ."},{"furigana":"{難|むずか}しそうですね。やめます。","ja":"難しそうですね。やめます。","vi":"Khó quá, em bỏ ạ."}],"line":3,"why_vi":"Nghe bước một thì hỏi bước tiếp theo; hỏi lại bước một hay bỏ cuộc đều sai."},{"distractors":[{"furigana":"ネジは{何本|なんぼん}ですか。","ja":"ネジは何本ですか。","vi":"Mấy con ốc vít ạ?"},{"furigana":"もう{終|お}わりました。","ja":"もう終わりました。","vi":"Em làm xong rồi ạ."}],"line":5,"why_vi":"Nghe bước vặn ốc thì hỏi bước kiểm tra cuối; hỏi lại ốc hay nói xong rồi đều sai nhịp."}]}', 'cpath-wrk-22', '7a8f7e1bcd88'),
  ('WRK-23', 'FACTORY-INSTRUCTION', 2, 'N2', '指示を聞く', 'Nghe chỉ thị', 'Tổ trưởng giao việc và dặn dò số lượng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今日|きょう}の{休憩|きゅうけい}は{何時|なんじ}ですか。","ja":"今日の休憩は何時ですか。","vi":"Hôm nay nghỉ giải lao mấy giờ ạ?"},{"furigana":"ボーナスは{出|で}ますか。","ja":"ボーナスは出ますか。","vi":"Có thưởng không ạ?"}],"line":1,"why_vi":"Muốn nhận việc thì xin giao việc; hỏi giờ nghỉ hay lương đều sai."},{"distractors":[{"furigana":"{何個|なんこ}ですか。","ja":"何個ですか。","vi":"Bao nhiêu cái ạ?"},{"furigana":"{百個|ひゃっこ}は{多|おお}すぎます。","ja":"百個は多すぎます。","vi":"Một trăm cái nhiều quá ạ."}],"line":3,"why_vi":"Nhận việc thì hỏi tiêu chuẩn có giống mọi khi không; hỏi lại số lượng hay từ chối làm đều sai."},{"distractors":[{"furigana":"{基準|きじゅん}を{教|おし}えてください。","ja":"基準を教えてください。","vi":"Cho em biết tiêu chuẩn ạ."},{"furigana":"もうすぐ{終|お}わります。","ja":"もうすぐ終わります。","vi":"Em sắp xong rồi ạ."}],"line":5,"why_vi":"Biết tiêu chuẩn thì hỏi hạn hoàn thành; hỏi lại tiêu chuẩn hay nói làm xong ngay đều sai nhịp."}]}', 'cpath-wrk-23', '7a8f7e1bcd88'),
  ('WRK-24', 'FACTORY-INSTRUCTION', 3, 'N2', '数量の確認', 'Xác nhận số lượng', 'Kiểm tra số lượng hàng cần giao.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{今日|きょう}の{昼|ひる}ごはんは{何|なん}ですか。","ja":"今日の昼ごはんは何ですか。","vi":"Bữa trưa nay là gì ạ?"},{"furigana":"この{製品|せいひん}はいくらで{売|う}りますか。","ja":"この製品はいくらで売りますか。","vi":"Sản phẩm này bán bao nhiêu ạ?"}],"line":1,"why_vi":"Muốn biết số lượng giao thì hỏi trực tiếp; hỏi giá hay giờ nghỉ đều sai."},{"distractors":[{"furigana":"{全部|ぜんぶ}で{二百個|にひゃっこ}ですか。","ja":"全部で二百個ですか。","vi":"Tổng cộng hai trăm cái ạ?"},{"furigana":"{箱|はこ}の{色|いろ}は{何色|なにいろ}ですか。","ja":"箱の色は何色ですか。","vi":"Hộp màu gì ạ?"}],"line":3,"why_vi":"Biết tổng số và đơn vị thì hỏi số lượng mỗi hộp; hỏi lại tổng số hay hỏi màu hộp đều sai."},{"distractors":[{"furigana":"{二十個|にじゅっこ}ですか。","ja":"二十個ですか。","vi":"Hai mươi cái ạ?"},{"furigana":"{今日|きょう}はもう{帰|かえ}りたいです。","ja":"今日はもう帰りたいです。","vi":"Hôm nay em muốn về rồi ạ."}],"line":5,"why_vi":"Tính ra mười hộp thì xác nhận và đi kiểm tra; hỏi lại số lượng mỗi hộp hay đòi nghỉ đều sai."}]}', 'cpath-wrk-24', '7a8f7e1bcd88'),
  ('WRK-25', 'FACTORY-ERROR', 1, 'N2', '機械の故障を報告', 'Báo máy hỏng', 'Báo máy dừng đột ngột cho tổ trưởng.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{機械|きかい}は{動|うご}いています。","ja":"機械は動いています。","vi":"Máy đang chạy ạ."},{"furigana":"{今日|きょう}の{作業|さぎょう}は{終|お}わりました。","ja":"今日の作業は終わりました。","vi":"Việc hôm nay đã xong ạ."}],"line":1,"why_vi":"Máy hỏng thì báo ngay tình trạng; khen máy chạy tốt hay báo đi ăn đều sai."},{"distractors":[{"furigana":"{緑|みどり}のランプが{点|つ}いています。","ja":"緑のランプが点いています。","vi":"Đèn xanh đang sáng ạ."},{"furigana":"ランプは{消|き}えています。","ja":"ランプは消えています。","vi":"Đèn đã tắt ạ."}],"line":3,"why_vi":"Được hỏi đèn báo thì miêu tả đèn đỏ nhấp nháy; nói đèn xanh hay không thấy đèn đều mâu thuẫn."},{"distractors":[{"furigana":"{機械|きかい}が{直|なお}りました。","ja":"機械が直りました。","vi":"Máy tự hết hỏng rồi ạ."},{"furigana":"このまま{帰|かえ}ります。","ja":"このまま帰ります。","vi":"Em về luôn đây ạ."}],"line":5,"why_vi":"Được chỉ nhấn nút dừng thì hỏi có gọi thợ sửa không; bảo máy tự chạy lại hay bỏ đi đều sai."}]}', 'cpath-wrk-25', '7a8f7e1bcd88'),
  ('WRK-26', 'FACTORY-ERROR', 2, 'N2', '異常音の報告', 'Báo tiếng kêu lạ', 'Báo tiếng kêu lạ phát ra từ máy.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{機械|きかい}は{静|しず}かです。","ja":"機械は静かです。","vi":"Máy im lặng ạ."},{"furigana":"この{機械|きかい}は{新|あたら}しいですね。","ja":"この機械は新しいですね。","vi":"Máy này mới nhỉ."}],"line":1,"why_vi":"Nghe tiếng lạ thì báo ngay; nói máy im lặng hay khen máy mới đều sai."},{"distractors":[{"furigana":"{分|わ}かりません。","ja":"分かりません。","vi":"Em không biết ạ."},{"furigana":"きれいな{音|おと}です。","ja":"きれいな音です。","vi":"Tiếng hay ạ."}],"line":3,"why_vi":"Được hỏi tiếng gì thì miêu tả tiếng lạch cạch; nói không rõ hay bảo tiếng đẹp đều không trả lời câu hỏi."},{"distractors":[{"furigana":"{止|と}めなくてもいいです。","ja":"止めなくてもいいです。","vi":"Không cần dừng máy đâu ạ."},{"furigana":"{点検|てんけん}はしません。","ja":"点検はしません。","vi":"Em không kiểm tra đâu ạ."}],"line":5,"why_vi":"Được đề nghị dừng máy thì hỏi xác nhận kiểm tra; bảo cứ để máy chạy hay bỏ đi đều sai."}]}', 'cpath-wrk-26', '7a8f7e1bcd88'),
  ('WRK-27', 'FACTORY-ERROR', 3, 'N2', '応急処置', 'Xử lý tạm thời', 'Hướng dẫn xử lý tạm thời khi máy có vấn đề.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"{機械|きかい}は{正常|せいじょう}です。","ja":"機械は正常です。","vi":"Máy bình thường ạ."},{"furigana":"この{工場|こうじょう}はきれいですね。","ja":"この工場はきれいですね。","vi":"Nhà máy này sạch nhỉ."}],"line":1,"why_vi":"Phát hiện rò dầu thì báo ngay; nói máy bình thường hay khen nhà máy đều sai."},{"distractors":[{"furigana":"{本当|ほんとう}に{止|と}めますか。","ja":"本当に止めますか。","vi":"Thật sự dừng máy ạ?"},{"furigana":"このままにします。","ja":"このままにします。","vi":"Em cứ để nguyên vậy ạ."}],"line":3,"why_vi":"Được yêu cầu dừng máy thì hỏi cách xử lý tạm thời; hỏi lại có phải dừng máy không hay bỏ đi đều sai."},{"distractors":[{"furigana":"どうやって{拭|ふ}きますか。","ja":"どうやって拭きますか。","vi":"Lau bằng cách nào ạ?"},{"furigana":"{報告|ほうこく}はしません。","ja":"報告はしません。","vi":"Em không báo cáo đâu ạ."}],"line":5,"why_vi":"Nghe hướng dẫn lau dầu thì hỏi có cần báo cáo sau đó không; hỏi lại cách lau hay bảo không báo cáo đều sai."}]}', 'cpath-wrk-27', '7a8f7e1bcd88'),
  ('WRK-40', 'SERVICE-COMPLAINT', 1, 'N2', '不良品の苦情', 'Phàn nàn hàng lỗi', 'Khách phàn nàn về sản phẩm bị lỗi.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"この{商品|しょうひん}は{素晴|すば}らしいです。","ja":"この商品は素晴らしいです。","vi":"Sản phẩm này tuyệt vời ạ."},{"furigana":"もう{一|ひと}つ{買|か}いたいです。","ja":"もう一つ買いたいです。","vi":"Em muốn mua thêm một cái ạ."}],"line":1,"why_vi":"Sản phẩm lỗi thì báo ngay tình trạng; khen sản phẩm hay xin thêm đồ đều sai."},{"distractors":[{"furigana":"{自分|じぶん}で{傷|きず}つけました。","ja":"自分で傷つけました。","vi":"Em tự làm xước ạ."},{"furigana":"{分|わ}かりません。","ja":"分かりません。","vi":"Em không biết ạ."}],"line":3,"why_vi":"Được hỏi thì nói rõ vết xước có từ lúc mở; nói tự làm xước hay không nhớ đều sai."},{"distractors":[{"furigana":"{取|と}り{替|か}えはいりません。","ja":"取り替えはいりません。","vi":"Em không cần đổi ạ."},{"furigana":"{賠償金|ばいしょうきん}を{払|はら}ってください。","ja":"賠償金を払ってください。","vi":"Trả tiền bồi thường đi ạ."}],"line":5,"why_vi":"Được đề nghị đổi mới thì hỏi có hoàn tiền không; từ chối cả hai hay đòi bồi thường lớn đều sai nhịp."}]}', 'cpath-wrk-40', '7a8f7e1bcd88'),
  ('WRK-41', 'SERVICE-COMPLAINT', 2, 'N2', '返金の依頼', 'Yêu cầu hoàn tiền', 'Khách yêu cầu hoàn tiền với quản lý.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"この{店|みせ}は{最悪|さいあく}です。","ja":"この店は最悪です。","vi":"Cửa hàng này tệ nhất ạ."},{"furigana":"もう{来|き}ません。","ja":"もう来ません。","vi":"Em không đến nữa đâu ạ."}],"line":1,"why_vi":"Muốn hoàn tiền thì nói thẳng với quản lý; chửi bới hay bỏ đi đều sai."},{"distractors":[{"furigana":"{昨日|きのう}の{天気|てんき}は{良|よ}かったです。","ja":"昨日の天気は良かったです。","vi":"Hôm qua trời đẹp ạ."},{"furigana":"{特|とく}に{何|なに}もありません。","ja":"特に何もありません。","vi":"Không có gì đặc biệt ạ."}],"line":3,"why_vi":"Được hỏi diễn biến thì nói sản phẩm lỗi ban đầu; kể chuyện khác hay không trả lời đều sai."},{"distractors":[{"furigana":"もっとお{金|かね}をください。","ja":"もっとお金をください。","vi":"Đưa thêm tiền cho em ạ."},{"furigana":"では、さようなら。","ja":"では、さようなら。","vi":"Vậy tạm biệt ạ."}],"line":5,"why_vi":"Được hứa hoàn tiền thì hỏi nhận lời xin lỗi; đòi thêm tiền hay bỏ đi đều sai."}]}', 'cpath-wrk-41', '7a8f7e1bcd88'),
  ('WRK-42', 'SERVICE-COMPLAINT', 3, 'N2', 'お詫びと対応', 'Xin lỗi và xử lý', 'Nhân viên xin lỗi và đề xuất cách giải quyết.', '{"learnerSpeaker":"リン","turns":[{"distractors":[{"furigana":"この{店|みせ}は{本当|ほんとう}にいい{店|みせ}ですね。","ja":"この店は本当にいい店ですね。","vi":"Cửa hàng này thật tốt nhỉ."},{"furigana":"{新商品|しんしょうひん}はありますか。","ja":"新商品はありますか。","vi":"Có sản phẩm mới không ạ?"}],"line":1,"why_vi":"Muốn biết tiến triển khiếu nại thì hỏi trực tiếp; khen cửa hàng hay hỏi mua hàng mới đều sai."},{"distractors":[{"furigana":"それはいくらですか。","ja":"それはいくらですか。","vi":"Cái đó bao nhiêu ạ?"},{"furigana":"もういいです。","ja":"もういいです。","vi":"Thôi được rồi ạ."}],"line":3,"why_vi":"Nhận lời xin lỗi thì hỏi đã biết nguyên nhân chưa; hỏi giá hay bỏ qua ngay đều sai nhịp."},{"distractors":[{"furigana":"{原因|げんいん}をもう{一度|いちど}{言|い}ってください。","ja":"原因をもう一度言ってください。","vi":"Nói lại nguyên nhân ạ."},{"furigana":"{賠償|ばいしょう}してください。","ja":"賠償してください。","vi":"Bồi thường đi ạ."}],"line":5,"why_vi":"Biết nguyên nhân thì hỏi cách xử lý sau này; hỏi lại nguyên nhân hay đòi bồi thường đều sai."}]}', 'cpath-wrk-42', '7a8f7e1bcd88')
INSERT INTO cpath_line (situation_code, line_order, speaker, learner, ja, furigana, vi, audio_path, seed_version) VALUES
  ('TRV-01', 1, '係員', 0, 'おはようございます。パスポートと予約番号をお願いします。', 'おはようございます。パスポートと{予約|よやく}{番号|ばんごう}をお{願|ねが}いします。', 'Chào anh. Cho tôi xin hộ chiếu và mã đặt chỗ ạ.', 'comm-path/TRAVEL/TRV-01-L1.mp3', '5f7a09dc7a13'),
  ('TRV-01', 2, 'リン', 1, 'はい、これです。窓側の席は空いていますか。', 'はい、これです。{窓側|まどがわ}の{席|せき}は{空|あ}いていますか。', 'Vâng, đây ạ. Còn ghế cạnh cửa sổ không ạ?', 'comm-path/TRAVEL/TRV-01-L2.mp3', '5f7a09dc7a13'),
  ('TRV-01', 3, '係員', 0, '前方でしたら一席ご用意できます。', '{前方|ぜんぽう}でしたら{一席|いっせき}ご{用意|ようい}できます。', 'Nếu ở phía trước thì tôi có thể sắp một ghế ạ.', 'comm-path/TRAVEL/TRV-01-L3.mp3', '5f7a09dc7a13'),
  ('TRV-01', 4, 'リン', 1, 'お願いします。預ける荷物は一つです。', 'お{願|ねが}いします。{預|あず}ける{荷物|にもつ}は{一|ひと}つです。', 'Cho tôi ghế đó ạ. Tôi gửi một kiện hành lý.', 'comm-path/TRAVEL/TRV-01-L4.mp3', '5f7a09dc7a13'),
  ('TRV-01', 5, '係員', 0, '重さを量りますので、こちらに載せてください。', '{重|おも}さを{量|はか}りますので、こちらに{載|の}せてください。', 'Tôi cân hành lý nên anh đặt lên đây ạ.', 'comm-path/TRAVEL/TRV-01-L5.mp3', '5f7a09dc7a13'),
  ('TRV-01', 6, 'リン', 1, '超過していますか。', '{超過|ちょうか}していますか。', 'Có quá cân không ạ?', 'comm-path/TRAVEL/TRV-01-L6.mp3', '5f7a09dc7a13'),
  ('TRV-01', 7, '係員', 0, '二キロ超えております。追加料金がかかりますが、よろしいですか。', '{二|に}キロ{超|こ}えております。{追加|ついか}{料金|りょうきん}がかかりますが、よろしいですか。', 'Quá hai ký ạ. Sẽ mất phí phụ thu, anh thấy được không ạ?', 'comm-path/TRAVEL/TRV-01-L7.mp3', '5f7a09dc7a13'),
  ('TRV-01', 8, 'リン', 1, '分かりました。搭乗口はどこですか。', '{分|わ}かりました。{搭乗|とうじょう}{口|ぐち}はどこですか。', 'Tôi hiểu rồi. Cửa lên máy bay ở đâu ạ?', 'comm-path/TRAVEL/TRV-01-L8.mp3', '5f7a09dc7a13'),
  ('TRV-01', 9, '係員', 0, '十五番です。三十分前までにお越しください。', '{十|じゅう}{五|ご}{番|ばん}です。{三十分|さんじゅっぷん}{前|まえ}までにお{越|こ}しください。', 'Cửa số mười lăm ạ. Xin anh đến trước ba mươi phút.', 'comm-path/TRAVEL/TRV-01-L9.mp3', '5f7a09dc7a13'),
  ('TRV-09', 1, 'リン', 1, 'すみません、何時から搭乗が始まりますか。', 'すみません、{何時|なんじ}から{搭乗|とうじょう}が{始|はじ}まりますか。', 'Xin lỗi, mấy giờ bắt đầu lên máy bay ạ?', 'comm-path/TRAVEL/TRV-09-L1.mp3', '5f7a09dc7a13'),
  ('TRV-09', 2, '係員', 0, '十五分後、二時半から始まります。', '{十五分|じゅうごふん}{後|ご}、{二時半|にじはん}から{始|はじ}まります。', 'Sau mười lăm phút, từ hai giờ rưỡi bắt đầu ạ.', 'comm-path/TRAVEL/TRV-09-L2.mp3', '5f7a09dc7a13'),
  ('TRV-09', 3, 'リン', 1, '搭乗口はここで合っていますか。', '{搭乗口|とうじょうぐち}はここで{合|あ}っていますか。', 'Cổng lên máy bay ở đây đúng không ạ?', 'comm-path/TRAVEL/TRV-09-L3.mp3', '5f7a09dc7a13'),
  ('TRV-09', 4, '係員', 0, 'はい、この十五番ゲートです。', 'はい、この{十五番|じゅうごばん}ゲートです。', 'Vâng, cổng số mười lăm này ạ.', 'comm-path/TRAVEL/TRV-09-L4.mp3', '5f7a09dc7a13'),
  ('TRV-09', 5, 'リン', 1, 'トイレは近くにありますか。', 'トイレは{近|ちか}くにありますか。', 'Nhà vệ sinh có gần đây không ạ?', 'comm-path/TRAVEL/TRV-09-L5.mp3', '5f7a09dc7a13'),
  ('TRV-09', 6, '係員', 0, 'あちらを右に行くとすぐあります。', 'あちらを{右|みぎ}に{行|い}くとすぐあります。', 'Đi về phía kia rồi rẽ phải là thấy ngay ạ.', 'comm-path/TRAVEL/TRV-09-L6.mp3', '5f7a09dc7a13'),
  ('TRV-09', 7, 'リン', 1, 'ありがとうございます。急いで行ってきます。', 'ありがとうございます。{急|いそ}いで{行|い}ってきます。', 'Cảm ơn anh. Tôi đi nhanh rồi quay lại.', 'comm-path/TRAVEL/TRV-09-L7.mp3', '5f7a09dc7a13'),
  ('TRV-10', 1, 'リン', 1, 'すみません、毛布をもう一枚もらえますか。', 'すみません、{毛布|もうふ}をもう{一枚|いちまい}もらえますか。', 'Xin lỗi, cho tôi xin thêm một cái chăn được không ạ?', 'comm-path/TRAVEL/TRV-10-L1.mp3', '5f7a09dc7a13'),
  ('TRV-10', 2, '係員', 0, 'かしこまりました。少々お待ちください。', 'かしこまりました。{少々|しょうしょう}お{待|ま}ちください。', 'Vâng ạ. Xin quý khách đợi một chút.', 'comm-path/TRAVEL/TRV-10-L2.mp3', '5f7a09dc7a13'),
  ('TRV-10', 3, '係員', 0, 'お待たせいたしました。どうぞ。', 'お{待|ま}たせいたしました。どうぞ。', 'Đã để quý khách chờ. Mời quý khách.', 'comm-path/TRAVEL/TRV-10-L3.mp3', '5f7a09dc7a13'),
  ('TRV-10', 4, 'リン', 1, 'ありがとうございます。あと、到着は何時ですか。', 'ありがとうございます。あと、{到着|とうちゃく}は{何時|なんじ}ですか。', 'Cảm ơn chị. À, mấy giờ thì hạ cánh ạ?', 'comm-path/TRAVEL/TRV-10-L4.mp3', '5f7a09dc7a13'),
  ('TRV-10', 5, '係員', 0, '予定では三時です。', '{予定|よてい}では{三時|さんじ}です。', 'Theo dự kiến là ba giờ ạ.', 'comm-path/TRAVEL/TRV-10-L5.mp3', '5f7a09dc7a13'),
  ('TRV-10', 6, 'リン', 1, '日本まで長いですね。', '{日本|にほん}まで{長|なが}いですね。', 'Đến Nhật lâu thật nhỉ.', 'comm-path/TRAVEL/TRV-10-L6.mp3', '5f7a09dc7a13'),
  ('TRV-10', 7, '係員', 0, 'はい、あと二時間ほどです。', 'はい、あと{二時間|にじかん}ほどです。', 'Vâng, còn khoảng hai tiếng nữa ạ.', 'comm-path/TRAVEL/TRV-10-L7.mp3', '5f7a09dc7a13'),
  ('TRV-02', 1, 'リン', 1, 'すみません、横浜へ行きたいんですが。', 'すみません、{横浜|よこはま}へ{行|い}きたいんですが。', 'Xin lỗi, tôi muốn đi Yokohama ạ.', 'comm-path/TRAVEL/TRV-02-L1.mp3', '5f7a09dc7a13'),
  ('TRV-02', 2, '駅員', 0, 'ここからですと、品川で乗り換えになります。', 'ここからですと、{品川|しながわ}で{乗|の}り{換|か}えになります。', 'Từ đây thì anh phải đổi tàu ở Shinagawa ạ.', 'comm-path/TRAVEL/TRV-02-L2.mp3', '5f7a09dc7a13'),
  ('TRV-02', 3, 'リン', 1, '特急と各駅停車、どちらが早いですか。', '{特急|とっきゅう}と{各駅|かくえき}{停車|ていしゃ}、どちらが{早|はや}いですか。', 'Tàu tốc hành và tàu thường, cái nào nhanh hơn ạ?', 'comm-path/TRAVEL/TRV-02-L3.mp3', '5f7a09dc7a13'),
  ('TRV-02', 4, '駅員', 0, '特急のほうが二十分ほど早く着きます。', '{特急|とっきゅう}のほうが{二十分|にじゅっぷん}ほど{早|はや}く{着|つ}きます。', 'Tàu tốc hành tới sớm hơn khoảng hai mươi phút ạ.', 'comm-path/TRAVEL/TRV-02-L4.mp3', '5f7a09dc7a13'),
  ('TRV-02', 5, 'リン', 1, '追加料金は要りますか。', '{追加|ついか}{料金|りょうきん}は{要|い}りますか。', 'Có cần trả thêm phí không ạ?', 'comm-path/TRAVEL/TRV-02-L5.mp3', '5f7a09dc7a13'),
  ('TRV-02', 6, '駅員', 0, 'はい、特急券が別に必要です。', 'はい、{特急|とっきゅう}{券|けん}が{別|べつ}に{必要|ひつよう}です。', 'Có ạ, cần thêm vé tốc hành riêng.', 'comm-path/TRAVEL/TRV-02-L6.mp3', '5f7a09dc7a13'),
  ('TRV-02', 7, 'リン', 1, 'では普通ので大丈夫です。何番線ですか。', 'では{普通|ふつう}ので{大丈夫|だいじょうぶ}です。{何|なん}{番線|ばんせん}ですか。', 'Vậy tàu thường cũng được ạ. Ở đường ray số mấy ạ?', 'comm-path/TRAVEL/TRV-02-L7.mp3', '5f7a09dc7a13'),
  ('TRV-02', 8, '駅員', 0, '三番線です。あと五分で発車します。', '{三|さん}{番線|ばんせん}です。あと{五|ご}{分|ふん}で{発車|はっしゃ}します。', 'Đường ray số ba ạ. Còn năm phút nữa là chạy.', 'comm-path/TRAVEL/TRV-02-L8.mp3', '5f7a09dc7a13'),
  ('TRV-11', 1, 'リン', 1, 'すみません、切符の買い方を教えてもらえますか。', 'すみません、{切符|きっぷ}の{買|か}い{方|かた}を{教|おし}えてもらえますか。', 'Xin lỗi, anh chỉ tôi cách mua vé được không ạ?', 'comm-path/TRAVEL/TRV-11-L1.mp3', '5f7a09dc7a13'),
  ('TRV-11', 2, '駅員', 0, '行き先はどちらですか。', '{行|い}き{先|さき}はどちらですか。', 'Anh đi đến đâu ạ?', 'comm-path/TRAVEL/TRV-11-L2.mp3', '5f7a09dc7a13'),
  ('TRV-11', 3, 'リン', 1, '京都までです。', '{京都|きょうと}までです。', 'Đến Kyoto ạ.', 'comm-path/TRAVEL/TRV-11-L3.mp3', '5f7a09dc7a13'),
  ('TRV-11', 4, '駅員', 0, 'では、この画面で京都を押してください。', 'では、この{画面|がめん}で{京都|きょうと}を{押|お}してください。', 'Vậy anh nhấn Kyoto trên màn hình này ạ.', 'comm-path/TRAVEL/TRV-11-L4.mp3', '5f7a09dc7a13'),
  ('TRV-11', 5, 'リン', 1, '運賃はいくらですか。', '{運賃|うんちん}はいくらですか。', 'Giá vé là bao nhiêu ạ?', 'comm-path/TRAVEL/TRV-11-L5.mp3', '5f7a09dc7a13'),
  ('TRV-11', 6, '駅員', 0, '千三百二十円です。', '{千三百二十円|せんさんびゃくにじゅうえん}です。', 'Một nghìn ba trăm hai mươi yên ạ.', 'comm-path/TRAVEL/TRV-11-L6.mp3', '5f7a09dc7a13'),
  ('TRV-11', 7, 'リン', 1, '現金で払えますか。', '{現金|げんきん}で{払|はら}えますか。', 'Trả bằng tiền mặt được không ạ?', 'comm-path/TRAVEL/TRV-11-L7.mp3', '5f7a09dc7a13'),
  ('TRV-11', 8, '駅員', 0, 'はい、こちらにお金を入れてください。', 'はい、こちらにお{金|かね}を{入|い}れてください。', 'Vâng, anh bỏ tiền vào đây ạ.', 'comm-path/TRAVEL/TRV-11-L8.mp3', '5f7a09dc7a13'),
  ('TRV-12', 1, 'リン', 1, 'すみません、終電は何時ですか。', 'すみません、{終電|しゅうでん}は{何時|なんじ}ですか。', 'Xin lỗi, chuyến tàu cuối là mấy giờ ạ?', 'comm-path/TRAVEL/TRV-12-L1.mp3', '5f7a09dc7a13'),
  ('TRV-12', 2, '駅員', 0, 'この線は十一時五十分までです。', 'この{線|せん}は{十一時五十分|じゅういちじごじゅっぷん}までです。', 'Tuyến này chạy đến mười một giờ năm mươi ạ.', 'comm-path/TRAVEL/TRV-12-L2.mp3', '5f7a09dc7a13'),
  ('TRV-12', 3, 'リン', 1, '乗り換えがありますか。', '{乗|の}り{換|か}えがありますか。', 'Có phải đổi tàu không ạ?', 'comm-path/TRAVEL/TRV-12-L3.mp3', '5f7a09dc7a13'),
  ('TRV-12', 4, '駅員', 0, 'ありません。一本で行けます。', 'ありません。{一本|いっぽん}で{行|い}けます。', 'Không ạ. Đi thẳng một chuyến là tới.', 'comm-path/TRAVEL/TRV-12-L4.mp3', '5f7a09dc7a13'),
  ('TRV-12', 5, 'リン', 1, '間に合いますか。', '{間|ま}に{合|あ}いますか。', 'Tôi có kịp không ạ?', 'comm-path/TRAVEL/TRV-12-L5.mp3', '5f7a09dc7a13'),
  ('TRV-12', 6, '駅員', 0, '今からなら十分間に合います。', '{今|いま}からなら{十分間|じゅっぷんかん}に{合|あ}います。', 'Đi từ bây giờ thì dư thời gian ạ.', 'comm-path/TRAVEL/TRV-12-L6.mp3', '5f7a09dc7a13'),
  ('TRV-12', 7, 'リン', 1, 'よかったです。ありがとうございます。', 'よかったです。ありがとうございます。', 'May quá. Cảm ơn anh.', 'comm-path/TRAVEL/TRV-12-L7.mp3', '5f7a09dc7a13'),
  ('TRV-03', 1, 'リン', 1, '予約したグエンです。', '{予約|よやく}したグエンです。', 'Tôi là Nguyễn, đã đặt phòng ạ.', 'comm-path/TRAVEL/TRV-03-L1.mp3', '5f7a09dc7a13'),
  ('TRV-03', 2, 'フロント', 0, 'お待ちしておりました。二泊、朝食付きでございますね。', 'お{待|ま}ちしておりました。{二|に}{泊|はく}、{朝食|ちょうしょく}{付|つ}きでございますね。', 'Chúng tôi đã chờ ngài. Hai đêm, kèm bữa sáng phải không ạ.', 'comm-path/TRAVEL/TRV-03-L2.mp3', '5f7a09dc7a13'),
  ('TRV-03', 3, 'リン', 1, 'はい。朝食は何時からですか。', 'はい。{朝食|ちょうしょく}は{何|なん}{時|じ}からですか。', 'Vâng. Bữa sáng từ mấy giờ ạ?', 'comm-path/TRAVEL/TRV-03-L3.mp3', '5f7a09dc7a13'),
  ('TRV-03', 4, 'フロント', 0, '七時から十時まで、二階のレストランでご用意しております。', '{七時|しちじ}から{十|じゅう}{時|じ}まで、{二|に}{階|かい}のレストランでご{用意|ようい}しております。', 'Từ bảy giờ đến mười giờ, ở nhà hàng tầng hai ạ.', 'comm-path/TRAVEL/TRV-03-L4.mp3', '5f7a09dc7a13'),
  ('TRV-03', 5, 'リン', 1, 'チェックアウトは何時までですか。', 'チェックアウトは{何時|なんじ}までですか。', 'Trả phòng muộn nhất mấy giờ ạ?', 'comm-path/TRAVEL/TRV-03-L5.mp3', '5f7a09dc7a13'),
  ('TRV-03', 6, 'フロント', 0, '十一時でございます。延長も承ります。', '{十|じゅう}{一|いち}{時|じ}でございます。{延長|えんちょう}も{承|うけたまわ}ります。', 'Mười một giờ ạ. Chúng tôi cũng nhận gia hạn.', 'comm-path/TRAVEL/TRV-03-L6.mp3', '5f7a09dc7a13'),
  ('TRV-03', 7, 'リン', 1, '荷物を先に預かってもらえますか。', '{荷物|にもつ}を{先|さき}に{預|あず}かってもらえますか。', 'Anh giữ hành lý giúp tôi trước được không ạ?', 'comm-path/TRAVEL/TRV-03-L7.mp3', '5f7a09dc7a13'),
  ('TRV-03', 8, 'フロント', 0, 'かしこまりました。こちらの札をお持ちください。', 'かしこまりました。こちらの{札|ふだ}をお{持|も}ちください。', 'Vâng ạ. Xin ngài giữ thẻ này.', 'comm-path/TRAVEL/TRV-03-L8.mp3', '5f7a09dc7a13'),
  ('TRV-13', 1, 'リン', 1, 'おはようございます。チェックアウトをお願いします。', 'おはようございます。チェックアウトをお{願|ねが}いします。', 'Chào chị. Cho tôi trả phòng ạ.', 'comm-path/TRAVEL/TRV-13-L1.mp3', '5f7a09dc7a13'),
  ('TRV-13', 2, 'フロント', 0, 'かしこまりました。お部屋番号を伺います。', 'かしこまりました。お{部屋|へや}{番号|ばんごう}を{伺|うかが}います。', 'Vâng ạ. Xin cho biết số phòng.', 'comm-path/TRAVEL/TRV-13-L2.mp3', '5f7a09dc7a13'),
  ('TRV-13', 3, 'リン', 1, '三百五号室です。', '{三百五号室|さんびゃくごごうしつ}です。', 'Phòng ba lẻ năm ạ.', 'comm-path/TRAVEL/TRV-13-L3.mp3', '5f7a09dc7a13'),
  ('TRV-13', 4, 'フロント', 0, 'では、お会計いたします。ミニバーのご利用はありますか。', 'では、お{会計|かいけい}いたします。ミニバーのご{利用|りよう}はありますか。', 'Vậy tôi tính tiền ạ. Quý khách có dùng minibar không ạ?', 'comm-path/TRAVEL/TRV-13-L4.mp3', '5f7a09dc7a13'),
  ('TRV-13', 5, 'リン', 1, 'ありません。それと、タクシーを呼んでもらえますか。', 'ありません。それと、タクシーを{呼|よ}んでもらえますか。', 'Không ạ. À, chị gọi taxi giúp tôi được không ạ?', 'comm-path/TRAVEL/TRV-13-L5.mp3', '5f7a09dc7a13'),
  ('TRV-13', 6, 'フロント', 0, 'はい。空港まででよろしいですか。', 'はい。{空港|くうこう}まででよろしいですか。', 'Vâng ạ. Đi ra sân bay phải không ạ?', 'comm-path/TRAVEL/TRV-13-L6.mp3', '5f7a09dc7a13'),
  ('TRV-13', 7, 'リン', 1, 'はい、お願いします。', 'はい、お{願|ねが}いします。', 'Vâng, nhờ chị ạ.', 'comm-path/TRAVEL/TRV-13-L7.mp3', '5f7a09dc7a13'),
  ('TRV-14', 1, 'リン', 1, 'すみません、部屋のWi-Fiのパスワードを教えてください。', 'すみません、{部屋|へや}のWi-Fiのパスワードを{教|おし}えてください。', 'Xin lỗi, cho tôi xin mật khẩu wifi của phòng ạ.', 'comm-path/TRAVEL/TRV-14-L1.mp3', '5f7a09dc7a13'),
  ('TRV-14', 2, 'フロント', 0, 'こちらのカードに書いてございます。', 'こちらのカードに{書|か}いてございます。', 'Mật khẩu ghi trên tấm thẻ này ạ.', 'comm-path/TRAVEL/TRV-14-L2.mp3', '5f7a09dc7a13'),
  ('TRV-14', 3, 'リン', 1, 'あと、タオルをもう一枚もらえますか。', 'あと、タオルをもう{一枚|いちまい}もらえますか。', 'À, cho tôi xin thêm một cái khăn được không ạ?', 'comm-path/TRAVEL/TRV-14-L3.mp3', '5f7a09dc7a13'),
  ('TRV-14', 4, 'フロント', 0, 'はい、すぐお届けします。', 'はい、すぐお{届|とど}けします。', 'Vâng, chúng tôi gửi lên ngay ạ.', 'comm-path/TRAVEL/TRV-14-L4.mp3', '5f7a09dc7a13'),
  ('TRV-14', 5, 'リン', 1, '冷蔵庫の飲み物は無料ですか。', '{冷蔵庫|れいぞうこ}の{飲|の}み{物|もの}は{無料|むりょう}ですか。', 'Đồ uống trong tủ lạnh có miễn phí không ạ?', 'comm-path/TRAVEL/TRV-14-L5.mp3', '5f7a09dc7a13'),
  ('TRV-14', 6, 'フロント', 0, 'いいえ、有料でございます。', 'いいえ、{有料|ゆうりょう}でございます。', 'Không ạ, những thứ đó tính phí.', 'comm-path/TRAVEL/TRV-14-L6.mp3', '5f7a09dc7a13'),
