  ('TRV-04', 1, '店員', 0, 'ご注文はお決まりですか。', 'ご{注文|ちゅうもん}はお{決|き}まりですか。', 'Quý khách đã chọn món chưa ạ?', 'comm-path/TRAVEL/TRV-04-L1.mp3', '5f7a09dc7a13'),
  ('TRV-04', 2, 'リン', 1, 'この定食には何が付きますか。', 'この{定食|ていしょく}には{何|なに}が{付|つ}きますか。', 'Suất cơm này gồm những gì ạ?', 'comm-path/TRAVEL/TRV-04-L2.mp3', '5f7a09dc7a13'),
