  ('TRV-04', 7, '店員', 0, '辛口に変更できます。少々お待ちください。', '{辛口|からくち}に{変更|へんこう}できます。{少々|しょうしょう}お{待|ま}ちください。', 'Chúng tôi đổi sang vị cay được ạ. Xin quý khách đợi chút.', 'comm-path/TRAVEL/TRV-04-L7.mp3', '5f7a09dc7a13'),
  ('TRV-15', 1, 'リン', 1, 'もしもし、今夜七時に予約したいんですが。', 'もしもし、{今夜|こんや}{七時|しちじ}に{予約|よやく}したいんですが。', 'Alo, tôi muốn đặt bàn lúc bảy giờ tối nay ạ.', 'comm-path/TRAVEL/TRV-15-L1.mp3', '5f7a09dc7a13'),
  ('TRV-15', 2, '店員', 0, 'ありがとうございます。何名様ですか。', 'ありがとうございます。{何名様|なんめいさま}ですか。', 'Cảm ơn quý khách. Mấy người ạ?', 'comm-path/TRAVEL/TRV-15-L2.mp3', '5f7a09dc7a13'),
  ('TRV-15', 3, 'リン', 1, '二人です。', '{二人|ふたり}です。', 'Hai người ạ.', 'comm-path/TRAVEL/TRV-15-L3.mp3', '5f7a09dc7a13'),
  ('TRV-15', 4, '店員', 0, 'かしこまりました。お名前をお願いします。', 'かしこまりました。お{名前|なまえ}をお{願|ねが}いします。', 'Vâng ạ. Xin tên quý khách.', 'comm-path/TRAVEL/TRV-15-L4.mp3', '5f7a09dc7a13'),
  ('TRV-15', 5, 'リン', 1, 'グエンです。', 'グエンです。', 'Tôi là Nguyễn ạ.', 'comm-path/TRAVEL/TRV-15-L5.mp3', '5f7a09dc7a13'),
