  ('TRV-16', 4, '店員', 0, 'はい、ご利用いただけます。', 'はい、ご{利用|りよう}いただけます。', 'Vâng, quý khách dùng được ạ.', 'comm-path/TRAVEL/TRV-16-L4.mp3', '5f7a09dc7a13'),
  ('TRV-16', 5, 'リン', 1, '二人で別々にできますか。', '{二人|ふたり}で{別々|べつべつ}にできますか。', 'Hai người tính riêng được không ạ?', 'comm-path/TRAVEL/TRV-16-L5.mp3', '5f7a09dc7a13'),
