  ('TRV-16', 7, 'リン', 1, 'ありがとうございます。', 'ありがとうございます。', 'Cảm ơn anh.', 'comm-path/TRAVEL/TRV-16-L7.mp3', '5f7a09dc7a13'),
  ('TRV-06', 1, 'リン', 1, 'すみません、美術館へはどう行けばいいですか。', 'すみません、{美術館|びじゅつかん}へはどう{行|い}けばいいですか。', 'Xin lỗi, đi tới bảo tàng mỹ thuật thế nào ạ?', 'comm-path/TRAVEL/TRV-06-L1.mp3', '5f7a09dc7a13'),
  ('TRV-06', 2, '通行人', 0, 'ここをまっすぐ行って、二つ目の信号を左です。', 'ここをまっすぐ{行|い}って、{二|ふた}つ{目|め}の{信号|しんごう}を{左|ひだり}です。', 'Đi thẳng đây, tới đèn thứ hai thì rẽ trái.', 'comm-path/TRAVEL/TRV-06-L2.mp3', '5f7a09dc7a13'),
  ('TRV-06', 3, 'リン', 1, '歩いてどのくらいですか。', '{歩|ある}いてどのくらいですか。', 'Đi bộ khoảng bao lâu ạ?', 'comm-path/TRAVEL/TRV-06-L3.mp3', '5f7a09dc7a13'),
  ('TRV-06', 4, '通行人', 0, '十分くらいかな。突き当たりに大きな時計がありますよ。', '{十分|じゅっぷん}くらいかな。{突|つ}き{当|あ}たりに{大|おお}きな{時計|とけい}がありますよ。', 'Chắc khoảng mười phút. Cuối đường có cái đồng hồ lớn đấy.', 'comm-path/TRAVEL/TRV-06-L4.mp3', '5f7a09dc7a13'),
