  ('TRV-07', 2, '駅員', 0, '何時ごろの、どの路線でしょうか。', '{何|なん}{時|じ}ごろの、どの{路線|ろせん}でしょうか。', 'Khoảng mấy giờ, tuyến nào ạ?', 'comm-path/TRAVEL/TRV-07-L2.mp3', '5f7a09dc7a13'),
