  ('TRV-07', 7, 'リン', 1, '見つかったらどう連絡がありますか。', '{見|み}つかったらどう{連絡|れんらく}がありますか。', 'Nếu tìm thấy thì báo cho tôi thế nào ạ?', 'comm-path/TRAVEL/TRV-07-L7.mp3', '5f7a09dc7a13'),
  ('TRV-07', 8, '駅員', 0, 'お電話を差し上げます。数日かかる場合もございます。', 'お{電話|でんわ}を{差|さ}し{上|あ}げます。{数日|すうじつ}かかる{場合|ばあい}もございます。', 'Chúng tôi sẽ gọi điện. Cũng có trường hợp mất vài ngày ạ.', 'comm-path/TRAVEL/TRV-07-L8.mp3', '5f7a09dc7a13'),
  ('TRV-08', 1, 'リン', 1, 'すみません、少し具合が悪くて。', 'すみません、{少|すこ}し{具合|ぐあい}が{悪|わる}くて。', 'Xin lỗi, tôi thấy hơi khó chịu trong người.', 'comm-path/TRAVEL/TRV-08-L1.mp3', '5f7a09dc7a13'),
  ('TRV-08', 2, 'フロント', 0, '大丈夫ですか。どのような症状でしょうか。', '{大丈夫|だいじょうぶ}ですか。どのような{症状|しょうじょう}でしょうか。', 'Ngài không sao chứ? Triệu chứng thế nào ạ?', 'comm-path/TRAVEL/TRV-08-L2.mp3', '5f7a09dc7a13'),
