  ('TRV-05', 1, 'リン', 1, 'これ、免税になりますか。', 'これ、{免税|めんぜい}になりますか。', 'Cái này được miễn thuế không ạ?', 'comm-path/TRAVEL/TRV-05-L1.mp3', '5f7a09dc7a13'),
  ('TRV-05', 2, '店員', 0, '五千円以上のお買い上げで対象になります。', '{五|ご}{千|せん}{円|えん}{以上|いじょう}のお{買|か}い{上|あ}げで{対象|たいしょう}になります。', 'Mua từ năm nghìn yên trở lên là thuộc diện được ạ.', 'comm-path/TRAVEL/TRV-05-L2.mp3', '5f7a09dc7a13'),
  ('TRV-05', 3, 'リン', 1, '今いくらですか。', '{今|いま}いくらですか。', 'Bây giờ là bao nhiêu ạ?', 'comm-path/TRAVEL/TRV-05-L3.mp3', '5f7a09dc7a13'),
