  ('TRV-17', 1, 'リン', 1, 'すみません、このシャツを試着できますか。', 'すみません、このシャツを{試着|しちゃく}できますか。', 'Xin lỗi, tôi thử cái áo sơ mi này được không ạ?', 'comm-path/TRAVEL/TRV-17-L1.mp3', '5f7a09dc7a13'),
  ('TRV-17', 2, '店員', 0, 'はい、試着室はあちらです。', 'はい、{試着室|しちゃくしつ}はあちらです。', 'Vâng, phòng thử đồ ở phía kia ạ.', 'comm-path/TRAVEL/TRV-17-L2.mp3', '5f7a09dc7a13'),
  ('TRV-17', 3, 'リン', 1, 'ちょっと小さいです。もう一つ上のサイズはありますか。', 'ちょっと{小|ちい}さいです。もう{一|ひと}つ{上|うえ}のサイズはありますか。', 'Hơi chật. Có cỡ lớn hơn một cỡ không ạ?', 'comm-path/TRAVEL/TRV-17-L3.mp3', '5f7a09dc7a13'),
  ('TRV-17', 4, '店員', 0, '少々お待ちください。確認してまいります。', '{少々|しょうしょう}お{待|ま}ちください。{確認|かくにん}してまいります。', 'Xin quý khách đợi một chút, tôi đi kiểm tra.', 'comm-path/TRAVEL/TRV-17-L4.mp3', '5f7a09dc7a13'),
  ('TRV-17', 5, '店員', 0, 'お待たせしました。こちらがMサイズです。', 'お{待|ま}たせしました。こちらがMサイズです。', 'Đã để quý khách chờ. Đây là cỡ M ạ.', 'comm-path/TRAVEL/TRV-17-L5.mp3', '5f7a09dc7a13'),
