  ('TRV-18', 1, 'リン', 1, 'すみません、昨日買ったこれを交換できますか。', 'すみません、{昨日|きのう}{買|か}ったこれを{交換|こうかん}できますか。', 'Xin lỗi, cái này tôi mua hôm qua có đổi được không ạ?', 'comm-path/TRAVEL/TRV-18-L1.mp3', '5f7a09dc7a13'),
  ('TRV-18', 2, '店員', 0, 'レシートはお持ちですか。', 'レシートはお{持|も}ちですか。', 'Quý khách có mang hóa đơn không ạ?', 'comm-path/TRAVEL/TRV-18-L2.mp3', '5f7a09dc7a13'),
  ('TRV-18', 3, 'リン', 1, 'はい、これです。色を変えたいです。', 'はい、これです。{色|いろ}を{変|か}えたいです。', 'Vâng, đây ạ. Tôi muốn đổi màu khác.', 'comm-path/TRAVEL/TRV-18-L3.mp3', '5f7a09dc7a13'),
  ('TRV-18', 4, '店員', 0, 'かしこまりました。青と白があります。', 'かしこまりました。{青|あお}と{白|しろ}があります。', 'Vâng ạ. Có màu xanh và màu trắng.', 'comm-path/TRAVEL/TRV-18-L4.mp3', '5f7a09dc7a13'),
  ('TRV-18', 5, 'リン', 1, 'では、青をお願いします。', 'では、{青|あお}をお{願|ねが}いします。', 'Vậy cho tôi màu xanh ạ.', 'comm-path/TRAVEL/TRV-18-L5.mp3', '5f7a09dc7a13'),
  ('TRV-18', 6, '店員', 0, 'こちらでございます。ありがとうございました。', 'こちらでございます。ありがとうございました。', 'Đây là hàng của quý khách. Cảm ơn quý khách ạ.', 'comm-path/TRAVEL/TRV-18-L6.mp3', '5f7a09dc7a13'),
  ('DLY-01', 1, 'リン', 1, '初期費用は全部でいくらになりますか。', '{初期|しょき}{費用|ひよう}は{全部|ぜんぶ}でいくらになりますか。', 'Chi phí ban đầu tổng cộng là bao nhiêu ạ?', 'comm-path/DAILY_LIFE/DLY-01-L1.mp3', 'd2c4b91916be'),
  ('DLY-01', 2, '不動産', 0, '家賃、敷金一か月、礼金なしで、合計十四万円ほどです。', '{家賃|やちん}、{敷金|しききん}{一|いっ}か{月|げつ}、{礼金|れいきん}なしで、{合計|ごうけい}{十|じゅう}{四|よん}{万|まん}{円|えん}ほどです。', 'Tiền thuê, đặt cọc một tháng, không tiền lễ, tổng khoảng mười bốn vạn ạ.', 'comm-path/DAILY_LIFE/DLY-01-L2.mp3', 'd2c4b91916be'),
  ('DLY-01', 3, 'リン', 1, '礼金がないのは助かります。共益費は別ですか。', '{礼金|れいきん}がないのは{助|たす}かります。{共益|きょうえき}{費|ひ}は{別|べつ}ですか。', 'Không có tiền lễ thì đỡ quá. Phí quản lý tính riêng ạ?', 'comm-path/DAILY_LIFE/DLY-01-L3.mp3', 'd2c4b91916be'),
  ('DLY-01', 4, '不動産', 0, 'はい、月三千円が別途かかります。', 'はい、{月|つき}{三千|さんぜん}{円|えん}が{別途|べっと}かかります。', 'Vâng, mỗi tháng thêm ba nghìn yên ạ.', 'comm-path/DAILY_LIFE/DLY-01-L4.mp3', 'd2c4b91916be'),
  ('DLY-01', 5, 'リン', 1, '日当たりはどうですか。', '{日当|ひあ}たりはどうですか。', 'Phòng có nắng không ạ?', 'comm-path/DAILY_LIFE/DLY-01-L5.mp3', 'd2c4b91916be'),
  ('DLY-01', 6, '不動産', 0, '南向きですので、昼間は明るいですよ。', '{南|みなみ}{向|む}きですので、{昼間|ひるま}は{明|あか}るいですよ。', 'Hướng nam nên ban ngày sáng lắm ạ.', 'comm-path/DAILY_LIFE/DLY-01-L6.mp3', 'd2c4b91916be'),
  ('DLY-01', 7, 'リン', 1, '騒音は気になりませんか。', '{騒音|そうおん}は{気|き}になりませんか。', 'Có ồn không ạ?', 'comm-path/DAILY_LIFE/DLY-01-L7.mp3', 'd2c4b91916be'),
  ('DLY-01', 8, '不動産', 0, '大通りから離れていますので、静かなほうです。', '{大通|おおどお}りから{離|はな}れていますので、{静|しず}かなほうです。', 'Xa đường lớn nên thuộc loại yên tĩnh ạ.', 'comm-path/DAILY_LIFE/DLY-01-L8.mp3', 'd2c4b91916be'),
  ('DLY-02', 1, 'リン', 1, 'この空き缶はどのごみですか。', 'この{空|あ}き{缶|かん}はどのごみですか。', 'Cái lon rỗng này thuộc loại rác nào ạ?', 'comm-path/DAILY_LIFE/DLY-02-L1.mp3', 'd2c4b91916be'),
  ('DLY-02', 2, '近所の人', 0, 'それは資源ごみ。水曜の朝に出すのよ。', 'それは{資源|しげん}ごみ。{水曜|すいよう}の{朝|あさ}に{出|だ}すのよ。', 'Cái đó là rác tái chế. Đem ra sáng thứ tư nhé.', 'comm-path/DAILY_LIFE/DLY-02-L2.mp3', 'd2c4b91916be'),
  ('DLY-02', 3, 'リン', 1, '洗ってから出すんですか。', '{洗|あら}ってから{出|だ}すんですか。', 'Phải rửa rồi mới đem ra ạ?', 'comm-path/DAILY_LIFE/DLY-02-L3.mp3', 'd2c4b91916be'),
  ('DLY-02', 4, '近所の人', 0, 'そう。中をゆすいで、つぶさずにね。', 'そう。{中|なか}をゆすいで、つぶさずにね。', 'Đúng. Tráng bên trong, và đừng bóp bẹp nhé.', 'comm-path/DAILY_LIFE/DLY-02-L4.mp3', 'd2c4b91916be'),
  ('DLY-02', 5, 'リン', 1, '古い椅子はどうすればいいですか。', '{古|ふる}い{椅子|いす}はどうすればいいですか。', 'Cái ghế cũ thì làm thế nào ạ?', 'comm-path/DAILY_LIFE/DLY-02-L5.mp3', 'd2c4b91916be'),
  ('DLY-02', 6, '近所の人', 0, 'あれは粗大ごみ。市役所に申し込んで、シールを買うの。', 'あれは{粗大|そだい}ごみ。{市役所|しやくしょ}に{申|もう}し{込|こ}んで、シールを{買|か}うの。', 'Cái đó là rác cồng kềnh. Đăng ký với thành phố rồi mua tem.', 'comm-path/DAILY_LIFE/DLY-02-L6.mp3', 'd2c4b91916be'),
  ('DLY-02', 7, 'リン', 1, '手続きが要るんですね。教えてくださってありがとうございます。', '{手続|てつづ}きが{要|い}るんですね。{教|おし}えてくださってありがとうございます。', 'Phải làm thủ tục nhỉ. Cảm ơn cô đã chỉ cho cháu.', 'comm-path/DAILY_LIFE/DLY-02-L7.mp3', 'd2c4b91916be'),
  ('DLY-09', 1, 'リン', 1, 'すみません、ゴミの出し方を教えてもらえますか。', 'すみません、ゴミの{出|だ}し{方|かた}を{教|おし}えてもらえますか。', 'Xin lỗi, anh chỉ tôi cách đổ rác được không ạ?', 'comm-path/DAILY_LIFE/DLY-09-L1.mp3', 'd2c4b91916be'),
  ('DLY-09', 2, '隣人', 0, '燃えるゴミは火曜日と金曜日です。', '{燃|も}えるゴミは{火曜日|かようび}と{金曜日|きんようび}です。', 'Rác cháy được là thứ Ba và thứ Sáu ạ.', 'comm-path/DAILY_LIFE/DLY-09-L2.mp3', 'd2c4b91916be'),
  ('DLY-09', 3, 'リン', 1, 'ペットボトルはどうすればいいですか。', 'ペットボトルはどうすればいいですか。', 'Chai nhựa thì phải làm thế nào ạ?', 'comm-path/DAILY_LIFE/DLY-09-L3.mp3', 'd2c4b91916be'),
  ('DLY-09', 4, '隣人', 0, '資源ゴミです。ラベルをはがして出してください。', '{資源|しげん}ゴミです。ラベルをはがして{出|だ}してください。', 'Đó là rác tái chế. Anh gỡ nhãn ra rồi bỏ ạ.', 'comm-path/DAILY_LIFE/DLY-09-L4.mp3', 'd2c4b91916be'),
  ('DLY-09', 5, 'リン', 1, '何時までに出せばいいですか。', '{何時|なんじ}までに{出|だ}せばいいですか。', 'Phải đổ trước mấy giờ ạ?', 'comm-path/DAILY_LIFE/DLY-09-L5.mp3', 'd2c4b91916be'),
