  ('DLY-10', 4, '店員', 0, '今朝取れたばかりですよ。', '{今朝|けさ}{取|と}れたばかりですよ。', 'Sáng nay mới hái về đấy ạ.', 'comm-path/DAILY_LIFE/DLY-10-L4.mp3', 'd2c4b91916be'),
