  ('DLY-16', 3, 'リン', 1, 'はい、ここにあります。', 'はい、ここにあります。', 'Vâng, đây ạ.', 'comm-path/DAILY_LIFE/DLY-16-L3.mp3', 'd2c4b91916be'),
  ('DLY-16', 4, '係員', 0, 'では、二週間借りられます。', 'では、{二週間|にしゅうかん}{借|か}りられます。', 'Vậy anh mượn được hai tuần ạ.', 'comm-path/DAILY_LIFE/DLY-16-L4.mp3', 'd2c4b91916be'),
  ('DLY-16', 5, 'リン', 1, '返却はどこでしますか。', '{返却|へんきゃく}はどこでしますか。', 'Trả sách ở đâu ạ?', 'comm-path/DAILY_LIFE/DLY-16-L5.mp3', 'd2c4b91916be'),
  ('DLY-16', 6, '係員', 0, 'こちらのカウンターにお願いします。', 'こちらのカウンターにお{願|ねが}いします。', 'Anh trả ở quầy này ạ.', 'comm-path/DAILY_LIFE/DLY-16-L6.mp3', 'd2c4b91916be'),
  ('DLY-16', 7, 'リン', 1, 'ありがとうございます。', 'ありがとうございます。', 'Cảm ơn chị.', 'comm-path/DAILY_LIFE/DLY-16-L7.mp3', 'd2c4b91916be'),
  ('DLY-04', 1, 'リン', 1, '振込をしたいのですが。', '{振込|ふりこみ}をしたいのですが。', 'Tôi muốn chuyển khoản ạ.', 'comm-path/DAILY_LIFE/DLY-04-L1.mp3', 'd2c4b91916be'),
  ('DLY-04', 2, '行員', 0, '他行宛てでしょうか。', '{他行|たこう}{宛|あ}てでしょうか。', 'Là chuyển sang ngân hàng khác phải không ạ?', 'comm-path/DAILY_LIFE/DLY-04-L2.mp3', 'd2c4b91916be'),
  ('DLY-04', 3, 'リン', 1, 'はい。手数料はいくらかかりますか。', 'はい。{手数料|てすうりょう}はいくらかかりますか。', 'Vâng. Phí là bao nhiêu ạ?', 'comm-path/DAILY_LIFE/DLY-04-L3.mp3', 'd2c4b91916be'),
  ('DLY-04', 4, '行員', 0, '窓口ですと四百四十円、ATMですと二百二十円です。', '{窓口|まどぐち}ですと{四|よん}{百|ひゃく}{四|よん}{十|じゅう}{円|えん}、ATMですと{二|に}{百|ひゃく}{二|に}{十|じゅう}{円|えん}です。', 'Ở quầy là bốn trăm bốn mươi yên, ở máy ATM là hai trăm hai mươi yên ạ.', 'comm-path/DAILY_LIFE/DLY-04-L4.mp3', 'd2c4b91916be'),
  ('DLY-04', 5, 'リン', 1, '思ったより違うんですね。ATMでもできますか。', '{思|おも}ったより{違|ちが}うんですね。ATMでもできますか。', 'Chênh nhiều hơn tôi tưởng nhỉ. Ở máy ATM cũng làm được ạ?', 'comm-path/DAILY_LIFE/DLY-04-L5.mp3', 'd2c4b91916be'),
  ('DLY-04', 6, '行員', 0, 'はい。ただ、通帳とキャッシュカードが必要です。', 'はい。ただ、{通帳|つうちょう}とキャッシュカードが{必要|ひつよう}です。', 'Vâng ạ. Chỉ có điều cần sổ ngân hàng và thẻ.', 'comm-path/DAILY_LIFE/DLY-04-L6.mp3', 'd2c4b91916be'),
  ('DLY-04', 7, 'リン', 1, '持っています。操作を教えていただけますか。', '{持|も}っています。{操作|そうさ}を{教|おし}えていただけますか。', 'Tôi có mang. Chị hướng dẫn thao tác giúp tôi được không ạ?', 'comm-path/DAILY_LIFE/DLY-04-L7.mp3', 'd2c4b91916be'),
  ('DLY-04', 8, '行員', 0, 'もちろんです。ご案内いたします。', 'もちろんです。ご{案内|あんない}いたします。', 'Tất nhiên rồi ạ. Tôi xin dẫn ngài đi.', 'comm-path/DAILY_LIFE/DLY-04-L8.mp3', 'd2c4b91916be'),
  ('DLY-06', 1, 'リン', 1, '不在票が入っていたので、再配達をお願いしたいのですが。', '{不在|ふざい}{票|ひょう}が{入|はい}っていたので、{再|さい}{配達|はいたつ}をお{願|ねが}いしたいのですが。', 'Tôi nhận được phiếu báo vắng nên muốn xin giao lại ạ.', 'comm-path/DAILY_LIFE/DLY-06-L1.mp3', 'd2c4b91916be'),
  ('DLY-06', 2, '係員', 0, '伝票番号をお願いいたします。', '{伝票|でんぴょう}{番号|ばんごう}をお{願|ねが}いいたします。', 'Xin cho tôi mã vận đơn ạ.', 'comm-path/DAILY_LIFE/DLY-06-L2.mp3', 'd2c4b91916be'),
  ('DLY-06', 3, 'リン', 1, 'はい、一二三四の五六七八です。', 'はい、{一|いち}{二|に}{三|さん}{四|よん}の{五|ご}{六|ろく}{七|なな}{八|はち}です。', 'Vâng, là một hai ba bốn năm sáu bảy tám ạ.', 'comm-path/DAILY_LIFE/DLY-06-L3.mp3', 'd2c4b91916be'),
  ('DLY-06', 4, '係員', 0, '本日の夜間でしたらお届けできます。', '{本日|ほんじつ}の{夜間|やかん}でしたらお{届|とど}けできます。', 'Nếu là buổi tối hôm nay thì chúng tôi giao được ạ.', 'comm-path/DAILY_LIFE/DLY-06-L4.mp3', 'd2c4b91916be'),
  ('DLY-06', 5, 'リン', 1, '何時から何時までですか。', '{何|なん}{時|じ}から{何|なん}{時|じ}までですか。', 'Từ mấy giờ đến mấy giờ ạ?', 'comm-path/DAILY_LIFE/DLY-06-L5.mp3', 'd2c4b91916be'),
  ('DLY-06', 6, '係員', 0, '七時から九時の間でございます。', '{七時|しちじ}から{九時|くじ}の{間|あいだ}でございます。', 'Trong khoảng bảy giờ đến chín giờ ạ.', 'comm-path/DAILY_LIFE/DLY-06-L6.mp3', 'd2c4b91916be'),
  ('DLY-06', 7, 'リン', 1, 'その時間で大丈夫です。呼び鈴を鳴らしてください。', 'その{時間|じかん}で{大丈夫|だいじょうぶ}です。{呼|よ}び{鈴|りん}を{鳴|な}らしてください。', 'Khung giờ đó được ạ. Anh bấm chuông giúp tôi nhé.', 'comm-path/DAILY_LIFE/DLY-06-L7.mp3', 'd2c4b91916be'),
  ('DLY-06', 8, '係員', 0, '承知いたしました。よろしくお願いいたします。', '{承知|しょうち}いたしました。よろしくお{願|ねが}いいたします。', 'Tôi đã rõ ạ. Xin cảm ơn quý khách.', 'comm-path/DAILY_LIFE/DLY-06-L8.mp3', 'd2c4b91916be'),
  ('DLY-12', 1, 'リン', 1, 'すみません、この小包をベトナムに送りたいです。', 'すみません、この{小包|こづつみ}をベトナムに{送|おく}りたいです。', 'Xin lỗi, tôi muốn gửi bưu kiện này về Việt Nam ạ.', 'comm-path/DAILY_LIFE/DLY-12-L1.mp3', 'd2c4b91916be'),
  ('DLY-12', 2, '係員', 0, '船便と航空便がありますが、どちらにしますか。', '{船便|ふなびん}と{航空便|こうくうびん}がありますが、どちらにしますか。', 'Có gửi đường biển và đường hàng không, anh chọn loại nào ạ?', 'comm-path/DAILY_LIFE/DLY-12-L2.mp3', 'd2c4b91916be'),
  ('DLY-12', 3, 'リン', 1, '航空便でお願いします。何日かかりますか。', '{航空便|こうくうびん}でお{願|ねが}いします。{何日|なんにち}かかりますか。', 'Cho tôi gửi đường hàng không. Mất mấy ngày ạ?', 'comm-path/DAILY_LIFE/DLY-12-L3.mp3', 'd2c4b91916be'),
  ('DLY-12', 4, '係員', 0, '一週間ほどです。', '{一週間|いっしゅうかん}ほどです。', 'Khoảng một tuần ạ.', 'comm-path/DAILY_LIFE/DLY-12-L4.mp3', 'd2c4b91916be'),
  ('DLY-12', 5, 'リン', 1, '中身は服です。税関申告書は要りますか。', '{中身|なかみ}は{服|ふく}です。{税関申告書|ぜいかんしんこくしょ}は{要|い}りますか。', 'Bên trong là quần áo. Có cần tờ khai hải quan không ạ?', 'comm-path/DAILY_LIFE/DLY-12-L5.mp3', 'd2c4b91916be'),
  ('DLY-12', 6, '係員', 0, 'はい、こちらに宛先をお書きください。', 'はい、こちらに{宛先|あてさき}をお{書|か}きください。', 'Vâng, anh ghi địa chỉ người nhận vào đây ạ.', 'comm-path/DAILY_LIFE/DLY-12-L6.mp3', 'd2c4b91916be'),
  ('DLY-12', 7, 'リン', 1, '分かりました。', '{分|わ}かりました。', 'Tôi hiểu rồi.', 'comm-path/DAILY_LIFE/DLY-12-L7.mp3', 'd2c4b91916be'),
  ('DLY-05', 1, '医師', 0, '今日はどうされましたか。', '{今日|きょう}はどうされましたか。', 'Hôm nay chị thấy sao?', 'comm-path/DAILY_LIFE/DLY-05-L1.mp3', 'd2c4b91916be'),
  ('DLY-05', 2, 'リン', 1, '三日前から咳が止まらなくて、夜眠れないんです。', '{三日|みっか}{前|まえ}から{咳|せき}が{止|と}まらなくて、{夜|よる}{眠|ねむ}れないんです。', 'Từ ba hôm trước tôi ho không dứt, đêm không ngủ được ạ.', 'comm-path/DAILY_LIFE/DLY-05-L2.mp3', 'd2c4b91916be'),
  ('DLY-05', 3, '医師', 0, '熱は測りましたか。', '{熱|ねつ}は{測|はか}りましたか。', 'Chị đo nhiệt độ chưa?', 'comm-path/DAILY_LIFE/DLY-05-L3.mp3', 'd2c4b91916be'),
  ('DLY-05', 4, 'リン', 1, '朝は三十七度五分でした。', '{朝|あさ}は{三十七度五分|さんじゅうななどごぶ}でした。', 'Sáng nay là ba mươi bảy độ rưỡi ạ.', 'comm-path/DAILY_LIFE/DLY-05-L4.mp3', 'd2c4b91916be'),
  ('DLY-05', 5, '医師', 0, '喉を見せてください。少し赤いですね。', '{喉|のど}を{見|み}せてください。{少|すこ}し{赤|あか}いですね。', 'Cho tôi xem họng nào. Hơi đỏ nhỉ.', 'comm-path/DAILY_LIFE/DLY-05-L5.mp3', 'd2c4b91916be'),
  ('DLY-05', 6, 'リン', 1, '薬をもらえますか。仕事があるので早く治したいです。', '{薬|くすり}をもらえますか。{仕事|しごと}があるので{早|はや}く{治|なお}したいです。', 'Tôi xin thuốc được không ạ? Tôi có việc nên muốn khỏi sớm.', 'comm-path/DAILY_LIFE/DLY-05-L6.mp3', 'd2c4b91916be'),
  ('DLY-05', 7, '医師', 0, '咳止めを五日分出します。眠くなる成分が入っています。', '{咳止|せきど}めを{五日分|いつかぶん}{出|だ}します。{眠|ねむ}くなる{成分|せいぶん}が{入|はい}っています。', 'Tôi kê thuốc ho năm ngày. Trong thuốc có thành phần gây buồn ngủ.', 'comm-path/DAILY_LIFE/DLY-05-L7.mp3', 'd2c4b91916be'),
  ('DLY-05', 8, 'リン', 1, '分かりました。運転は避けます。', '{分|わ}かりました。{運転|うんてん}は{避|さ}けます。', 'Tôi hiểu rồi. Tôi sẽ tránh lái xe.', 'comm-path/DAILY_LIFE/DLY-05-L8.mp3', 'd2c4b91916be'),
  ('DLY-13', 1, 'リン', 1, 'おはようございます。昨日から頭が痛いです。', 'おはようございます。{昨日|きのう}から{頭|あたま}が{痛|いた}いです。', 'Chào bác sĩ. Từ hôm qua tôi bị đau đầu ạ.', 'comm-path/DAILY_LIFE/DLY-13-L1.mp3', 'd2c4b91916be'),
  ('DLY-13', 2, '医師', 0, '熱はありますか。', '{熱|ねつ}はありますか。', 'Anh có bị sốt không ạ?', 'comm-path/DAILY_LIFE/DLY-13-L2.mp3', 'd2c4b91916be'),
  ('DLY-13', 3, 'リン', 1, '少しあります。三十七度五分です。', '{少|すこ}しあります。{三十七度五分|さんじゅうななどごぶ}です。', 'Có một chút. Ba mươi bảy độ rưỡi ạ.', 'comm-path/DAILY_LIFE/DLY-13-L3.mp3', 'd2c4b91916be'),
  ('DLY-13', 4, '医師', 0, 'のどや咳はどうですか。', 'のどや{咳|せき}はどうですか。', 'Họng và ho thì sao ạ?', 'comm-path/DAILY_LIFE/DLY-13-L4.mp3', 'd2c4b91916be'),
  ('DLY-13', 5, 'リン', 1, 'のどは大丈夫ですが、咳が少し出ます。', 'のどは{大丈夫|だいじょうぶ}ですが、{咳|せき}が{少|すこ}し{出|で}ます。', 'Họng thì không sao nhưng hơi ho ạ.', 'comm-path/DAILY_LIFE/DLY-13-L5.mp3', 'd2c4b91916be'),
  ('DLY-13', 6, '医師', 0, '風邪ですね。薬を出します。ゆっくり休んでください。', '{風邪|かぜ}ですね。{薬|くすり}を{出|だ}します。ゆっくり{休|やす}んでください。', 'Anh bị cảm rồi. Tôi kê thuốc. Anh nghỉ ngơi cho khỏe ạ.', 'comm-path/DAILY_LIFE/DLY-13-L6.mp3', 'd2c4b91916be'),
  ('DLY-13', 7, 'リン', 1, 'ありがとうございます。', 'ありがとうございます。', 'Cảm ơn bác sĩ.', 'comm-path/DAILY_LIFE/DLY-13-L7.mp3', 'd2c4b91916be'),
  ('DLY-14', 1, 'リン', 1, 'すみません、この処方箋の薬をお願いします。', 'すみません、この{処方箋|しょほうせん}の{薬|くすり}をお{願|ねが}いします。', 'Xin lỗi, cho tôi lấy thuốc theo đơn này ạ.', 'comm-path/DAILY_LIFE/DLY-14-L1.mp3', 'd2c4b91916be'),
  ('DLY-14', 2, '店員', 0, '保険証はお持ちですか。', '{保険証|ほけんしょう}はお{持|も}ちですか。', 'Anh có mang thẻ bảo hiểm không ạ?', 'comm-path/DAILY_LIFE/DLY-14-L2.mp3', 'd2c4b91916be'),
  ('DLY-14', 3, 'リン', 1, 'はい、これです。', 'はい、これです。', 'Vâng, đây ạ.', 'comm-path/DAILY_LIFE/DLY-14-L3.mp3', 'd2c4b91916be'),
  ('DLY-14', 4, '店員', 0, 'この薬は一日三回、食後に飲んでください。', 'この{薬|くすり}は{一日三回|いちにちさんかい}、{食後|しょくご}に{飲|の}んでください。', 'Thuốc này uống ba lần một ngày, sau bữa ăn ạ.', 'comm-path/DAILY_LIFE/DLY-14-L4.mp3', 'd2c4b91916be'),
  ('DLY-14', 5, 'リン', 1, '何日分ですか。', '{何日分|なんにちぶん}ですか。', 'Uống trong mấy ngày ạ?', 'comm-path/DAILY_LIFE/DLY-14-L5.mp3', 'd2c4b91916be'),
  ('DLY-14', 6, '店員', 0, '三日分です。', '{三日分|みっかぶん}です。', 'Ba ngày ạ.', 'comm-path/DAILY_LIFE/DLY-14-L6.mp3', 'd2c4b91916be'),
  ('DLY-14', 7, 'リン', 1, '分かりました。ありがとうございます。', '{分|わ}かりました。ありがとうございます。', 'Tôi hiểu rồi. Cảm ơn chị.', 'comm-path/DAILY_LIFE/DLY-14-L7.mp3', 'd2c4b91916be'),
  ('DLY-08', 1, 'リン', 1, '昨日は引っ越しで騒がしくて、すみませんでした。', '{昨日|きのう}は{引|ひ}っ{越|こ}しで{騒|さわ}がしくて、すみませんでした。', 'Hôm qua chuyển nhà ồn ào, cháu xin lỗi ạ.', 'comm-path/DAILY_LIFE/DLY-08-L1.mp3', 'd2c4b91916be'),
  ('DLY-08', 2, '隣人', 0, 'いえいえ、お互い様ですよ。', 'いえいえ、お{互|たが}い{様|さま}ですよ。', 'Không sao đâu, ai cũng có lúc thế mà.', 'comm-path/DAILY_LIFE/DLY-08-L2.mp3', 'd2c4b91916be'),
  ('DLY-08', 3, 'リン', 1, 'これ、少しですがどうぞ。', 'これ、{少|すこ}しですがどうぞ。', 'Đây, chút quà nhỏ, cô nhận cho ạ.', 'comm-path/DAILY_LIFE/DLY-08-L3.mp3', 'd2c4b91916be'),
  ('DLY-08', 4, '隣人', 0, 'あら、気を使わせてしまって。ありがとう。', 'あら、{気|き}を{使|つか}わせてしまって。ありがとう。', 'Ôi, làm cháu phải bận tâm rồi. Cảm ơn nhé.', 'comm-path/DAILY_LIFE/DLY-08-L4.mp3', 'd2c4b91916be'),
  ('DLY-08', 5, 'リン', 1, 'ごみ出しのことなど、また教えてください。', 'ごみ{出|だ}しのことなど、また{教|おし}えてください。', 'Chuyện đổ rác các thứ, cô chỉ thêm cho cháu với ạ.', 'comm-path/DAILY_LIFE/DLY-08-L5.mp3', 'd2c4b91916be'),
  ('DLY-08', 6, '隣人', 0, 'いつでも聞いてね。町内会の集まりも月に一度あるのよ。', 'いつでも{聞|き}いてね。{町内|ちょうない}{会|かい}の{集|あつ}まりも{月|つき}に{一度|いちど}あるのよ。', 'Cứ hỏi bất cứ lúc nào. Tổ dân phố mỗi tháng họp một lần đấy.', 'comm-path/DAILY_LIFE/DLY-08-L6.mp3', 'd2c4b91916be'),
  ('DLY-08', 7, 'リン', 1, '参加したほうがいいでしょうか。', '{参加|さんか}したほうがいいでしょうか。', 'Cháu có nên tham gia không ạ?', 'comm-path/DAILY_LIFE/DLY-08-L7.mp3', 'd2c4b91916be'),
  ('DLY-08', 8, '隣人', 0, '顔を覚えてもらえるから、一度来てみるといいわ。', '{顔|かお}を{覚|おぼ}えてもらえるから、{一度|いちど}{来|き}てみるといいわ。', 'Để mọi người nhớ mặt, thử đến một lần là tốt đấy.', 'comm-path/DAILY_LIFE/DLY-08-L8.mp3', 'd2c4b91916be'),
  ('DLY-17', 1, 'リン', 1, '週末、何か予定がある？', '{週末|しゅうまつ}、{何|なに}か{予定|よてい}がある？', 'Cuối tuần cậu có kế hoạch gì không?', 'comm-path/DAILY_LIFE/DLY-17-L1.mp3', 'd2c4b91916be'),
  ('DLY-17', 2, '友人', 0, '特にないよ。どうしたの？', '{特|とく}にないよ。どうしたの？', 'Không có gì đặc biệt. Sao vậy?', 'comm-path/DAILY_LIFE/DLY-17-L2.mp3', 'd2c4b91916be'),
