  ('BRSE-12', 7, '田中', 0, 'わかりました。エビデンスも一緒に送ってください。', 'わかりました。エビデンスも{一緒|いっしょ}に{送|おく}ってください。', 'Tôi hiểu rồi. Gửi kèm cả bằng chứng test nhé.', 'comm-path/BA/BRSE-12-L7.mp3', '80cfde997abf'),
  ('BRSE-12', 8, 'グエン', 0, 'かしこまりました。テスト結果報告書とエビデンスをまとめて、本日中にお送りいたします。', 'かしこまりました。テスト{結果|けっか}{報告|ほうこく}{書|しょ}とエビデンスをまとめて、{本日|ほんじつ}{中|ちゅう}にお{送|おく}りいたします。', 'Vâng. Trong hôm nay tôi sẽ tổng hợp báo cáo kết quả test và bằng chứng rồi gửi anh.', 'comm-path/BA/BRSE-12-L8.mp3', '80cfde997abf'),
  ('BRSE-18', 1, 'グエン', 0, 'ファムさん、結合テストの結果をご報告します。', 'ファムさん、{結合|けつごう}テストの{結果|けっか}をご{報告|ほうこく}します。', 'Anh Phạm, tôi báo cáo kết quả kiểm thử tích hợp ạ.', 'comm-path/BA/BRSE-18-L1.mp3', '80cfde997abf'),
  ('BRSE-18', 2, 'ファム', 0, '結果はどうでしたか。', '{結果|けっか}はどうでしたか。', 'Kết quả thế nào ạ?', 'comm-path/BA/BRSE-18-L2.mp3', '80cfde997abf'),
  ('BRSE-18', 3, 'グエン', 0, '五十のテストケースのうち、四十八件が合格しました。', '{五十|ごじゅう}のテストケースのうち、{四十八件|よんじゅうはっけん}が{合格|ごうかく}しました。', 'Trong năm mươi ca kiểm thử, bốn mươi tám ca đạt ạ.', 'comm-path/BA/BRSE-18-L3.mp3', '80cfde997abf'),
