  ('BRSE-19', 1, 'グエン', 0, '田中さん、テストケースの一覧を確認していただけますか。', '{田中|たなか}さん、テストケースの{一覧|いちらん}を{確認|かくにん}していただけますか。', 'Anh Tanaka, anh xác nhận giúp tôi danh sách ca kiểm thử được không ạ?', 'comm-path/BA/BRSE-19-L1.mp3', '80cfde997abf'),
  ('BRSE-19', 2, '田中', 0, 'はい、拝見します。', 'はい、{拝見|はいけん}します。', 'Vâng, tôi xem ạ.', 'comm-path/BA/BRSE-19-L2.mp3', '80cfde997abf'),
  ('BRSE-19', 3, 'グエン', 0, '不足している項目はありますか。', '{不足|ふそく}している{項目|こうもく}はありますか。', 'Có hạng mục nào còn thiếu không ạ?', 'comm-path/BA/BRSE-19-L3.mp3', '80cfde997abf'),
