  ('WRK-01', 4, '同僚', 0, '朝礼までまだ時間がありますね。', '{朝礼|ちょうれい}までまだ{時間|じかん}がありますね。', 'Còn thời gian đến giờ họp sáng nhỉ.', 'comm-path/WORK/WRK-01-L4.mp3', '7a8f7e1bcd88'),
