  ('WRK-02', 5, 'リン', 1, 'ありがとうございます。よろしくお願いします。', 'ありがとうございます。よろしくお{願|ねが}いします。', 'Cảm ơn anh. Rất mong được giúp đỡ ạ.', 'comm-path/WORK/WRK-02-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-02', 6, '先輩', 0, 'こちらこそ。', 'こちらこそ。', 'Tôi cũng vậy ạ.', 'comm-path/WORK/WRK-02-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-03', 1, 'リン', 1, 'お先に失礼します。', 'お{先|さき}に{失礼|しつれい}します。', 'Em xin phép về trước ạ.', 'comm-path/WORK/WRK-03-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-03', 2, '上司', 0, 'お疲れさま。明日の朝、資料を確認してね。', 'お{疲|つか}れさま。{明日|あした}の{朝|あさ}、{資料|しりょう}を{確認|かくにん}してね。', 'Vất vả rồi. Sáng mai em xem lại tài liệu nhé.', 'comm-path/WORK/WRK-03-L2.mp3', '7a8f7e1bcd88'),
