  ('WRK-03', 4, '上司', 0, 'あと、明日の会議は九時からだよ。', 'あと、{明日|あした}の{会議|かいぎ}は{九時|くじ}からだよ。', 'À, họp ngày mai bắt đầu từ chín giờ đấy.', 'comm-path/WORK/WRK-03-L4.mp3', '7a8f7e1bcd88'),
