  ('WRK-07', 6, '上司', 0, 'じゃ、気をつけて行ってきて。', 'じゃ、{気|き}をつけて{行|い}ってきて。', 'Vậy em đi cẩn thận nhé.', 'comm-path/WORK/WRK-07-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-08', 1, 'リン', 1, '部長、今日は三時に早退してもいいですか。', '{部長|ぶちょう}、{今日|きょう}は{三時|さんじ}に{早退|そうたい}してもいいですか。', 'Thưa trưởng phòng, hôm nay em xin về sớm lúc ba giờ được không ạ?', 'comm-path/WORK/WRK-08-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-08', 2, '上司', 0, 'どうしたの？', 'どうしたの？', 'Có chuyện gì ạ?', 'comm-path/WORK/WRK-08-L2.mp3', '7a8f7e1bcd88'),
