  ('WRK-08', 4, '上司', 0, 'それは大変だね。早く帰りなさい。', 'それは{大変|たいへん}だね。{早|はや}く{帰|かえ}りなさい。', 'Vậy là vất vả rồi. Em về sớm đi.', 'comm-path/WORK/WRK-08-L4.mp3', '7a8f7e1bcd88'),
