  ('WRK-11', 2, '取引先', 0, 'お世話になっております。佐藤ですが、田中さんに伝言をお願いできますか。', 'お{世話|せわ}になっております。{佐藤|さとう}ですが、{田中|たなか}さんに{伝言|でんごん}をお{願|ねが}いできますか。', 'Chúng tôi luôn được giúp đỡ. Tôi là Sato, nhờ chuyển lời nhắn cho anh Tanaka được không ạ?', 'comm-path/WORK/WRK-11-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-11', 3, 'リン', 1, 'はい、承ります。', 'はい、{承|うけたまわ}ります。', 'Vâng, tôi xin nghe ạ.', 'comm-path/WORK/WRK-11-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-11', 4, '取引先', 0, '明日の会議を十時に変更したいとお伝えください。', '{明日|あした}の{会議|かいぎ}を{十時|じゅうじ}に{変更|へんこう}したいとお{伝|つた}えください。', 'Xin nói là muốn đổi cuộc họp ngày mai sang mười giờ ạ.', 'comm-path/WORK/WRK-11-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-11', 5, 'リン', 1, 'かしこまりました。復唱いたします。明日の会議を十時に変更ですね。', 'かしこまりました。{復唱|ふくしょう}いたします。{明日|あした}の{会議|かいぎ}を{十時|じゅうじ}に{変更|へんこう}ですね。', 'Vâng ạ. Tôi xin nhắc lại: đổi cuộc họp ngày mai sang mười giờ ạ.', 'comm-path/WORK/WRK-11-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-11', 6, '取引先', 0, 'はい、よろしくお願いします。', 'はい、よろしくお{願|ねが}いします。', 'Vâng, nhờ anh ạ.', 'comm-path/WORK/WRK-11-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-12', 1, 'リン', 1, 'お世話になっております。ミライ商事のリンです。', 'お{世話|せわ}になっております。ミライ{商事|しょうじ}のリンです。', 'Chúng tôi luôn được quý công ty giúp đỡ. Tôi là Linh, công ty Mirai Shōji ạ.', 'comm-path/WORK/WRK-12-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-12', 2, '取引先', 0, 'ああ、リンさん。こんにちは。', 'ああ、リンさん。こんにちは。', 'À, chị Linh. Chào chị.', 'comm-path/WORK/WRK-12-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-12', 3, 'リン', 1, '明日の打ち合わせの件でご連絡しました。', '{明日|あした}の{打|う}ち{合|あ}わせの{件|けん}でご{連絡|れんらく}しました。', 'Tôi gọi để trao đổi về buổi họp ngày mai ạ.', 'comm-path/WORK/WRK-12-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-12', 4, '取引先', 0, 'はい、何でしょうか。', 'はい、{何|なん}でしょうか。', 'Vâng, có việc gì ạ?', 'comm-path/WORK/WRK-12-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-12', 5, 'リン', 1, '時間を十四時に変更していただけますか。', '{時間|じかん}を{十四時|じゅうよじ}に{変更|へんこう}していただけますか。', 'Chúng ta đổi giờ sang mười bốn giờ được không ạ?', 'comm-path/WORK/WRK-12-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-12', 6, '取引先', 0, '大丈夫です。十四時に伺います。', '{大丈夫|だいじょうぶ}です。{十四時|じゅうよじ}に{伺|うかが}います。', 'Được ạ. Mười bốn giờ tôi sẽ đến.', 'comm-path/WORK/WRK-12-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-16', 1, 'リン', 1, '主任、作業場に入る前に何か必要ですか。', '{主任|しゅにん}、{作業場|さぎょうば}に{入|はい}る{前|まえ}に{何|なに}か{必要|ひつよう}ですか。', 'Thưa tổ trưởng, trước khi vào xưởng cần chuẩn bị gì ạ?', 'comm-path/WORK/WRK-16-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-16', 2, '主任', 0, 'ヘルメットと安全靴を着用してください。', 'ヘルメットと{安全靴|あんぜんぐつ}を{着用|ちゃくよう}してください。', 'Hãy đội mũ bảo hộ và đi giày bảo hộ ạ.', 'comm-path/WORK/WRK-16-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-16', 3, 'リン', 1, '手袋も必要ですか。', '{手袋|てぶくろ}も{必要|ひつよう}ですか。', 'Găng tay có cần không ạ?', 'comm-path/WORK/WRK-16-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-16', 4, '主任', 0, 'はい、作業の前に必ずつけてください。', 'はい、{作業|さぎょう}の{前|まえ}に{必|かなら}ずつけてください。', 'Có, trước khi làm việc nhất định phải đeo ạ.', 'comm-path/WORK/WRK-16-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-16', 5, 'リン', 1, '分かりました。すぐに着用します。', '{分|わ}かりました。すぐに{着用|ちゃくよう}します。', 'Em hiểu rồi. Em đeo ngay đây ạ.', 'comm-path/WORK/WRK-16-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-16', 6, '主任', 0, '安全第一ですから、忘れないでください。', '{安全第一|あんぜんだいいち}ですから、{忘|わす}れないでください。', 'An toàn là trên hết nên đừng quên nhé.', 'comm-path/WORK/WRK-16-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-17', 1, 'リン', 1, '先輩、ここで喫煙してもいいですか。', '{先輩|せんぱい}、ここで{喫煙|きつえん}してもいいですか。', 'Anh ơi, hút thuốc ở đây được không ạ?', 'comm-path/WORK/WRK-17-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-17', 2, '先輩', 0, 'だめです。この辺は火気厳禁です。', 'だめです。この{辺|へん}は{火気厳禁|かきげんきん}です。', 'Không được. Khu này cấm lửa ạ.', 'comm-path/WORK/WRK-17-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-17', 3, 'リン', 1, 'では、どこで吸えますか。', 'では、どこで{吸|す}えますか。', 'Vậy hút ở đâu được ạ?', 'comm-path/WORK/WRK-17-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-17', 4, '先輩', 0, '喫煙所でお願いします。', '{喫煙所|きつえんじょ}でお{願|ねが}いします。', 'Hút ở khu vực hút thuốc ạ.', 'comm-path/WORK/WRK-17-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-17', 5, 'リン', 1, '分かりました。喫煙所はどこですか。', '{分|わ}かりました。{喫煙所|きつえんじょ}はどこですか。', 'Em hiểu rồi. Khu hút thuốc ở đâu ạ?', 'comm-path/WORK/WRK-17-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-17', 6, '先輩', 0, '工場の裏口のそばです。', '{工場|こうじょう}の{裏口|うらぐち}のそばです。', 'Ở gần cổng sau của nhà máy ạ.', 'comm-path/WORK/WRK-17-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-18', 1, 'リン', 1, '主任、今日は避難訓練がありますか。', '{主任|しゅにん}、{今日|きょう}は{避難訓練|ひなんくんれん}がありますか。', 'Thưa tổ trưởng, hôm nay có diễn tập sơ tán không ạ?', 'comm-path/WORK/WRK-18-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-18', 2, '主任', 0, 'はい、午後三時からです。', 'はい、{午後|ごご}{三時|さんじ}からです。', 'Có, từ ba giờ chiều ạ.', 'comm-path/WORK/WRK-18-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-18', 3, 'リン', 1, 'どこに集まりますか。', 'どこに{集|あつ}まりますか。', 'Tập trung ở đâu ạ?', 'comm-path/WORK/WRK-18-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-18', 4, '主任', 0, '工場の前の広場です。', '{工場|こうじょう}の{前|まえ}の{広場|ひろば}です。', 'Ở quảng trường trước nhà máy ạ.', 'comm-path/WORK/WRK-18-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-18', 5, 'リン', 1, '非常口はどこですか。', '{非常口|ひじょうぐち}はどこですか。', 'Lối thoát hiểm ở đâu ạ?', 'comm-path/WORK/WRK-18-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-18', 6, '主任', 0, '各フロアに二か所あります。', '{各|かく}フロアに{二|に}か{所|しょ}あります。', 'Mỗi tầng có hai chỗ ạ.', 'comm-path/WORK/WRK-18-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-19', 1, 'リン', 1, '主任、来週のシフトを確認したいです。', '{主任|しゅにん}、{来週|らいしゅう}のシフトを{確認|かくにん}したいです。', 'Thưa tổ trưởng, em muốn xác nhận ca làm tuần sau ạ.', 'comm-path/WORK/WRK-19-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-19', 2, '主任', 0, 'リンさんは来週、夜勤です。', 'リンさんは{来週|らいしゅう}、{夜勤|やきん}です。', 'Tuần sau em làm ca đêm ạ.', 'comm-path/WORK/WRK-19-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-19', 3, 'リン', 1, '何時から何時までですか。', '{何時|なんじ}から{何時|なんじ}までですか。', 'Từ mấy giờ đến mấy giờ ạ?', 'comm-path/WORK/WRK-19-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-19', 4, '主任', 0, '午後十時から朝六時までです。', '{午後十時|ごごじゅうじ}から{朝六時|あさろくじ}までです。', 'Từ mười giờ tối đến sáu giờ sáng ạ.', 'comm-path/WORK/WRK-19-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-19', 5, 'リン', 1, '休憩はありますか。', '{休憩|きゅうけい}はありますか。', 'Có giờ nghỉ giải lao không ạ?', 'comm-path/WORK/WRK-19-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-19', 6, '主任', 0, '夜中に一時間あります。', '{夜中|よなか}に{一時間|いちじかん}あります。', 'Có một tiếng vào giữa đêm ạ.', 'comm-path/WORK/WRK-19-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-20', 1, 'リン', 1, 'お疲れさまです。夜勤、よろしくお願いします。', 'お{疲|つか}れさまです。{夜勤|やきん}、よろしくお{願|ねが}いします。', 'Vất vả rồi. Ca đêm nhờ anh ạ.', 'comm-path/WORK/WRK-20-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-20', 2, '同僚', 0, 'こちらこそ。何か引き継ぎはありますか。', 'こちらこそ。{何|なに}か{引|ひ}き{継|つ}ぎはありますか。', 'Tôi cũng vậy. Có gì bàn giao không ạ?', 'comm-path/WORK/WRK-20-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-20', 3, 'リン', 1, '三番の機械が少し調子悪いです。', '{三番|さんばん}の{機械|きかい}が{少|すこ}し{調子|ちょうし}{悪|わる}いです。', 'Máy số ba hơi có vấn đề ạ.', 'comm-path/WORK/WRK-20-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-20', 4, '同僚', 0, '分かりました。注意して見ます。', '{分|わ}かりました。{注意|ちゅうい}して{見|み}ます。', 'Tôi hiểu rồi. Tôi sẽ để ý ạ.', 'comm-path/WORK/WRK-20-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-20', 5, 'リン', 1, 'あと、材料が残り少ないです。', 'あと、{材料|ざいりょう}が{残|のこ}り{少|すく}ないです。', 'À, nguyên liệu còn ít ạ.', 'comm-path/WORK/WRK-20-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-20', 6, '同僚', 0, '了解です。補充しておきます。', '{了解|りょうかい}です。{補充|ほじゅう}しておきます。', 'Rõ rồi. Tôi sẽ bổ sung ạ.', 'comm-path/WORK/WRK-20-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-21', 1, 'リン', 1, '工場長、お呼びですか。', '{工場長|こうじょうちょう}、お{呼|よ}びですか。', 'Thưa quản đốc, ông gọi em ạ?', 'comm-path/WORK/WRK-21-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-21', 2, '工場長', 0, 'リンさん、今日から三十分残業できますか。', 'リンさん、{今日|きょう}から{三十分|さんじゅっぷん}{残業|ざんぎょう}できますか。', 'Linh, từ hôm nay em tăng ca ba mươi phút được không?', 'comm-path/WORK/WRK-21-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-21', 3, 'リン', 1, '分かりました。何時までですか。', '{分|わ}かりました。{何時|なんじ}までですか。', 'Vâng ạ. Đến mấy giờ ạ?', 'comm-path/WORK/WRK-21-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-21', 4, '工場長', 0, '定時の後、三十分です。', '{定時|ていじ}の{後|あと}、{三十分|さんじゅっぷん}です。', 'Sau giờ quy định ba mươi phút ạ.', 'comm-path/WORK/WRK-21-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-21', 5, 'リン', 1, '残業代は出ますか。', '{残業代|ざんぎょうだい}は{出|で}ますか。', 'Có trả tiền tăng ca không ạ?', 'comm-path/WORK/WRK-21-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-21', 6, '工場長', 0, 'はい、きちんと支払います。', 'はい、きちんと{支払|しはら}います。', 'Có, chúng tôi trả đầy đủ ạ.', 'comm-path/WORK/WRK-21-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-28', 1, 'リン', 1, '主任、今日は何をすればいいですか。', '{主任|しゅにん}、{今日|きょう}は{何|なに}をすればいいですか。', 'Thưa tổ trưởng, hôm nay em cần làm gì ạ?', 'comm-path/WORK/WRK-28-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-28', 2, '主任', 0, '作業が終わったら、工具を元の場所に戻してください。', '{作業|さぎょう}が{終|お}わったら、{工具|こうぐ}を{元|もと}の{場所|ばしょ}に{戻|もど}してください。', 'Sau khi xong việc, hãy để dụng cụ về chỗ cũ ạ.', 'comm-path/WORK/WRK-28-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-28', 3, 'リン', 1, '不要なものは捨てますか。', '{不要|ふよう}なものは{捨|す}てますか。', 'Đồ không cần thì vứt đi ạ?', 'comm-path/WORK/WRK-28-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-28', 4, '主任', 0, 'はい、廃棄物の箱に入れてください。', 'はい、{廃棄物|はいきぶつ}の{箱|はこ}に{入|い}れてください。', 'Vâng, bỏ vào thùng phế liệu ạ.', 'comm-path/WORK/WRK-28-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-28', 5, 'リン', 1, '掃除もしますか。', '{掃除|そうじ}もしますか。', 'Có dọn vệ sinh không ạ?', 'comm-path/WORK/WRK-28-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-28', 6, '主任', 0, 'はい、床をきれいにしてください。', 'はい、{床|ゆか}をきれいにしてください。', 'Có, lau sạch sàn nhà ạ.', 'comm-path/WORK/WRK-28-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-29', 1, 'リン', 1, '今週の掃除当番は誰ですか。', '{今週|こんしゅう}の{掃除当番|そうじとうばん}は{誰|だれ}ですか。', 'Tuần này ai trực vệ sinh ạ?', 'comm-path/WORK/WRK-29-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-29', 2, '同僚', 0, '私たち二人ですよ。', '{私|わたし}たち{二人|ふたり}ですよ。', 'Hai chúng ta đấy ạ.', 'comm-path/WORK/WRK-29-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-29', 3, 'リン', 1, 'いつ掃除しますか。', 'いつ{掃除|そうじ}しますか。', 'Khi nào dọn vệ sinh ạ?', 'comm-path/WORK/WRK-29-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-29', 4, '同僚', 0, '毎日、終業後に十分間です。', '{毎日|まいにち}、{終業後|しゅうぎょうご}に{十分間|じゅっぷんかん}です。', 'Mỗi ngày mười phút sau giờ làm ạ.', 'comm-path/WORK/WRK-29-L4.mp3', '7a8f7e1bcd88'),
