  ('WRK-29', 6, '同僚', 0, '三番のラインの周りです。', '{三番|さんばん}のラインの{周|まわ}りです。', 'Quanh dây chuyền số ba ạ.', 'comm-path/WORK/WRK-29-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-30', 1, 'リン', 1, '先輩、5Sの点検をお願いします。', '{先輩|せんぱい}、5Sの{点検|てんけん}をお{願|ねが}いします。', 'Anh ơi, nhờ anh kiểm tra 5S ạ.', 'comm-path/WORK/WRK-30-L1.mp3', '7a8f7e1bcd88'),
