  ('WRK-26', 5, 'リン', 1, '止めてから点検しますか。', '{止|と}めてから{点検|てんけん}しますか。', 'Dừng máy rồi kiểm tra ạ?', 'comm-path/WORK/WRK-26-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-26', 6, '先輩', 0, 'はい、一緒に確認しましょう。', 'はい、{一緒|いっしょ}に{確認|かくにん}しましょう。', 'Vâng, cùng kiểm tra nhé.', 'comm-path/WORK/WRK-26-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-27', 1, 'リン', 1, '主任、油漏れを発見しました。', '{主任|しゅにん}、{油漏|あぶらも}れを{発見|はっけん}しました。', 'Thưa tổ trưởng, em phát hiện rò rỉ dầu ạ.', 'comm-path/WORK/WRK-27-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-27', 2, '主任', 0, 'すぐに機械を停止してください。', 'すぐに{機械|きかい}を{停止|ていし}してください。', 'Hãy dừng máy ngay lập tức ạ.', 'comm-path/WORK/WRK-27-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-27', 3, 'リン', 1, '応急処置はどうすればいいですか。', '{応急処置|おうきゅうしょち}はどうすればいいですか。', 'Xử lý tạm thời thế nào ạ?', 'comm-path/WORK/WRK-27-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-27', 4, '主任', 0, 'まず、漏れた油を拭き取ってください。', 'まず、{漏|も}れた{油|あぶら}を{拭|ふ}き{取|と}ってください。', 'Trước tiên, lau sạch dầu bị rò ạ.', 'comm-path/WORK/WRK-27-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-27', 5, 'リン', 1, 'その後、報告しますか。', 'その{後|あと}、{報告|ほうこく}しますか。', 'Sau đó em báo cáo ạ?', 'comm-path/WORK/WRK-27-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-27', 6, '主任', 0, 'はい、すぐに知らせてください。', 'はい、すぐに{知|し}らせてください。', 'Vâng, báo ngay cho tôi ạ.', 'comm-path/WORK/WRK-27-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-40', 1, 'リン', 1, 'すみません、買った商品に傷があります。', 'すみません、{買|か}った{商品|しょうひん}に{傷|きず}があります。', 'Xin lỗi, sản phẩm em mua bị xước ạ.', 'comm-path/WORK/WRK-40-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-40', 2, '店員', 0, '申し訳ございません。確認させてください。', '{申|もう}し{訳|わけ}ございません。{確認|かくにん}させてください。', 'Thành thật xin lỗi quý khách. Cho tôi kiểm tra ạ.', 'comm-path/WORK/WRK-40-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-40', 3, 'リン', 1, '開けた時から傷がありました。', '{開|あ}けた{時|とき}から{傷|きず}がありました。', 'Từ lúc mở ra đã có vết xước rồi ạ.', 'comm-path/WORK/WRK-40-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-40', 4, '店員', 0, 'かしこまりました。新しいものとお取り替えします。', 'かしこまりました。{新|あたら}しいものとお{取|と}り{替|か}えします。', 'Vâng ạ. Tôi đổi cho quý khách sản phẩm mới ạ.', 'comm-path/WORK/WRK-40-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-40', 5, 'リン', 1, '返金もできますか。', '{返金|へんきん}もできますか。', 'Có thể hoàn tiền được không ạ?', 'comm-path/WORK/WRK-40-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-40', 6, '店員', 0, 'はい、ご希望に応じます。', 'はい、ご{希望|きぼう}に{応|おう}じます。', 'Vâng, chúng tôi đáp ứng theo mong muốn của quý khách ạ.', 'comm-path/WORK/WRK-40-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-41', 1, 'リン', 1, '店長さん、返金をお願いしたいです。', '{店長|てんちょう}さん、{返金|へんきん}をお{願|ねが}いしたいです。', 'Quản lý ơi, em muốn yêu cầu hoàn tiền ạ.', 'comm-path/WORK/WRK-41-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-41', 2, '店長', 0, '経緯をお聞かせいただけますか。', '{経緯|けいい}をお{聞|き}かせいただけますか。', 'Cho tôi nghe diễn biến sự việc ạ.', 'comm-path/WORK/WRK-41-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-41', 3, 'リン', 1, '買った商品が初期不良でした。', '{買|か}った{商品|しょうひん}が{初期不良|しょきふりょう}でした。', 'Sản phẩm em mua bị lỗi ban đầu ạ.', 'comm-path/WORK/WRK-41-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-41', 4, '店長', 0, '大変申し訳ございません。すぐに返金いたします。', '{大変|たいへん}{申|もう}し{訳|わけ}ございません。すぐに{返金|へんきん}いたします。', 'Thành thật xin lỗi. Tôi hoàn tiền ngay ạ.', 'comm-path/WORK/WRK-41-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-41', 5, 'リン', 1, 'お詫びの言葉もいただけますか。', 'お{詫|わ}びの{言葉|ことば}もいただけますか。', 'Em có thể nhận lời xin lỗi không ạ?', 'comm-path/WORK/WRK-41-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-41', 6, '店長', 0, 'はい、心よりお詫び申し上げます。', 'はい、{心|こころ}よりお{詫|わ}び{申|もう}し{上|あ}げます。', 'Vâng, tôi chân thành xin lỗi quý khách ạ.', 'comm-path/WORK/WRK-41-L6.mp3', '7a8f7e1bcd88'),
  ('WRK-42', 1, 'リン', 1, 'この前のクレームの件はどうなりましたか。', 'この{前|まえ}のクレームの{件|けん}はどうなりましたか。', 'Chuyện khiếu nại lần trước thế nào rồi ạ?', 'comm-path/WORK/WRK-42-L1.mp3', '7a8f7e1bcd88'),
  ('WRK-42', 2, '店員', 0, 'ご迷惑をおかけして申し訳ございません。', 'ご{迷惑|めいわく}をおかけして{申|もう}し{訳|わけ}ございません。', 'Chúng tôi thành thật xin lỗi vì đã làm phiền quý khách ạ.', 'comm-path/WORK/WRK-42-L2.mp3', '7a8f7e1bcd88'),
  ('WRK-42', 3, 'リン', 1, '原因は分かりましたか。', '{原因|げんいん}は{分|わ}かりましたか。', 'Đã biết nguyên nhân chưa ạ?', 'comm-path/WORK/WRK-42-L3.mp3', '7a8f7e1bcd88'),
  ('WRK-42', 4, '店員', 0, 'はい、調査の結果、初期不良でした。', 'はい、{調査|ちょうさ}の{結果|けっか}、{初期不良|しょきふりょう}でした。', 'Vâng, kết quả điều tra cho thấy là lỗi ban đầu ạ.', 'comm-path/WORK/WRK-42-L4.mp3', '7a8f7e1bcd88'),
  ('WRK-42', 5, 'リン', 1, '今後の対応はどうなりますか。', '{今後|こんご}の{対応|たいおう}はどうなりますか。', 'Cách xử lý sau này thế nào ạ?', 'comm-path/WORK/WRK-42-L5.mp3', '7a8f7e1bcd88'),
  ('WRK-42', 6, '店員', 0, '再発防止に努めます。ご指摘ありがとうございます。', '{再発防止|さいはつぼうし}に{努|つと}めます。ご{指摘|してき}ありがとうございます。', 'Chúng tôi sẽ cố gắng ngăn tái diễn. Cảm ơn góp ý của quý khách ạ.', 'comm-path/WORK/WRK-42-L6.mp3', '7a8f7e1bcd88')
