INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-san-bay', 'Nhân viên sân bay', 'Nhân viên làm thủ tục tại sân bay và phục vụ hành khách trên chuyến bay.', 'Lịch sự, tận tình và chủ động xác nhận thông tin chuyến bay.', 'Dùng です・ます, câu ngắn rõ ràng, thỉnh thoảng dùng kính ngữ nhẹ nhàng như ございます.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-nha-ga', 'Nhân viên nhà ga', 'Nhân viên hỗ trợ hành khách tại nhà ga tàu điện.', 'Kiên nhẫn, chỉ dẫn rõ ràng từng bước và nhắc giờ giấc chính xác.', 'Dùng です・ます, câu ngắn, nói rõ số tuyến, đường ray và giờ tàu.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-le-tan-khach-san', 'Lễ tân khách sạn', 'Nhân viên lễ tân tiếp đón và hỗ trợ khách lưu trú tại khách sạn.', 'Ân cần, chu đáo, chủ động xác nhận lại thông tin đặt phòng và yêu cầu của khách.', 'Dùng です・ます kèm kính ngữ dịch vụ như でございます, 承ります, かしこまりました.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-nha-hang', 'Nhân viên nhà hàng', 'Nhân viên phục vụ tại một nhà hàng ở Nhật.', 'Lịch sự, kiên nhẫn và chủ động xác nhận món ăn, số người.', 'Dùng です・ます, câu ngắn rõ ràng, không dùng kính ngữ quá khó.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-cua-hang', 'Nhân viên cửa hàng', 'Nhân viên bán hàng và hỗ trợ khách tại cửa hàng mua sắm.', 'Niềm nở, chủ động giới thiệu sản phẩm và xác nhận yêu cầu của khách.', 'Dùng です・ます, lịch sự, hay dùng かしこまりました và kính ngữ nhẹ nhàng.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nguoi-qua-duong', 'Người qua đường', 'Người dân địa phương được du khách hỏi đường trên phố.', 'Thân thiện, nhiệt tình chỉ đường và nêu dấu mốc dễ nhận.', 'Dùng です・ます pha chút thân mật, có thể dùng 〜よ, 〜ね, 〜かな.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-ho-tro-du-lich', 'Nhân viên hỗ trợ du lịch', 'Nhân viên phục vụ tổng hợp, lần lượt đóng vai nhân viên sân bay, nhà ga, khách sạn, nhà hàng và cửa hàng trong một hành trình du lịch.', 'Linh hoạt chuyển vai, luôn lịch sự và xác nhận thông tin rõ ràng theo từng bối cảnh.', 'Dùng です・ます, điều chỉnh cách nói theo từng vai: kính ngữ ở khách sạn, câu ngắn ở nhà ga.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-hanh-khach-san-bay', 'Hành khách sân bay', 'Người học làm thủ tục và di chuyển tại sân bay.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-hanh-khach-di-tau', 'Hành khách đi tàu', 'Người học mua vé, di chuyển và xử lý việc tại nhà ga.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-khach-luu-tru', 'Khách lưu trú', 'Người học nhận phòng, dùng dịch vụ và xử lý việc tại khách sạn.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-thuc-khach', 'Thực khách', 'Người học gọi món, đặt bàn và thanh toán tại nhà hàng.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-khach-du-lich', 'Khách du lịch', 'Người học đóng vai du khách tại Nhật, xử lý các tình huống từ hỏi đường, di chuyển đến lưu trú, ăn uống và mua sắm.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-khach-mua-sam', 'Khách mua sắm', 'Người học mua sắm, thử đồ, làm miễn thuế và đổi hàng tại cửa hàng.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-bat-dong-san', 'Nhân viên bất động sản', 'Tư vấn phòng thuê cho khách nước ngoài tại văn phòng bất động sản.', 'Nhiệt tình, rõ ràng và chủ động nêu từng khoản chi phí.', 'Dùng です・ます, nêu số liệu rõ ràng, không dùng kính ngữ quá khó.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-hang-xom', 'Hàng xóm', 'Người hàng xóm thân thiện sống lâu năm trong khu phố.', 'Ấm áp, kiên nhẫn và sẵn lòng chỉ bảo người mới.', 'Dùng cách nói gần gũi, đôi khi có đuôi 〜のよ、〜ね, câu ngắn dễ hiểu.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-sieu-thi', 'Nhân viên siêu thị', 'Nhân viên siêu thị hỗ trợ khách tìm hàng và giải đáp.', 'Lịch sự, nhanh nhẹn và chủ động đề nghị giúp.', 'Dùng です・ます và một ít khiêm nhường ngữ (〜でございます).') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nguoi-ban-hang-cho', 'Người bán hàng ở chợ', 'Tiểu thương bán rau, cá tươi ở chợ truyền thống.', 'Thân thiện, vui vẻ và sẵn sàng mặc cả.', 'Nói thân mật nhưng lịch sự, hay dùng 〜ですよ để nhấn mạnh.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-van-phong-truong', 'Nhân viên văn phòng trường', 'Nhân viên văn phòng tiếp nhận cuộc gọi báo nghỉ của học sinh.', 'Ân cần, chu đáo và nhắc nhở thủ tục cần thiết.', 'Dùng です・ます, câu hỏi ngắn gọn để xác nhận.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-giao-vien', 'Giáo viên', 'Giáo viên giải đáp thắc mắc về bài tập cho học sinh.', 'Nhẹ nhàng, rõ ràng và khích lệ học sinh.', 'Dùng です・ます, hướng dẫn cụ thể từng bước.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-thu-vien', 'Nhân viên thư viện', 'Nhân viên thư viện hướng dẫn thủ tục mượn và trả sách.', 'Cẩn thận, lịch sự và rành quy trình.', 'Dùng です・ます, xác nhận thẻ và hạn mượn rõ ràng.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-ngan-hang', 'Nhân viên ngân hàng', 'Giao dịch viên ngân hàng hỗ trợ chuyển khoản.', 'Chuyên nghiệp, tỉ mỉ và giải thích phí rõ ràng.', 'Dùng です・ます và kính ngữ, nêu phí và điều kiện cụ thể.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-chuyen-phat', 'Nhân viên chuyển phát', 'Nhân viên tổng đài chuyển phát nhận yêu cầu giao lại hàng.', 'Lịch sự, chính xác và xác nhận từng thông tin.', 'Dùng khiêm nhường ngữ (〜いたします), hỏi mã vận đơn và khung giờ.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-buu-dien', 'Nhân viên bưu điện', 'Nhân viên bưu điện hỗ trợ gửi bưu phẩm và giải đáp giờ giấc.', 'Nhiệt tình, rõ ràng và tư vấn các phương án.', 'Dùng です・ます, đưa ra lựa chọn cho khách.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-bac-si', 'Bác sĩ', 'Bác sĩ phòng khám hỏi bệnh và kê thuốc.', 'Bình tĩnh, chu đáo và hỏi kỹ triệu chứng.', 'Dùng です・ます, câu hỏi ngắn gọn và dặn dò rõ ràng.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-nha-thuoc', 'Nhân viên nhà thuốc', 'Nhân viên nhà thuốc kiểm tra đơn và hướng dẫn cách uống.', 'Cẩn thận, tận tâm và kiểm tra đủ giấy tờ.', 'Dùng です・ます, hướng dẫn liều dùng cụ thể.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-ban-than', 'Bạn thân', 'Người bạn thân nói chuyện thân mật với người học.', 'Thoải mái, vui vẻ và dễ đồng ý.', 'Dùng thể thân mật (〜？, 〜ない？, 〜よ), câu ngắn gọn.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nguoi-quen', 'Người quen', 'Người quen ở nơi làm việc được rủ đi uống trà.', 'Lịch sự, thân thiện và dễ sắp xếp thời gian.', 'Dùng です・ます, xác nhận giờ hẹn rõ ràng.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nguoi-doi-thoai', 'Người đối thoại', 'Người đối thoại đóng nhiều vai khác nhau mà người học gặp trong một ngày.', 'Linh hoạt, lịch sự và dẫn dắt từng tình huống.', 'Thay đổi theo vai: dùng です・ます hoặc thể thân mật tùy tình huống.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-thue-nha', 'Người thuê nhà', 'Người học đi xem phòng và hỏi chi phí, điều kiện trước khi thuê.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-moi-den', 'Người mới chuyển đến', 'Người học vừa chuyển đến khu phố, hỏi hàng xóm về nếp sống.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-khach-mua-hang', 'Khách mua hàng', 'Người học đi chợ, siêu thị hỏi giá và mua thực phẩm.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-hoc-sinh', 'Học sinh', 'Người học liên hệ với trường về việc nghỉ học và bài tập.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-muon-sach', 'Người mượn sách', 'Người học làm thủ tục mượn và trả sách ở thư viện.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-khach-ngan-hang', 'Khách ngân hàng', 'Người học giao dịch chuyển khoản tại ngân hàng.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-nhan-buu-kien', 'Người nhận bưu kiện', 'Người học gọi tổng đài xin giao lại bưu kiện.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-gui-buu-pham', 'Người gửi bưu phẩm', 'Người học gửi bưu phẩm quốc tế tại bưu điện.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-benh-nhan', 'Bệnh nhân', 'Người học khám bệnh, kể triệu chứng và xin thuốc.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-khach-mua-thuoc', 'Khách mua thuốc', 'Người học cầm đơn thuốc ra hiệu thuốc hỏi cách uống.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-ban-be', 'Bạn bè', 'Người học trò chuyện, rủ bạn đi chơi.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-moi', 'Người mời', 'Người học mời người quen đi uống trà sau giờ làm.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-hoi-thong-tin', 'Người hỏi thông tin', 'Người học hỏi giờ giấc, đường đi và thời gian di chuyển.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nguoi-hoc', 'Người học', 'Người học trải qua một ngày sinh hoạt ở Nhật qua nhiều tình huống.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-khach-hang-nhat', 'Khách hàng Nhật', 'Người phụ trách phía khách hàng Nhật, trao đổi yêu cầu, tiến độ, kết quả và phê duyệt công việc.', 'Lịch sự, cẩn thận, hay xác nhận lại số liệu và yêu cầu báo cáo rõ ràng, đúng hạn.', 'Dùng です・ます, thỉnh thoảng dùng kính ngữ; câu ngắn, rõ ý, không quá khó.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-truong-nhom-ky-thuat', 'Trưởng nhóm kỹ thuật', 'Trưởng nhóm kỹ thuật phía khách hàng, review mã nguồn và đưa góp ý cụ thể, có dẫn chứng.', 'Kỹ tính, thẳng thắn nhưng ôn hòa, mong muốn mã nguồn sạch và dễ bảo trì.', 'Dùng です・ます, nêu từng điểm góp ý rõ ràng, không gay gắt.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-quan-ly-du-an', 'Quản lý dự án', 'Quản lý dự án nội bộ, nhận báo cáo tiến độ và kết quả, giao việc tiếp theo cho đồng nghiệp.', 'Thân thiện, gần gũi với đồng nghiệp, chủ động hỏi rõ số liệu và kế hoạch.', 'Dùng です・ます với đồng nghiệp, câu ngắn, động viên và hỏi đúng trọng tâm.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-brse', 'Kỹ sư cầu nối (BrSE)', 'Người học đóng vai BrSE, làm đầu mối giữa đội phát triển Việt Nam và khách hàng Nhật.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-dong-nghiep', 'Đồng nghiệp', 'Người đồng nghiệp ngang hàng trong công ty, cùng làm việc và hỗ trợ nhau.', 'Thân thiện, cởi mở và sẵn sàng giúp đỡ.', 'Dùng です・ます với đồng nghiệp, câu ngắn gọn tự nhiên.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-dan-anh', 'Đàn anh', 'Đồng nghiệp vào công ty trước, có thâm niên, hướng dẫn người mới.', 'Kiên nhẫn, tận tình chỉ bảo và gần gũi.', 'Dùng です・ます thân thiện, thỉnh thoảng dùng thể thường khi gần gũi.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-cap-tren', 'Cấp trên', 'Trưởng phòng hoặc quản lý trực tiếp tại văn phòng.', 'Nghiêm túc nhưng công bằng, quan tâm tiến độ công việc.', 'Dùng です・ます, đôi khi dùng thể thường nhẹ nhàng với cấp dưới.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-doi-tac', 'Đối tác', 'Người đại diện công ty đối tác gọi điện trao đổi công việc.', 'Lịch sự, chuyên nghiệp và rõ ràng.', 'Dùng kính ngữ khiêm nhường khi nói chuyện qua điện thoại.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-to-truong', 'Tổ trưởng', 'Người quản lý một tổ sản xuất trong nhà máy.', 'Cẩn thận, coi trọng an toàn và đúng quy trình.', 'Dùng です・ます, câu chỉ dẫn ngắn gọn dễ hiểu.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-quan-doc', 'Quản đốc', 'Người quản lý nhà máy, phụ trách điều hành sản xuất.', 'Quyết đoán, rõ ràng về số lượng và thời hạn.', 'Dùng です・ます, câu giao việc rõ ràng.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-nhan-vien-ban-hang', 'Nhân viên bán hàng', 'Nhân viên phục vụ tại cửa hàng.', 'Lịch sự, chu đáo và chủ động giới thiệu sản phẩm.', 'Dùng kính ngữ với khách hàng, câu lịch sự.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('AI', 'cpath-quan-ly-cua-hang', 'Quản lý cửa hàng', 'Quản lý cửa hàng, xử lý khiếu nại của khách.', 'Điềm tĩnh, chân thành khi xin lỗi và giải quyết vấn đề.', 'Dùng kính ngữ lịch sự, tỏ thái độ thành thật.') AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-nhan-vien-cong-ty', 'Nhân viên công ty', 'Người học là nhân viên văn phòng tại công ty Nhật.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-cong-nhan-nha-may', 'Công nhân nhà máy', 'Người học là công nhân làm việc trong nhà máy sản xuất.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario_role (role_kind, code, name, description, personality, speech_style) VALUES ('LEARNER', 'cpath-khach-hang', 'Khách hàng', 'Người học là khách hàng mua sắm hoặc đặt phòng.', NULL, NULL) AS n ON DUPLICATE KEY UPDATE name = n.name, description = n.description, personality = n.personality, speech_style = n.speech_style;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-san-bay'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hanh-khach-san-bay'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Làm thủ tục ở sân bay', 'cpath-trv-01', 'Bạn làm thủ tục, chọn ghế, gửi hành lý và xác nhận cửa lên máy bay với nhân viên sân bay.', 'N4', 'EASY', 8, 'Bạn làm thủ tục chuyến bay đi Nhật và muốn chọn ghế cạnh cửa sổ, đồng thời gửi một kiện hành lý.', 'Quầy làm thủ tục tại sân bay', 'Buổi sáng', '{"goals":[{"code":"PASSPORT","type":"MISSION","title":"Xuất trình giấy tờ","required":true,"conditions":[{"type":"KEYWORD","value":"パスポート|予約番号|はい、これです"}],"description":"Đưa hộ chiếu và mã đặt chỗ khi nhân viên yêu cầu.","displayOrder":1},{"code":"SEAT","type":"MISSION","title":"Chọn chỗ ngồi","required":true,"conditions":[{"type":"KEYWORD","value":"窓側|通路側|席"}],"description":"Hỏi hoặc xin chỗ ngồi cạnh cửa sổ hay lối đi.","displayOrder":2},{"code":"BAGGAGE","type":"MISSION","title":"Gửi hành lý","required":true,"conditions":[{"type":"KEYWORD","value":"預ける|荷物|一つ"}],"description":"Nói số kiện hành lý muốn gửi.","displayOrder":3},{"code":"GATE","type":"MISSION","title":"Xác nhận cửa lên máy bay","required":true,"conditions":[{"type":"KEYWORD","value":"搭乗口|どこ|分かりました"}],"description":"Hỏi cửa lên máy bay và ghi nhớ giờ có mặt.","displayOrder":4}],"states":[{"code":"PASSPORT_CHECK","name":"Nhận giấy tờ","next":"SEAT_SELECT","prompt":"Chào hành khách, xin hộ chiếu và mã đặt chỗ.","allowedGoalCodes":["PASSPORT"],"suggestedReplies":["パスポートと予約番号です。","はい、これです。"]},{"code":"SEAT_SELECT","name":"Chọn chỗ ngồi","next":"BAGGAGE","prompt":"Xác nhận chuyến bay và hỏi hành khách muốn ngồi đâu.","allowedGoalCodes":["SEAT"],"suggestedReplies":["窓側の席は空いていますか。","窓側をお願いします。"]},{"code":"BAGGAGE","name":"Gửi hành lý","next":"GATE","prompt":"Yêu cầu hành khách đặt hành lý lên cân và báo cân nặng.","allowedGoalCodes":["BAGGAGE"],"suggestedReplies":["預ける荷物は一つです。","こちらに載せますね。"]},{"code":"GATE","name":"Cửa lên máy bay","next":"END","prompt":"Báo cửa lên máy bay và nhắc giờ có mặt trước giờ bay.","allowedGoalCodes":["GATE"],"suggestedReplies":["搭乗口はどこですか。","分かりました。ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành thủ tục","message":"ご搭乗口までお気をつけてお越しください。良い旅を。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"PASSPORT_CHECK"}', '{"grammar":[{"example":"パスポートと予約番号をお願いします。","pattern":"〜をお願いします","explanation":"Cách lịch sự để đề nghị hoặc nhờ ai làm việc gì."},{"example":"窓側の席は空いていますか。","pattern":"〜は空いていますか","explanation":"Hỏi chỗ hay món còn trống không."}],"vocabulary":[{"jlpt":"N4","term":"予約番号","example":"予約番号はこちらです。","meaning":"mã đặt chỗ","reading":"よやくばんごう"},{"jlpt":"N4","term":"窓側","example":"窓側の席をお願いします。","meaning":"phía cửa sổ","reading":"まどがわ"},{"jlpt":"N4","term":"預ける","example":"荷物を預けます。","meaning":"gửi (hành lý)","reading":"あずける"},{"jlpt":"N4","term":"搭乗口","example":"搭乗口はどこですか。","meaning":"cửa lên máy bay","reading":"とうじょうぐち"}],"exampleDialogue":[{"text":"おはようございます。パスポートと予約番号をお願いします。","speaker":"ai","translation":"Chào anh. Cho tôi xin hộ chiếu và mã đặt chỗ ạ."},{"text":"はい、これです。窓側の席は空いていますか。","speaker":"learner","translation":"Vâng, đây ạ. Còn ghế cạnh cửa sổ không ạ?"},{"text":"前方でしたら一席ご用意できます。","speaker":"ai","translation":"Nếu ở phía trước thì tôi có thể sắp một ghế ạ."},{"text":"お願いします。預ける荷物は一つです。","speaker":"learner","translation":"Cho tôi ghế đó ạ. Tôi gửi một kiện hành lý."},{"text":"搭乗口は十五番です。三十分前までにお越しください。","speaker":"ai","translation":"Cửa số mười lăm ạ. Xin anh đến trước ba mươi phút."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-san-bay'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hanh-khach-san-bay'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận cổng lên máy bay', 'cpath-trv-09', 'Bạn hỏi giờ bắt đầu lên máy bay, xác nhận cổng và hỏi vị trí nhà vệ sinh gần đó.', 'N4', 'EASY', 7, 'Bạn đang đợi ở khu vực cổng lên máy bay và muốn xác nhận lại giờ bắt đầu cùng cổng đúng.', 'Cổng lên máy bay tại sân bay', 'Buổi chiều', '{"goals":[{"code":"TIME","type":"MISSION","title":"Hỏi giờ lên máy bay","required":true,"conditions":[{"type":"KEYWORD","value":"何時から|搭乗|始まります"}],"description":"Hỏi nhân viên mấy giờ bắt đầu lên máy bay.","displayOrder":1},{"code":"GATE_CONFIRM","type":"MISSION","title":"Xác nhận cổng","required":true,"conditions":[{"type":"KEYWORD","value":"搭乗口|ここで|合っています"}],"description":"Xác nhận cổng lên máy bay có đúng không.","displayOrder":2},{"code":"TOILET","type":"MISSION","title":"Hỏi vị trí nhà vệ sinh","required":true,"conditions":[{"type":"KEYWORD","value":"トイレ|近く|あります"}],"description":"Hỏi nhà vệ sinh có gần đây không.","displayOrder":3}],"states":[{"code":"WAIT","name":"Hỏi giờ lên máy bay","next":"GATE_CHECK","prompt":"Chào hành khách đang đợi, sẵn sàng trả lời về giờ lên máy bay.","allowedGoalCodes":["TIME"],"suggestedReplies":["何時から搭乗が始まりますか。","搭乗は何時からですか。"]},{"code":"GATE_CHECK","name":"Xác nhận cổng","next":"TOILET_Q","prompt":"Báo giờ bắt đầu và chờ hành khách xác nhận cổng.","allowedGoalCodes":["GATE_CONFIRM"],"suggestedReplies":["搭乗口はここで合っていますか。","このゲートで大丈夫ですか。"]},{"code":"TOILET_Q","name":"Hỏi nhà vệ sinh","next":"END","prompt":"Xác nhận cổng và hướng dẫn vị trí nhà vệ sinh.","allowedGoalCodes":["TOILET"],"suggestedReplies":["トイレは近くにありますか。","ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nắm rõ giờ và cổng","message":"十五番ゲートでお待ちください。良い旅を。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"WAIT"}', '{"grammar":[{"example":"十五分後、二時半から始まります。","pattern":"〜から始まります","explanation":"Dùng khi hỏi hoặc trả lời giờ bắt đầu của sự kiện."},{"example":"搭乗口はここで合っていますか。","pattern":"〜で合っていますか","explanation":"Xác nhận thông tin một cách lịch sự."}],"vocabulary":[{"jlpt":"N4","term":"搭乗","example":"搭乗が始まります。","meaning":"lên máy bay","reading":"とうじょう"},{"jlpt":"N4","term":"搭乗口","example":"搭乗口はここです。","meaning":"cổng lên máy bay","reading":"とうじょうぐち"},{"jlpt":"N5","term":"トイレ","example":"トイレは近くにありますか。","meaning":"nhà vệ sinh","reading":"トイレ"},{"jlpt":"N5","term":"近く","example":"近くにあります。","meaning":"gần đây","reading":"ちかく"}],"exampleDialogue":[{"text":"すみません、何時から搭乗が始まりますか。","speaker":"learner","translation":"Xin lỗi, mấy giờ bắt đầu lên máy bay ạ?"},{"text":"十五分後、二時半から始まります。","speaker":"ai","translation":"Sau mười lăm phút, từ hai giờ rưỡi bắt đầu ạ."},{"text":"搭乗口はここで合っていますか。","speaker":"learner","translation":"Cổng lên máy bay ở đây đúng không ạ?"},{"text":"はい、この十五番ゲートです。","speaker":"ai","translation":"Vâng, cổng số mười lăm này ạ."},{"text":"トイレは近くにありますか。","speaker":"learner","translation":"Nhà vệ sinh có gần đây không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-san-bay'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hanh-khach-san-bay'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nhờ giúp trên máy bay', 'cpath-trv-10', 'Bạn xin thêm chăn và hỏi giờ hạ cánh với tiếp viên trên máy bay.', 'N4', 'EASY', 6, 'Trên chuyến bay dài đi Nhật, bạn thấy lạnh và muốn xin thêm chăn, rồi hỏi giờ hạ cánh.', 'Trong khoang máy bay', 'Buổi chiều', '{"goals":[{"code":"BLANKET","type":"MISSION","title":"Xin thêm chăn","required":true,"conditions":[{"type":"KEYWORD","value":"毛布|一枚|もらえます"}],"description":"Xin thêm một cái chăn.","displayOrder":1},{"code":"ARRIVAL","type":"MISSION","title":"Hỏi giờ hạ cánh","required":true,"conditions":[{"type":"KEYWORD","value":"到着|何時|ありがとう"}],"description":"Hỏi giờ hạ cánh sau khi nhận chăn.","displayOrder":2}],"states":[{"code":"BLANKET_Q","name":"Xin chăn","next":"ARRIVAL_Q","prompt":"Chào hành khách, hỏi xem cần giúp gì trên chuyến bay.","allowedGoalCodes":["BLANKET"],"suggestedReplies":["毛布をもう一枚もらえますか。","すみません、毛布をお願いします。"]},{"code":"ARRIVAL_Q","name":"Hỏi giờ hạ cánh","next":"END","prompt":"Đưa chăn và trả lời về lịch trình chuyến bay.","allowedGoalCodes":["ARRIVAL"],"suggestedReplies":["到着は何時ですか。","ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nhận chăn và biết giờ đến","message":"まもなく着陸いたします。シートベルトをお締めください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"BLANKET_Q"}', '{"grammar":[{"example":"毛布をもう一枚もらえますか。","pattern":"〜をもう一枚もらえますか","explanation":"Nhờ nhân viên đưa thêm một đồ dùng."},{"example":"到着は何時ですか。","pattern":"〜は何時ですか","explanation":"Hỏi thời điểm một cách đơn giản."}],"vocabulary":[{"jlpt":"N4","term":"毛布","example":"毛布をもう一枚ください。","meaning":"cái chăn","reading":"もうふ"},{"jlpt":"N4","term":"到着","example":"到着は三時です。","meaning":"đến nơi, hạ cánh","reading":"とうちゃく"},{"jlpt":"N4","term":"予定","example":"予定では三時です。","meaning":"dự kiến","reading":"よてい"},{"jlpt":"N4","term":"機内","example":"機内でお待ちください。","meaning":"trong máy bay","reading":"きない"}],"exampleDialogue":[{"text":"すみません、毛布をもう一枚もらえますか。","speaker":"learner","translation":"Xin lỗi, cho tôi xin thêm một cái chăn được không ạ?"},{"text":"かしこまりました。少々お待ちください。","speaker":"ai","translation":"Vâng ạ. Xin quý khách đợi một chút."},{"text":"ありがとうございます。あと、到着は何時ですか。","speaker":"learner","translation":"Cảm ơn chị. À, mấy giờ thì hạ cánh ạ?"},{"text":"予定では三時です。","speaker":"ai","translation":"Theo dự kiến là ba giờ ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-ga'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hanh-khach-di-tau'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Đổi tàu', 'cpath-trv-02', 'Bạn hỏi nhân viên ga cách đổi tàu để tới Yokohama, so sánh loại tàu và xác nhận đường ray.', 'N4', 'EASY', 8, 'Bạn muốn đi Yokohama nhưng chưa rõ phải đổi tàu ở đâu và chọn loại tàu nào cho hợp lý.', 'Nhà ga tàu điện', 'Buổi sáng', '{"goals":[{"code":"DESTINATION","type":"MISSION","title":"Nói điểm đến","required":true,"conditions":[{"type":"KEYWORD","value":"行きたい|横浜|すみません"}],"description":"Nói ga mình muốn đến.","displayOrder":1},{"code":"COMPARE","type":"MISSION","title":"Hỏi so sánh loại tàu","required":true,"conditions":[{"type":"KEYWORD","value":"特急|各駅停車|どちら"}],"description":"Hỏi tàu nào nhanh hơn.","displayOrder":2},{"code":"FARE","type":"MISSION","title":"Hỏi phí phụ thu","required":true,"conditions":[{"type":"KEYWORD","value":"追加料金|要ります|必要"}],"description":"Hỏi có cần trả thêm phí không.","displayOrder":3},{"code":"PLATFORM","type":"MISSION","title":"Hỏi đường ray","required":true,"conditions":[{"type":"KEYWORD","value":"何番線|普通|大丈夫"}],"description":"Chọn loại tàu và hỏi đường ray số mấy.","displayOrder":4}],"states":[{"code":"ASK_ROUTE","name":"Hỏi đường","next":"COMPARE","prompt":"Chào hành khách, hỏi ga muốn đến để chỉ đường.","allowedGoalCodes":["DESTINATION"],"suggestedReplies":["横浜へ行きたいんですが。","〜へ行きたいです。"]},{"code":"COMPARE","name":"So sánh tàu","next":"FARE","prompt":"Báo phải đổi tàu và so sánh tàu tốc hành với tàu thường.","allowedGoalCodes":["COMPARE"],"suggestedReplies":["特急と各駅停車、どちらが早いですか。","どちらが早いですか。"]},{"code":"FARE","name":"Hỏi phí","next":"PLATFORM","prompt":"Báo tàu tốc hành nhanh hơn và có mất phí riêng.","allowedGoalCodes":["FARE"],"suggestedReplies":["追加料金は要りますか。","特急券が要りますか。"]},{"code":"PLATFORM","name":"Hỏi đường ray","next":"END","prompt":"Xác nhận chọn tàu thường và báo đường ray, giờ chạy.","allowedGoalCodes":["PLATFORM"],"suggestedReplies":["普通ので大丈夫です。何番線ですか。","何番線ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã chọn được tuyến","message":"三番線から発車いたします。お気をつけて。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ASK_ROUTE"}', '{"grammar":[{"example":"品川で乗り換えになります。","pattern":"〜になります","explanation":"Cách nói gián tiếp, mềm hơn nói thẳng です."},{"example":"特急のほうが二十分ほど早く着きます。","pattern":"〜のほうが〜","explanation":"Mẫu so sánh cơ bản khi tư vấn."}],"vocabulary":[{"jlpt":"N4","term":"乗り換え","example":"品川で乗り換えです。","meaning":"đổi tàu","reading":"のりかえ"},{"jlpt":"N4","term":"特急","example":"特急が早いです。","meaning":"tàu tốc hành","reading":"とっきゅう"},{"jlpt":"N4","term":"各駅停車","example":"各駅停車で行きます。","meaning":"tàu thường dừng mọi ga","reading":"かくえきていしゃ"},{"jlpt":"N4","term":"何番線","example":"何番線ですか。","meaning":"đường ray số mấy","reading":"なんばんせん"}],"exampleDialogue":[{"text":"すみません、横浜へ行きたいんですが。","speaker":"learner","translation":"Xin lỗi, tôi muốn đi Yokohama ạ."},{"text":"ここからですと、品川で乗り換えになります。","speaker":"ai","translation":"Từ đây thì anh phải đổi tàu ở Shinagawa ạ."},{"text":"特急と各駅停車、どちらが早いですか。","speaker":"learner","translation":"Tàu tốc hành và tàu thường, cái nào nhanh hơn ạ?"},{"text":"特急のほうが二十分ほど早く着きます。","speaker":"ai","translation":"Tàu tốc hành tới sớm hơn khoảng hai mươi phút ạ."},{"text":"では普通ので大丈夫です。何番線ですか。","speaker":"learner","translation":"Vậy tàu thường cũng được ạ. Ở đường ray số mấy ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-ga'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hanh-khach-di-tau'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Mua vé tàu', 'cpath-trv-11', 'Bạn nhờ nhân viên chỉ cách mua vé, nói điểm đến và hỏi giá cùng cách thanh toán.', 'N4', 'EASY', 7, 'Bạn lần đầu dùng máy bán vé tự động và cần nhờ nhân viên chỉ cách mua vé đi Kyoto.', 'Máy bán vé tại nhà ga', 'Buổi sáng', '{"goals":[{"code":"HOW_TO_BUY","type":"MISSION","title":"Nhờ chỉ cách mua vé","required":true,"conditions":[{"type":"KEYWORD","value":"買い方|教えて|切符"}],"description":"Nhờ nhân viên chỉ cách mua vé.","displayOrder":1},{"code":"DESTINATION","type":"MISSION","title":"Nói điểm đến","required":true,"conditions":[{"type":"KEYWORD","value":"京都|まで|行き先"}],"description":"Nói ga mình muốn đến.","displayOrder":2},{"code":"FARE","type":"MISSION","title":"Hỏi giá vé","required":true,"conditions":[{"type":"KEYWORD","value":"運賃|いくら"}],"description":"Hỏi giá vé sau khi chọn ga.","displayOrder":3},{"code":"PAYMENT","type":"MISSION","title":"Hỏi cách trả tiền","required":true,"conditions":[{"type":"KEYWORD","value":"現金|払えます|お金"}],"description":"Hỏi trả tiền mặt được không.","displayOrder":4}],"states":[{"code":"HELP_BUY","name":"Nhờ hướng dẫn","next":"DEST","prompt":"Chào hành khách tại máy bán vé, hỏi cần giúp gì.","allowedGoalCodes":["HOW_TO_BUY"],"suggestedReplies":["切符の買い方を教えてもらえますか。","買い方を教えてください。"]},{"code":"DEST","name":"Chọn điểm đến","next":"FARE","prompt":"Hỏi điểm đến và hướng dẫn chọn trên màn hình.","allowedGoalCodes":["DESTINATION"],"suggestedReplies":["京都までです。","〜までです。"]},{"code":"FARE","name":"Hỏi giá","next":"PAYMENT","prompt":"Báo giá vé sau khi chọn ga.","allowedGoalCodes":["FARE"],"suggestedReplies":["運賃はいくらですか。","いくらですか。"]},{"code":"PAYMENT","name":"Hỏi thanh toán","next":"END","prompt":"Báo giá và hướng dẫn bỏ tiền vào máy.","allowedGoalCodes":["PAYMENT"],"suggestedReplies":["現金で払えますか。","ここにお金を入れますね。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã mua được vé","message":"こちらにお金を入れてください。お気をつけて。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"HELP_BUY"}', '{"grammar":[{"example":"切符の買い方を教えてもらえますか。","pattern":"〜方を教えてもらえますか","explanation":"Nhờ hướng dẫn một thao tác."},{"example":"京都までです。","pattern":"〜までです","explanation":"Nói điểm đến khi mua vé."}],"vocabulary":[{"jlpt":"N4","term":"切符","example":"切符を買います。","meaning":"vé","reading":"きっぷ"},{"jlpt":"N4","term":"行き先","example":"行き先は京都です。","meaning":"điểm đến","reading":"いきさき"},{"jlpt":"N4","term":"運賃","example":"運賃はいくらですか。","meaning":"tiền vé","reading":"うんちん"},{"jlpt":"N4","term":"現金","example":"現金で払えますか。","meaning":"tiền mặt","reading":"げんきん"}],"exampleDialogue":[{"text":"すみません、切符の買い方を教えてもらえますか。","speaker":"learner","translation":"Xin lỗi, anh chỉ tôi cách mua vé được không ạ?"},{"text":"行き先はどちらですか。","speaker":"ai","translation":"Anh đi đến đâu ạ?"},{"text":"京都までです。","speaker":"learner","translation":"Đến Kyoto ạ."},{"text":"では、この画面で京都を押してください。","speaker":"ai","translation":"Vậy anh nhấn Kyoto trên màn hình này ạ."},{"text":"運賃はいくらですか。","speaker":"learner","translation":"Giá vé là bao nhiêu ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-ga'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hanh-khach-di-tau'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi chuyến tàu cuối', 'cpath-trv-12', 'Bạn hỏi giờ chuyến tàu cuối, xác nhận không phải đổi tàu và hỏi có kịp không.', 'N4', 'EASY', 7, 'Buổi tối muộn, bạn cần biết chuyến tàu cuối về nhà và liệu mình có kịp giờ không.', 'Cửa soát vé nhà ga', 'Buổi tối', '{"goals":[{"code":"LAST_TRAIN","type":"MISSION","title":"Hỏi chuyến tàu cuối","required":true,"conditions":[{"type":"KEYWORD","value":"終電|何時|すみません"}],"description":"Hỏi giờ chuyến tàu cuối.","displayOrder":1},{"code":"TRANSFER","type":"MISSION","title":"Hỏi đổi tàu","required":true,"conditions":[{"type":"KEYWORD","value":"乗り換え|一本|あります"}],"description":"Hỏi có phải đổi tàu không.","displayOrder":2},{"code":"IN_TIME","type":"MISSION","title":"Hỏi có kịp không","required":true,"conditions":[{"type":"KEYWORD","value":"間に合います|今から|大丈夫"}],"description":"Hỏi đi bây giờ có kịp không.","displayOrder":3}],"states":[{"code":"ASK_LAST","name":"Hỏi chuyến cuối","next":"TRANSFER","prompt":"Chào hành khách, sẵn sàng trả lời giờ chuyến tàu cuối.","allowedGoalCodes":["LAST_TRAIN"],"suggestedReplies":["終電は何時ですか。","最終は何時ですか。"]},{"code":"TRANSFER","name":"Hỏi đổi tàu","next":"IN_TIME","prompt":"Báo giờ chuyến cuối và xác nhận đi thẳng hay đổi tàu.","allowedGoalCodes":["TRANSFER"],"suggestedReplies":["乗り換えがありますか。","一本で行けますか。"]},{"code":"IN_TIME","name":"Hỏi có kịp không","next":"END","prompt":"Xác nhận đi thẳng và trả lời có kịp giờ không.","allowedGoalCodes":["IN_TIME"],"suggestedReplies":["間に合いますか。","今からでも大丈夫ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nắm giờ chuyến cuối","message":"今からなら十分間に合います。お気をつけて。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ASK_LAST"}', '{"grammar":[{"example":"終電は何時までですか。","pattern":"〜は何時までですか","explanation":"Hỏi thời gian kết thúc của dịch vụ."},{"example":"一本で行けます。","pattern":"〜で行けます","explanation":"Diễn tả cách di chuyển khả thi."}],"vocabulary":[{"jlpt":"N4","term":"終電","example":"終電は何時ですか。","meaning":"chuyến tàu cuối","reading":"しゅうでん"},{"jlpt":"N4","term":"乗り換え","example":"乗り換えがありますか。","meaning":"đổi tàu","reading":"のりかえ"},{"jlpt":"N4","term":"間に合う","example":"間に合いますか。","meaning":"kịp giờ","reading":"まにあう"},{"jlpt":"N4","term":"一本","example":"一本で行けます。","meaning":"một chuyến (thẳng)","reading":"いっぽん"}],"exampleDialogue":[{"text":"すみません、終電は何時ですか。","speaker":"learner","translation":"Xin lỗi, chuyến tàu cuối là mấy giờ ạ?"},{"text":"この線は十一時五十分までです。","speaker":"ai","translation":"Tuyến này chạy đến mười một giờ năm mươi ạ."},{"text":"乗り換えがありますか。","speaker":"learner","translation":"Có phải đổi tàu không ạ?"},{"text":"ありません。一本で行けます。","speaker":"ai","translation":"Không ạ. Đi thẳng một chuyến là tới."},{"text":"間に合いますか。","speaker":"learner","translation":"Tôi có kịp không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-le-tan-khach-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-luu-tru'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nhận phòng khách sạn', 'cpath-trv-03', 'Bạn nhận phòng, hỏi giờ ăn sáng và giờ trả phòng, rồi nhờ giữ hành lý.', 'N4', 'EASY', 8, 'Bạn đến nhận phòng đã đặt trước hai đêm kèm bữa sáng và muốn gửi hành lý trước khi ra ngoài.', 'Quầy lễ tân khách sạn', 'Buổi chiều', '{"goals":[{"code":"NAME","type":"MISSION","title":"Báo tên đặt phòng","required":true,"conditions":[{"type":"KEYWORD","value":"予約|グエン|です"}],"description":"Báo tên mình đã đặt phòng.","displayOrder":1},{"code":"BREAKFAST","type":"MISSION","title":"Hỏi giờ ăn sáng","required":true,"conditions":[{"type":"KEYWORD","value":"朝食|何時|はい"}],"description":"Xác nhận và hỏi giờ bữa sáng.","displayOrder":2},{"code":"CHECKOUT","type":"MISSION","title":"Hỏi giờ trả phòng","required":true,"conditions":[{"type":"KEYWORD","value":"チェックアウト|何時|まで"}],"description":"Hỏi giờ trả phòng muộn nhất.","displayOrder":3},{"code":"LUGGAGE","type":"MISSION","title":"Nhờ giữ hành lý","required":true,"conditions":[{"type":"KEYWORD","value":"荷物|預かって|先に"}],"description":"Nhờ giữ hành lý trước.","displayOrder":4}],"states":[{"code":"CHECKIN","name":"Nhận phòng","next":"BREAKFAST","prompt":"Chào khách, xác nhận thông tin đặt phòng.","allowedGoalCodes":["NAME"],"suggestedReplies":["予約したグエンです。","グエンと申します。"]},{"code":"BREAKFAST","name":"Hỏi bữa sáng","next":"CHECKOUT","prompt":"Báo thông tin phòng kèm bữa sáng, hỏi khách có cần gì.","allowedGoalCodes":["BREAKFAST"],"suggestedReplies":["朝食は何時からですか。","はい、朝食付きです。"]},{"code":"CHECKOUT","name":"Hỏi trả phòng","next":"LUGGAGE","prompt":"Báo giờ và chỗ ăn sáng, trả lời về giờ trả phòng.","allowedGoalCodes":["CHECKOUT"],"suggestedReplies":["チェックアウトは何時までですか。","何時までですか。"]},{"code":"LUGGAGE","name":"Gửi hành lý","next":"END","prompt":"Báo giờ trả phòng và nhận giữ hành lý cho khách.","allowedGoalCodes":["LUGGAGE"],"suggestedReplies":["荷物を先に預かってもらえますか。","荷物を預けたいです。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nhận phòng xong","message":"こちらの札をお持ちください。ごゆっくりお過ごしください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"CHECKIN"}', '{"grammar":[{"example":"朝食は何時からですか。","pattern":"〜は何時からですか","explanation":"Hỏi giờ bắt đầu của dịch vụ."},{"example":"荷物を先に預かってもらえますか。","pattern":"〜てもらえますか","explanation":"Nhờ vả lịch sự."}],"vocabulary":[{"jlpt":"N4","term":"予約","example":"予約したグエンです。","meaning":"đặt chỗ","reading":"よやく"},{"jlpt":"N4","term":"朝食","example":"朝食は何時からですか。","meaning":"bữa sáng","reading":"ちょうしょく"},{"jlpt":"N4","term":"チェックアウト","example":"チェックアウトは何時までですか。","meaning":"trả phòng","reading":"チェックアウト"},{"jlpt":"N4","term":"荷物","example":"荷物を預けたいです。","meaning":"hành lý","reading":"にもつ"}],"exampleDialogue":[{"text":"予約したグエンです。","speaker":"learner","translation":"Tôi là Nguyễn, đã đặt phòng ạ."},{"text":"お待ちしておりました。二泊、朝食付きでございますね。","speaker":"ai","translation":"Chúng tôi đã chờ ngài. Hai đêm, kèm bữa sáng phải không ạ."},{"text":"はい。朝食は何時からですか。","speaker":"learner","translation":"Vâng. Bữa sáng từ mấy giờ ạ?"},{"text":"七時から十時まで、二階のレストランでご用意しております。","speaker":"ai","translation":"Từ bảy giờ đến mười giờ, ở nhà hàng tầng hai ạ."},{"text":"チェックアウトは何時までですか。","speaker":"learner","translation":"Trả phòng muộn nhất mấy giờ ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-le-tan-khach-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-luu-tru'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Trả phòng và gọi taxi', 'cpath-trv-13', 'Bạn trả phòng, báo số phòng, xác nhận không dùng minibar và nhờ gọi taxi ra sân bay.', 'N4', 'EASY', 7, 'Buổi sáng trước khi ra sân bay, bạn trả phòng và nhờ lễ tân gọi taxi.', 'Quầy lễ tân khách sạn', 'Buổi sáng', '{"goals":[{"code":"CHECKOUT","type":"MISSION","title":"Yêu cầu trả phòng","required":true,"conditions":[{"type":"KEYWORD","value":"チェックアウト|お願いします"}],"description":"Xin trả phòng.","displayOrder":1},{"code":"ROOM_NO","type":"MISSION","title":"Báo số phòng","required":true,"conditions":[{"type":"KEYWORD","value":"号室|三百五|部屋"}],"description":"Báo số phòng của mình.","displayOrder":2},{"code":"MINIBAR","type":"MISSION","title":"Trả lời minibar","required":true,"conditions":[{"type":"KEYWORD","value":"ありません|ミニバー|使って"}],"description":"Trả lời có dùng minibar không.","displayOrder":3},{"code":"TAXI","type":"MISSION","title":"Nhờ gọi taxi","required":true,"conditions":[{"type":"KEYWORD","value":"タクシー|呼んで|空港"}],"description":"Nhờ gọi taxi ra sân bay.","displayOrder":4}],"states":[{"code":"CHECKOUT","name":"Trả phòng","next":"ROOM_NO","prompt":"Chào khách, hỏi khách cần trả phòng và xin số phòng.","allowedGoalCodes":["CHECKOUT"],"suggestedReplies":["チェックアウトをお願いします。","お会計をお願いします。"]},{"code":"ROOM_NO","name":"Báo số phòng","next":"MINIBAR","prompt":"Xin số phòng và hỏi về minibar.","allowedGoalCodes":["ROOM_NO"],"suggestedReplies":["三百五号室です。","〜号室です。"]},{"code":"MINIBAR","name":"Xác nhận minibar","next":"TAXI","prompt":"Hỏi khách có dùng minibar không để tính tiền.","allowedGoalCodes":["MINIBAR"],"suggestedReplies":["ありません。","ミニバーは使いませんでした。"]},{"code":"TAXI","name":"Gọi taxi","next":"END","prompt":"Tính tiền và hỏi khách có cần gọi taxi không.","allowedGoalCodes":["TAXI"],"suggestedReplies":["タクシーを呼んでもらえますか。","空港までお願いします。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã trả phòng và gọi taxi","message":"タクシーを呼んでおきます。ありがとうございました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"CHECKOUT"}', '{"grammar":[{"example":"チェックアウトをお願いします。","pattern":"〜をお願いします","explanation":"Câu đề nghị cơ bản trong dịch vụ."},{"example":"タクシーを呼んでもらえますか。","pattern":"〜てもらえますか","explanation":"Nhờ vả lịch sự."}],"vocabulary":[{"jlpt":"N4","term":"チェックアウト","example":"チェックアウトをお願いします。","meaning":"trả phòng","reading":"チェックアウト"},{"jlpt":"N4","term":"部屋番号","example":"部屋番号を教えてください。","meaning":"số phòng","reading":"へやばんごう"},{"jlpt":"N4","term":"ミニバー","example":"ミニバーは使いませんでした。","meaning":"minibar","reading":"ミニバー"},{"jlpt":"N5","term":"タクシー","example":"タクシーを呼んでください。","meaning":"taxi","reading":"タクシー"}],"exampleDialogue":[{"text":"おはようございます。チェックアウトをお願いします。","speaker":"learner","translation":"Chào chị. Cho tôi trả phòng ạ."},{"text":"かしこまりました。お部屋番号を伺います。","speaker":"ai","translation":"Vâng ạ. Xin cho biết số phòng."},{"text":"三百五号室です。","speaker":"learner","translation":"Phòng ba lẻ năm ạ."},{"text":"では、お会計いたします。ミニバーのご利用はありますか。","speaker":"ai","translation":"Vậy tôi tính tiền ạ. Quý khách có dùng minibar không ạ?"},{"text":"ありません。それと、タクシーを呼んでもらえますか。","speaker":"learner","translation":"Không ạ. À, chị gọi taxi giúp tôi được không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-le-tan-khach-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-luu-tru'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi về tiện nghi phòng', 'cpath-trv-14', 'Bạn xin mật khẩu wifi, xin thêm khăn và hỏi đồ uống trong tủ lạnh có miễn phí không.', 'N4', 'EASY', 7, 'Bạn vừa vào phòng, cần mật khẩu wifi, xin thêm khăn và muốn biết đồ uống trong tủ lạnh có tính phí không.', 'Quầy lễ tân khách sạn', 'Buổi tối', '{"goals":[{"code":"WIFI","type":"MISSION","title":"Xin mật khẩu wifi","required":true,"conditions":[{"type":"KEYWORD","value":"Wi-Fi|パスワード|教えて"}],"description":"Xin mật khẩu wifi của phòng.","displayOrder":1},{"code":"TOWEL","type":"MISSION","title":"Xin thêm khăn","required":true,"conditions":[{"type":"KEYWORD","value":"タオル|一枚|もらえます"}],"description":"Xin thêm một cái khăn.","displayOrder":2},{"code":"FREE","type":"MISSION","title":"Hỏi đồ uống miễn phí","required":true,"conditions":[{"type":"KEYWORD","value":"無料|冷蔵庫|飲み物"}],"description":"Hỏi đồ uống trong tủ lạnh có miễn phí không.","displayOrder":3}],"states":[{"code":"WIFI","name":"Xin mật khẩu wifi","next":"TOWEL","prompt":"Chào khách, sẵn sàng hỗ trợ thông tin phòng.","allowedGoalCodes":["WIFI"],"suggestedReplies":["Wi-Fiのパスワードを教えてください。","パスワードは何ですか。"]},{"code":"TOWEL","name":"Xin thêm khăn","next":"FREE","prompt":"Đưa thẻ mật khẩu và hỏi khách có cần thêm gì.","allowedGoalCodes":["TOWEL"],"suggestedReplies":["タオルをもう一枚もらえますか。","タオルをください。"]},{"code":"FREE","name":"Hỏi đồ miễn phí","next":"END","prompt":"Hẹn gửi khăn lên và trả lời về đồ uống trong tủ lạnh.","allowedGoalCodes":["FREE"],"suggestedReplies":["冷蔵庫の飲み物は無料ですか。","無料ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã rõ tiện nghi phòng","message":"タオルをすぐお届けします。何かあればお申し付けください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"WIFI"}', '{"grammar":[{"example":"Wi-Fiのパスワードを教えてください。","pattern":"〜を教えてください","explanation":"Xin thông tin một cách lịch sự."},{"example":"冷蔵庫の飲み物は無料ですか。","pattern":"〜は無料ですか","explanation":"Hỏi về phí dịch vụ."}],"vocabulary":[{"jlpt":"N5","term":"パスワード","example":"パスワードを教えてください。","meaning":"mật khẩu","reading":"パスワード"},{"jlpt":"N5","term":"タオル","example":"タオルをもう一枚ください。","meaning":"khăn tắm","reading":"タオル"},{"jlpt":"N4","term":"冷蔵庫","example":"冷蔵庫の飲み物です。","meaning":"tủ lạnh","reading":"れいぞうこ"},{"jlpt":"N4","term":"無料","example":"無料ですか。","meaning":"miễn phí","reading":"むりょう"}],"exampleDialogue":[{"text":"すみません、部屋のWi-Fiのパスワードを教えてください。","speaker":"learner","translation":"Xin lỗi, cho tôi xin mật khẩu wifi của phòng ạ."},{"text":"こちらのカードに書いてございます。","speaker":"ai","translation":"Mật khẩu ghi trên tấm thẻ này ạ."},{"text":"あと、タオルをもう一枚もらえますか。","speaker":"learner","translation":"À, cho tôi xin thêm một cái khăn được không ạ?"},{"text":"はい、すぐお届けします。","speaker":"ai","translation":"Vâng, chúng tôi gửi lên ngay ạ."},{"text":"冷蔵庫の飲み物は無料ですか。","speaker":"learner","translation":"Đồ uống trong tủ lạnh có miễn phí không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'food-drink'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-thuc-khach'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Gọi món ở nhà hàng', 'cpath-trv-04', 'Bạn hỏi thành phần suất ăn, nói món không ăn được, gọi món và yêu cầu làm cay.', 'N4', 'EASY', 8, 'Bạn không ăn được thịt lợn nên muốn hỏi kỹ thành phần trước khi gọi một suất cơm phần.', 'Nhà hàng gia đình', 'Buổi trưa', '{"goals":[{"code":"CONTENTS","type":"MISSION","title":"Hỏi thành phần suất ăn","required":true,"conditions":[{"type":"KEYWORD","value":"定食|何が|付きます"}],"description":"Hỏi suất ăn gồm những gì.","displayOrder":1},{"code":"ALLERGY","type":"MISSION","title":"Nói món không ăn được","required":true,"conditions":[{"type":"KEYWORD","value":"豚肉|入って|食べられない"}],"description":"Hỏi có thịt lợn không và nói mình không ăn được.","displayOrder":2},{"code":"ORDER","type":"MISSION","title":"Gọi món","required":true,"conditions":[{"type":"KEYWORD","value":"お願いします|これ|ください"}],"description":"Gọi món sau khi yên tâm.","displayOrder":3},{"code":"SPICY","type":"MISSION","title":"Yêu cầu vị cay","required":true,"conditions":[{"type":"KEYWORD","value":"辛く|できます|辛口"}],"description":"Hỏi làm cay được không.","displayOrder":4}],"states":[{"code":"ORDER_Q","name":"Hỏi món","next":"ALLERGY","prompt":"Chào khách, hỏi khách đã chọn món chưa.","allowedGoalCodes":["CONTENTS"],"suggestedReplies":["この定食には何が付きますか。","定食は何が付きますか。"]},{"code":"ALLERGY","name":"Hỏi thành phần","next":"ORDER","prompt":"Mô tả suất ăn và hỏi khách có kiêng món gì.","allowedGoalCodes":["ALLERGY"],"suggestedReplies":["豚肉は入っていますか。食べられないんです。","豚肉は入っていますか。"]},{"code":"ORDER","name":"Gọi món","next":"SPICY","prompt":"Xác nhận món không có thịt lợn, hỏi khách chọn món gì.","allowedGoalCodes":["ORDER"],"suggestedReplies":["では、これをお願いします。","これにします。"]},{"code":"SPICY","name":"Yêu cầu vị cay","next":"END","prompt":"Nhận món và hỏi khách có muốn điều chỉnh vị không.","allowedGoalCodes":["SPICY"],"suggestedReplies":["辛くできますか。","辛口でお願いします。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã gọi món xong","message":"かしこまりました。少々お待ちください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ORDER_Q"}', '{"grammar":[{"example":"ご飯とみそ汁、小鉢が二つ付きます。","pattern":"〜が付きます","explanation":"Dùng khi mô tả suất ăn hoặc dịch vụ đi kèm."},{"example":"豚肉は入っていますか。","pattern":"〜は入っていますか","explanation":"Hỏi thành phần món ăn."}],"vocabulary":[{"jlpt":"N4","term":"定食","example":"この定食には何が付きますか。","meaning":"suất cơm phần","reading":"ていしょく"},{"jlpt":"N4","term":"豚肉","example":"豚肉は入っていますか。","meaning":"thịt lợn","reading":"ぶたにく"},{"jlpt":"N4","term":"辛口","example":"辛口にできますか。","meaning":"vị cay","reading":"からくち"},{"jlpt":"N4","term":"注文","example":"ご注文はお決まりですか。","meaning":"gọi món","reading":"ちゅうもん"}],"exampleDialogue":[{"text":"ご注文はお決まりですか。","speaker":"ai","translation":"Quý khách đã chọn món chưa ạ?"},{"text":"この定食には何が付きますか。","speaker":"learner","translation":"Suất cơm này gồm những gì ạ?"},{"text":"ご飯とみそ汁、小鉢が二つ付きます。","speaker":"ai","translation":"Có cơm, canh miso và hai món nhỏ ạ."},{"text":"豚肉は入っていますか。食べられないんです。","speaker":"learner","translation":"Có thịt lợn không ạ? Tôi không ăn được."},{"text":"こちらは鶏肉ですので、ご安心ください。","speaker":"ai","translation":"Món này là thịt gà nên quý khách yên tâm ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'food-drink'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-thuc-khach'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Đặt bàn qua điện thoại', 'cpath-trv-15', 'Bạn gọi điện đặt bàn, nói số người và báo tên cho nhà hàng.', 'N4', 'EASY', 6, 'Bạn muốn đặt bàn cho hai người vào bảy giờ tối nay bằng điện thoại.', 'Gọi điện tới nhà hàng', 'Buổi chiều', '{"goals":[{"code":"BOOK","type":"MISSION","title":"Đặt bàn","required":true,"conditions":[{"type":"KEYWORD","value":"予約|七時|したい"}],"description":"Gọi điện đặt bàn cho giờ cụ thể.","displayOrder":1},{"code":"PEOPLE","type":"MISSION","title":"Nói số người","required":true,"conditions":[{"type":"KEYWORD","value":"二人|何名|名様"}],"description":"Nói số người đi ăn.","displayOrder":2},{"code":"NAME","type":"MISSION","title":"Báo tên","required":true,"conditions":[{"type":"KEYWORD","value":"グエン|名前|です"}],"description":"Báo tên để nhà hàng ghi nhận.","displayOrder":3}],"states":[{"code":"CALL","name":"Đặt bàn","next":"PEOPLE","prompt":"Bắt máy và hỏi khách muốn đặt bàn lúc mấy giờ, mấy người.","allowedGoalCodes":["BOOK"],"suggestedReplies":["今夜七時に予約したいんですが。","予約をお願いします。"]},{"code":"PEOPLE","name":"Số người","next":"NAME","prompt":"Hỏi số người và xin tên khách.","allowedGoalCodes":["PEOPLE"],"suggestedReplies":["二人です。","二人、お願いします。"]},{"code":"NAME","name":"Báo tên","next":"END","prompt":"Xác nhận lại tên và giờ đặt bàn.","allowedGoalCodes":["NAME"],"suggestedReplies":["グエンです。","名前はグエンです。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã đặt bàn xong","message":"承知いたしました。七時にお待ちしております。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"CALL"}', '{"grammar":[{"example":"今夜七時に予約したいんですが。","pattern":"〜したいんですが","explanation":"Mở lời nhờ vả một cách mềm mại."},{"example":"何名様ですか。","pattern":"〜名様","explanation":"Đếm người một cách kính trọng."}],"vocabulary":[{"jlpt":"N4","term":"予約","example":"予約したいんですが。","meaning":"đặt chỗ","reading":"よやく"},{"jlpt":"N5","term":"今夜","example":"今夜七時に予約します。","meaning":"tối nay","reading":"こんや"},{"jlpt":"N5","term":"二人","example":"二人です。","meaning":"hai người","reading":"ふたり"},{"jlpt":"N5","term":"名前","example":"お名前をお願いします。","meaning":"tên","reading":"なまえ"}],"exampleDialogue":[{"text":"もしもし、今夜七時に予約したいんですが。","speaker":"learner","translation":"Alo, tôi muốn đặt bàn lúc bảy giờ tối nay ạ."},{"text":"ありがとうございます。何名様ですか。","speaker":"ai","translation":"Cảm ơn quý khách. Mấy người ạ?"},{"text":"二人です。","speaker":"learner","translation":"Hai người ạ."},{"text":"かしこまりました。お名前をお願いします。","speaker":"ai","translation":"Vâng ạ. Xin tên quý khách."},{"text":"グエンです。","speaker":"learner","translation":"Tôi là Nguyễn ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'food-drink'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-thuc-khach'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Tính tiền và chia đều', 'cpath-trv-16', 'Bạn xin tính tiền, hỏi trả thẻ và xin chia tiền riêng cho hai người.', 'N4', 'EASY', 7, 'Sau bữa ăn cùng bạn, bạn xin tính tiền, muốn trả thẻ và chia đều cho hai người.', 'Quầy thanh toán nhà hàng', 'Buổi tối', '{"goals":[{"code":"BILL","type":"MISSION","title":"Xin tính tiền","required":true,"conditions":[{"type":"KEYWORD","value":"お会計|お願いします"}],"description":"Xin tính tiền sau bữa ăn.","displayOrder":1},{"code":"CARD","type":"MISSION","title":"Hỏi trả thẻ","required":true,"conditions":[{"type":"KEYWORD","value":"カード|払えます|利用"}],"description":"Hỏi trả bằng thẻ được không.","displayOrder":2},{"code":"SPLIT","type":"MISSION","title":"Chia tiền","required":true,"conditions":[{"type":"KEYWORD","value":"別々|二人|割り勘"}],"description":"Hỏi tính riêng cho hai người.","displayOrder":3}],"states":[{"code":"BILL","name":"Tính tiền","next":"CARD","prompt":"Nhận yêu cầu và báo tổng tiền.","allowedGoalCodes":["BILL"],"suggestedReplies":["お会計をお願いします。","すみません、お会計を。"]},{"code":"CARD","name":"Hỏi trả thẻ","next":"SPLIT","prompt":"Báo tổng tiền và trả lời về hình thức thanh toán.","allowedGoalCodes":["CARD"],"suggestedReplies":["カードで払えますか。","カードでお願いします。"]},{"code":"SPLIT","name":"Chia tiền","next":"END","prompt":"Xác nhận trả thẻ được và hỏi có chia tiền không.","allowedGoalCodes":["SPLIT"],"suggestedReplies":["二人で別々にできますか。","割り勘でお願いします。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã thanh toán xong","message":"千六百円ずつになります。ありがとうございました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"BILL"}', '{"grammar":[{"example":"カードで払えますか。","pattern":"〜で払えますか","explanation":"Hỏi hình thức thanh toán."},{"example":"千六百円ずつになります。","pattern":"〜ずつになります","explanation":"Chia đều thành từng phần."}],"vocabulary":[{"jlpt":"N4","term":"お会計","example":"お会計をお願いします。","meaning":"thanh toán","reading":"おかいけい"},{"jlpt":"N5","term":"カード","example":"カードで払えますか。","meaning":"thẻ","reading":"カード"},{"jlpt":"N4","term":"別々","example":"二人で別々にできますか。","meaning":"riêng từng phần","reading":"べつべつ"},{"jlpt":"N4","term":"割り勘","example":"割り勘でお願いします。","meaning":"chia đều tiền","reading":"わりかん"}],"exampleDialogue":[{"text":"すみません、お会計をお願いします。","speaker":"learner","translation":"Xin lỗi, cho tôi tính tiền ạ."},{"text":"はい、三千二百円です。","speaker":"ai","translation":"Vâng, ba nghìn hai trăm yên ạ."},{"text":"カードで払えますか。","speaker":"learner","translation":"Trả bằng thẻ được không ạ?"},{"text":"はい、ご利用いただけます。","speaker":"ai","translation":"Vâng, quý khách dùng được ạ."},{"text":"二人で別々にできますか。","speaker":"learner","translation":"Hai người tính riêng được không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nguoi-qua-duong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-du-lich'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Khi bị lạc đường', 'cpath-trv-06', 'Bạn hỏi đường, hỏi thời gian đi bộ và xác nhận dấu mốc dễ nhận.', 'N4', 'EASY', 7, 'Bản đồ không rõ, bạn cần hỏi một người dân địa phương đường đến bảo tàng mỹ thuật.', 'Trên đường phố Nhật', 'Buổi sáng', '{"goals":[{"code":"ASK_WAY","type":"MISSION","title":"Hỏi đường","required":true,"conditions":[{"type":"KEYWORD","value":"どう行けば|美術館|すみません"}],"description":"Hỏi đường tới bảo tàng mỹ thuật.","displayOrder":1},{"code":"DURATION","type":"MISSION","title":"Hỏi thời gian đi bộ","required":true,"conditions":[{"type":"KEYWORD","value":"歩いて|どのくらい|十分"}],"description":"Hỏi đi bộ mất bao lâu.","displayOrder":2},{"code":"LANDMARK","type":"MISSION","title":"Xác nhận dấu mốc","required":true,"conditions":[{"type":"KEYWORD","value":"目印|助かりました|時計"}],"description":"Xác nhận dấu mốc và cảm ơn.","displayOrder":3}],"states":[{"code":"ASK_WAY","name":"Hỏi đường","next":"DURATION","prompt":"Chào người hỏi đường, chỉ đường đến bảo tàng mỹ thuật.","allowedGoalCodes":["ASK_WAY"],"suggestedReplies":["美術館へはどう行けばいいですか。","美術館に行きたいんですが。"]},{"code":"DURATION","name":"Hỏi thời gian","next":"LANDMARK","prompt":"Chỉ đường và báo thời gian đi bộ, nêu dấu mốc.","allowedGoalCodes":["DURATION"],"suggestedReplies":["歩いてどのくらいですか。","遠いですか。"]},{"code":"LANDMARK","name":"Xác nhận dấu mốc","next":"END","prompt":"Nêu dấu mốc dễ nhận và nhắc có thể hôm nay là ngày đóng cửa.","allowedGoalCodes":["LANDMARK"],"suggestedReplies":["それが目印ですね。助かりました。","ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã tìm được đường","message":"気をつけて行ってくださいね。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ASK_WAY"}', '{"grammar":[{"example":"美術館へはどう行けばいいですか。","pattern":"どう行けばいいですか","explanation":"Mẫu hỏi đường chuẩn nhất."},{"example":"確認したほうがいいですね。","pattern":"〜たほうがいい","explanation":"Khuyên nên làm gì, nhẹ nhàng hơn mệnh lệnh."}],"vocabulary":[{"jlpt":"N4","term":"美術館","example":"美術館へ行きます。","meaning":"bảo tàng mỹ thuật","reading":"びじゅつかん"},{"jlpt":"N5","term":"まっすぐ","example":"まっすぐ行ってください。","meaning":"đi thẳng","reading":"まっすぐ"},{"jlpt":"N5","term":"信号","example":"二つ目の信号を左です。","meaning":"đèn tín hiệu","reading":"しんごう"},{"jlpt":"N4","term":"目印","example":"それが目印ですね。","meaning":"dấu mốc dễ nhận","reading":"めじるし"}],"exampleDialogue":[{"text":"すみません、美術館へはどう行けばいいですか。","speaker":"learner","translation":"Xin lỗi, đi tới bảo tàng mỹ thuật thế nào ạ?"},{"text":"ここをまっすぐ行って、二つ目の信号を左です。","speaker":"ai","translation":"Đi thẳng đây, tới đèn thứ hai thì rẽ trái."},{"text":"歩いてどのくらいですか。","speaker":"learner","translation":"Đi bộ khoảng bao lâu ạ?"},{"text":"十分くらいかな。突き当たりに大きな時計がありますよ。","speaker":"ai","translation":"Chắc khoảng mười phút. Cuối đường có cái đồng hồ lớn đấy."},{"text":"それが目印ですね。助かりました。","speaker":"learner","translation":"Đó là dấu mốc nhỉ. Đỡ cho tôi quá."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-ga'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hanh-khach-di-tau'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Để quên đồ', 'cpath-trv-07', 'Bạn báo để quên túi, nói chi tiết chuyến tàu, kể đồ bên trong và hỏi cách liên lạc.', 'N3', 'MEDIUM', 8, 'Bạn lỡ để quên ba lô trên tàu và cần báo với nhân viên ga để làm thủ tục tìm đồ.', 'Quầy hỗ trợ nhà ga', 'Buổi chiều', '{"goals":[{"code":"REPORT","type":"MISSION","title":"Báo để quên đồ","required":true,"conditions":[{"type":"KEYWORD","value":"忘れて|鞄|電車"}],"description":"Báo mình để quên túi trên tàu.","displayOrder":1},{"code":"DETAILS","type":"MISSION","title":"Nói chi tiết chuyến tàu","required":true,"conditions":[{"type":"KEYWORD","value":"三時|山手線|リュック"}],"description":"Nói giờ, tuyến và màu túi.","displayOrder":2},{"code":"CONTENTS","type":"MISSION","title":"Nói đồ bên trong","required":true,"conditions":[{"type":"KEYWORD","value":"ノートパソコン|名刺|中身"}],"description":"Kể đồ bên trong để nhận dạng.","displayOrder":3},{"code":"CONTACT","type":"MISSION","title":"Hỏi cách liên lạc","required":true,"conditions":[{"type":"KEYWORD","value":"連絡|電話|見つかった"}],"description":"Hỏi tìm thấy thì liên lạc thế nào.","displayOrder":4}],"states":[{"code":"REPORT","name":"Báo mất đồ","next":"DETAILS","prompt":"Chào hành khách, hỏi giờ và tuyến tàu để quên đồ.","allowedGoalCodes":["REPORT"],"suggestedReplies":["電車に鞄を忘れてしまったんですが。","忘れ物をしたんですが。"]},{"code":"DETAILS","name":"Chi tiết chuyến tàu","next":"CONTENTS","prompt":"Hỏi giờ, tuyến và màu sắc hành lý.","allowedGoalCodes":["DETAILS"],"suggestedReplies":["三時ごろ、山手線です。黒いリュックです。","三時ごろです。"]},{"code":"CONTENTS","name":"Đồ bên trong","next":"CONTACT","prompt":"Hỏi đồ bên trong để nhận dạng và nhờ điền phiếu.","allowedGoalCodes":["CONTENTS"],"suggestedReplies":["ノートパソコンと名刺入れが入っています。","パソコンが入っています。"]},{"code":"CONTACT","name":"Cách liên lạc","next":"END","prompt":"Hẹn tra tìm và nói cách liên lạc khi tìm thấy.","allowedGoalCodes":["CONTACT"],"suggestedReplies":["見つかったらどう連絡がありますか。","電話をください。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã làm thủ tục tìm đồ","message":"お電話を差し上げます。少々お待ちください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"REPORT"}', '{"grammar":[{"example":"電車に鞄を忘れてしまったんですが。","pattern":"〜てしまった","explanation":"Diễn tả sự tiếc nuối về việc đã xảy ra."},{"example":"お電話を差し上げます。","pattern":"差し上げます","explanation":"Khiêm nhường ngữ của あげる."}],"vocabulary":[{"jlpt":"N3","term":"鞄","example":"鞄を忘れました。","meaning":"cái túi","reading":"かばん"},{"jlpt":"N3","term":"路線","example":"どの路線ですか。","meaning":"tuyến tàu","reading":"ろせん"},{"jlpt":"N3","term":"忘れ物","example":"忘れ物をしました。","meaning":"đồ để quên","reading":"わすれもの"},{"jlpt":"N3","term":"連絡","example":"後で連絡します。","meaning":"liên lạc","reading":"れんらく"}],"exampleDialogue":[{"text":"電車に鞄を忘れてしまったんですが。","speaker":"learner","translation":"Tôi lỡ để quên túi trên tàu ạ."},{"text":"何時ごろの、どの路線でしょうか。","speaker":"ai","translation":"Khoảng mấy giờ, tuyến nào ạ?"},{"text":"三時ごろ、山手線です。黒いリュックです。","speaker":"learner","translation":"Khoảng ba giờ, tuyến Yamanote. Là ba lô màu đen."},{"text":"中身で分かるものはございますか。","speaker":"ai","translation":"Có thứ gì bên trong để nhận dạng không ạ?"},{"text":"ノートパソコンと、名刺入れが入っています。","speaker":"learner","translation":"Có máy tính xách tay và hộp danh thiếp ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-le-tan-khach-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-luu-tru'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Bị mệt khi đang đi du lịch', 'cpath-trv-08', 'Bạn nói triệu chứng, nhận lời giúp đỡ tìm bệnh viện và hỏi về bảo hiểm.', 'N3', 'MEDIUM', 8, 'Bạn bị sốt và đau đầu giữa chuyến đi, cần nhờ lễ tân khách sạn giúp tìm bác sĩ.', 'Quầy lễ tân khách sạn', 'Buổi tối', '{"goals":[{"code":"SYMPTOM","type":"MISSION","title":"Nói triệu chứng","required":true,"conditions":[{"type":"KEYWORD","value":"具合|熱|頭"}],"description":"Nói mình thấy mệt và triệu chứng.","displayOrder":1},{"code":"HELP","type":"MISSION","title":"Nhận giúp đỡ","required":true,"conditions":[{"type":"KEYWORD","value":"お願いします|病院|分からなくて"}],"description":"Nhờ tra bệnh viện và nói không rành tiếng Nhật.","displayOrder":2},{"code":"INSURANCE","type":"MISSION","title":"Hỏi bảo hiểm","required":true,"conditions":[{"type":"KEYWORD","value":"保険|使えます|ありがとう"}],"description":"Hỏi bảo hiểm có dùng được không.","displayOrder":3}],"states":[{"code":"SYMPTOM","name":"Kể triệu chứng","next":"HELP","prompt":"Hỏi thăm tình trạng và triệu chứng của khách.","allowedGoalCodes":["SYMPTOM"],"suggestedReplies":["少し具合が悪くて。熱があって、頭が痛いんです。","熱があります。"]},{"code":"HELP","name":"Nhận giúp đỡ","next":"INSURANCE","prompt":"Đề nghị tra bệnh viện gần đây và tìm phòng khám nói tiếng Anh.","allowedGoalCodes":["HELP"],"suggestedReplies":["お願いします。日本語があまり分からなくて。","お願いします。"]},{"code":"INSURANCE","name":"Hỏi bảo hiểm","next":"END","prompt":"Báo có phòng khám nói tiếng Anh, hỏi có cần đặt hẹn không.","allowedGoalCodes":["INSURANCE"],"suggestedReplies":["保険は使えますか。","旅行保険があります。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã được hỗ trợ y tế","message":"予約を取っておきます。お大事に。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"SYMPTOM"}', '{"grammar":[{"example":"少し具合が悪くて。","pattern":"具合が悪い","explanation":"Cách nói chung khi chưa rõ bệnh gì."},{"example":"近くの病院をお調べしましょうか。","pattern":"〜ましょうか","explanation":"Đề nghị giúp đỡ, hay dùng trong dịch vụ."}],"vocabulary":[{"jlpt":"N3","term":"具合","example":"具合が悪いです。","meaning":"tình trạng cơ thể","reading":"ぐあい"},{"jlpt":"N5","term":"熱","example":"熱があります。","meaning":"sốt","reading":"ねつ"},{"jlpt":"N5","term":"病院","example":"病院に行きます。","meaning":"bệnh viện","reading":"びょういん"},{"jlpt":"N3","term":"保険","example":"保険は使えますか。","meaning":"bảo hiểm","reading":"ほけん"}],"exampleDialogue":[{"text":"すみません、少し具合が悪くて。","speaker":"learner","translation":"Xin lỗi, tôi thấy hơi khó chịu trong người."},{"text":"大丈夫ですか。どのような症状でしょうか。","speaker":"ai","translation":"Ngài không sao chứ? Triệu chứng thế nào ạ?"},{"text":"熱があって、頭が痛いんです。","speaker":"learner","translation":"Tôi bị sốt và đau đầu ạ."},{"text":"近くの病院をお調べしましょうか。","speaker":"ai","translation":"Để tôi tra bệnh viện gần đây giúp ngài nhé?"},{"text":"お願いします。日本語があまり分からなくて。","speaker":"learner","translation":"Nhờ chị ạ. Tôi không rành tiếng Nhật lắm."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-cua-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-mua-sam'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Mua sắm và miễn thuế', 'cpath-trv-05', 'Bạn hỏi điều kiện miễn thuế, hỏi tổng tiền, xác nhận hộ chiếu và yêu cầu gói quà.', 'N3', 'MEDIUM', 8, 'Bạn mua quà lưu niệm và muốn làm thủ tục miễn thuế, đồng thời nhờ gói quà riêng từng phần.', 'Cửa hàng quà lưu niệm', 'Buổi chiều', '{"goals":[{"code":"TAX_FREE","type":"MISSION","title":"Hỏi miễn thuế","required":true,"conditions":[{"type":"KEYWORD","value":"免税|対象|五千円"}],"description":"Hỏi món hàng có được miễn thuế không.","displayOrder":1},{"code":"TOTAL","type":"MISSION","title":"Hỏi tổng tiền","required":true,"conditions":[{"type":"KEYWORD","value":"いくら|税込み|六千"}],"description":"Hỏi tổng tiền hiện tại.","displayOrder":2},{"code":"PASSPORT","type":"MISSION","title":"Xác nhận hộ chiếu","required":true,"conditions":[{"type":"KEYWORD","value":"パスポート|要ります|免税で"}],"description":"Xin miễn thuế và xác nhận cần hộ chiếu.","displayOrder":3},{"code":"WRAP","type":"MISSION","title":"Yêu cầu gói quà","required":true,"conditions":[{"type":"KEYWORD","value":"分けて|包んで|土産"}],"description":"Yêu cầu gói riêng từng phần.","displayOrder":4}],"states":[{"code":"TAX_FREE","name":"Hỏi miễn thuế","next":"TOTAL","prompt":"Chào khách, trả lời điều kiện miễn thuế.","allowedGoalCodes":["TAX_FREE"],"suggestedReplies":["これ、免税になりますか。","免税はありますか。"]},{"code":"TOTAL","name":"Hỏi tổng tiền","next":"PASSPORT","prompt":"Báo mức mua tối thiểu và tổng tiền hiện tại.","allowedGoalCodes":["TOTAL"],"suggestedReplies":["今いくらですか。","税込みでいくらですか。"]},{"code":"PASSPORT","name":"Xác nhận hộ chiếu","next":"WRAP","prompt":"Báo tổng tiền đã đủ điều kiện, nhận hộ chiếu và hỏi cách gói.","allowedGoalCodes":["PASSPORT"],"suggestedReplies":["では免税でお願いします。パスポートが要りますよね。","パスポートはこちらです。"]},{"code":"WRAP","name":"Yêu cầu gói quà","next":"END","prompt":"Hỏi khách có cần gói quà không.","allowedGoalCodes":["WRAP"],"suggestedReplies":["土産なので、分けて包んでください。","包んでください。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã làm miễn thuế xong","message":"かしこまりました。少々お時間をいただきます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"TAX_FREE"}', '{"grammar":[{"example":"五千円以上のお買い上げで対象になります。","pattern":"〜以上","explanation":"Từ ~ trở lên, hay gặp trong điều kiện khuyến mãi."},{"example":"包装はいかがなさいますか。","pattern":"いかがなさいますか","explanation":"Tôn kính ngữ của どうしますか."}],"vocabulary":[{"jlpt":"N3","term":"免税","example":"免税になりますか。","meaning":"miễn thuế","reading":"めんぜい"},{"jlpt":"N3","term":"税込み","example":"税込みでいくらですか。","meaning":"đã gồm thuế","reading":"ぜいこみ"},{"jlpt":"N4","term":"パスポート","example":"パスポートが要ります。","meaning":"hộ chiếu","reading":"パスポート"},{"jlpt":"N3","term":"包装","example":"包装をお願いします。","meaning":"gói quà","reading":"ほうそう"}],"exampleDialogue":[{"text":"これ、免税になりますか。","speaker":"learner","translation":"Cái này được miễn thuế không ạ?"},{"text":"五千円以上のお買い上げで対象になります。","speaker":"ai","translation":"Mua từ năm nghìn yên trở lên là thuộc diện được ạ."},{"text":"今いくらですか。","speaker":"learner","translation":"Bây giờ là bao nhiêu ạ?"},{"text":"税込みで六千二百円でございます。","speaker":"ai","translation":"Gồm thuế là sáu nghìn hai trăm yên ạ."},{"text":"では免税でお願いします。パスポートが要りますよね。","speaker":"learner","translation":"Vậy cho tôi miễn thuế ạ. Cần hộ chiếu đúng không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-cua-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-mua-sam'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Thử đồ', 'cpath-trv-17', 'Bạn xin thử áo, nói áo chật để xin cỡ lớn hơn và quyết định mua khi vừa.', 'N4', 'EASY', 7, 'Bạn muốn thử một chiếc áo sơ mi và xin cỡ khác nếu không vừa.', 'Cửa hàng quần áo', 'Buổi chiều', '{"goals":[{"code":"TRY_ON","type":"MISSION","title":"Xin thử đồ","required":true,"conditions":[{"type":"KEYWORD","value":"試着|できます|シャツ"}],"description":"Xin thử áo sơ mi.","displayOrder":1},{"code":"SIZE","type":"MISSION","title":"Xin cỡ khác","required":true,"conditions":[{"type":"KEYWORD","value":"小さい|サイズ|上"}],"description":"Nói áo chật và xin cỡ lớn hơn.","displayOrder":2},{"code":"DECIDE","type":"MISSION","title":"Quyết định mua","required":true,"conditions":[{"type":"KEYWORD","value":"ちょうどいい|これにします|Mサイズ"}],"description":"Thử vừa và quyết định mua.","displayOrder":3}],"states":[{"code":"TRY_ON","name":"Xin thử","next":"SIZE","prompt":"Chào khách, chỉ phòng thử đồ.","allowedGoalCodes":["TRY_ON"],"suggestedReplies":["このシャツを試着できますか。","試着してもいいですか。"]},{"code":"SIZE","name":"Xin cỡ khác","next":"DECIDE","prompt":"Hỏi cảm nhận sau khi thử và mang cỡ khác.","allowedGoalCodes":["SIZE"],"suggestedReplies":["ちょっと小さいです。もう一つ上のサイズはありますか。","大きいサイズはありますか。"]},{"code":"DECIDE","name":"Quyết định mua","next":"END","prompt":"Đưa cỡ M và hỏi khách đã ưng chưa.","allowedGoalCodes":["DECIDE"],"suggestedReplies":["ちょうどいいです。これにします。","これにします。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã chọn được đồ","message":"ありがとうございました。またお越しください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"TRY_ON"}', '{"grammar":[{"example":"このシャツを試着できますか。","pattern":"〜できますか","explanation":"Xin phép làm một việc."},{"example":"もう一つ上のサイズはありますか。","pattern":"〜はありますか","explanation":"Hỏi về hàng trong cửa hàng."}],"vocabulary":[{"jlpt":"N4","term":"試着","example":"試着できますか。","meaning":"mặc thử","reading":"しちゃく"},{"jlpt":"N5","term":"シャツ","example":"このシャツを試着します。","meaning":"áo sơ mi","reading":"シャツ"},{"jlpt":"N5","term":"サイズ","example":"サイズはMです。","meaning":"cỡ","reading":"サイズ"},{"jlpt":"N5","term":"ちょうど","example":"ちょうどいいです。","meaning":"vừa vặn","reading":"ちょうど"}],"exampleDialogue":[{"text":"すみません、このシャツを試着できますか。","speaker":"learner","translation":"Xin lỗi, tôi thử cái áo sơ mi này được không ạ?"},{"text":"はい、試着室はあちらです。","speaker":"ai","translation":"Vâng, phòng thử đồ ở phía kia ạ."},{"text":"ちょっと小さいです。もう一つ上のサイズはありますか。","speaker":"learner","translation":"Hơi chật. Có cỡ lớn hơn một cỡ không ạ?"},{"text":"少々お待ちください。確認してまいります。","speaker":"ai","translation":"Xin quý khách đợi một chút, tôi đi kiểm tra."},{"text":"ちょうどいいです。これにします。","speaker":"learner","translation":"Vừa vặn ạ. Tôi lấy cái này."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-cua-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-mua-sam'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Đổi hàng', 'cpath-trv-18', 'Bạn xin đổi hàng, đưa hóa đơn và chọn màu mới.', 'N4', 'EASY', 7, 'Bạn mua nhầm màu hôm qua và muốn đổi sang màu khác, có mang theo hóa đơn.', 'Quầy đổi hàng của cửa hàng', 'Buổi sáng', '{"goals":[{"code":"EXCHANGE","type":"MISSION","title":"Xin đổi hàng","required":true,"conditions":[{"type":"KEYWORD","value":"交換|昨日|買った"}],"description":"Nói muốn đổi món đã mua hôm qua.","displayOrder":1},{"code":"RECEIPT","type":"MISSION","title":"Đưa hóa đơn","required":true,"conditions":[{"type":"KEYWORD","value":"レシート|これです|はい"}],"description":"Đưa hóa đơn khi được hỏi.","displayOrder":2},{"code":"COLOR","type":"MISSION","title":"Chọn màu mới","required":true,"conditions":[{"type":"KEYWORD","value":"青|白|色を"}],"description":"Nói muốn đổi màu và chọn màu.","displayOrder":3}],"states":[{"code":"EXCHANGE","name":"Xin đổi","next":"RECEIPT","prompt":"Chào khách, hỏi hóa đơn mua hàng.","allowedGoalCodes":["EXCHANGE"],"suggestedReplies":["昨日買ったこれを交換できますか。","交換したいんですが。"]},{"code":"RECEIPT","name":"Đưa hóa đơn","next":"COLOR","prompt":"Nhận hóa đơn và hỏi khách muốn đổi gì.","allowedGoalCodes":["RECEIPT"],"suggestedReplies":["はい、これです。色を変えたいです。","レシートはこれです。"]},{"code":"COLOR","name":"Chọn màu","next":"END","prompt":"Báo các màu còn lại và hỏi khách chọn màu nào.","allowedGoalCodes":["COLOR"],"suggestedReplies":["では、青をお願いします。","白にします。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã đổi hàng xong","message":"こちらでございます。ありがとうございました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"EXCHANGE"}', '{"grammar":[{"example":"昨日買ったこれを交換できますか。","pattern":"〜たこれを交換できますか","explanation":"Xin đổi hàng đã mua."},{"example":"色を変えたいです。","pattern":"〜たいです","explanation":"Bày tỏ mong muốn."}],"vocabulary":[{"jlpt":"N4","term":"交換","example":"交換できますか。","meaning":"đổi hàng","reading":"こうかん"},{"jlpt":"N5","term":"レシート","example":"レシートはこれです。","meaning":"hóa đơn mua hàng","reading":"レシート"},{"jlpt":"N5","term":"色","example":"色を変えたいです。","meaning":"màu sắc","reading":"いろ"},{"jlpt":"N5","term":"昨日","example":"昨日買いました。","meaning":"hôm qua","reading":"きのう"}],"exampleDialogue":[{"text":"すみません、昨日買ったこれを交換できますか。","speaker":"learner","translation":"Xin lỗi, cái này tôi mua hôm qua có đổi được không ạ?"},{"text":"レシートはお持ちですか。","speaker":"ai","translation":"Quý khách có mang hóa đơn không ạ?"},{"text":"はい、これです。色を変えたいです。","speaker":"learner","translation":"Vâng, đây ạ. Tôi muốn đổi màu khác."},{"text":"かしこまりました。青と白があります。","speaker":"ai","translation":"Vâng ạ. Có màu xanh và màu trắng."},{"text":"では、青をお願いします。","speaker":"learner","translation":"Vậy cho tôi màu xanh ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ho-tro-du-lich'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-du-lich'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chuyến du lịch Nhật Bản trọn hành trình', 'cpath-test-travel', 'Cuộc gọi tổng hợp giúp bạn luyện lại các tình huống du lịch chính từ sân bay, tàu, khách sạn, ăn uống, mua sắm đến xử lý sự cố.', 'N3', 'MEDIUM', 14, 'Bạn có chuyến du lịch Nhật Bản trọn ngày và lần lượt gặp các nhân viên phục vụ ở sân bay, nhà ga, khách sạn, nhà hàng và cửa hàng.', 'Sân bay, nhà ga, khách sạn, nhà hàng và cửa hàng', 'Cả ngày', '{"goals":[{"code":"CHECKIN_AIR","type":"MISSION","title":"Làm thủ tục sân bay","required":true,"conditions":[{"type":"KEYWORD","value":"パスポート|予約番号|窓側"}],"description":"Làm thủ tục chuyến bay, xuất trình giấy tờ và chọn ghế.","displayOrder":1},{"code":"TRAIN","type":"MISSION","title":"Hỏi đường tàu","required":true,"conditions":[{"type":"KEYWORD","value":"切符|乗り換え|横浜"}],"description":"Mua vé hoặc hỏi cách đổi tàu.","displayOrder":2},{"code":"HOTEL","type":"MISSION","title":"Nhận phòng khách sạn","required":true,"conditions":[{"type":"KEYWORD","value":"予約|チェックイン|朝食"}],"description":"Nhận phòng và hỏi giờ ăn sáng.","displayOrder":3},{"code":"FOOD","type":"MISSION","title":"Gọi món nhà hàng","required":true,"conditions":[{"type":"KEYWORD","value":"お願いします|定食|お会計"}],"description":"Gọi món và thanh toán.","displayOrder":4},{"code":"SHOP","type":"MISSION","title":"Mua quà miễn thuế","required":true,"conditions":[{"type":"KEYWORD","value":"免税|パスポート|いくら"}],"description":"Mua quà và làm thủ tục miễn thuế.","displayOrder":5},{"code":"TROUBLE","type":"MISSION","title":"Xử lý sự cố","required":true,"conditions":[{"type":"KEYWORD","value":"忘れて|具合|どう行けば"}],"description":"Báo sự cố như quên đồ, mệt hoặc hỏi đường.","displayOrder":6}],"states":[{"code":"AIRPORT","name":"Sân bay","next":"TRAIN_STATION","prompt":"Đóng vai nhân viên sân bay: xin hộ chiếu và hỏi chỗ ngồi.","allowedGoalCodes":["CHECKIN_AIR"],"suggestedReplies":["パスポートと予約番号です。","窓側をお願いします。"]},{"code":"TRAIN_STATION","name":"Nhà ga","next":"HOTEL_FRONT","prompt":"Đóng vai nhân viên nhà ga: hướng dẫn mua vé hoặc đổi tàu.","allowedGoalCodes":["TRAIN"],"suggestedReplies":["切符を買いたいんですが。","乗り換えはありますか。"]},{"code":"HOTEL_FRONT","name":"Khách sạn","next":"RESTAURANT","prompt":"Đóng vai lễ tân: nhận phòng và báo giờ ăn sáng.","allowedGoalCodes":["HOTEL"],"suggestedReplies":["予約したグエンです。","朝食は何時からですか。"]},{"code":"RESTAURANT","name":"Nhà hàng","next":"SHOP","prompt":"Đóng vai nhân viên nhà hàng: nhận món và tính tiền.","allowedGoalCodes":["FOOD"],"suggestedReplies":["この定食をお願いします。","お会計をお願いします。"]},{"code":"SHOP","name":"Mua sắm","next":"TROUBLE","prompt":"Đóng vai nhân viên cửa hàng: hướng dẫn miễn thuế.","allowedGoalCodes":["SHOP"],"suggestedReplies":["免税になりますか。","パスポートが要りますよね。"]},{"code":"TROUBLE","name":"Sự cố","next":"END","prompt":"Đóng vai nhân viên hỗ trợ: xử lý tình huống khách gặp sự cố.","allowedGoalCodes":["TROUBLE"],"suggestedReplies":["すみません、鞄を忘れてしまって。","助けてください。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành hành trình","message":"素敵な旅になりますように。お気をつけて。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"AIRPORT"}', '{"grammar":[{"example":"パスポートと予約番号をお願いします。","pattern":"〜をお願いします","explanation":"Cách lịch sự để đề nghị hoặc nhờ ai làm việc gì."},{"example":"タクシーを呼んでもらえますか。","pattern":"〜てもらえますか","explanation":"Nhờ vả lịch sự."},{"example":"美術館へはどう行けばいいですか。","pattern":"どう行けばいいですか","explanation":"Mẫu hỏi đường chuẩn nhất."}],"vocabulary":[{"jlpt":"N4","term":"予約","example":"予約したグエンです。","meaning":"đặt chỗ","reading":"よやく"},{"jlpt":"N4","term":"切符","example":"切符を買います。","meaning":"vé","reading":"きっぷ"},{"jlpt":"N3","term":"免税","example":"免税になりますか。","meaning":"miễn thuế","reading":"めんぜい"},{"jlpt":"N4","term":"お会計","example":"お会計をお願いします。","meaning":"thanh toán","reading":"おかいけい"},{"jlpt":"N3","term":"忘れ物","example":"忘れ物をしました。","meaning":"đồ để quên","reading":"わすれもの"}],"exampleDialogue":[{"text":"おはようございます。パスポートと予約番号をお願いします。","speaker":"ai","translation":"Chào anh. Cho tôi xin hộ chiếu và mã đặt chỗ ạ."},{"text":"はい、これです。窓側の席は空いていますか。","speaker":"learner","translation":"Vâng, đây ạ. Còn ghế cạnh cửa sổ không ạ?"},{"text":"いらっしゃいませ。何名様ですか。","speaker":"ai","translation":"Xin chào quý khách. Mấy người ạ?"},{"text":"二人です。この定食をお願いします。","speaker":"learner","translation":"Hai người. Cho tôi suất cơm phần này ạ."},{"text":"かしこまりました。お会計はレジでお願いします。","speaker":"ai","translation":"Vâng ạ. Xin thanh toán ở quầy."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-bat-dong-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-thue-nha'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Thuê phòng', 'cpath-dly-01', 'Bạn xem phòng và hỏi nhân viên bất động sản về chi phí ban đầu, phí quản lý, độ nắng và tiếng ồn.', 'N4', 'EASY', 6, 'Bạn đang tìm phòng trọ gần trường và muốn hỏi kỹ các khoản chi phí ban đầu trước khi quyết định.', 'Văn phòng bất động sản gần ga', 'Buổi sáng', '{"goals":[{"code":"COST","type":"MISSION","title":"Hỏi tổng chi phí ban đầu","required":true,"conditions":[{"type":"KEYWORD","value":"初期費用|いくら|家賃|敷金"}],"description":"Hỏi tổng chi phí ban đầu để thuê phòng.","displayOrder":1},{"code":"FEE","type":"MISSION","title":"Hỏi phí quản lý riêng","required":true,"conditions":[{"type":"KEYWORD","value":"共益費|別|別途|礼金"}],"description":"Xác nhận phí quản lý có tính riêng không.","displayOrder":2},{"code":"SUN","type":"MISSION","title":"Hỏi phòng có nắng không","required":true,"conditions":[{"type":"KEYWORD","value":"日当たり|南向き|昼間|明るい"}],"description":"Hỏi về độ chiếu nắng của phòng.","displayOrder":3},{"code":"NOISE","type":"MISSION","title":"Hỏi về tiếng ồn","required":true,"conditions":[{"type":"KEYWORD","value":"騒音|静か|大通り|気になりませんか"}],"description":"Hỏi phòng có ồn không.","displayOrder":4}],"states":[{"code":"S1","name":"Chào và hỏi chi phí","next":"S2","prompt":"Chào khách, mời xem phòng và sẵn sàng báo chi phí ban đầu.","allowedGoalCodes":["COST"],"suggestedReplies":["初期費用は全部でいくらになりますか。"]},{"code":"S2","name":"Báo phí và xác nhận phí riêng","next":"S3","prompt":"Nêu từng khoản (tiền thuê, cọc, tiền lễ) và phí quản lý tính riêng.","allowedGoalCodes":["FEE"],"suggestedReplies":["礼金がないのは助かります。共益費は別ですか。"],"transitionText":"Sau khi biết tổng chi phí…"},{"code":"S3","name":"Hỏi độ nắng","next":"S4","prompt":"Mô tả hướng phòng và ánh sáng ban ngày.","allowedGoalCodes":["SUN"],"suggestedReplies":["日当たりはどうですか。"]},{"code":"S4","name":"Hỏi tiếng ồn","next":"END","prompt":"Cho biết phòng xa hay gần đường lớn, có yên tĩnh không.","allowedGoalCodes":["NOISE"],"suggestedReplies":["騒音は気になりませんか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành xem phòng","message":"ご来店ありがとうございます。ご検討ください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"共益費は別ですか。","pattern":"〜は別ですか","explanation":"Cách hỏi một khoản có tính riêng ngoài khoản chính không."},{"example":"静かなほうです。","pattern":"〜ほうです","explanation":"Cách nói dè dặt, tránh khẳng định tuyệt đối."}],"vocabulary":[{"jlpt":"N4","term":"家賃","example":"家賃はいくらですか。","meaning":"tiền thuê nhà","reading":"やちん"},{"jlpt":"N4","term":"敷金","example":"敷金は一か月分です。","meaning":"tiền đặt cọc","reading":"しききん"},{"jlpt":"N4","term":"礼金","example":"礼金はありません。","meaning":"tiền lễ cho chủ nhà","reading":"れいきん"},{"jlpt":"N4","term":"日当たり","example":"日当たりがいいです。","meaning":"độ chiếu nắng","reading":"ひあたり"}],"exampleDialogue":[{"text":"初期費用は全部でいくらになりますか。","speaker":"learner","translation":"Chi phí ban đầu tổng cộng là bao nhiêu ạ?"},{"text":"家賃、敷金一か月、礼金なしで、合計十四万円ほどです。","speaker":"ai","translation":"Tiền thuê, cọc một tháng, không tiền lễ, tổng khoảng mười bốn vạn ạ."},{"text":"日当たりはどうですか。","speaker":"learner","translation":"Phòng có nắng không ạ?"},{"text":"南向きですので、昼間は明るいですよ。","speaker":"ai","translation":"Hướng nam nên ban ngày sáng lắm ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-hang-xom'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-moi-den'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Phân loại rác', 'cpath-dly-02', 'Bạn hỏi hàng xóm cách phân loại rác, cách xử lý lon rỗng và đồ cồng kềnh.', 'N4', 'EASY', 6, 'Bạn mới chuyển đến và được hàng xóm chỉ cách phân loại rác trong khu phố.', 'Trước cổng nhà trong khu phố', 'Buổi sáng', '{"goals":[{"code":"KIND","type":"MISSION","title":"Hỏi loại rác của lon rỗng","required":true,"conditions":[{"type":"KEYWORD","value":"空き缶|どのごみ|何ごみ|資源"}],"description":"Hỏi lon rỗng thuộc loại rác nào.","displayOrder":1},{"code":"WASH","type":"MISSION","title":"Xác nhận cách xử lý lon","required":true,"conditions":[{"type":"KEYWORD","value":"洗って|ゆすいで|つぶさず|出し方"}],"description":"Xác nhận có phải rửa và không bóp bẹp không.","displayOrder":2},{"code":"BULKY","type":"MISSION","title":"Hỏi cách xử lý đồ cồng kềnh","required":true,"conditions":[{"type":"KEYWORD","value":"古い椅子|粗大ごみ|どうすれば|市役所"}],"description":"Hỏi cách xử lý cái ghế cũ.","displayOrder":3},{"code":"THANKS","type":"MISSION","title":"Cảm ơn hàng xóm","required":true,"conditions":[{"type":"KEYWORD","value":"手続き|ありがとうございます|分かりました"}],"description":"Xác nhận cần thủ tục và cảm ơn.","displayOrder":4}],"states":[{"code":"S1","name":"Hỏi loại rác","next":"S2","prompt":"Chỉ cho người mới biết lon rỗng là rác tái chế và ngày đem ra.","allowedGoalCodes":["KIND"],"suggestedReplies":["この空き缶はどのごみですか。"]},{"code":"S2","name":"Xác nhận cách xử lý","next":"S3","prompt":"Dặn tráng bên trong và đừng bóp bẹp lon.","allowedGoalCodes":["WASH"],"suggestedReplies":["洗ってから出すんですか。"],"transitionText":"Sau khi biết loại rác…"},{"code":"S3","name":"Hỏi đồ cồng kềnh","next":"S4","prompt":"Giải thích ghế cũ là rác cồng kềnh, cần đăng ký và mua tem.","allowedGoalCodes":["BULKY"],"suggestedReplies":["古い椅子はどうすればいいですか。"]},{"code":"S4","name":"Cảm ơn","next":"END","prompt":"Vui vẻ chấp nhận lời cảm ơn và dặn thêm.","allowedGoalCodes":["THANKS"],"suggestedReplies":["手続きが要るんですね。教えてくださってありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nắm cách phân loại rác","message":"何かあったら、またいつでも聞いてね。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"洗ってから出すんですか。","pattern":"〜てから","explanation":"Nhấn mạnh thứ tự trước sau của hai việc."},{"example":"つぶさずにね。","pattern":"〜ずに","explanation":"Dạng văn viết của ないで, nghĩa là \\"mà không ~\\"."}],"vocabulary":[{"jlpt":"N4","term":"分別","example":"ごみの分別を教えてください。","meaning":"phân loại (rác)","reading":"ぶんべつ"},{"jlpt":"N4","term":"資源ごみ","example":"これは資源ごみです。","meaning":"rác tái chế","reading":"しげんごみ"},{"jlpt":"N4","term":"粗大ごみ","example":"椅子は粗大ごみです。","meaning":"rác cồng kềnh","reading":"そだいごみ"},{"jlpt":"N4","term":"手続き","example":"手続きが要ります。","meaning":"thủ tục","reading":"てつづき"}],"exampleDialogue":[{"text":"この空き缶はどのごみですか。","speaker":"learner","translation":"Cái lon rỗng này thuộc loại rác nào ạ?"},{"text":"それは資源ごみ。水曜の朝に出すのよ。","speaker":"ai","translation":"Cái đó là rác tái chế. Đem ra sáng thứ tư nhé."},{"text":"洗ってから出すんですか。","speaker":"learner","translation":"Phải rửa rồi mới đem ra ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-hang-xom'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-moi-den'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi cách phân loại rác', 'cpath-dly-09', 'Bạn hỏi hàng xóm về cách đổ rác, cách xử lý chai nhựa và giờ đổ rác.', 'N4', 'EASY', 6, 'Bạn cần nắm rõ ngày và giờ đổ rác của khu phố nên sang hỏi hàng xóm.', 'Trước nhà hàng xóm', 'Buổi sáng', '{"goals":[{"code":"HOW","type":"MISSION","title":"Nhờ chỉ cách đổ rác","required":true,"conditions":[{"type":"KEYWORD","value":"出し方|教えてもらえますか|燃える|火曜日"}],"description":"Nhờ hàng xóm chỉ cách đổ rác.","displayOrder":1},{"code":"BOTTLE","type":"MISSION","title":"Hỏi cách xử lý chai nhựa","required":true,"conditions":[{"type":"KEYWORD","value":"ペットボトル|資源|ラベル|どうすれば"}],"description":"Hỏi cách bỏ chai nhựa.","displayOrder":2},{"code":"TIME","type":"MISSION","title":"Hỏi giờ đổ rác","required":true,"conditions":[{"type":"KEYWORD","value":"何時まで|八時|朝|まで"}],"description":"Hỏi phải đổ rác trước mấy giờ.","displayOrder":3}],"states":[{"code":"S1","name":"Nhờ chỉ cách đổ rác","next":"S2","prompt":"Chỉ ngày đổ rác cháy được trong tuần.","allowedGoalCodes":["HOW"],"suggestedReplies":["すみません、ゴミの出し方を教えてもらえますか。"]},{"code":"S2","name":"Hỏi chai nhựa","next":"S3","prompt":"Cho biết chai nhựa là rác tái chế và cần gỡ nhãn.","allowedGoalCodes":["BOTTLE"],"suggestedReplies":["ペットボトルはどうすればいいですか。"]},{"code":"S3","name":"Hỏi giờ đổ rác","next":"END","prompt":"Cho biết giờ cuối phải đem rác ra.","allowedGoalCodes":["TIME"],"suggestedReplies":["何時までに出せばいいですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã biết lịch đổ rác","message":"ありがとうございます。気をつけてくださいね。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"ゴミの出し方を教えてもらえますか。","pattern":"〜方を教えてもらえますか","explanation":"Cách lịch sự nhờ người khác hướng dẫn cách làm."},{"example":"ペットボトルはどうすればいいですか。","pattern":"〜はどうすればいいですか","explanation":"Hỏi cách xử lý một việc."}],"vocabulary":[{"jlpt":"N4","term":"燃えるゴミ","example":"燃えるゴミは火曜日です。","meaning":"rác cháy được","reading":"もえるゴミ"},{"jlpt":"N4","term":"資源ゴミ","example":"資源ゴミは金曜日です。","meaning":"rác tái chế","reading":"しげんゴミ"},{"jlpt":"N4","term":"ラベル","example":"ラベルをはがしてください。","meaning":"nhãn dán","reading":"ラベル"},{"jlpt":"N4","term":"回収日","example":"回収日を教えてください。","meaning":"ngày thu gom","reading":"かいしゅうび"}],"exampleDialogue":[{"text":"すみません、ゴミの出し方を教えてもらえますか。","speaker":"learner","translation":"Xin lỗi, anh chỉ tôi cách đổ rác được không ạ?"},{"text":"燃えるゴミは火曜日と金曜日です。","speaker":"ai","translation":"Rác cháy được là thứ Ba và thứ Sáu ạ."},{"text":"何時までに出せばいいですか。","speaker":"learner","translation":"Phải đổ trước mấy giờ ạ?"},{"text":"朝八時までです。","speaker":"ai","translation":"Trước tám giờ sáng ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-sieu-thi'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-mua-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Đi siêu thị', 'cpath-dly-03', 'Bạn hỏi nhân viên siêu thị về hạn dùng, giờ giảm giá và vị trí để sữa.', 'N4', 'EASY', 6, 'Bạn vào siêu thị mua món ăn sẵn và sữa, muốn hỏi hạn dùng và giờ giảm giá.', 'Siêu thị gần nhà', 'Buổi chiều', '{"goals":[{"code":"DATE","type":"MISSION","title":"Hỏi hạn dùng","required":true,"conditions":[{"type":"KEYWORD","value":"消費期限|いつまで|本日|半額"}],"description":"Hỏi hạn dùng của món ăn sẵn.","displayOrder":1},{"code":"HOUR","type":"MISSION","title":"Hỏi giờ giảm giá","required":true,"conditions":[{"type":"KEYWORD","value":"何時ごろ|七時|値引き|半額"}],"description":"Hỏi từ mấy giờ bắt đầu giảm giá.","displayOrder":2},{"code":"FIND","type":"MISSION","title":"Hỏi vị trí sữa","required":true,"conditions":[{"type":"KEYWORD","value":"牛乳|どこ|冷蔵|案内"}],"description":"Hỏi sữa ở khu vực nào.","displayOrder":3},{"code":"POLITE","type":"MISSION","title":"Từ chối lịch sự","required":true,"conditions":[{"type":"KEYWORD","value":"大丈夫|ありがとうございます|結構です"}],"description":"Lịch sự từ chối lời dẫn đường và cảm ơn.","displayOrder":4}],"states":[{"code":"S1","name":"Hỏi hạn dùng","next":"S2","prompt":"Cho biết hạn dùng trong hôm nay và giờ giảm nửa giá.","allowedGoalCodes":["DATE"],"suggestedReplies":["すみません、この惣菜の消費期限はいつまでですか。"]},{"code":"S2","name":"Hỏi giờ giảm giá","next":"S3","prompt":"Cho biết thời điểm dán tem giảm giá.","allowedGoalCodes":["HOUR"],"suggestedReplies":["何時ごろからですか。"]},{"code":"S3","name":"Hỏi vị trí sữa","next":"S4","prompt":"Chỉ khu vực để sữa và đề nghị dẫn đi.","allowedGoalCodes":["FIND"],"suggestedReplies":["分かりました。牛乳はどこにありますか。"]},{"code":"S4","name":"Từ chối lịch sự","next":"END","prompt":"Vui vẻ chấp nhận lời từ chối của khách.","allowedGoalCodes":["POLITE"],"suggestedReplies":["大丈夫です。ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Mua sắm xong","message":"ありがとうございました。またどうぞ。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"七時過ぎには値引きシールを貼ります。","pattern":"〜過ぎ","explanation":"Cách nói thời điểm \\"sau ~ giờ\\"."},{"example":"ご案内しましょうか。","pattern":"ご案内しましょうか","explanation":"Khiêm nhường ngữ dùng khi đề nghị giúp."}],"vocabulary":[{"jlpt":"N4","term":"消費期限","example":"消費期限はいつまでですか。","meaning":"hạn dùng an toàn","reading":"しょうひきげん"},{"jlpt":"N4","term":"半額","example":"夕方から半額になります。","meaning":"giảm nửa giá","reading":"はんがく"},{"jlpt":"N4","term":"惣菜","example":"惣菜を買います。","meaning":"đồ ăn làm sẵn","reading":"そうざい"},{"jlpt":"N4","term":"牛乳","example":"牛乳はどこですか。","meaning":"sữa","reading":"ぎゅうにゅう"}],"exampleDialogue":[{"text":"この惣菜の消費期限はいつまでですか。","speaker":"learner","translation":"Món ăn sẵn này hạn dùng đến bao giờ ạ?"},{"text":"本日中でございます。夕方から半額になります。","speaker":"ai","translation":"Trong hôm nay ạ. Từ chiều sẽ giảm nửa giá."},{"text":"牛乳はどこにありますか。","speaker":"learner","translation":"Sữa ở đâu ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nguoi-ban-hang-cho'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-mua-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Mua rau', 'cpath-dly-10', 'Bạn hỏi giá, hỏi độ tươi rồi mua rau và xin bớt giá.', 'N4', 'EASY', 6, 'Bạn ra chợ mua rau tươi cho bữa tối và muốn hỏi giá rồi mặc cả.', 'Sạp rau trong chợ', 'Buổi sáng', '{"goals":[{"code":"PRICE","type":"MISSION","title":"Hỏi giá rau","required":true,"conditions":[{"type":"KEYWORD","value":"いくら|野菜|値段|二百円"}],"description":"Hỏi giá rau.","displayOrder":1},{"code":"FRESH","type":"MISSION","title":"Hỏi rau có tươi không","required":true,"conditions":[{"type":"KEYWORD","value":"新鮮|今朝|取れた"}],"description":"Hỏi rau có tươi không.","displayOrder":2},{"code":"BUY","type":"MISSION","title":"Mua và xin bớt","required":true,"conditions":[{"type":"KEYWORD","value":"ください|安く|二袋|三百五十円|お願いします"}],"description":"Mua hai túi và xin bớt giá.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi giá","next":"S2","prompt":"Báo giá một túi rau.","allowedGoalCodes":["PRICE"],"suggestedReplies":["すみません、この野菜はいくらですか。"]},{"code":"S2","name":"Hỏi độ tươi","next":"S3","prompt":"Xác nhận rau mới hái sáng nay.","allowedGoalCodes":["FRESH"],"suggestedReplies":["新鮮ですか。"]},{"code":"S3","name":"Mua và xin bớt","next":"END","prompt":"Đề xuất mức giá tốt hơn cho hai túi.","allowedGoalCodes":["BUY"],"suggestedReplies":["じゃ、二袋ください。安くしてもらえますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã mua được rau","message":"ありがとうございます。またどうぞ。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"この野菜はいくらですか。","pattern":"〜はいくらですか","explanation":"Cách hỏi giá một sản phẩm."},{"example":"三百五十円でどうですか。","pattern":"〜でどうですか","explanation":"Cách đề nghị một mức giá."}],"vocabulary":[{"jlpt":"N4","term":"野菜","example":"野菜を買います。","meaning":"rau","reading":"やさい"},{"jlpt":"N4","term":"新鮮","example":"新鮮な野菜です。","meaning":"tươi","reading":"しんせん"},{"jlpt":"N4","term":"安い","example":"安くしてください。","meaning":"rẻ","reading":"やすい"},{"jlpt":"N4","term":"一袋","example":"一袋ください。","meaning":"một túi","reading":"ひとふくろ"}],"exampleDialogue":[{"text":"この野菜はいくらですか。","speaker":"learner","translation":"Rau này bao nhiêu tiền ạ?"},{"text":"一袋二百円です。","speaker":"ai","translation":"Một túi hai trăm yên ạ."},{"text":"安くしてもらえますか。","speaker":"learner","translation":"Bớt chút được không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nguoi-ban-hang-cho'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-mua-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chọn cá', 'cpath-dly-11', 'Bạn hỏi cá tươi, chọn một con và nhờ người bán lọc thành ba miếng.', 'N4', 'EASY', 6, 'Bạn muốn nấu cá tươi nên nhờ người bán chỉ loại ngon và lọc sẵn.', 'Quầy cá trong chợ', 'Buổi sáng', '{"goals":[{"code":"FRESH","type":"MISSION","title":"Hỏi cá tươi","required":true,"conditions":[{"type":"KEYWORD","value":"新鮮|魚|さば|どれ"}],"description":"Hỏi cá nào tươi nhất.","displayOrder":1},{"code":"ORDER","type":"MISSION","title":"Chọn cá và nhờ lọc","required":true,"conditions":[{"type":"KEYWORD","value":"一匹|お願いします|三枚おろし|できますか"}],"description":"Mua một con và nhờ lọc thành ba miếng.","displayOrder":2},{"code":"THANKS","type":"MISSION","title":"Cảm ơn","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございます|分かりました"}],"description":"Cảm ơn người bán.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi cá tươi","next":"S2","prompt":"Giới thiệu loại cá tươi nhất trong ngày.","allowedGoalCodes":["FRESH"],"suggestedReplies":["すみません、新鮮な魚はどれですか。"]},{"code":"S2","name":"Chọn và nhờ lọc","next":"S3","prompt":"Nhận đơn và lọc cá ngay.","allowedGoalCodes":["ORDER"],"suggestedReplies":["一匹でお願いします。三枚おろしにできますか。"]},{"code":"S3","name":"Cảm ơn","next":"END","prompt":"Trao cá đã lọc và đáp lại lời cảm ơn.","allowedGoalCodes":["THANKS"],"suggestedReplies":["ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã mua được cá","message":"ありがとうございました。またどうぞ。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"新鮮な魚はどれですか。","pattern":"〜はどれですか","explanation":"Cách hỏi chọn một món cụ thể."},{"example":"三枚おろしにできますか。","pattern":"〜にできますか","explanation":"Yêu cầu cách chế biến."}],"vocabulary":[{"jlpt":"N4","term":"魚","example":"魚を買います。","meaning":"cá","reading":"さかな"},{"jlpt":"N4","term":"新鮮","example":"新鮮な魚です。","meaning":"tươi","reading":"しんせん"},{"jlpt":"N4","term":"一匹","example":"一匹ください。","meaning":"một con","reading":"いっぴき"},{"jlpt":"N4","term":"おろす","example":"魚をおろします。","meaning":"lọc (cá)","reading":"おろす"}],"exampleDialogue":[{"text":"新鮮な魚はどれですか。","speaker":"learner","translation":"Cá nào tươi ạ?"},{"text":"こちらのさばが今日一番です。","speaker":"ai","translation":"Cá thu bên này tươi nhất hôm nay ạ."},{"text":"三枚おろしにできますか。","speaker":"learner","translation":"Lọc thành ba miếng được không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-van-phong-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hoc-sinh'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo nghỉ học', 'cpath-dly-07', 'Bạn gọi văn phòng trường báo nghỉ vì sốt, nói dự định đi khám và hỏi bài tập hôm nay.', 'N4', 'EASY', 6, 'Bạn bị sốt, không thể đến trường nên gọi điện báo nghỉ và hỏi bài tập.', 'Văn phòng trường học (qua điện thoại)', 'Buổi sáng', '{"goals":[{"code":"INTRO","type":"MISSION","title":"Xưng tên và lớp","required":true,"conditions":[{"type":"KEYWORD","value":"おはようございます|二年|グエン|です"}],"description":"Chào và xưng tên, lớp của mình.","displayOrder":1},{"code":"REASON","type":"MISSION","title":"Nói lý do nghỉ","required":true,"conditions":[{"type":"KEYWORD","value":"熱|休ませていただきたい|病院"}],"description":"Nói lý do xin nghỉ học.","displayOrder":2},{"code":"HOSPITAL","type":"MISSION","title":"Nói dự định đi khám","required":true,"conditions":[{"type":"KEYWORD","value":"午後|病院|予定|診断書"}],"description":"Nói dự định đi bệnh viện.","displayOrder":3},{"code":"HOMEWORK","type":"MISSION","title":"Hỏi bài tập hôm nay","required":true,"conditions":[{"type":"KEYWORD","value":"課題|どうすれば|掲示板|確認"}],"description":"Hỏi cách nhận bài tập hôm nay.","displayOrder":4}],"states":[{"code":"S1","name":"Chào và xưng danh","next":"S2","prompt":"Hỏi học sinh có chuyện gì.","allowedGoalCodes":["INTRO"],"suggestedReplies":["おはようございます。二年のグエンです。"]},{"code":"S2","name":"Báo lý do nghỉ","next":"S3","prompt":"Hỏi đã đi bệnh viện chưa.","allowedGoalCodes":["REASON"],"suggestedReplies":["熱があるので、今日は休ませていただきたいです。"]},{"code":"S3","name":"Nói dự định đi khám","next":"S4","prompt":"Dặn mang giấy khám khi có.","allowedGoalCodes":["HOSPITAL"],"suggestedReplies":["午後に行く予定です。"]},{"code":"S4","name":"Hỏi bài tập","next":"END","prompt":"Cho biết bài tập đăng trên bảng tin lớp.","allowedGoalCodes":["HOMEWORK"],"suggestedReplies":["今日の課題はどうすればいいですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã báo nghỉ xong","message":"お大事にしてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"休ませていただきたいです。","pattern":"〜させていただきたい","explanation":"Khiêm nhường ngữ, rất lịch sự khi xin phép."},{"example":"午後に行く予定です。","pattern":"〜予定です","explanation":"Nói kế hoạch đã sắp xếp."}],"vocabulary":[{"jlpt":"N4","term":"欠席","example":"今日は欠席します。","meaning":"vắng mặt","reading":"けっせき"},{"jlpt":"N4","term":"熱","example":"熱があります。","meaning":"sốt","reading":"ねつ"},{"jlpt":"N4","term":"診断書","example":"診断書を出します。","meaning":"giấy khám","reading":"しんだんしょ"},{"jlpt":"N4","term":"課題","example":"課題を確認してください。","meaning":"bài tập lớn","reading":"かだい"}],"exampleDialogue":[{"text":"熱があるので、今日は休ませていただきたいです。","speaker":"learner","translation":"Em bị sốt nên hôm nay xin phép nghỉ ạ."},{"text":"分かりました。病院には行きましたか。","speaker":"ai","translation":"Cô hiểu rồi. Em đi bệnh viện chưa?"},{"text":"今日の課題はどうすればいいですか。","speaker":"learner","translation":"Bài tập hôm nay em làm thế nào ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-giao-vien'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-hoc-sinh'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi về bài tập', 'cpath-dly-15', 'Bạn hỏi cô giáo hạn nộp bài tập và xác nhận cách nộp bài.', 'N4', 'EASY', 6, 'Bạn muốn hỏi cô giáo về hạn nộp và cách nộp bài tập.', 'Trong lớp học', 'Buổi sáng', '{"goals":[{"code":"DEADLINE","type":"MISSION","title":"Hỏi hạn nộp","required":true,"conditions":[{"type":"KEYWORD","value":"締め切り|いつ|月曜日|まで"}],"description":"Hỏi hạn nộp bài tập.","displayOrder":1},{"code":"HOW","type":"MISSION","title":"Xác nhận cách nộp","required":true,"conditions":[{"type":"KEYWORD","value":"ノート|提出|箱|ばいい"}],"description":"Xác nhận cách nộp bài.","displayOrder":2},{"code":"THANKS","type":"MISSION","title":"Cảm ơn cô","required":true,"conditions":[{"type":"KEYWORD","value":"分かりました|ありがとうございます"}],"description":"Cảm ơn cô giáo.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi hạn nộp","next":"S2","prompt":"Cho biết hạn nộp bài tập.","allowedGoalCodes":["DEADLINE"],"suggestedReplies":["先生、宿題の締め切りはいつですか。"]},{"code":"S2","name":"Xác nhận cách nộp","next":"S3","prompt":"Hướng dẫn nơi nộp bài.","allowedGoalCodes":["HOW"],"suggestedReplies":["ノートに書いて提出すればいいですか。"]},{"code":"S3","name":"Cảm ơn","next":"END","prompt":"Đáp lại lời cảm ơn của học sinh.","allowedGoalCodes":["THANKS"],"suggestedReplies":["分かりました。ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nắm cách nộp bài","message":"はい、頑張ってください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"宿題の締め切りはいつですか。","pattern":"〜はいつですか","explanation":"Cách hỏi thời hạn / thời điểm."},{"example":"ノートに書いて提出すればいいですか。","pattern":"〜ばいいですか","explanation":"Xác nhận cách làm đúng."}],"vocabulary":[{"jlpt":"N4","term":"宿題","example":"宿題を出します。","meaning":"bài tập về nhà","reading":"しゅくだい"},{"jlpt":"N4","term":"締め切り","example":"締め切りは月曜日です。","meaning":"hạn chót","reading":"しめきり"},{"jlpt":"N4","term":"提出","example":"ノートを提出します。","meaning":"nộp","reading":"ていしゅつ"},{"jlpt":"N4","term":"教室","example":"教室の前の箱です。","meaning":"lớp học","reading":"きょうしつ"}],"exampleDialogue":[{"text":"宿題の締め切りはいつですか。","speaker":"learner","translation":"Hạn nộp bài tập là khi nào ạ?"},{"text":"来週の月曜日までです。","speaker":"ai","translation":"Đến thứ Hai tuần sau ạ."},{"text":"ノートに書いて提出すればいいですか。","speaker":"learner","translation":"Viết vào vở rồi nộp là được ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-thu-vien'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-muon-sach'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Mượn sách ở thư viện', 'cpath-dly-16', 'Bạn xin mượn sách, đưa thẻ mượn và hỏi nơi trả sách.', 'N4', 'EASY', 6, 'Bạn cần mượn một quyển sách và muốn nắm thủ tục mượn, trả.', 'Quầy thủ thư trong thư viện', 'Buổi chiều', '{"goals":[{"code":"BORROW","type":"MISSION","title":"Xin mượn sách","required":true,"conditions":[{"type":"KEYWORD","value":"借りたい|本|お願いします"}],"description":"Nói muốn mượn sách.","displayOrder":1},{"code":"CARD","type":"MISSION","title":"Đưa thẻ mượn sách","required":true,"conditions":[{"type":"KEYWORD","value":"はい|カード|ここにあります|お持ち"}],"description":"Đưa thẻ mượn sách.","displayOrder":2},{"code":"RETURN","type":"MISSION","title":"Hỏi nơi trả sách","required":true,"conditions":[{"type":"KEYWORD","value":"返却|どこ|カウンター"}],"description":"Hỏi nơi trả sách.","displayOrder":3}],"states":[{"code":"S1","name":"Xin mượn sách","next":"S2","prompt":"Hỏi khách có thẻ mượn sách không.","allowedGoalCodes":["BORROW"],"suggestedReplies":["すみません、この本を借りたいです。"]},{"code":"S2","name":"Đưa thẻ","next":"S3","prompt":"Cho biết hạn mượn là hai tuần.","allowedGoalCodes":["CARD"],"suggestedReplies":["はい、ここにあります。"]},{"code":"S3","name":"Hỏi nơi trả","next":"END","prompt":"Chỉ quầy trả sách.","allowedGoalCodes":["RETURN"],"suggestedReplies":["返却はどこでしますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã mượn được sách","message":"ありがとうございました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"この本を借りたいです。","pattern":"〜を借りたいです","explanation":"Bày tỏ nhu cầu mượn."},{"example":"返却はどこでしますか。","pattern":"〜はどこでしますか","explanation":"Hỏi địa điểm làm một việc."}],"vocabulary":[{"jlpt":"N4","term":"借りる","example":"本を借ります。","meaning":"mượn","reading":"かりる"},{"jlpt":"N4","term":"返却","example":"返却はカウンターです。","meaning":"trả lại (sách)","reading":"へんきゃく"},{"jlpt":"N4","term":"図書館","example":"図書館で借ります。","meaning":"thư viện","reading":"としょかん"},{"jlpt":"N4","term":"貸出カード","example":"貸出カードを持っています。","meaning":"thẻ mượn sách","reading":"かしだしカード"}],"exampleDialogue":[{"text":"この本を借りたいです。","speaker":"learner","translation":"Tôi muốn mượn quyển sách này ạ."},{"text":"貸出カードはお持ちですか。","speaker":"ai","translation":"Anh có thẻ mượn sách không ạ?"},{"text":"返却はどこでしますか。","speaker":"learner","translation":"Trả sách ở đâu ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ngan-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-ngan-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Làm thủ tục ngân hàng', 'cpath-dly-04', 'Bạn nói nhu cầu chuyển khoản, hỏi phí, so sánh ATM và nhờ hướng dẫn thao tác.', 'N3', 'MEDIUM', 7, 'Bạn đến ngân hàng chuyển khoản sang ngân hàng khác và muốn so sánh phí để chọn cách rẻ nhất.', 'Quầy giao dịch ngân hàng', 'Buổi sáng', '{"goals":[{"code":"WANT","type":"MISSION","title":"Nói muốn chuyển khoản","required":true,"conditions":[{"type":"KEYWORD","value":"振込|したい|他行|口座"}],"description":"Nói nhu cầu chuyển khoản.","displayOrder":1},{"code":"FEE","type":"MISSION","title":"Hỏi phí chuyển khoản","required":true,"conditions":[{"type":"KEYWORD","value":"手数料|いくら|窓口|ATM"}],"description":"Hỏi phí chuyển khoản.","displayOrder":2},{"code":"ATM","type":"MISSION","title":"Hỏi dùng máy ATM","required":true,"conditions":[{"type":"KEYWORD","value":"ATM|できますか|思ったより|違う"}],"description":"Hỏi có làm được ở ATM không.","displayOrder":3},{"code":"GUIDE","type":"MISSION","title":"Nhờ hướng dẫn thao tác","required":true,"conditions":[{"type":"KEYWORD","value":"通帳|キャッシュカード|教えていただけますか|操作"}],"description":"Nhờ nhân viên hướng dẫn thao tác.","displayOrder":4}],"states":[{"code":"S1","name":"Nói nhu cầu","next":"S2","prompt":"Hỏi có phải chuyển sang ngân hàng khác không.","allowedGoalCodes":["WANT"],"suggestedReplies":["振込をしたいのですが。"]},{"code":"S2","name":"Hỏi phí","next":"S3","prompt":"Báo phí ở quầy và ở ATM.","allowedGoalCodes":["FEE"],"suggestedReplies":["手数料はいくらかかりますか。"]},{"code":"S3","name":"Hỏi dùng ATM","next":"S4","prompt":"Cho biết ATM cần sổ và thẻ.","allowedGoalCodes":["ATM"],"suggestedReplies":["ATMでもできますか。"]},{"code":"S4","name":"Nhờ hướng dẫn","next":"END","prompt":"Đồng ý hướng dẫn thao tác.","allowedGoalCodes":["GUIDE"],"suggestedReplies":["操作を教えていただけますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã xong thủ tục","message":"ありがとうございました。ご案内いたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"思ったより違うんですね。","pattern":"〜より","explanation":"Cách so sánh \\"hơn so với ~\\"."},{"example":"操作を教えていただけますか。","pattern":"〜ていただけますか","explanation":"Cách nhờ vả rất lịch sự."}],"vocabulary":[{"jlpt":"N3","term":"振込","example":"振込をしたいです。","meaning":"chuyển khoản","reading":"ふりこみ"},{"jlpt":"N3","term":"手数料","example":"手数料はいくらですか。","meaning":"phí giao dịch","reading":"てすうりょう"},{"jlpt":"N3","term":"通帳","example":"通帳が必要です。","meaning":"sổ ngân hàng","reading":"つうちょう"},{"jlpt":"N3","term":"窓口","example":"窓口でお願いします。","meaning":"quầy giao dịch","reading":"まどぐち"}],"exampleDialogue":[{"text":"振込をしたいのですが。","speaker":"learner","translation":"Tôi muốn chuyển khoản ạ."},{"text":"他行宛てでしょうか。","speaker":"ai","translation":"Là chuyển sang ngân hàng khác phải không ạ?"},{"text":"手数料はいくらかかりますか。","speaker":"learner","translation":"Phí là bao nhiêu ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-chuyen-phat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-nhan-buu-kien'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nhận lại bưu kiện', 'cpath-dly-06', 'Bạn gọi tổng đài xin giao lại hàng, đọc mã vận đơn và chốt khung giờ giao.', 'N3', 'MEDIUM', 7, 'Bạn nhận được phiếu báo vắng nhà nên gọi tổng đài xin giao lại hàng.', 'Tổng đài chuyển phát (qua điện thoại)', 'Buổi tối', '{"goals":[{"code":"REQUEST","type":"MISSION","title":"Xin giao lại hàng","required":true,"conditions":[{"type":"KEYWORD","value":"不在票|再配達|お願いしたい|届け"}],"description":"Nói nhu cầu xin giao lại hàng.","displayOrder":1},{"code":"NUMBER","type":"MISSION","title":"Đọc mã vận đơn","required":true,"conditions":[{"type":"KEYWORD","value":"伝票番号|一二三四|五六七八"}],"description":"Đọc mã vận đơn.","displayOrder":2},{"code":"TIME","type":"MISSION","title":"Hỏi khung giờ giao","required":true,"conditions":[{"type":"KEYWORD","value":"何時から|七時|九時|夜間"}],"description":"Hỏi khung giờ giao hàng.","displayOrder":3},{"code":"OK","type":"MISSION","title":"Xác nhận và nhờ bấm chuông","required":true,"conditions":[{"type":"KEYWORD","value":"大丈夫|呼び鈴|鳴らしてください|その時間"}],"description":"Đồng ý khung giờ và nhờ bấm chuông.","displayOrder":4}],"states":[{"code":"S1","name":"Xin giao lại","next":"S2","prompt":"Xin mã vận đơn.","allowedGoalCodes":["REQUEST"],"suggestedReplies":["不在票が入っていたので、再配達をお願いしたいのですが。"]},{"code":"S2","name":"Đọc mã vận đơn","next":"S3","prompt":"Cho biết giao được vào tối nay.","allowedGoalCodes":["NUMBER"],"suggestedReplies":["はい、一二三四の五六七八です。"]},{"code":"S3","name":"Hỏi khung giờ","next":"S4","prompt":"Cho biết khung giờ từ bảy đến chín giờ.","allowedGoalCodes":["TIME"],"suggestedReplies":["何時から何時までですか。"]},{"code":"S4","name":"Xác nhận và nhờ bấm chuông","next":"END","prompt":"Xác nhận yêu cầu của khách.","allowedGoalCodes":["OK"],"suggestedReplies":["その時間で大丈夫です。呼び鈴を鳴らしてください。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã đặt lịch giao lại","message":"承知いたしました。よろしくお願いいたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"七時から九時の間でございます。","pattern":"〜の間","explanation":"Dùng cho khoảng thời gian có đầu có cuối."},{"example":"承知いたしました。","pattern":"承知いたしました","explanation":"Khiêm nhường ngữ, chuẩn khi tiếp khách."}],"vocabulary":[{"jlpt":"N3","term":"再配達","example":"再配達をお願いします。","meaning":"giao lại","reading":"さいはいたつ"},{"jlpt":"N3","term":"不在票","example":"不在票が入っていました。","meaning":"phiếu báo vắng","reading":"ふざいひょう"},{"jlpt":"N3","term":"伝票番号","example":"伝票番号を教えてください。","meaning":"mã vận đơn","reading":"でんぴょうばんごう"},{"jlpt":"N3","term":"宅配便","example":"宅配便で届きます。","meaning":"chuyển phát tận nhà","reading":"たくはいびん"}],"exampleDialogue":[{"text":"再配達をお願いしたいのですが。","speaker":"learner","translation":"Tôi muốn xin giao lại ạ."},{"text":"伝票番号をお願いいたします。","speaker":"ai","translation":"Xin cho tôi mã vận đơn ạ."},{"text":"何時から何時までですか。","speaker":"learner","translation":"Từ mấy giờ đến mấy giờ ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-buu-dien'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-gui-buu-pham'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Gửi bưu phẩm quốc tế', 'cpath-dly-12', 'Bạn gửi bưu phẩm quốc tế, chọn đường hàng không và khai tờ khai hải quan.', 'N3', 'MEDIUM', 7, 'Bạn muốn gửi một bưu phẩm quần áo về Việt Nam và hỏi cách gửi nhanh, an toàn.', 'Quầy giao dịch bưu điện', 'Buổi chiều', '{"goals":[{"code":"SEND","type":"MISSION","title":"Nói muốn gửi bưu phẩm","required":true,"conditions":[{"type":"KEYWORD","value":"小包|ベトナム|送りたい|国際"}],"description":"Nói muốn gửi bưu phẩm về Việt Nam.","displayOrder":1},{"code":"CHOOSE","type":"MISSION","title":"Chọn cách gửi và hỏi thời gian","required":true,"conditions":[{"type":"KEYWORD","value":"航空便|船便|何日|一週間"}],"description":"Chọn đường gửi và hỏi thời gian.","displayOrder":2},{"code":"DECLARE","type":"MISSION","title":"Khai nội dung và hỏi tờ khai","required":true,"conditions":[{"type":"KEYWORD","value":"中身|服|税関申告書|要りますか"}],"description":"Khai nội dung và hỏi có cần tờ khai hải quan không.","displayOrder":3}],"states":[{"code":"S1","name":"Nói muốn gửi","next":"S2","prompt":"Đưa ra lựa chọn đường biển hay đường hàng không.","allowedGoalCodes":["SEND"],"suggestedReplies":["この小包をベトナムに送りたいです。"]},{"code":"S2","name":"Chọn cách gửi","next":"S3","prompt":"Cho biết thời gian vận chuyển.","allowedGoalCodes":["CHOOSE"],"suggestedReplies":["航空便でお願いします。何日かかりますか。"]},{"code":"S3","name":"Khai nội dung","next":"END","prompt":"Yêu cầu ghi địa chỉ người nhận vào tờ khai.","allowedGoalCodes":["DECLARE"],"suggestedReplies":["中身は服です。税関申告書は要りますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã gửi bưu phẩm","message":"ありがとうございました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"船便と航空便がありますが、どちらにしますか。","pattern":"〜がありますが、どちらにしますか","explanation":"Đưa ra lựa chọn cho khách."},{"example":"税関申告書は要りますか。","pattern":"〜は要りますか","explanation":"Hỏi về giấy tờ/vật cần thiết."}],"vocabulary":[{"jlpt":"N3","term":"小包","example":"小包を送ります。","meaning":"bưu kiện","reading":"こづつみ"},{"jlpt":"N3","term":"国際郵便","example":"国際郵便で送ります。","meaning":"bưu phẩm quốc tế","reading":"こくさいゆうびん"},{"jlpt":"N3","term":"航空便","example":"航空便でお願いします。","meaning":"đường hàng không","reading":"こうくうびん"},{"jlpt":"N3","term":"宛先","example":"宛先を書いてください。","meaning":"địa chỉ người nhận","reading":"あてさき"}],"exampleDialogue":[{"text":"この小包をベトナムに送りたいです。","speaker":"learner","translation":"Tôi muốn gửi bưu kiện này về Việt Nam ạ."},{"text":"船便と航空便がありますが、どちらにしますか。","speaker":"ai","translation":"Có gửi đường biển và đường hàng không, anh chọn loại nào ạ?"},{"text":"税関申告書は要りますか。","speaker":"learner","translation":"Có cần tờ khai hải quan không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-bac-si'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-benh-nhan'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Khám bệnh', 'cpath-dly-05', 'Bạn kể triệu chứng ho, báo nhiệt độ, xin thuốc và hứa tránh lái xe.', 'N3', 'MEDIUM', 7, 'Bạn bị ho mấy ngày không khỏi nên đến phòng khám để được kê thuốc.', 'Phòng khám bác sĩ', 'Buổi sáng', '{"goals":[{"code":"SYMPTOM","type":"MISSION","title":"Kể triệu chứng","required":true,"conditions":[{"type":"KEYWORD","value":"咳|止まらない|眠れない|三日|症状"}],"description":"Kể triệu chứng ho kéo dài.","displayOrder":1},{"code":"TEMP","type":"MISSION","title":"Báo nhiệt độ","required":true,"conditions":[{"type":"KEYWORD","value":"熱|測り|三十七度五分|朝"}],"description":"Báo nhiệt độ đã đo.","displayOrder":2},{"code":"MEDICINE","type":"MISSION","title":"Xin thuốc","required":true,"conditions":[{"type":"KEYWORD","value":"薬|もらえますか|治したい|仕事"}],"description":"Xin thuốc để mau khỏi.","displayOrder":3},{"code":"CARE","type":"MISSION","title":"Hứa tránh lái xe","required":true,"conditions":[{"type":"KEYWORD","value":"運転|避けます|眠くなる|分かりました"}],"description":"Hứa tránh lái xe khi uống thuốc.","displayOrder":4}],"states":[{"code":"S1","name":"Kể triệu chứng","next":"S2","prompt":"Hỏi bệnh nhân đã đo nhiệt độ chưa.","allowedGoalCodes":["SYMPTOM"],"suggestedReplies":["三日前から咳が止まらなくて、夜眠れないんです。"]},{"code":"S2","name":"Báo nhiệt độ","next":"S3","prompt":"Xem họng và nhận xét họng hơi đỏ.","allowedGoalCodes":["TEMP"],"suggestedReplies":["朝は三十七度五分でした。"]},{"code":"S3","name":"Xin thuốc","next":"S4","prompt":"Kê thuốc ho và dặn thuốc có thành phần gây buồn ngủ.","allowedGoalCodes":["MEDICINE"],"suggestedReplies":["薬をもらえますか。仕事があるので早く治したいです。"]},{"code":"S4","name":"Hứa tránh lái xe","next":"END","prompt":"Dặn dò và chúc bệnh nhân mau khỏi.","allowedGoalCodes":["CARE"],"suggestedReplies":["分かりました。運転は避けます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã khám xong","message":"お大事にしてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"咳が止まらなくて、夜眠れないんです。","pattern":"〜が止まらない","explanation":"Mô tả triệu chứng kéo dài không dứt."},{"example":"咳止めを五日分出します。","pattern":"〜分","explanation":"Chỉ phần dùng cho số ngày."}],"vocabulary":[{"jlpt":"N3","term":"咳","example":"咳が止まりません。","meaning":"ho","reading":"せき"},{"jlpt":"N3","term":"熱","example":"熱を測りました。","meaning":"sốt","reading":"ねつ"},{"jlpt":"N3","term":"薬","example":"薬をください。","meaning":"thuốc","reading":"くすり"},{"jlpt":"N3","term":"症状","example":"症状を話してください。","meaning":"triệu chứng","reading":"しょうじょう"}],"exampleDialogue":[{"text":"今日はどうされましたか。","speaker":"ai","translation":"Hôm nay chị thấy sao?"},{"text":"咳が止まらなくて、夜眠れないんです。","speaker":"learner","translation":"Tôi ho không dứt, đêm không ngủ được ạ."},{"text":"運転は避けます。","speaker":"learner","translation":"Tôi sẽ tránh lái xe."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-bac-si'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-benh-nhan'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Khám bệnh (đau đầu)', 'cpath-dly-13', 'Bạn kể triệu chứng đau đầu, báo sốt nhẹ và tình trạng họng, ho cho bác sĩ.', 'N3', 'MEDIUM', 7, 'Bạn bị đau đầu từ hôm qua nên đến phòng khám kể triệu chứng cho bác sĩ.', 'Phòng khám bác sĩ', 'Buổi sáng', '{"goals":[{"code":"SYMPTOM","type":"MISSION","title":"Kể triệu chứng đau đầu","required":true,"conditions":[{"type":"KEYWORD","value":"頭|痛い|昨日から|おはよう"}],"description":"Kể triệu chứng đau đầu từ hôm qua.","displayOrder":1},{"code":"FEVER","type":"MISSION","title":"Báo sốt nhẹ","required":true,"conditions":[{"type":"KEYWORD","value":"熱|少し|三十七度五分"}],"description":"Báo có sốt nhẹ.","displayOrder":2},{"code":"THROAT","type":"MISSION","title":"Kể tình trạng họng và ho","required":true,"conditions":[{"type":"KEYWORD","value":"のど|咳|大丈夫|出ます"}],"description":"Kể họng ổn nhưng hơi ho.","displayOrder":3},{"code":"THANKS","type":"MISSION","title":"Cảm ơn bác sĩ","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございます|分かりました"}],"description":"Cảm ơn bác sĩ.","displayOrder":4}],"states":[{"code":"S1","name":"Kể triệu chứng","next":"S2","prompt":"Hỏi bệnh nhân có sốt không.","allowedGoalCodes":["SYMPTOM"],"suggestedReplies":["おはようございます。昨日から頭が痛いです。"]},{"code":"S2","name":"Báo sốt nhẹ","next":"S3","prompt":"Hỏi thêm về họng và ho.","allowedGoalCodes":["FEVER"],"suggestedReplies":["少しあります。三十七度五分です。"]},{"code":"S3","name":"Kể họng và ho","next":"S4","prompt":"Kết luận bị cảm và kê thuốc, dặn nghỉ ngơi.","allowedGoalCodes":["THROAT"],"suggestedReplies":["のどは大丈夫ですが、咳が少し出ます。"]},{"code":"S4","name":"Cảm ơn","next":"END","prompt":"Đáp lại lời cảm ơn của bệnh nhân.","allowedGoalCodes":["THANKS"],"suggestedReplies":["ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã khám xong","message":"お大事にしてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"昨日から頭が痛いです。","pattern":"〜から〜が痛いです","explanation":"Kể triệu chứng đau bắt đầu từ khi nào."},{"example":"のどや咳はどうですか。","pattern":"〜はどうですか","explanation":"Hỏi thăm tình trạng."}],"vocabulary":[{"jlpt":"N3","term":"頭痛","example":"頭痛がします。","meaning":"đau đầu","reading":"ずつう"},{"jlpt":"N3","term":"のど","example":"のどが痛いです。","meaning":"họng","reading":"のど"},{"jlpt":"N3","term":"風邪","example":"風邪ですね。","meaning":"cảm","reading":"かぜ"},{"jlpt":"N3","term":"診察","example":"診察を受ける。","meaning":"khám bệnh","reading":"しんさつ"}],"exampleDialogue":[{"text":"昨日から頭が痛いです。","speaker":"learner","translation":"Từ hôm qua tôi bị đau đầu ạ."},{"text":"熱はありますか。","speaker":"ai","translation":"Anh có bị sốt không ạ?"},{"text":"のどは大丈夫ですが、咳が少し出ます。","speaker":"learner","translation":"Họng thì không sao nhưng hơi ho ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-nha-thuoc'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-mua-thuoc'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Mua thuốc ở hiệu thuốc', 'cpath-dly-14', 'Bạn đưa đơn thuốc, đưa thẻ bảo hiểm và hỏi số ngày uống thuốc.', 'N3', 'MEDIUM', 7, 'Bạn cầm đơn thuốc ra hiệu thuốc để lấy thuốc và hỏi cách uống.', 'Quầy thuốc trong hiệu thuốc', 'Buổi chiều', '{"goals":[{"code":"RX","type":"MISSION","title":"Đưa đơn thuốc","required":true,"conditions":[{"type":"KEYWORD","value":"処方箋|薬|お願いします"}],"description":"Đưa đơn thuốc để lấy thuốc.","displayOrder":1},{"code":"INSURANCE","type":"MISSION","title":"Đưa thẻ bảo hiểm","required":true,"conditions":[{"type":"KEYWORD","value":"保険証|はい|これです|お持ち"}],"description":"Đưa thẻ bảo hiểm.","displayOrder":2},{"code":"DOSE","type":"MISSION","title":"Hỏi số ngày uống","required":true,"conditions":[{"type":"KEYWORD","value":"何日分|一日三回|食後|三日分"}],"description":"Hỏi thuốc uống trong mấy ngày.","displayOrder":3}],"states":[{"code":"S1","name":"Đưa đơn thuốc","next":"S2","prompt":"Hỏi khách có mang thẻ bảo hiểm không.","allowedGoalCodes":["RX"],"suggestedReplies":["この処方箋の薬をお願いします。"]},{"code":"S2","name":"Đưa thẻ bảo hiểm","next":"S3","prompt":"Hướng dẫn cách uống thuốc.","allowedGoalCodes":["INSURANCE"],"suggestedReplies":["はい、これです。"]},{"code":"S3","name":"Hỏi số ngày uống","next":"END","prompt":"Cho biết thuốc dùng trong ba ngày.","allowedGoalCodes":["DOSE"],"suggestedReplies":["何日分ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nhận thuốc","message":"お大事にしてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"この処方箋の薬をお願いします。","pattern":"〜の薬をお願いします","explanation":"Yêu cầu lấy thuốc theo đơn."},{"example":"保険証はお持ちですか。","pattern":"〜をお持ちですか","explanation":"Nhân viên hỏi khách có mang theo gì."}],"vocabulary":[{"jlpt":"N3","term":"処方箋","example":"処方箋を出します。","meaning":"đơn thuốc","reading":"しょほうせん"},{"jlpt":"N3","term":"保険証","example":"保険証を持っています。","meaning":"thẻ bảo hiểm y tế","reading":"ほけんしょう"},{"jlpt":"N3","term":"薬局","example":"薬局で薬をもらいます。","meaning":"nhà thuốc","reading":"やっきょく"},{"jlpt":"N3","term":"食後","example":"食後に飲みます。","meaning":"sau bữa ăn","reading":"しょくご"}],"exampleDialogue":[{"text":"この処方箋の薬をお願いします。","speaker":"learner","translation":"Cho tôi lấy thuốc theo đơn này ạ."},{"text":"保険証はお持ちですか。","speaker":"ai","translation":"Anh có mang thẻ bảo hiểm không ạ?"},{"text":"この薬は一日三回、食後に飲んでください。","speaker":"ai","translation":"Thuốc này uống ba lần một ngày, sau bữa ăn ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-hang-xom'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-moi-den'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chuyện hàng xóm', 'cpath-dly-08', 'Bạn xin lỗi hàng xóm, tặng quà nhỏ và hỏi về nếp sống, tổ dân phố.', 'N3', 'MEDIUM', 7, 'Bạn vừa chuyển đến và sang chào, xin lỗi hàng xóm vì tiếng ồn hôm qua.', 'Trước nhà hàng xóm', 'Buổi chiều', '{"goals":[{"code":"APOLOGY","type":"MISSION","title":"Xin lỗi vì tiếng ồn","required":true,"conditions":[{"type":"KEYWORD","value":"引っ越し|騒がしく|すみません|お互い様"}],"description":"Xin lỗi hàng xóm vì tiếng ồn khi chuyển nhà.","displayOrder":1},{"code":"GIFT","type":"MISSION","title":"Tặng quà nhỏ","required":true,"conditions":[{"type":"KEYWORD","value":"これ|少しですが|どうぞ|気を使う"}],"description":"Tặng món quà nhỏ.","displayOrder":2},{"code":"ASK","type":"MISSION","title":"Nhờ chỉ thêm chuyện đổ rác","required":true,"conditions":[{"type":"KEYWORD","value":"ごみ出し|教えてください|また"}],"description":"Nhờ hàng xóm chỉ thêm chuyện đổ rác.","displayOrder":3},{"code":"JOIN","type":"MISSION","title":"Hỏi về tham gia tổ dân phố","required":true,"conditions":[{"type":"KEYWORD","value":"参加|町内会|ほうがいい|集まり"}],"description":"Hỏi có nên tham gia tổ dân phố không.","displayOrder":4}],"states":[{"code":"S1","name":"Xin lỗi vì tiếng ồn","next":"S2","prompt":"Xua tay cho qua chuyện, nói ai cũng có lúc thế.","allowedGoalCodes":["APOLOGY"],"suggestedReplies":["昨日は引っ越しで騒がしくて、すみませんでした。"]},{"code":"S2","name":"Tặng quà nhỏ","next":"S3","prompt":"Vui vẻ nhận quà và cảm ơn.","allowedGoalCodes":["GIFT"],"suggestedReplies":["これ、少しですがどうぞ。"]},{"code":"S3","name":"Nhờ chỉ chuyện đổ rác","next":"S4","prompt":"Nhận lời và nhắc tổ dân phố họp mỗi tháng một lần.","allowedGoalCodes":["ASK"],"suggestedReplies":["ごみ出しのことなど、また教えてください。"]},{"code":"S4","name":"Hỏi tham gia tổ dân phố","next":"END","prompt":"Khuyên nên đến một lần để mọi người nhớ mặt.","allowedGoalCodes":["JOIN"],"suggestedReplies":["参加したほうがいいでしょうか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã chào hỏi hàng xóm","message":"また何かあったら声をかけてね。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"お互い様ですよ。","pattern":"お互い様","explanation":"Cụm xã giao dùng khi được xin lỗi hoặc cảm ơn."},{"example":"気を使わせてしまって。","pattern":"気を使う","explanation":"Nói về sự quan tâm ý tứ với người khác."}],"vocabulary":[{"jlpt":"N3","term":"引っ越し","example":"引っ越しで騒がしかったです。","meaning":"chuyển nhà","reading":"ひっこし"},{"jlpt":"N3","term":"近所","example":"近所の人に挨拶します。","meaning":"hàng xóm","reading":"きんじょ"},{"jlpt":"N3","term":"挨拶","example":"挨拶に行きます。","meaning":"chào hỏi","reading":"あいさつ"},{"jlpt":"N3","term":"町内会","example":"町内会に参加します。","meaning":"tổ dân phố","reading":"ちょうないかい"}],"exampleDialogue":[{"text":"昨日は引っ越しで騒がしくて、すみませんでした。","speaker":"learner","translation":"Hôm qua chuyển nhà ồn ào, cháu xin lỗi ạ."},{"text":"いえいえ、お互い様ですよ。","speaker":"ai","translation":"Không sao đâu, ai cũng có lúc thế mà."},{"text":"参加したほうがいいでしょうか。","speaker":"learner","translation":"Cháu có nên tham gia không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-ban-than'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-ban-be'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Rủ đi xem phim', 'cpath-dly-17', 'Bạn hỏi bạn có rảnh không, rủ đi xem phim và chốt giờ, địa điểm.', 'N3', 'MEDIUM', 7, 'Bạn muốn rủ bạn thân đi xem phim vào cuối tuần.', 'Nhắn tin với bạn', 'Buổi tối', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi bạn có rảnh không","required":true,"conditions":[{"type":"KEYWORD","value":"予定|週末|ある|どうした"}],"description":"Hỏi bạn cuối tuần có bận không.","displayOrder":1},{"code":"INVITE","type":"MISSION","title":"Rủ đi xem phim","required":true,"conditions":[{"type":"KEYWORD","value":"映画|行かない|一緒に|見に"}],"description":"Rủ bạn đi xem phim.","displayOrder":2},{"code":"TIME","type":"MISSION","title":"Chốt giờ hẹn","required":true,"conditions":[{"type":"KEYWORD","value":"三時|土曜日|どう|待ち合わせ|駅"}],"description":"Đề xuất giờ và địa điểm gặp.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi bạn có rảnh","next":"S2","prompt":"Đáp là không có kế hoạch đặc biệt.","allowedGoalCodes":["ASK"],"suggestedReplies":["週末、何か予定がある？"]},{"code":"S2","name":"Rủ đi xem phim","next":"S3","prompt":"Đồng ý và hỏi giờ.","allowedGoalCodes":["INVITE"],"suggestedReplies":["一緒に映画を見に行かない？"]},{"code":"S3","name":"Chốt giờ và địa điểm","next":"END","prompt":"Đồng ý giờ và hẹn gặp ở ga.","allowedGoalCodes":["TIME"],"suggestedReplies":["土曜日の三時からどう？"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã hẹn xong","message":"うん、また土曜日にね。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"一緒に映画を見に行かない？","pattern":"〜に行かない？","explanation":"Cách rủ bạn bè thân mật."},{"example":"土曜日の三時からどう？","pattern":"〜からどう？","explanation":"Đề xuất thời gian với bạn."}],"vocabulary":[{"jlpt":"N3","term":"映画","example":"映画を見ます。","meaning":"phim","reading":"えいが"},{"jlpt":"N3","term":"週末","example":"週末に会いましょう。","meaning":"cuối tuần","reading":"しゅうまつ"},{"jlpt":"N3","term":"待ち合わせ","example":"駅で待ち合わせよう。","meaning":"hẹn gặp","reading":"まちあわせ"},{"jlpt":"N3","term":"誘う","example":"友達を誘います。","meaning":"rủ","reading":"さそう"}],"exampleDialogue":[{"text":"週末、何か予定がある？","speaker":"learner","translation":"Cuối tuần cậu có kế hoạch gì không?"},{"text":"特にないよ。どうしたの？","speaker":"ai","translation":"Không có gì đặc biệt. Sao vậy?"},{"text":"一緒に映画を見に行かない？","speaker":"learner","translation":"Đi xem phim cùng mình không?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nguoi-quen'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-moi'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Rủ đi uống cà phê', 'cpath-dly-18', 'Bạn hỏi người quen có rảnh không, mời đi uống trà và chốt giờ, địa điểm.', 'N3', 'MEDIUM', 7, 'Bạn muốn mời một người quen đi uống trà sau giờ làm để trò chuyện.', 'Nơi làm việc', 'Buổi tối', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi có thời gian không","required":true,"conditions":[{"type":"KEYWORD","value":"仕事の後|時間|ありますか|大丈夫"}],"description":"Hỏi người quen có rảnh sau giờ làm không.","displayOrder":1},{"code":"INVITE","type":"MISSION","title":"Mời đi uống trà","required":true,"conditions":[{"type":"KEYWORD","value":"喫茶店|お茶しませんか|近く|お茶"}],"description":"Mời đi uống trà ở quán gần đây.","displayOrder":2},{"code":"MEET","type":"MISSION","title":"Chốt giờ và địa điểm","required":true,"conditions":[{"type":"KEYWORD","value":"六時|駅前|どうですか|連絡|楽しみ"}],"description":"Chốt giờ và địa điểm gặp.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi có thời gian","next":"S2","prompt":"Đáp là rảnh.","allowedGoalCodes":["ASK"],"suggestedReplies":["今日は仕事の後、時間がありますか。"]},{"code":"S2","name":"Mời đi uống trà","next":"S3","prompt":"Đồng ý và hỏi giờ gặp.","allowedGoalCodes":["INVITE"],"suggestedReplies":["近くの喫茶店でお茶しませんか。"]},{"code":"S3","name":"Chốt giờ và địa điểm","next":"END","prompt":"Đồng ý giờ và nói sẽ liên lạc lại.","allowedGoalCodes":["MEET"],"suggestedReplies":["六時に駅前でどうですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã hẹn xong","message":"こちらこそ、楽しみにしています。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"近くの喫茶店でお茶しませんか。","pattern":"〜ませんか","explanation":"Cách mời lịch sự."},{"example":"何時ごろにしますか。","pattern":"〜ごろにしますか","explanation":"Hỏi giờ hẹn."}],"vocabulary":[{"jlpt":"N3","term":"喫茶店","example":"喫茶店で会いましょう。","meaning":"quán cà phê","reading":"きっさてん"},{"jlpt":"N3","term":"連絡","example":"後で連絡します。","meaning":"liên lạc","reading":"れんらく"},{"jlpt":"N3","term":"楽しみ","example":"楽しみにしています。","meaning":"mong chờ","reading":"たのしみ"},{"jlpt":"N3","term":"約束","example":"約束をしました。","meaning":"hẹn, lời hứa","reading":"やくそく"}],"exampleDialogue":[{"text":"今日は仕事の後、時間がありますか。","speaker":"learner","translation":"Hôm nay sau giờ làm, anh có thời gian không ạ?"},{"text":"はい、大丈夫ですよ。","speaker":"ai","translation":"Vâng, tôi rảnh ạ."},{"text":"六時に駅前でどうですか。","speaker":"learner","translation":"Sáu giờ ở trước ga được không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-buu-dien'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-hoi-thong-tin'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi giờ mở cửa', 'cpath-dly-19', 'Bạn hỏi nhân viên bưu điện về giờ mở cửa, giờ đóng cửa và giờ hiện tại.', 'N5', 'EASY', 6, 'Bạn đến bưu điện hơi sớm nên hỏi giờ mở cửa để chờ.', 'Trước cửa bưu điện', 'Buổi sáng', '{"goals":[{"code":"OPEN","type":"MISSION","title":"Hỏi giờ mở cửa","required":true,"conditions":[{"type":"KEYWORD","value":"何時|開きますか|郵便局|九時"}],"description":"Hỏi bưu điện mở cửa lúc mấy giờ.","displayOrder":1},{"code":"CLOSE","type":"MISSION","title":"Hỏi giờ đóng cửa","required":true,"conditions":[{"type":"KEYWORD","value":"閉まりますか|五時|まで"}],"description":"Hỏi bưu điện đóng cửa lúc mấy giờ.","displayOrder":2},{"code":"NOW","type":"MISSION","title":"Hỏi giờ hiện tại","required":true,"conditions":[{"type":"KEYWORD","value":"今|何時|八時五十分|十分"}],"description":"Hỏi giờ hiện tại để ước lượng thời gian chờ.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi giờ mở cửa","next":"S2","prompt":"Cho biết mở cửa từ chín giờ.","allowedGoalCodes":["OPEN"],"suggestedReplies":["郵便局は何時に開きますか。"]},{"code":"S2","name":"Hỏi giờ đóng cửa","next":"S3","prompt":"Cho biết đóng cửa lúc năm giờ.","allowedGoalCodes":["CLOSE"],"suggestedReplies":["何時に閉まりますか。"]},{"code":"S3","name":"Hỏi giờ hiện tại","next":"END","prompt":"Cho biết giờ hiện tại.","allowedGoalCodes":["NOW"],"suggestedReplies":["今、何時ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã biết giờ giấc","message":"ありがとうございました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"郵便局は何時に開きますか。","pattern":"〜は何時に開きますか","explanation":"Hỏi giờ mở cửa."},{"example":"九時からです。五時までです。","pattern":"〜からです / 〜までです","explanation":"Nói khoảng thời gian."}],"vocabulary":[{"jlpt":"N5","term":"開く","example":"店が開きます。","meaning":"mở cửa","reading":"あく"},{"jlpt":"N5","term":"閉まる","example":"店が閉まります。","meaning":"đóng cửa","reading":"しまる"},{"jlpt":"N5","term":"何時","example":"今、何時ですか。","meaning":"mấy giờ","reading":"なんじ"},{"jlpt":"N5","term":"郵便局","example":"郵便局に行きます。","meaning":"bưu điện","reading":"ゆうびんきょく"}],"exampleDialogue":[{"text":"郵便局は何時に開きますか。","speaker":"learner","translation":"Bưu điện mở cửa lúc mấy giờ ạ?"},{"text":"九時からです。","speaker":"ai","translation":"Từ chín giờ ạ."},{"text":"今、何時ですか。","speaker":"learner","translation":"Bây giờ là mấy giờ ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-ban-than'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-ban-be'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Giờ hẹn gặp', 'cpath-dly-20', 'Bạn hỏi giờ gặp, đề xuất giờ và chốt địa điểm gặp với bạn.', 'N5', 'EASY', 6, 'Bạn nhắn tin với bạn để hẹn giờ và địa điểm đi chơi ngày mai.', 'Nhắn tin với bạn', 'Buổi tối', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi giờ gặp","required":true,"conditions":[{"type":"KEYWORD","value":"何時|会う|明日|どう"}],"description":"Hỏi bạn mai gặp lúc mấy giờ.","displayOrder":1},{"code":"SUGGEST","type":"MISSION","title":"Đề xuất giờ","required":true,"conditions":[{"type":"KEYWORD","value":"十一時|早い|十時|どう"}],"description":"Đề xuất giờ phù hợp.","displayOrder":2},{"code":"PLACE","type":"MISSION","title":"Chốt địa điểm","required":true,"conditions":[{"type":"KEYWORD","value":"改札前|どこ|待ち合わせ|また明日"}],"description":"Chốt địa điểm gặp.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi giờ gặp","next":"S2","prompt":"Đề xuất mười giờ.","allowedGoalCodes":["ASK"],"suggestedReplies":["明日、何時に会う？"]},{"code":"S2","name":"Đề xuất giờ","next":"S3","prompt":"Đồng ý và hỏi địa điểm.","allowedGoalCodes":["SUGGEST"],"suggestedReplies":["ちょっと早いな。十一時はどう？"]},{"code":"S3","name":"Chốt địa điểm","next":"END","prompt":"Xác nhận giờ và địa điểm trước cổng soát vé.","allowedGoalCodes":["PLACE"],"suggestedReplies":["駅の改札前はどう？"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã hẹn xong","message":"うん、また明日。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"十一時はどう？","pattern":"〜はどう？","explanation":"Cách đề xuất với bạn bè."},{"example":"明日、何時に会う？","pattern":"〜に会う？","explanation":"Hỏi giờ gặp bạn."}],"vocabulary":[{"jlpt":"N5","term":"明日","example":"明日、会おう。","meaning":"ngày mai","reading":"あした"},{"jlpt":"N5","term":"何時","example":"何時に会う？","meaning":"mấy giờ","reading":"なんじ"},{"jlpt":"N5","term":"改札","example":"改札前で待ちます。","meaning":"cổng soát vé","reading":"かいさつ"},{"jlpt":"N5","term":"待ち合わせ","example":"待ち合わせる。","meaning":"hẹn gặp","reading":"まちあわせ"}],"exampleDialogue":[{"text":"明日、何時に会う？","speaker":"learner","translation":"Ngày mai, mấy giờ mình gặp nhau?"},{"text":"十時はどう？","speaker":"ai","translation":"Mười giờ được không?"},{"text":"駅の改札前はどう？","speaker":"learner","translation":"Trước cổng soát vé ở ga được không?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nguoi-qua-duong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-hoi-thong-tin'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi thời gian đi lại', 'cpath-dly-21', 'Bạn hỏi thời gian đi bộ ra ga, hỏi xe buýt và tần suất chuyến.', 'N5', 'EASY', 6, 'Bạn muốn ra ga và hỏi người qua đường về thời gian đi bộ cũng như xe buýt.', 'Trên đường gần ga', 'Buổi sáng', '{"goals":[{"code":"WALK","type":"MISSION","title":"Hỏi thời gian đi bộ","required":true,"conditions":[{"type":"KEYWORD","value":"歩いて|どのくらい|かかりますか|駅|十五分"}],"description":"Hỏi đi bộ ra ga mất bao lâu.","displayOrder":1},{"code":"BUS","type":"MISSION","title":"Hỏi xe buýt","required":true,"conditions":[{"type":"KEYWORD","value":"バス|ありますか|五分|着きます"}],"description":"Hỏi có xe buýt không.","displayOrder":2},{"code":"FREQ","type":"MISSION","title":"Hỏi tần suất xe buýt","required":true,"conditions":[{"type":"KEYWORD","value":"何分おき|十分|来ますか"}],"description":"Hỏi xe buýt bao lâu một chuyến.","displayOrder":3}],"states":[{"code":"S1","name":"Hỏi thời gian đi bộ","next":"S2","prompt":"Cho biết đi bộ mất khoảng mười lăm phút.","allowedGoalCodes":["WALK"],"suggestedReplies":["駅まで歩いてどのくらいかかりますか。"]},{"code":"S2","name":"Hỏi xe buýt","next":"S3","prompt":"Cho biết có xe buýt, năm phút tới nơi.","allowedGoalCodes":["BUS"],"suggestedReplies":["バスはありますか。"]},{"code":"S3","name":"Hỏi tần suất","next":"END","prompt":"Cho biết mười phút một chuyến.","allowedGoalCodes":["FREQ"],"suggestedReplies":["バスは何分おきに来ますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã nắm đường đi","message":"気をつけて行ってください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"駅まで歩いてどのくらいかかりますか。","pattern":"〜までどのくらいかかりますか","explanation":"Hỏi thời gian di chuyển."},{"example":"バスは何分おきに来ますか。","pattern":"〜おきに来ますか","explanation":"Hỏi tần suất phương tiện."}],"vocabulary":[{"jlpt":"N5","term":"歩いて","example":"歩いて行きます。","meaning":"đi bộ","reading":"あるいて"},{"jlpt":"N5","term":"バス","example":"バスで行きます。","meaning":"xe buýt","reading":"バス"},{"jlpt":"N5","term":"かかる","example":"五分かかります。","meaning":"mất (thời gian)","reading":"かかる"},{"jlpt":"N5","term":"駅","example":"駅まで歩きます。","meaning":"nhà ga","reading":"えき"}],"exampleDialogue":[{"text":"駅まで歩いてどのくらいかかりますか。","speaker":"learner","translation":"Đi bộ ra ga mất khoảng bao lâu ạ?"},{"text":"十五分ぐらいです。","speaker":"ai","translation":"Khoảng mười lăm phút ạ."},{"text":"バスは何分おきに来ますか。","speaker":"learner","translation":"Xe buýt bao nhiêu phút một chuyến ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'daily-life'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nguoi-doi-thoai'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nguoi-hoc'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Một ngày sinh hoạt ở Nhật', 'cpath-test-daily-life', 'Một cuộc gọi tổng hợp đi qua các chủ đề nhà cửa, đi chợ, ngân hàng, sức khoẻ, quan hệ xã hội và thời gian.', 'N3', 'HARD', 14, 'Bạn trải qua một ngày sinh hoạt bận rộn ở Nhật: thuê phòng, đi siêu thị, làm thủ tục ngân hàng, khám bệnh, rủ bạn đi chơi và hỏi giờ mở cửa bưu điện.', 'Nhiều địa điểm trong ngày', 'Cả ngày', '{"goals":[{"code":"RENT","type":"MISSION","title":"Hỏi chi phí thuê phòng","required":true,"conditions":[{"type":"KEYWORD","value":"初期費用|家賃|敷金|いくら|礼金"}],"description":"Hỏi tổng chi phí thuê phòng.","displayOrder":1},{"code":"MARKET","type":"MISSION","title":"Hỏi hạn dùng ở siêu thị","required":true,"conditions":[{"type":"KEYWORD","value":"消費期限|半額|いつまで|値引き"}],"description":"Hỏi hạn dùng và giờ giảm giá ở siêu thị.","displayOrder":2},{"code":"BANK","type":"MISSION","title":"Chuyển khoản và hỏi phí","required":true,"conditions":[{"type":"KEYWORD","value":"振込|手数料|ATM|いくら"}],"description":"Chuyển khoản và hỏi phí ở ngân hàng.","displayOrder":3},{"code":"HEALTH","type":"MISSION","title":"Kể triệu chứng bệnh","required":true,"conditions":[{"type":"KEYWORD","value":"咳|熱|頭|薬|痛い"}],"description":"Kể triệu chứng và xin thuốc ở phòng khám.","displayOrder":4},{"code":"SOCIAL","type":"MISSION","title":"Rủ bạn đi chơi","required":true,"conditions":[{"type":"KEYWORD","value":"映画|喫茶店|行かない|ませんか|一緒に"}],"description":"Rủ bạn hoặc người quen đi chơi.","displayOrder":5},{"code":"TIME","type":"MISSION","title":"Hỏi giờ mở cửa","required":true,"conditions":[{"type":"KEYWORD","value":"何時|開きますか|閉まりますか|まで"}],"description":"Hỏi giờ mở cửa một địa điểm.","displayOrder":6}],"states":[{"code":"S1","name":"Thuê phòng","next":"S2","prompt":"Đóng vai nhân viên bất động sản, báo chi phí thuê phòng.","allowedGoalCodes":["RENT"],"suggestedReplies":["初期費用は全部でいくらになりますか。"]},{"code":"S2","name":"Đi siêu thị","next":"S3","prompt":"Đóng vai nhân viên siêu thị, cho biết hạn dùng và giờ giảm giá.","allowedGoalCodes":["MARKET"],"suggestedReplies":["この惣菜の消費期限はいつまでですか。"]},{"code":"S3","name":"Làm thủ tục ngân hàng","next":"S4","prompt":"Đóng vai giao dịch viên, báo phí chuyển khoản.","allowedGoalCodes":["BANK"],"suggestedReplies":["振込をしたいのですが。手数料はいくらかかりますか。"]},{"code":"S4","name":"Khám bệnh","next":"S5","prompt":"Đóng vai bác sĩ, hỏi triệu chứng và kê thuốc.","allowedGoalCodes":["HEALTH"],"suggestedReplies":["咳が止まらなくて、夜眠れないんです。"]},{"code":"S5","name":"Rủ bạn đi chơi","next":"S6","prompt":"Đóng vai bạn, đồng ý đi chơi.","allowedGoalCodes":["SOCIAL"],"suggestedReplies":["一緒に映画を見に行かない？"]},{"code":"S6","name":"Hỏi giờ mở cửa","next":"END","prompt":"Đóng vai nhân viên, cho biết giờ mở cửa.","allowedGoalCodes":["TIME"],"suggestedReplies":["郵便局は何時に開きますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Đã hoàn thành một ngày sinh hoạt","message":"今日はいろいろありましたね。お疲れさまでした。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"S1"}', '{"grammar":[{"example":"共益費は別ですか。","pattern":"〜は別ですか","explanation":"Hỏi một khoản có tính riêng không."},{"example":"操作を教えていただけますか。","pattern":"〜ていただけますか","explanation":"Nhờ vả rất lịch sự."},{"example":"一緒に映画を見に行かない？","pattern":"〜に行かない？","explanation":"Rủ bạn bè thân mật."}],"vocabulary":[{"jlpt":"N3","term":"家賃","example":"家賃はいくらですか。","meaning":"tiền thuê nhà","reading":"やちん"},{"jlpt":"N3","term":"消費期限","example":"消費期限はいつまでですか。","meaning":"hạn dùng","reading":"しょうひきげん"},{"jlpt":"N3","term":"手数料","example":"手数料はいくらですか。","meaning":"phí giao dịch","reading":"てすうりょう"},{"jlpt":"N3","term":"薬","example":"薬をください。","meaning":"thuốc","reading":"くすり"},{"jlpt":"N5","term":"何時","example":"何時に開きますか。","meaning":"mấy giờ","reading":"なんじ"}],"exampleDialogue":[{"text":"初期費用は全部でいくらになりますか。","speaker":"learner","translation":"Chi phí ban đầu tổng cộng là bao nhiêu ạ?"},{"text":"家賃、敷金一か月、礼金なしで、合計十四万円ほどです。","speaker":"ai","translation":"Tiền thuê, cọc một tháng, không tiền lễ, tổng khoảng mười bốn vạn ạ."},{"text":"手数料はいくらかかりますか。","speaker":"learner","translation":"Phí là bao nhiêu ạ?"},{"text":"咳止めを五日分出します。","speaker":"ai","translation":"Tôi kê thuốc ho năm ngày."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chào hỏi lần đầu gặp khách hàng', 'cpath-brse-01', 'Bạn giới thiệu bản thân, trao danh thiếp, đáp lời khen và nhận vai trò đầu mối liên lạc với khách hàng.', 'N3', 'EASY', 7, 'Bạn là BrSE dự án, lần đầu đến văn phòng khách hàng Nhật trong buổi kick-off và cần giới thiệu bản thân.', 'Phòng họp tại văn phòng khách hàng', 'Buổi sáng', '{"goals":[{"code":"JIKO","type":"MISSION","title":"Tự giới thiệu","required":true,"conditions":[{"type":"KEYWORD","value":"申します|担当いたします|ブリッジSE|初めまして"}],"description":"Chào lần đầu, nói tên công ty và vai trò BrSE của mình.","displayOrder":1},{"code":"MEISHI","type":"MISSION","title":"Trao danh thiếp","required":true,"conditions":[{"type":"KEYWORD","value":"名刺|よろしくお願いいたします|よろしくお願いします"}],"description":"Đưa danh thiếp và nói mong được giúp đỡ.","displayOrder":2},{"code":"KENJO","type":"MISSION","title":"Đáp lời khen khiêm tốn","required":true,"conditions":[{"type":"KEYWORD","value":"勉強中|ありがとうございます|参加しておりました"}],"description":"Đáp lời khen tiếng Nhật và kể kinh nghiệm làm với khách Nhật.","displayOrder":3},{"code":"MADOGUCHI","type":"MISSION","title":"Nhận vai trò đầu mối","required":true,"conditions":[{"type":"KEYWORD","value":"窓口|ご連絡ください|進捗|ダナン"}],"description":"Xác nhận đội ở Đà Nẵng và mời khách liên lạc bất cứ lúc nào.","displayOrder":4}],"states":[{"code":"GREETING","name":"Chào hỏi","next":"INTRO","prompt":"Chào khách và mời người học giới thiệu bản thân.","allowedGoalCodes":["JIKO"],"suggestedReplies":["初めまして。VJソリューションズのグエンと申します。","本プロジェクトでブリッジSEを担当いたします。"]},{"code":"INTRO","name":"Trao danh thiếp","next":"SMALLTALK","prompt":"Đưa danh thiếp và hỏi thêm về người học.","allowedGoalCodes":["MEISHI"],"suggestedReplies":["こちら、私の名刺です。","どうぞよろしくお願いいたします。"],"transitionText":"Sau khi tự giới thiệu…"},{"code":"SMALLTALK","name":"Khen tiếng Nhật","next":"ROLE","prompt":"Khen tiếng Nhật và hỏi kinh nghiệm làm với khách Nhật.","allowedGoalCodes":["KENJO"],"suggestedReplies":["まだまだ勉強中です。","以前、日本のお客様向けのプロジェクトに参加しておりました。"],"transitionText":"Sau khi trao danh thiếp…"},{"code":"ROLE","name":"Xác nhận đầu mối","next":"END","prompt":"Hỏi về đội phát triển và xác nhận người học là đầu mối liên lạc.","allowedGoalCodes":["MADOGUCHI"],"suggestedReplies":["ダナンに十名のチームがおります。","私が窓口となって、仕様の確認や進捗のご報告をさせていただきます。","何かございましたら、いつでもご連絡ください。"],"transitionText":"Sau khi trò chuyện…"}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành chào hỏi","message":"本日はありがとうございました。今後ともよろしくお願いいたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"GREETING"}', '{"grammar":[{"pattern":"〜と申します","example":"VJソリューションズのグエンと申します。","explanation":"Cách tự giới thiệu khiêm nhường, lịch sự hơn 〜です."},{"pattern":"〜を担当いたします","example":"本プロジェクトでブリッジSEを担当いたします。","explanation":"Nói rõ vai trò mình phụ trách trong dự án."}],"vocabulary":[{"jlpt":"N3","term":"名刺","reading":"めいし","meaning":"danh thiếp","example":"こちら、私の名刺です。"},{"jlpt":"N3","term":"窓口","reading":"まどぐち","meaning":"đầu mối liên lạc","example":"私が窓口となって対応いたします。"},{"jlpt":"N3","term":"担当","reading":"たんとう","meaning":"phụ trách","example":"私がブリッジSEを担当いたします。"},{"jlpt":"N3","term":"進捗","reading":"しんちょく","meaning":"tiến độ","example":"進捗をご報告いたします。"}],"exampleDialogue":[{"text":"初めまして。ミライテックの田中です。","speaker":"ai","translation":"Xin chào, tôi là Tanaka của Miraitech."},{"text":"初めまして。VJソリューションズのグエンと申します。本プロジェクトでブリッジSEを担当いたします。","speaker":"learner","translation":"Xin chào, tôi là Nguyễn của VJ Solutions. Tôi sẽ phụ trách vai trò BrSE cho dự án này."},{"text":"グエンさんは日本語がお上手ですね。","speaker":"ai","translation":"Anh Nguyễn nói tiếng Nhật giỏi quá."},{"text":"ありがとうございます。まだまだ勉強中です。","speaker":"learner","translation":"Cảm ơn anh. Tôi vẫn còn đang học."},{"text":"開発チームはダナンにあるんですよね。","speaker":"ai","translation":"Đội phát triển ở Đà Nẵng phải không?"},{"text":"はい、ダナンに十名のチームがおります。私が窓口となって対応いたします。","speaker":"learner","translation":"Vâng, ở Đà Nẵng có đội 10 người. Tôi sẽ làm đầu mối."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nghe điện thoại khi người được tìm vắng mặt', 'cpath-brse-02', 'Bạn chào đầu máy, báo PM đang họp, ghi lời nhắn và số điện thoại, rồi xác nhận lại trước khi cúp máy.', 'N2', 'MEDIUM', 8, 'Khách hàng Nhật gọi điện tìm PM (anh Phạm) nhưng PM đang họp, bạn là người bắt máy và nhận lời nhắn.', 'Văn phòng, qua điện thoại', 'Buổi chiều', '{"goals":[{"code":"UKETSUKE","type":"MISSION","title":"Nhận cuộc gọi","required":true,"conditions":[{"type":"KEYWORD","value":"お電話ありがとうございます|でございます|VJソリューションズ"}],"description":"Chào đầu máy, nói tên công ty và tên mình.","displayOrder":1},{"code":"FUKUSHU","type":"MISSION","title":"Đáp lời chào","required":true,"conditions":[{"type":"KEYWORD","value":"こちらこそ|お世話になっております"}],"description":"Đáp lại lời chào cố định của khách.","displayOrder":2},{"code":"RUSU","type":"MISSION","title":"Báo PM vắng mặt","required":true,"conditions":[{"type":"KEYWORD","value":"会議中|申し訳ございません|終わる予定です"}],"description":"Báo PM đang họp và giờ dự kiến xong.","displayOrder":3},{"code":"DENGON","type":"MISSION","title":"Nhận lời nhắn","required":true,"conditions":[{"type":"KEYWORD","value":"申し伝えます|折り返し|承りました"}],"description":"Đề nghị chuyển lời, nhắc lại nội dung và số điện thoại.","displayOrder":4}],"states":[{"code":"PICKUP","name":"Nhận cuộc gọi","next":"GREETING","prompt":"Chào khách, xưng tên công ty và tên mình.","allowedGoalCodes":["UKETSUKE"],"suggestedReplies":["お電話ありがとうございます。VJソリューションズのグエンでございます。"]},{"code":"GREETING","name":"Chào hỏi qua điện thoại","next":"ABSENT","prompt":"Đáp lại lời chào và hỏi khách cần gặp ai.","allowedGoalCodes":["FUKUSHU"],"suggestedReplies":["こちらこそ、いつもお世話になっております。"],"transitionText":"Sau khi khách xưng danh…"},{"code":"ABSENT","name":"Báo vắng mặt","next":"MESSAGE","prompt":"Báo PM đang họp và đề nghị nhắn gọi lại.","allowedGoalCodes":["RUSU"],"suggestedReplies":["申し訳ございません。ファムはただいま会議中でございます。","会議が終わり次第、折り返しお電話を差し上げるよう、申し伝えましょうか。"],"transitionText":"Sau khi khách hỏi tìm PM…"},{"code":"MESSAGE","name":"Nhận lời nhắn","next":"END","prompt":"Ghi lời nhắn, xin số điện thoại và đọc lại để xác nhận.","allowedGoalCodes":["DENGON"],"suggestedReplies":["かしこまりました。明日のリリースの件ですね。","私、グエンが承りました。","失礼いたします。"],"transitionText":"Sau khi khách cho lời nhắn…"}],"endings":{"success":{"code":"SUCCESS","title":"Nhận lời nhắn xong","message":"かしこまりました。確かに申し伝えます。失礼いたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"PICKUP"}', '{"grammar":[{"pattern":"〜はただいま〜中でございます","example":"ファムはただいま会議中でございます。","explanation":"Báo người được tìm đang bận; với khách bên ngoài thì gọi đồng nghiệp mình không kèm さん."},{"pattern":"私、〇〇が承りました","example":"私、グエンが承りました。","explanation":"Câu kết chuẩn khi nhận lời nhắn qua điện thoại."}],"vocabulary":[{"jlpt":"N2","term":"折り返し","reading":"おりかえし","meaning":"gọi lại","example":"折り返しお電話いたします。"},{"jlpt":"N2","term":"申し伝える","reading":"もうしつたえる","meaning":"chuyển lời (khiêm nhường)","example":"確かに申し伝えます。"},{"jlpt":"N2","term":"承る","reading":"うけたまわる","meaning":"nhận lời (khiêm nhường)","example":"私、グエンが承りました。"},{"jlpt":"N2","term":"念のため","reading":"ねんのため","meaning":"để chắc chắn","example":"念のため、お電話番号をお伺いしてもよろしいでしょうか。"}],"exampleDialogue":[{"text":"お電話ありがとうございます。VJソリューションズのグエンでございます。","speaker":"ai","translation":"Cảm ơn quý khách đã gọi. Nguyễn của VJ Solutions xin nghe."},{"text":"プロジェクトマネージャーのファムさんはいらっしゃいますか。","speaker":"ai","translation":"Anh Phạm, quản lý dự án, có ở đó không?"},{"text":"申し訳ございません。ファムはただいま会議中でございます。11時には終わる予定です。","speaker":"learner","translation":"Thành thật xin lỗi, anh Phạm hiện đang họp. Dự kiến 11 giờ sẽ xong."},{"text":"会議が終わり次第、折り返しお電話を差し上げるよう、申し伝えましょうか。","speaker":"learner","translation":"Tôi nhắn anh ấy họp xong sẽ gọi lại cho anh nhé?"},{"text":"はい、お願いします。明日のリリースの件でご相談したいことがあると伝えてください。","speaker":"ai","translation":"Vâng, nhờ anh. Anh nhắn giúp là tôi muốn trao đổi về đợt release ngày mai."},{"text":"かしこまりました。明日のリリースの件ですね。私、グエンが承りました。失礼いたします。","speaker":"learner","translation":"Tôi hiểu rồi. Về đợt release ngày mai ạ. Tôi là Nguyễn đã nhận lời nhắn. Xin phép anh."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nhờ khách hàng hỗ trợ', 'cpath-brse-09', 'Bạn mở lời nhờ vả, nêu bối cảnh, đề nghị số lượng và hạn cụ thể, rồi cảm ơn khi khách nhận làm.', 'N3', 'EASY', 6, 'Sắp tới test tích hợp nhưng khách chưa cấp tài khoản test, bạn cần nhờ khách chuẩn bị kịp thời hạn.', 'Văn phòng, qua điện thoại', 'Buổi sáng', '{"goals":[{"code":"ONEGAI","type":"MISSION","title":"Mở lời nhờ vả","required":true,"conditions":[{"type":"KEYWORD","value":"一つお願いがあるのですが|お願い"}],"description":"Nói mình có một việc muốn nhờ.","displayOrder":1},{"code":"HAIKEI","type":"MISSION","title":"Nêu bối cảnh","required":true,"conditions":[{"type":"KEYWORD","value":"結合テスト|アカウント|発行されておりません"}],"description":"Trình bày tuần sau bắt đầu test tích hợp mà chưa có tài khoản test.","displayOrder":2},{"code":"KIGEN","type":"MISSION","title":"Đề nghị hạn và số lượng","required":true,"conditions":[{"type":"KEYWORD","value":"金曜日|5名分|可能でしょうか"}],"description":"Nhờ cấp 5 tài khoản trước thứ Sáu.","displayOrder":3},{"code":"KANSHA","type":"MISSION","title":"Cảm ơn khi khách nhận","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございます|お手数をおかけしますが"}],"description":"Cảm ơn và nói làm phiền khách.","displayOrder":4}],"states":[{"code":"REQUEST","name":"Mở lời nhờ vả","next":"CONTEXT","prompt":"Hỏi xem người học muốn nhờ gì.","allowedGoalCodes":["ONEGAI"],"suggestedReplies":["田中様、一つお願いがあるのですが。"]},{"code":"CONTEXT","name":"Nêu bối cảnh","next":"DEADLINE","prompt":"Hỏi rõ tình hình test và tài khoản.","allowedGoalCodes":["HAIKEI"],"suggestedReplies":["来週から結合テストを始める予定なのですが、テスト用のアカウントがまだ発行されておりません。"],"transitionText":"Sau khi khách hỏi việc gì…"},{"code":"DEADLINE","name":"Đề nghị hạn cụ thể","next":"THANKS","prompt":"Xác nhận hạn và số lượng tài khoản cần cấp.","allowedGoalCodes":["KIGEN"],"suggestedReplies":["お忙しいところ恐縮ですが、金曜日までに5名分発行していただくことは可能でしょうか。"],"transitionText":"Sau khi khách nhận lời xem xét…"},{"code":"THANKS","name":"Cảm ơn","next":"END","prompt":"Khách nhận làm trong hôm nay, mời người học cảm ơn.","allowedGoalCodes":["KANSHA"],"suggestedReplies":["ありがとうございます。お手数をおかけしますが、よろしくお願いいたします。"],"transitionText":"Sau khi khách hẹn hôm nay sẽ sắp xếp…"}],"endings":{"success":{"code":"SUCCESS","title":"Nhờ khách hỗ trợ xong","message":"ありがとうございます。よろしくお願いいたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"REQUEST"}', '{"grammar":[{"pattern":"〜していただくことは可能でしょうか","example":"金曜日までに5名分発行していただくことは可能でしょうか。","explanation":"Nhờ vả lịch sự, kèm hạn chót và số lượng rõ ràng."},{"pattern":"お手数をおかけしますが","example":"お手数をおかけしますが、よろしくお願いいたします。","explanation":"Cách nói khi làm phiền người khác giúp mình."}],"vocabulary":[{"jlpt":"N3","term":"発行","reading":"はっこう","meaning":"cấp phát","example":"テスト用のアカウントを発行していただけますか。"},{"jlpt":"N3","term":"結合テスト","reading":"けつごうテスト","meaning":"kiểm thử tích hợp","example":"来週から結合テストを始める予定です。"},{"jlpt":"N3","term":"手配","reading":"てはい","meaning":"sắp xếp, lo liệu","example":"今日中に手配します。"},{"jlpt":"N3","term":"恐縮","reading":"きょうしゅく","meaning":"lấy làm ngại, áy náy","example":"お忙しいところ恐縮ですが、よろしくお願いいたします。"}],"exampleDialogue":[{"text":"田中様、一つお願いがあるのですが。","speaker":"learner","translation":"Anh Tanaka, tôi có một việc muốn nhờ."},{"text":"はい、何でしょう。","speaker":"ai","translation":"Vâng, việc gì vậy?"},{"text":"来週から結合テストを始める予定なのですが、テスト用のアカウントがまだ発行されておりません。","speaker":"learner","translation":"Tuần sau chúng tôi dự định bắt đầu test tích hợp, nhưng tài khoản test vẫn chưa được cấp."},{"text":"お忙しいところ恐縮ですが、金曜日までに5名分発行していただくことは可能でしょうか。","speaker":"learner","translation":"Biết anh đang bận, nhưng trước thứ Sáu anh có thể cấp giúp 5 tài khoản được không ạ?"},{"text":"ああ、すみません、忘れていました。今日中に手配します。","speaker":"ai","translation":"À, xin lỗi, tôi quên mất. Trong hôm nay tôi sẽ sắp xếp."},{"text":"ありがとうございます。お手数をおかけしますが、よろしくお願いいたします。","speaker":"learner","translation":"Cảm ơn anh. Làm phiền anh, rất mong anh giúp đỡ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận điểm chưa rõ trong đặc tả', 'cpath-brse-03', 'Bạn xin phép hỏi, chỉ rõ vị trí và điểm còn thiếu, đưa phương án cho khách chọn rồi nhắc lại để chốt.', 'N2', 'MEDIUM', 7, 'Bạn phát hiện tài liệu đặc tả thiếu cách mở khóa tài khoản và cần hỏi lại khách hàng.', 'Phòng họp trực tuyến', 'Buổi sáng', '{"goals":[{"code":"SHITSUMON","type":"MISSION","title":"Xin phép hỏi","required":true,"conditions":[{"type":"KEYWORD","value":"確認させていただきたい|仕様書|よろしいでしょうか"}],"description":"Mở lời muốn xác nhận một điểm trong đặc tả.","displayOrder":1},{"code":"SHITEKI","type":"MISSION","title":"Chỉ rõ điểm thiếu","required":true,"conditions":[{"type":"KEYWORD","value":"画面設計書|ロック|解除方法|記載"}],"description":"Nêu vị trí và điều còn thiếu trong tài liệu.","displayOrder":2},{"code":"SENTAKU","type":"MISSION","title":"Đưa phương án chọn","required":true,"conditions":[{"type":"KEYWORD","value":"自動で解除|手動で解除|どちらをご想定でしょうか"}],"description":"Đưa hai cách mở khóa để khách chọn.","displayOrder":3},{"code":"KAKUNIN","type":"MISSION","title":"Nhắc lại để chốt","required":true,"conditions":[{"type":"KEYWORD","value":"ということでよろしいでしょうか|自動解除|手動解除"}],"description":"Nhắc lại đúng cả hai yêu cầu để xác nhận.","displayOrder":4}],"states":[{"code":"ASK","name":"Xin phép hỏi","next":"POINT","prompt":"Cho phép người học đặt câu hỏi.","allowedGoalCodes":["SHITSUMON"],"suggestedReplies":["仕様書の件で一点確認させていただきたいのですが、今お時間よろしいでしょうか。"]},{"code":"POINT","name":"Chỉ rõ điểm thiếu","next":"OPTION","prompt":"Xác nhận vị trí và điều còn thiếu.","allowedGoalCodes":["SHITEKI"],"suggestedReplies":["画面設計書の3ページ目、ログイン画面についてです。ロックの解除方法について記載がございません。"],"transitionText":"Sau khi khách đồng ý nghe…"},{"code":"OPTION","name":"Đưa phương án chọn","next":"CONFIRM","prompt":"Đưa phương án và hỏi khách muốn chọn cách nào.","allowedGoalCodes":["SENTAKU"],"suggestedReplies":["一定時間が経過したら自動で解除する方式と、管理者が手動で解除する方式が考えられますが、どちらをご想定でしょうか。"],"transitionText":"Sau khi khách nhận ra chỗ thiếu…"},{"code":"CONFIRM","name":"Nhắc lại để chốt","next":"END","prompt":"Nhắc lại đúng cả hai yêu cầu để khách xác nhận.","allowedGoalCodes":["KAKUNIN"],"suggestedReplies":["30分後の自動解除と、管理者による手動解除の両方を実装する、ということでよろしいでしょうか。"],"transitionText":"Sau khi khách chọn phương án…"}],"endings":{"success":{"code":"SUCCESS","title":"Chốt xong điểm đặc tả","message":"ありがとうございます。認識齟齬を防ぐため、本日中にQ&A表に記載してお送りいたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ASK"}', '{"grammar":[{"pattern":"〜について記載がございません","example":"ロックの解除方法について記載がございません。","explanation":"Nêu khách quan điều còn thiếu trong tài liệu."},{"pattern":"〜ということでよろしいでしょうか","example":"30分後の自動解除と管理者による手動解除の両方を実装する、ということでよろしいでしょうか。","explanation":"Nhắc lại để chốt, kỹ năng cốt lõi của BrSE."}],"vocabulary":[{"jlpt":"N2","term":"仕様書","reading":"しようしょ","meaning":"tài liệu đặc tả","example":"仕様書の件で確認させていただきたいのですが。"},{"jlpt":"N2","term":"画面設計書","reading":"がめんせっけいしょ","meaning":"tài liệu thiết kế màn hình","example":"画面設計書の3ページ目をご覧ください。"},{"jlpt":"N2","term":"解除","reading":"かいじょ","meaning":"mở khóa, hủy bỏ","example":"30分後に自動で解除します。"},{"jlpt":"N2","term":"認識齟齬","reading":"にんしきそご","meaning":"hiểu sai lệch giữa hai bên","example":"認識齟齬を防ぐため、Q&A表に記載します。"}],"exampleDialogue":[{"text":"田中様、仕様書の件で一点確認させていただきたいのですが、今お時間よろしいでしょうか。","speaker":"learner","translation":"Anh Tanaka, tôi muốn xác nhận một điểm trong tài liệu đặc tả, bây giờ anh có tiện không ạ?"},{"text":"画面設計書の3ページ目、ログイン画面についてです。パスワードを5回間違えるとアカウントをロックすると書かれていますが、ロックの解除方法について記載がございません。","speaker":"learner","translation":"Về màn hình đăng nhập ở trang 3. Tài liệu ghi nhập sai mật khẩu 5 lần sẽ khóa tài khoản, nhưng không ghi cách mở khóa."},{"text":"ああ、そこは抜けていましたね。","speaker":"ai","translation":"À, chỗ đó bị sót thật."},{"text":"一定時間が経過したら自動で解除する方式と、管理者が手動で解除する方式が考えられますが、どちらをご想定でしょうか。","speaker":"learner","translation":"Có thể tự động mở khóa sau một khoảng thời gian, hoặc để quản trị viên mở khóa thủ công. Anh đang hình dung theo cách nào ạ?"},{"text":"30分後に自動で解除する形でお願いします。管理者による解除も、念のため入れておいてください。","speaker":"ai","translation":"Làm theo kiểu tự động mở khóa sau 30 phút. Cho thêm cả chức năng quản trị viên mở khóa để phòng hờ."},{"text":"承知いたしました。30分後の自動解除と、管理者による手動解除の両方を実装する、ということでよろしいでしょうか。","speaker":"learner","translation":"Tôi hiểu rồi. Vậy là triển khai cả tự động mở khóa sau 30 phút lẫn quản trị viên mở khóa thủ công, đúng không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xử lý yêu cầu thay đổi đặc tả', 'cpath-brse-07', 'Bạn nhắc lại đúng yêu cầu, hỏi rõ màn hình và trường dữ liệu, nói rõ đây là việc ngoài phạm vi rồi hẹn gửi ước tính.', 'N2', 'MEDIUM', 7, 'Khách hàng muốn thêm chức năng xuất CSV ngoài phạm vi, bạn cần làm rõ yêu cầu và đề nghị ước tính công số.', 'Phòng họp trực tuyến', 'Buổi sáng', '{"goals":[{"code":"SAIKAKUNIN","type":"MISSION","title":"Nhắc lại yêu cầu","required":true,"conditions":[{"type":"KEYWORD","value":"CSV出力機能|追加|画面|項目"}],"description":"Nhắc lại đúng chức năng xuất CSV và hỏi rõ phạm vi.","displayOrder":1},{"code":"HANIGAI","type":"MISSION","title":"Nói rõ ngoài phạm vi","required":true,"conditions":[{"type":"KEYWORD","value":"開発範囲外|工数|見積もらせていただきたい"}],"description":"Nói rõ việc nằm ngoài phạm vi và xin ước tính công số.","displayOrder":2},{"code":"YOTEI","type":"MISSION","title":"Hẹn gửi ước tính","required":true,"conditions":[{"type":"KEYWORD","value":"明日中|見積もりをご提出|相談"}],"description":"Hẹn trao đổi đội phát triển rồi gửi ước tính, kèm bàn phạm vi release.","displayOrder":3}],"states":[{"code":"REQ","name":"Nhận yêu cầu","next":"DETAIL","prompt":"Khách nêu yêu cầu thêm chức năng xuất CSV, mời người học hỏi rõ.","allowedGoalCodes":["SAIKAKUNIN"],"suggestedReplies":["CSV出力機能の追加ですね。対象となる画面とデータの項目を教えていただけますか。"]},{"code":"DETAIL","name":"Làm rõ phạm vi","next":"SCOPE","prompt":"Khách mô tả màn hình và dữ liệu, mời người học nói rõ phạm vi công việc.","allowedGoalCodes":["HANIGAI"],"suggestedReplies":["現在の開発範囲外の作業となりますので、工数とスケジュールへの影響を見積もらせていただきたいと思います。"],"transitionText":"Sau khi khách mô tả yêu cầu…"},{"code":"SCOPE","name":"Hẹn gửi ước tính","next":"END","prompt":"Khách hỏi mất bao lâu, mời người học hẹn gửi ước tính và bàn phạm vi release.","allowedGoalCodes":["YOTEI"],"suggestedReplies":["開発チームと確認のうえ、明日中に見積もりをご提出いたします。","今回のリリースに含めるか、次回に回すかもご相談させてください。"],"transitionText":"Sau khi khách hỏi mất bao lâu…"}],"endings":{"success":{"code":"SUCCESS","title":"Hẹn gửi ước tính xong","message":"承知いたしました。明日中に見積もりをご提出いたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"REQ"}', '{"grammar":[{"pattern":"開発範囲外の作業となりますので","example":"現在の開発範囲外の作業となりますので、見積もらせていただきたいと思います。","explanation":"Nói rõ ngay từ đầu để tránh bị hiểu là làm miễn phí."},{"pattern":"〜のうえ","example":"開発チームと確認のうえ、見積もりをご提出いたします。","explanation":"Nghĩa là \'sau khi ~\', rất hay gặp trong email công việc (N2)."}],"vocabulary":[{"jlpt":"N2","term":"工数","reading":"こうすう","meaning":"công số (man-day, man-hour)","example":"工数を見積もらせていただきたいと思います。"},{"jlpt":"N2","term":"見積もり","reading":"みつもり","meaning":"ước tính, báo giá","example":"明日中に見積もりをご提出いたします。"},{"jlpt":"N2","term":"追加","reading":"ついか","meaning":"thêm","example":"CSV出力機能を追加してほしいとのことですね。"},{"jlpt":"N2","term":"範囲外","reading":"はんいがい","meaning":"ngoài phạm vi","example":"現在の開発範囲外の作業となります。"}],"exampleDialogue":[{"text":"実は、ユーザーから要望があって、CSVでデータを出力する機能を追加してほしいんです。","speaker":"ai","translation":"Thật ra người dùng có yêu cầu, tôi muốn thêm chức năng xuất dữ liệu ra CSV."},{"text":"CSV出力機能の追加ですね。対象となる画面とデータの項目を教えていただけますか。","speaker":"learner","translation":"Thêm chức năng xuất CSV ạ. Anh cho tôi biết màn hình và các trường dữ liệu cần xuất được không?"},{"text":"注文一覧の画面で、表示されている項目をそのまま出力できればいいです。","speaker":"ai","translation":"Ở màn hình danh sách đơn hàng, xuất nguyên các cột đang hiển thị là được."},{"text":"承知いたしました。ただ、現在の開発範囲外の作業となりますので、工数とスケジュールへの影響を見積もらせていただきたいと思います。","speaker":"learner","translation":"Tôi hiểu rồi. Tuy nhiên đây là công việc ngoài phạm vi phát triển hiện tại, nên chúng tôi xin phép ước tính công số và ảnh hưởng tới lịch trình."},{"text":"どのくらいかかりそうですか。","speaker":"ai","translation":"Có vẻ mất khoảng bao lâu?"},{"text":"開発チームと確認のうえ、明日中に見積もりをご提出いたします。今回のリリースに含めるか、次回に回すかもご相談させてください。","speaker":"learner","translation":"Sau khi trao đổi với đội phát triển, trong ngày mai tôi sẽ gửi bản ước tính. Đồng thời cho tôi trao đổi luôn việc đưa vào đợt release này hay dời sang đợt sau."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận yêu cầu', 'cpath-brse-15', 'Bạn mở đầu việc muốn xác nhận, hỏi độ ưu tiên của chức năng, rồi nhờ khách gửi đặc tả trước tuần sau.', 'N2', 'MEDIUM', 6, 'Bạn họp với khách hàng Nhật để làm rõ một yêu cầu mới và nhờ gửi tài liệu đặc tả đúng hạn.', 'Phòng họp tại văn phòng khách hàng', 'Buổi sáng', '{"goals":[{"code":"KAKUNIN","type":"MISSION","title":"Mở đầu xác nhận","required":true,"conditions":[{"type":"KEYWORD","value":"確認したいのですが|新しい要件|要件"}],"description":"Nói rõ muốn xác nhận yêu cầu mới.","displayOrder":1},{"code":"YUSEN","type":"MISSION","title":"Hỏi độ ưu tiên","required":true,"conditions":[{"type":"KEYWORD","value":"優先度|高いですか"}],"description":"Hỏi độ ưu tiên của chức năng có cao không.","displayOrder":2},{"code":"SHIRYO","type":"MISSION","title":"Nhờ gửi đặc tả","required":true,"conditions":[{"type":"KEYWORD","value":"仕様書|いただけますか|来週までに"}],"description":"Nhờ khách gửi tài liệu đặc tả trước hạn cụ thể.","displayOrder":3}],"states":[{"code":"TOPIC","name":"Mở đầu","next":"PRIORITY","prompt":"Khách hỏi lại nội dung, mời người học nêu chủ đề cần xác nhận.","allowedGoalCodes":["KAKUNIN"],"suggestedReplies":["新しい要件について確認したいのですが。"]},{"code":"PRIORITY","name":"Hỏi độ ưu tiên","next":"DOC","prompt":"Mời người học hỏi độ ưu tiên của chức năng.","allowedGoalCodes":["YUSEN"],"suggestedReplies":["この機能の優先度は高いですか。"],"transitionText":"Sau khi khách hỏi là gì…"},{"code":"DOC","name":"Nhờ gửi đặc tả","next":"END","prompt":"Khách nói muốn đưa vào release tháng sau, mời người học nhờ gửi đặc tả đúng hạn.","allowedGoalCodes":["SHIRYO"],"suggestedReplies":["では、仕様書を来週までにいただけますか。"],"transitionText":"Sau khi khách xác nhận ưu tiên cao…"}],"endings":{"success":{"code":"SUCCESS","title":"Xác nhận yêu cầu xong","message":"ありがとうございます。よろしくお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"TOPIC"}', '{"grammar":[{"pattern":"〜について確認したいのですが","example":"新しい要件について確認したいのですが。","explanation":"Mở đầu cuộc trao đổi công việc."},{"pattern":"〜までにいただけますか","example":"仕様書を来週までにいただけますか。","explanation":"Nhờ đối tác gửi tài liệu đúng hạn."}],"vocabulary":[{"jlpt":"N2","term":"要件","reading":"ようけん","meaning":"yêu cầu","example":"新しい要件について確認したいのですが。"},{"jlpt":"N2","term":"優先度","reading":"ゆうせんど","meaning":"độ ưu tiên","example":"この機能の優先度は高いですか。"},{"jlpt":"N2","term":"仕様書","reading":"しようしょ","meaning":"tài liệu đặc tả","example":"仕様書を来週までにいただけますか。"},{"jlpt":"N2","term":"リリース","reading":"リリース","meaning":"phát hành","example":"来月のリリースに入れたいです。"}],"exampleDialogue":[{"text":"田中さん、新しい要件について確認したいのですが。","speaker":"learner","translation":"Anh Tanaka, tôi muốn xác nhận về yêu cầu mới ạ."},{"text":"はい、何でしょうか。","speaker":"ai","translation":"Vâng, là gì ạ?"},{"text":"この機能の優先度は高いですか。","speaker":"learner","translation":"Độ ưu tiên của chức năng này có cao không ạ?"},{"text":"はい、来月のリリースに入れたいです。","speaker":"ai","translation":"Có, chúng tôi muốn đưa vào bản phát hành tháng sau."},{"text":"では、仕様書を来週までにいただけますか。","speaker":"learner","translation":"Vậy anh gửi tài liệu đặc tả cho tôi trước tuần sau được không ạ?"},{"text":"分かりました。水曜日までに送ります。","speaker":"ai","translation":"Được ạ. Tôi sẽ gửi trước thứ Tư."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo tiến độ trong họp định kỳ', 'cpath-brse-04', 'Bạn báo hạng mục đã xong, nêu hạng mục chậm cùng nguyên nhân và dự báo, rồi hẹn mốc kiểm tra lại.', 'N2', 'MEDIUM', 8, 'BrSE báo cáo tiến độ tuần, trong đó có một hạng mục đang chậm, cần nêu rõ và hẹn báo lại.', 'Phòng họp trực tuyến', 'Buổi sáng', '{"goals":[{"code":"HOUKOKU","type":"MISSION","title":"Mở đầu báo cáo","required":true,"conditions":[{"type":"KEYWORD","value":"進捗をご報告いたします|報告"}],"description":"Nói sẽ báo cáo tiến độ tuần này.","displayOrder":1},{"code":"KANRYOU","type":"MISSION","title":"Báo hạng mục đã xong","required":true,"conditions":[{"type":"KEYWORD","value":"予定どおり完了|単体テスト|実施中"}],"description":"Nêu hạng mục hoàn thành đúng kế hoạch.","displayOrder":2},{"code":"CHITAI","type":"MISSION","title":"Báo hạng mục chậm","required":true,"conditions":[{"type":"KEYWORD","value":"仕様確認|70%程度|とどまっております"}],"description":"Nêu hạng mục chậm cùng nguyên nhân và mức độ.","displayOrder":3},{"code":"MITOOSHI","type":"MISSION","title":"Nêu dự báo và rủi ro","required":true,"conditions":[{"type":"KEYWORD","value":"見込み|リスク|ご報告いたします"}],"description":"Nêu dự báo bắt kịp kèm rủi ro và hẹn báo lại.","displayOrder":4}],"states":[{"code":"OPEN","name":"Mở đầu báo cáo","next":"GOOD","prompt":"Mời người học bắt đầu báo cáo tiến độ.","allowedGoalCodes":["HOUKOKU"],"suggestedReplies":["それでは、今週の進捗をご報告いたします。"]},{"code":"GOOD","name":"Báo tin tốt","next":"DELAY","prompt":"Mời người học nêu hạng mục đã hoàn thành.","allowedGoalCodes":["KANRYOU"],"suggestedReplies":["会員登録機能は予定どおり完了し、現在、単体テストを実施中です。"],"transitionText":"Sau khi mở đầu…"},{"code":"DELAY","name":"Báo hạng mục chậm","next":"RISK","prompt":"Mời người học nêu hạng mục chậm và nguyên nhân.","allowedGoalCodes":["CHITAI"],"suggestedReplies":["決済機能については、外部APIの仕様確認に時間がかかったため、進捗は予定の70%程度にとどまっております。"],"transitionText":"Sau khi báo hạng mục xong…"},{"code":"RISK","name":"Nêu dự báo và rủi ro","next":"END","prompt":"Khách hỏi ảnh hưởng lịch trình, mời người học nêu dự báo và hẹn báo lại.","allowedGoalCodes":["MITOOSHI"],"suggestedReplies":["来週の作業で遅れを取り戻せる見込みです。","APIの接続テストで問題が出た場合は、2日ほど遅れる可能性がございます。","水曜日の時点で状況を確認し、改めてご報告いたします。"],"transitionText":"Sau khi khách hỏi ảnh hưởng…"}],"endings":{"success":{"code":"SUCCESS","title":"Báo cáo tiến độ xong","message":"ありがとうございます。状況が分かりました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"pattern":"〜程度にとどまっております","example":"進捗は予定の70%程度にとどまっております。","explanation":"Báo tin chậm một cách khách quan, không than phiền."},{"pattern":"〜見込みです","example":"来週の作業で遅れを取り戻せる見込みです。","explanation":"Nêu dự báo; luôn kèm điều kiện rủi ro, đừng hứa chắc."}],"vocabulary":[{"jlpt":"N2","term":"進捗","reading":"しんちょく","meaning":"tiến độ","example":"今週の進捗をご報告いたします。"},{"jlpt":"N2","term":"予定どおり","reading":"よていどおり","meaning":"đúng kế hoạch","example":"予定どおり完了しました。"},{"jlpt":"N2","term":"見込み","reading":"みこみ","meaning":"dự kiến, khả năng","example":"遅れを取り戻せる見込みです。"},{"jlpt":"N2","term":"リスク","reading":"リスク","meaning":"rủi ro","example":"リスクがはっきりした時点で教えてください。"}],"exampleDialogue":[{"text":"それでは、今週の進捗をご報告いたします。","speaker":"learner","translation":"Sau đây tôi xin báo cáo tiến độ tuần này."},{"text":"会員登録機能は予定どおり完了し、現在、単体テストを実施中です。","speaker":"learner","translation":"Chức năng đăng ký thành viên đã hoàn thành đúng kế hoạch, hiện đang chạy unit test."},{"text":"一方、決済機能については、外部APIの仕様確認に時間がかかったため、進捗は予定の70%程度にとどまっております。","speaker":"learner","translation":"Ngược lại, chức năng thanh toán mất thời gian xác nhận đặc tả API bên ngoài nên tiến độ mới đạt khoảng 70% kế hoạch."},{"text":"全体のスケジュールには影響がありそうですか。","speaker":"ai","translation":"Có ảnh hưởng tới lịch trình tổng thể không?"},{"text":"現時点では、来週の作業で遅れを取り戻せる見込みです。ただ、APIの接続テストで問題が出た場合は、2日ほど遅れる可能性がございます。","speaker":"learner","translation":"Hiện tại dự kiến tuần sau sẽ bắt kịp. Tuy nhiên, nếu test kết nối API phát sinh vấn đề thì có khả năng chậm khoảng 2 ngày."},{"text":"承知いたしました。水曜日の時点で状況を確認し、改めてご報告いたします。","speaker":"learner","translation":"Vâng. Đến thứ Tư tôi sẽ kiểm tra tình hình và báo cáo lại."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo chậm bàn giao và xin lỗi', 'cpath-brse-05', 'Bạn mở đầu báo tin xấu, xin lỗi, nêu nguyên nhân và biện pháp, rồi đưa phương án bàn giao từng phần.', 'N2', 'HARD', 8, 'Test tích hợp phát sinh nhiều lỗi, bạn phải báo lùi ngày bàn giao, nêu nguyên nhân và biện pháp phòng tái phát.', 'Phòng họp trực tuyến', 'Buổi chiều', '{"goals":[{"code":"MAE","type":"MISSION","title":"Mở đầu báo tin xấu","required":true,"conditions":[{"type":"KEYWORD","value":"申し上げにくいのですが|報告がございます"}],"description":"Mở đầu bằng cụm đệm khi sắp báo tin khó nói.","displayOrder":1},{"code":"SHOUCHI","type":"MISSION","title":"Xin lỗi chân thành","required":true,"conditions":[{"type":"KEYWORD","value":"申し訳ございません|ご迷惑をおかけして"}],"description":"Xin lỗi vì gây phiền phức.","displayOrder":2},{"code":"GENIN","type":"MISSION","title":"Nêu nguyên nhân và biện pháp","required":true,"conditions":[{"type":"KEYWORD","value":"原因|影響範囲|チェックリスト|徹底いたします"}],"description":"Nêu nguyên nhân và biện pháp phòng tái phát cụ thể.","displayOrder":3},{"code":"TEIAN","type":"MISSION","title":"Đưa phương án bàn giao","required":true,"conditions":[{"type":"KEYWORD","value":"納品可能|毎日|ご報告いたします"}],"description":"Đưa phương án bàn giao từng phần và xác nhận báo cáo hằng ngày.","displayOrder":4}],"states":[{"code":"BADNEWS","name":"Mở đầu báo tin xấu","next":"APOLOGY","prompt":"Khách hỏi có chuyện gì, mời người học báo lùi ngày bàn giao.","allowedGoalCodes":["MAE"],"suggestedReplies":["大変申し上げにくいのですが、テスト工程の件でご報告がございます。"]},{"code":"APOLOGY","name":"Xin lỗi","next":"CAUSE","prompt":"Khách tỏ ra khó xử, mời người học xin lỗi.","allowedGoalCodes":["SHOUCHI"],"suggestedReplies":["ご迷惑をおかけして、誠に申し訳ございません。"],"transitionText":"Sau khi khách bày tỏ khó xử…"},{"code":"CAUSE","name":"Nêu nguyên nhân và biện pháp","next":"PLAN","prompt":"Mời người học nêu nguyên nhân và biện pháp phòng tái phát.","allowedGoalCodes":["GENIN"],"suggestedReplies":["原因は、仕様変更の影響範囲の調査が不十分だったことです。","今後は、変更のたびに影響範囲をチェックリストで確認するよう、チームで徹底いたします。"],"transitionText":"Sau khi xin lỗi…"},{"code":"PLAN","name":"Đưa phương án bàn giao","next":"END","prompt":"Khách hỏi có thể bàn giao một phần không, mời người học đưa phương án và xác nhận báo cáo hằng ngày.","allowedGoalCodes":["TEIAN"],"suggestedReplies":["ログイン機能と会員管理機能であれば、15日に納品可能です。","毎日夕方に進捗をメールでご報告いたします。"],"transitionText":"Sau khi khách hỏi bàn giao từng phần…"}],"endings":{"success":{"code":"SUCCESS","title":"Chốt phương án bàn giao","message":"では、それでお願いします。修正の状況は毎日共有してください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"BADNEWS"}', '{"grammar":[{"pattern":"大変申し上げにくいのですが","example":"大変申し上げにくいのですが、テスト工程の件でご報告がございます。","explanation":"Mở đầu trước khi báo tin xấu."},{"pattern":"〜させていただけないでしょうか","example":"納品日を当初の15日から18日に変更させていただけないでしょうか。","explanation":"Xin phép ở mức lịch sự cao khi nhờ khách chấp thuận thay đổi."}],"vocabulary":[{"jlpt":"N2","term":"納期","reading":"のうき","meaning":"hạn bàn giao","example":"納品日を変更させていただけないでしょうか。"},{"jlpt":"N2","term":"納品","reading":"のうひん","meaning":"bàn giao sản phẩm","example":"15日に納品可能です。"},{"jlpt":"N2","term":"原因","reading":"げんいん","meaning":"nguyên nhân","example":"原因は、影響範囲の調査が不十分だったことです。"},{"jlpt":"N2","term":"影響範囲","reading":"えいきょうはんい","meaning":"phạm vi ảnh hưởng","example":"影響範囲をチェックリストで確認します。"}],"exampleDialogue":[{"text":"田中様、大変申し上げにくいのですが、テスト工程の件でご報告がございます。","speaker":"learner","translation":"Anh Tanaka, thật khó nói nhưng tôi có việc cần báo cáo về giai đoạn test."},{"text":"結合テストで想定以上の不具合が見つかり、修正に時間を要しております。そのため、納品日を当初の15日から18日に変更させていただけないでしょうか。","speaker":"learner","translation":"Test tích hợp phát hiện nhiều lỗi hơn dự kiến, việc sửa đang tốn thời gian. Vì vậy, cho phép chúng tôi lùi ngày bàn giao từ ngày 15 sang ngày 18 được không ạ?"},{"text":"3日遅れですか。こちらもユーザーへの説明があるので、正直困りますね。","speaker":"ai","translation":"Chậm 3 ngày à. Bên tôi còn phải giải thích với người dùng, nói thật là khó xử."},{"text":"ご迷惑をおかけして、誠に申し訳ございません。","speaker":"learner","translation":"Chúng tôi thành thật xin lỗi vì đã gây phiền phức."},{"text":"原因は、仕様変更の影響範囲の調査が不十分だったことです。今後は、変更のたびに影響範囲をチェックリストで確認するよう、チームで徹底いたします。","speaker":"learner","translation":"Nguyên nhân là việc khảo sát phạm vi ảnh hưởng của thay đổi đặc tả chưa đầy đủ. Từ nay, mỗi lần thay đổi, cả đội sẽ kiểm tra phạm vi ảnh hưởng bằng checklist một cách triệt để."},{"text":"はい、ログイン機能と会員管理機能であれば、15日に納品可能です。残りの機能を18日に納品する形でいかがでしょうか。","speaker":"learner","translation":"Vâng, nếu là chức năng đăng nhập và quản lý thành viên thì ngày 15 có thể bàn giao. Phần còn lại bàn giao ngày 18, anh thấy thế nào ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Sắp xếp lịch họp', 'cpath-brse-08', 'Bạn hỏi lịch khách, đề xuất mốc giờ hợp lệ, ghi rõ múi giờ rồi hẹn gửi link họp và tài liệu trước.', 'N3', 'EASY', 7, 'Bạn muốn xin một buổi họp review định nghĩa yêu cầu, có tính tới chênh lệch múi giờ Nhật - Việt.', 'Văn phòng, qua điện thoại', 'Buổi chiều', '{"goals":[{"code":"TSUGOU","type":"MISSION","title":"Hỏi lịch khách","required":true,"conditions":[{"type":"KEYWORD","value":"ご都合はいかがでしょうか|レビュー会議"}],"description":"Nêu mục đích và hỏi lịch của khách.","displayOrder":1},{"code":"TEIAN","type":"MISSION","title":"Đề xuất mốc giờ","required":true,"conditions":[{"type":"KEYWORD","value":"木曜日の15時|はいかがでしょうか"}],"description":"Đề xuất 15 giờ thứ Năm đúng lịch khách rảnh.","displayOrder":2},{"code":"JISA","type":"MISSION","title":"Nêu chênh lệch múi giờ","required":true,"conditions":[{"type":"KEYWORD","value":"日本時間|ベトナムは13時"}],"description":"Nêu giờ Việt Nam khi biết 15 giờ Nhật.","displayOrder":3},{"code":"SHIRYOU","type":"MISSION","title":"Hẹn gửi link và tài liệu","required":true,"conditions":[{"type":"KEYWORD","value":"URL|資料|前日までにお送り"}],"description":"Hẹn gửi link họp và tài liệu trước một ngày.","displayOrder":4}],"states":[{"code":"ASK","name":"Hỏi lịch khách","next":"PROPOSE","prompt":"Khách cho biết lịch rảnh, mời người học đề xuất mốc giờ.","allowedGoalCodes":["TSUGOU"],"suggestedReplies":["来週、要件定義のレビュー会議をお願いしたいのですが、ご都合はいかがでしょうか。"]},{"code":"PROPOSE","name":"Đề xuất mốc giờ","next":"TIMEZONE","prompt":"Mời người học đề xuất mốc giờ nằm trong lịch khách đã nêu.","allowedGoalCodes":["TEIAN"],"suggestedReplies":["では、木曜日の15時からはいかがでしょうか。1時間ほどを予定しております。"],"transitionText":"Sau khi khách nêu lịch rảnh…"},{"code":"TIMEZONE","name":"Nêu chênh lệch múi giờ","next":"SEND","prompt":"Mời người học giải thích múi giờ để đội Việt Nam tham gia được.","allowedGoalCodes":["JISA"],"suggestedReplies":["日本時間の15時ですと、ベトナムは13時になりますので、開発チームも参加できます。"],"transitionText":"Sau khi khách đồng ý giờ…"},{"code":"SEND","name":"Hẹn gửi link và tài liệu","next":"END","prompt":"Khách muốn nhận tài liệu trước, mời người học hẹn gửi.","allowedGoalCodes":["SHIRYOU"],"suggestedReplies":["後ほど、会議のURLと資料をお送りいたします。","かしこまりました。前日までにお送りいたします。"],"transitionText":"Sau khi chốt lịch…"}],"endings":{"success":{"code":"SUCCESS","title":"Chốt lịch họp xong","message":"かしこまりました。前日までに資料をお送りいたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ASK"}', '{"grammar":[{"pattern":"ご都合はいかがでしょうか","example":"来週、レビュー会議をお願いしたいのですが、ご都合はいかがでしょうか。","explanation":"Hỏi lịch của khách một cách lịch sự."},{"pattern":"日本時間の〜","example":"日本時間の15時ですと、ベトナムは13時になります。","explanation":"Luôn ghi rõ múi giờ; Việt Nam chậm hơn Nhật 2 tiếng."}],"vocabulary":[{"jlpt":"N3","term":"都合","reading":"つごう","meaning":"lịch rảnh, tiện","example":"ご都合はいかがでしょうか。"},{"jlpt":"N3","term":"要件定義","reading":"ようけんていぎ","meaning":"định nghĩa yêu cầu","example":"要件定義のレビュー会議をお願いしたいのですが。"},{"jlpt":"N3","term":"事前","reading":"じぜん","meaning":"trước, trước khi","example":"資料は事前にいただけると助かります。"},{"jlpt":"N3","term":"前日","reading":"ぜんじつ","meaning":"một ngày trước đó","example":"前日までにお送りいたします。"}],"exampleDialogue":[{"text":"来週、要件定義のレビュー会議をお願いしたいのですが、ご都合はいかがでしょうか。","speaker":"learner","translation":"Tuần sau tôi muốn xin một buổi họp review định nghĩa yêu cầu, lịch của anh thế nào ạ?"},{"text":"来週ですか。火曜と木曜の午後なら空いています。","speaker":"ai","translation":"Tuần sau à. Chiều thứ Ba và thứ Năm thì tôi rảnh."},{"text":"ありがとうございます。では、木曜日の15時からはいかがでしょうか。1時間ほどを予定しております。","speaker":"learner","translation":"Cảm ơn anh. Vậy từ 15 giờ thứ Năm có được không ạ? Dự kiến khoảng 1 tiếng."},{"text":"日本時間の15時ですと、ベトナムは13時になりますので、開発チームも参加できます。","speaker":"learner","translation":"15 giờ giờ Nhật là 13 giờ ở Việt Nam, nên đội phát triển cũng tham gia được."},{"text":"資料は事前にいただけると助かります。","speaker":"ai","translation":"Nếu gửi tài liệu trước thì tốt quá."},{"text":"かしこまりました。前日までにお送りいたします。","speaker":"learner","translation":"Vâng. Tôi sẽ gửi trước một ngày."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chốt nội dung cuối buổi họp', 'cpath-brse-10', 'Bạn xác nhận từng nội dung đã quyết định, hẹn gửi biên bản trong hôm nay và kết thúc họp lịch sự.', 'N2', 'MEDIUM', 7, 'Cuối buổi họp, bạn cần nhắc lại các quyết định, hẹn gửi biên bản và cảm ơn khách đã dành thời gian.', 'Phòng họp trực tuyến', 'Buổi chiều', '{"goals":[{"code":"KETTEI","type":"MISSION","title":"Xác nhận nội dung quyết định","required":true,"conditions":[{"type":"KEYWORD","value":"決定事項|確認させていただきます|自動で解除"}],"description":"Nêu từng điểm đã chốt kèm ai làm, khi nào.","displayOrder":1},{"code":"GIJIROKU","type":"MISSION","title":"Hẹn gửi biên bản","required":true,"conditions":[{"type":"KEYWORD","value":"議事録|本日中|ご指摘ください"}],"description":"Hẹn soạn và gửi biên bản, mời khách chỉ ra nếu sai.","displayOrder":2},{"code":"KANSHA","type":"MISSION","title":"Cảm ơn và kết thúc","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございました|お時間をいただき"}],"description":"Cảm ơn khách đã dành thời gian ở thể quá khứ lịch sự.","displayOrder":3}],"states":[{"code":"SUMMARY","name":"Xác nhận nội dung","next":"MINUTES","prompt":"Mời người học nhắc lại các nội dung đã quyết định.","allowedGoalCodes":["KETTEI"],"suggestedReplies":["最後に、本日の決定事項を確認させていただきます。","一点目、アカウントのロックは30分後に自動で解除します。二点目、CSV出力機能の見積もりを、明日中に弊社から提出いたします。"]},{"code":"MINUTES","name":"Hẹn gửi biên bản","next":"CLOSE","prompt":"Khách xác nhận đúng, mời người học hẹn gửi biên bản.","allowedGoalCodes":["GIJIROKU"],"suggestedReplies":["議事録は本日中に作成して共有いたします。内容に相違がございましたら、ご指摘ください。"],"transitionText":"Sau khi khách xác nhận nội dung…"},{"code":"CLOSE","name":"Cảm ơn và kết thúc","next":"END","prompt":"Mời người học cảm ơn khách và kết thúc buổi họp.","allowedGoalCodes":["KANSHA"],"suggestedReplies":["本日はお忙しいところ、お時間をいただきありがとうございました。"],"transitionText":"Sau khi khách nhờ gửi biên bản…"}],"endings":{"success":{"code":"SUCCESS","title":"Kết thúc họp xong","message":"こちらこそ、ありがとうございました。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"SUMMARY"}', '{"grammar":[{"pattern":"〜を確認させていただきます","example":"本日の決定事項を確認させていただきます。","explanation":"Thói quen bắt buộc của BrSE trước khi kết thúc họp."},{"pattern":"相違がございましたら、ご指摘ください","example":"内容に相違がございましたら、ご指摘ください。","explanation":"Mời khách phản hồi nếu biên bản có chỗ sai lệch."}],"vocabulary":[{"jlpt":"N2","term":"決定事項","reading":"けっていじこう","meaning":"nội dung đã quyết định","example":"本日の決定事項を確認させていただきます。"},{"jlpt":"N2","term":"議事録","reading":"ぎじろく","meaning":"biên bản cuộc họp","example":"議事録は本日中に作成して共有いたします。"},{"jlpt":"N2","term":"相違","reading":"そうい","meaning":"sai lệch","example":"内容に相違がございましたら、ご指摘ください。"},{"jlpt":"N2","term":"弊社","reading":"へいしゃ","meaning":"công ty chúng tôi (khiêm nhường)","example":"見積もりを、明日中に弊社から提出いたします。"}],"exampleDialogue":[{"text":"最後に、本日の決定事項を確認させていただきます。","speaker":"learner","translation":"Cuối cùng, cho phép tôi xác nhận lại các nội dung đã quyết định hôm nay."},{"text":"一点目、アカウントのロックは30分後に自動で解除します。二点目、CSV出力機能の見積もりを、明日中に弊社から提出いたします。","speaker":"learner","translation":"Thứ nhất, tài khoản bị khóa sẽ tự động mở sau 30 phút. Thứ hai, trong ngày mai công ty chúng tôi sẽ gửi bản ước tính chức năng xuất CSV."},{"text":"はい、それで合っています。","speaker":"ai","translation":"Vâng, đúng như vậy."},{"text":"議事録は本日中に作成して共有いたします。内容に相違がございましたら、ご指摘ください。","speaker":"learner","translation":"Trong hôm nay tôi sẽ soạn biên bản họp và chia sẻ. Nếu nội dung có chỗ sai lệch, mong anh chỉ ra giúp."},{"text":"本日はお忙しいところ、お時間をいただきありがとうございました。","speaker":"learner","translation":"Cảm ơn anh hôm nay đã dành thời gian dù rất bận."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-truong-nhom-ky-thuat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Tiếp nhận góp ý code review', 'cpath-brse-11', 'Bạn cảm ơn góp ý, nhận lỗi thiếu log, đồng ý gom code trùng lặp và hẹn sửa xong rồi xin review lại.', 'N2', 'MEDIUM', 8, 'Trưởng nhóm kỹ thuật phía khách hàng review pull request và đưa góp ý, bạn tiếp nhận và hẹn sửa.', 'Phòng họp trực tuyến', 'Buổi chiều', '{"goals":[{"code":"UKETSUKE","type":"MISSION","title":"Đón nhận góp ý","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございます|お願いいたします"}],"description":"Cảm ơn và mời đối phương nói tiếp.","displayOrder":1},{"code":"LOG","type":"MISSION","title":"Nhận lỗi thiếu log","required":true,"conditions":[{"type":"KEYWORD","value":"ご指摘ありがとうございます|ログを出力|修正いたします"}],"description":"Nhận góp ý và nói sẽ sửa để ghi log trong xử lý ngoại lệ.","displayOrder":2},{"code":"KYOUTSUU","type":"MISSION","title":"Đồng ý gom code chung","required":true,"conditions":[{"type":"KEYWORD","value":"おっしゃるとおりです|共通のバリデーションクラス|回帰テスト"}],"description":"Đồng ý gom vào class validation chung và chạy test hồi quy.","displayOrder":3},{"code":"SAIREVIEW","type":"MISSION","title":"Hẹn sửa và xin review lại","required":true,"conditions":[{"type":"KEYWORD","value":"本日中に修正|再レビューを依頼"}],"description":"Hẹn sửa trong hôm nay và gửi yêu cầu review lại.","displayOrder":4}],"states":[{"code":"FEEDBACK","name":"Nhận góp ý","next":"LOGFIX","prompt":"Đưa góp ý đầu tiên về việc thiếu log, mời người học tiếp nhận.","allowedGoalCodes":["UKETSUKE"],"suggestedReplies":["ありがとうございます。お願いいたします。"]},{"code":"LOGFIX","name":"Nhận lỗi thiếu log","next":"REFACTOR","prompt":"Mời người học xác nhận cách sửa lỗi thiếu log.","allowedGoalCodes":["LOG"],"suggestedReplies":["ご指摘ありがとうございます。例外処理の中でログを出力するよう修正いたします。"],"transitionText":"Sau khi nhận góp ý…"},{"code":"REFACTOR","name":"Gom code trùng lặp","next":"DONE","prompt":"Góp ý gom đoạn kiểm tra đầu vào dùng chung, mời người học đồng ý.","allowedGoalCodes":["KYOUTSUU"],"suggestedReplies":["おっしゃるとおりです。共通のバリデーションクラスにまとめます。","影響範囲を確認したうえで、既存画面の回帰テストも実施いたします。"],"transitionText":"Sau khi sửa phần log…"},{"code":"DONE","name":"Hẹn sửa và xin review lại","next":"END","prompt":"Khách dặn sửa xong thì xin review lại, mời người học hẹn thời gian.","allowedGoalCodes":["SAIREVIEW"],"suggestedReplies":["承知いたしました。本日中に修正して、再レビューを依頼いたします。"],"transitionText":"Sau khi thống nhất cách sửa…"}],"endings":{"success":{"code":"SUCCESS","title":"Tiếp nhận góp ý xong","message":"お願いします。修正が終わったら、再レビューを依頼してください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"FEEDBACK"}', '{"grammar":[{"pattern":"ご指摘ありがとうございます","example":"ご指摘ありがとうございます。例外処理の中でログを出力するよう修正いたします。","explanation":"Câu mở đầu chuẩn khi nhận góp ý, kể cả khi chưa đồng ý hoàn toàn."},{"pattern":"〜たうえで","example":"影響範囲を確認したうえで、回帰テストも実施いたします。","explanation":"Nhấn mạnh làm bước kiểm tra trước, rồi mới làm bước tiếp theo (N2)."}],"vocabulary":[{"jlpt":"N2","term":"例外処理","reading":"れいがいしょり","meaning":"xử lý ngoại lệ","example":"例外処理の中でログを出力します。"},{"jlpt":"N2","term":"共通化","reading":"きょうつうか","meaning":"gom thành dùng chung","example":"同じ入力チェックを共通化できませんか。"},{"jlpt":"N2","term":"回帰テスト","reading":"かいきテスト","meaning":"kiểm thử hồi quy","example":"既存画面の回帰テストも実施いたします。"},{"jlpt":"N2","term":"レビュー","reading":"レビュー","meaning":"review","example":"修正が終わったら、再レビューを依頼してください。"}],"exampleDialogue":[{"text":"プルリクエストを確認しました。何点か指摘があります。","speaker":"ai","translation":"Tôi đã xem pull request. Có vài điểm cần góp ý."},{"text":"ありがとうございます。お願いいたします。","speaker":"learner","translation":"Cảm ơn anh. Anh cứ nói ạ."},{"text":"まず、ログイン処理で例外が発生した場合、エラーログが出力されていません。","speaker":"ai","translation":"Trước tiên, khi xử lý đăng nhập phát sinh ngoại lệ thì không có log lỗi nào được ghi ra."},{"text":"ご指摘ありがとうございます。例外処理の中でログを出力するよう修正いたします。","speaker":"learner","translation":"Cảm ơn anh đã chỉ ra. Tôi sẽ sửa để ghi log trong phần xử lý ngoại lệ."},{"text":"それから、同じ入力チェックが3つの画面に書かれていますね。共通化できませんか。","speaker":"ai","translation":"Ngoài ra, cùng một đoạn kiểm tra đầu vào được viết ở 3 màn hình. Gom lại dùng chung được không?"},{"text":"おっしゃるとおりです。共通のバリデーションクラスにまとめます。影響範囲を確認したうえで、既存画面の回帰テストも実施いたします。","speaker":"learner","translation":"Anh nói đúng ạ. Tôi sẽ gom vào một class validation dùng chung. Sau khi xác nhận phạm vi ảnh hưởng, tôi sẽ chạy cả test hồi quy cho các màn hình hiện có."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-quan-ly-du-an'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo tiến độ', 'cpath-brse-16', 'Bạn mở đầu báo cáo, nêu việc đã xong và việc sắp làm, rồi nhận lời báo khi có vấn đề.', 'N2', 'MEDIUM', 6, 'Bạn báo cáo tiến độ phát triển cho PM nội bộ (anh Phạm).', 'Văn phòng, nói chuyện với PM', 'Buổi sáng', '{"goals":[{"code":"HOUKOKU","type":"MISSION","title":"Mở đầu báo cáo","required":true,"conditions":[{"type":"KEYWORD","value":"進捗をご報告します|開発"}],"description":"Nói rõ mình báo cáo tiến độ phát triển.","displayOrder":1},{"code":"SHURYOU","type":"MISSION","title":"Nêu việc đã xong","required":true,"conditions":[{"type":"KEYWORD","value":"実装が終わりました|完了"}],"description":"Nêu phần đã hoàn thành.","displayOrder":2},{"code":"TSUGI","type":"MISSION","title":"Nêu việc sắp làm","required":true,"conditions":[{"type":"KEYWORD","value":"APIの連携に入ります|明日から"}],"description":"Nêu kế hoạch tiếp theo là kết nối API.","displayOrder":3}],"states":[{"code":"REPORT","name":"Mở đầu báo cáo","next":"DONE","prompt":"PM mời báo cáo, mời người học nêu việc đã hoàn thành.","allowedGoalCodes":["HOUKOKU"],"suggestedReplies":["ファムさん、開発の進捗をご報告します。"]},{"code":"DONE","name":"Nêu việc đã xong","next":"NEXT","prompt":"Mời người học nói việc đã hoàn thành.","allowedGoalCodes":["SHURYOU"],"suggestedReplies":["昨日までに画面の実装が終わりました。"],"transitionText":"Sau khi mở đầu…"},{"code":"NEXT","name":"Nêu việc sắp làm","next":"END","prompt":"PM hỏi việc tiếp theo, mời người học nêu kế hoạch.","allowedGoalCodes":["TSUGI"],"suggestedReplies":["明日からAPIの連携に入ります。"],"transitionText":"Sau khi báo việc đã xong…"}],"endings":{"success":{"code":"SUCCESS","title":"Báo cáo tiến độ xong","message":"分かりました。何か問題があれば教えてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"REPORT"}', '{"grammar":[{"pattern":"〜の進捗をご報告します","example":"開発の進捗をご報告します。","explanation":"Mở đầu báo cáo tiến độ."},{"pattern":"〜に入ります","example":"明日からAPIの連携に入ります。","explanation":"Nói việc sắp bắt đầu làm."}],"vocabulary":[{"jlpt":"N2","term":"実装","reading":"じっそう","meaning":"hiện thực hóa, viết code","example":"画面の実装が終わりました。"},{"jlpt":"N2","term":"進捗","reading":"しんちょく","meaning":"tiến độ","example":"開発の進捗をご報告します。"},{"jlpt":"N2","term":"連携","reading":"れんけい","meaning":"kết nối, liên kết","example":"明日からAPIの連携に入ります。"},{"jlpt":"N2","term":"順調","reading":"じゅんちょう","meaning":"thuận lợi","example":"順調ですね。次は何をしますか。"}],"exampleDialogue":[{"text":"ファムさん、開発の進捗をご報告します。","speaker":"learner","translation":"Anh Phạm, tôi báo cáo tiến độ phát triển ạ."},{"text":"お願いします。","speaker":"ai","translation":"Vâng, anh báo cáo đi."},{"text":"昨日までに画面の実装が終わりました。","speaker":"learner","translation":"Đến hôm qua đã xong phần lập trình màn hình ạ."},{"text":"順調ですね。次は何をしますか。","speaker":"ai","translation":"Thuận lợi nhỉ. Tiếp theo anh làm gì ạ?"},{"text":"明日からAPIの連携に入ります。","speaker":"learner","translation":"Từ mai tôi bắt đầu kết nối API ạ."},{"text":"分かりました。何か問題があれば教えてください。","speaker":"ai","translation":"Được ạ. Có vấn đề gì thì báo tôi."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận môi trường phát triển', 'cpath-brse-17', 'Bạn hỏi địa chỉ kết nối API, hỏi cách lấy khóa xác thực rồi hẹn liên lạc lại khi kết nối được.', 'N2', 'MEDIUM', 6, 'Bạn cần hỏi khách hàng về địa chỉ kết nối API dùng cho phát triển.', 'Văn phòng, qua điện thoại', 'Buổi sáng', '{"goals":[{"code":"SETSUZOKU","type":"MISSION","title":"Hỏi địa chỉ kết nối","required":true,"conditions":[{"type":"KEYWORD","value":"接続先|教えてください|API"}],"description":"Hỏi địa chỉ kết nối API dùng cho phát triển.","displayOrder":1},{"code":"NINSHOU","type":"MISSION","title":"Hỏi cách lấy khóa xác thực","required":true,"conditions":[{"type":"KEYWORD","value":"認証キー|どこで取得できますか"}],"description":"Hỏi nơi lấy khóa xác thực.","displayOrder":2},{"code":"YAKUSOKU","type":"MISSION","title":"Hẹn liên lạc lại","required":true,"conditions":[{"type":"KEYWORD","value":"接続できたら|連絡します"}],"description":"Hẹn liên lạc lại khi kết nối được.","displayOrder":3}],"states":[{"code":"ASK","name":"Hỏi địa chỉ kết nối","next":"KEY","prompt":"Khách nói đã gửi URL qua email, mời người học hỏi tiếp khóa xác thực.","allowedGoalCodes":["SETSUZOKU"],"suggestedReplies":["開発用のAPIの接続先を教えてください。"]},{"code":"KEY","name":"Hỏi cách lấy khóa xác thực","next":"CONTACT","prompt":"Mời người học hỏi nơi lấy khóa xác thực.","allowedGoalCodes":["NINSHOU"],"suggestedReplies":["認証キーはどこで取得できますか。"],"transitionText":"Sau khi khách cho URL…"},{"code":"CONTACT","name":"Hẹn liên lạc lại","next":"END","prompt":"Khách nói cấp được trên màn hình quản trị, mời người học hẹn liên lạc lại.","allowedGoalCodes":["YAKUSOKU"],"suggestedReplies":["分かりました。接続できたらまた連絡します。"],"transitionText":"Sau khi khách hướng dẫn…"}],"endings":{"success":{"code":"SUCCESS","title":"Xác nhận môi trường xong","message":"よろしくお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ASK"}', '{"grammar":[{"pattern":"〜を教えてください","example":"開発用のAPIの接続先を教えてください。","explanation":"Xin thông tin kỹ thuật."},{"pattern":"〜はどこで取得できますか","example":"認証キーはどこで取得できますか。","explanation":"Hỏi cách lấy thông tin."}],"vocabulary":[{"jlpt":"N2","term":"接続先","reading":"せつぞくさき","meaning":"địa chỉ kết nối","example":"APIの接続先を教えてください。"},{"jlpt":"N2","term":"認証キー","reading":"にんしょうキー","meaning":"khóa xác thực","example":"認証キーはどこで取得できますか。"},{"jlpt":"N2","term":"取得","reading":"しゅとく","meaning":"lấy, nhận","example":"認証キーを取得できますか。"},{"jlpt":"N2","term":"テスト環境","reading":"テストかんきょう","meaning":"môi trường kiểm thử","example":"テスト環境のURLをメールで送りました。"}],"exampleDialogue":[{"text":"田中さん、開発用のAPIの接続先を教えてください。","speaker":"learner","translation":"Anh Tanaka, cho tôi xin địa chỉ kết nối API dùng cho phát triển ạ."},{"text":"はい、テスト環境のURLをメールで送りました。","speaker":"ai","translation":"Vâng, tôi đã gửi URL môi trường kiểm thử qua email rồi."},{"text":"認証キーはどこで取得できますか。","speaker":"learner","translation":"Khóa xác thực lấy ở đâu được ạ?"},{"text":"管理画面で発行できます。","speaker":"ai","translation":"Có thể cấp trên màn hình quản trị ạ."},{"text":"分かりました。接続できたらまた連絡します。","speaker":"learner","translation":"Tôi hiểu rồi. Kết nối được tôi sẽ liên lạc lại ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo kết quả kiểm thử', 'cpath-brse-12', 'Bạn báo số liệu test khớp nhau, giải thích case chưa chạy, nêu chi tiết case không đạt và hẹn gửi evidence.', 'N2', 'HARD', 8, 'Kết thúc đợt test tích hợp, bạn báo cáo số liệu và kế hoạch xử lý các case không đạt.', 'Phòng họp trực tuyến', 'Buổi chiều', '{"goals":[{"code":"SUUJI","type":"MISSION","title":"Báo số liệu test","required":true,"conditions":[{"type":"KEYWORD","value":"全420件|合格|不合格|消化"}],"description":"Báo số case đã thực hiện, đạt và không đạt khớp nhau.","displayOrder":1},{"code":"NOKORI","type":"MISSION","title":"Giải thích case chưa chạy","required":true,"conditions":[{"type":"KEYWORD","value":"外部システム|検証環境|準備でき次第"}],"description":"Giải thích 8 case còn lại chưa chạy được vì thiếu môi trường đối tác.","displayOrder":2},{"code":"UCHIWAKE","type":"MISSION","title":"Nêu chi tiết case không đạt","required":true,"conditions":[{"type":"KEYWORD","value":"重大度|高|再テスト"}],"description":"Nêu chi tiết mức độ và ưu tiên sửa lỗi mức cao.","displayOrder":3},{"code":"EVIDENCE","type":"MISSION","title":"Hẹn gửi evidence","required":true,"conditions":[{"type":"KEYWORD","value":"報告書|エビデンス|本日中にお送り"}],"description":"Hẹn gửi báo cáo và bằng chứng trong hôm nay.","displayOrder":4}],"states":[{"code":"NUMBERS","name":"Báo số liệu test","next":"REMAIN","prompt":"Mời người học báo số liệu case đã chạy, đạt và không đạt.","allowedGoalCodes":["SUUJI"],"suggestedReplies":["テストケース全420件のうち412件を消化し、合格は398件、不合格は14件でした。"]},{"code":"REMAIN","name":"Giải thích case chưa chạy","next":"DETAIL","prompt":"Khách hỏi 8 case còn lại, mời người học giải thích.","allowedGoalCodes":["NOKORI"],"suggestedReplies":["外部システムとの接続が必要なケースで、先方の検証環境が準備でき次第、実施する予定です。"],"transitionText":"Sau khi báo số liệu…"},{"code":"DETAIL","name":"Nêu chi tiết case không đạt","next":"SEND","prompt":"Khách hỏi chi tiết 14 case không đạt, mời người học nêu phân loại.","allowedGoalCodes":["UCHIWAKE"],"suggestedReplies":["重大度「高」が2件、「中」が5件、「低」が7件です。","「高」の2件は明日までに修正し、再テストいたします。"],"transitionText":"Sau khi giải thích case chưa chạy…"},{"code":"SEND","name":"Hẹn gửi evidence","next":"END","prompt":"Khách yêu cầu gửi kèm bằng chứng, mời người học hẹn gửi.","allowedGoalCodes":["EVIDENCE"],"suggestedReplies":["かしこまりました。テスト結果報告書とエビデンスをまとめて、本日中にお送りいたします。"],"transitionText":"Sau khi khách yêu cầu evidence…"}],"endings":{"success":{"code":"SUCCESS","title":"Báo cáo kết quả test xong","message":"わかりました。エビデンスも一緒に送ってください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"NUMBERS"}', '{"grammar":[{"pattern":"全〜件のうち〜件を消化し","example":"テストケース全420件のうち412件を消化し、合格は398件、不合格は14件でした。","explanation":"Cách báo số liệu test chuẩn trong dự án Nhật."},{"pattern":"〜次第","example":"先方の検証環境が準備でき次第、実施する予定です。","explanation":"Nghĩa là \'ngay khi ~\', dùng khi việc của mình phụ thuộc vào bên khác (N2)."}],"vocabulary":[{"jlpt":"N2","term":"消化","reading":"しょうか","meaning":"thực hiện xong (test case)","example":"412件を消化しました。"},{"jlpt":"N2","term":"不合格","reading":"ふごうかく","meaning":"không đạt","example":"不合格は14件でした。"},{"jlpt":"N2","term":"内訳","reading":"うちわけ","meaning":"chi tiết phân loại","example":"不合格の14件の内訳を教えてください。"},{"jlpt":"N2","term":"エビデンス","reading":"エビデンス","meaning":"bằng chứng (ảnh chụp, log)","example":"エビデンスも一緒に送ってください。"}],"exampleDialogue":[{"text":"結合テストの結果をご報告いたします。","speaker":"learner","translation":"Tôi xin báo cáo kết quả test tích hợp."},{"text":"テストケース全420件のうち412件を消化し、合格は398件、不合格は14件でした。","speaker":"learner","translation":"Trong tổng số 420 test case, đã thực hiện 412 case, đạt 398 case và không đạt 14 case."},{"text":"残りの8件はどうなっていますか。","speaker":"ai","translation":"Còn 8 case còn lại thì sao?"},{"text":"外部システムとの接続が必要なケースで、先方の検証環境が準備でき次第、実施する予定です。","speaker":"learner","translation":"Đó là các case cần kết nối với hệ thống bên ngoài, chúng tôi sẽ thực hiện ngay khi môi trường staging phía đối tác sẵn sàng."},{"text":"不合格の14件の内訳を教えてください。","speaker":"ai","translation":"Cho tôi biết chi tiết 14 case không đạt."},{"text":"重大度「高」が2件、「中」が5件、「低」が7件です。「高」の2件は明日までに修正し、再テストいたします。","speaker":"learner","translation":"Mức độ nghiêm trọng \'cao\' 2 case, \'trung bình\' 5 case, \'thấp\' 7 case. 2 case mức \'cao\' sẽ được sửa và test lại trước ngày mai."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-quan-ly-du-an'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo kết quả kiểm thử', 'cpath-brse-18', 'Bạn báo số ca đạt và không đạt, nêu trạng thái từng ca lỗi rồi nhận lời chia sẻ kết quả trong hôm nay.', 'N2', 'MEDIUM', 6, 'Bạn báo cáo kết quả kiểm thử tích hợp cho PM nội bộ (anh Phạm).', 'Văn phòng, nói chuyện với PM', 'Buổi chiều', '{"goals":[{"code":"HOUKOKU","type":"MISSION","title":"Mở đầu báo cáo","required":true,"conditions":[{"type":"KEYWORD","value":"結合テストの結果をご報告します"}],"description":"Nói rõ mình báo cáo kết quả kiểm thử tích hợp.","displayOrder":1},{"code":"SUUJI","type":"MISSION","title":"Báo số ca đạt và không đạt","required":true,"conditions":[{"type":"KEYWORD","value":"五十のテストケース|四十八件が合格"}],"description":"Nêu số ca đạt trong tổng số ca kiểm thử.","displayOrder":2},{"code":"GENIN","type":"MISSION","title":"Nêu trạng thái từng ca lỗi","required":true,"conditions":[{"type":"KEYWORD","value":"修正済み|調査中"}],"description":"Nêu một ca đã sửa xong, một ca đang điều tra.","displayOrder":3}],"states":[{"code":"REPORT","name":"Mở đầu báo cáo","next":"NUMBERS","prompt":"PM hỏi kết quả, mời người học báo số ca đạt.","allowedGoalCodes":["HOUKOKU"],"suggestedReplies":["ファムさん、結合テストの結果をご報告します。"]},{"code":"NUMBERS","name":"Báo số ca đạt","next":"CAUSE","prompt":"Mời người học nêu số ca đạt và không đạt.","allowedGoalCodes":["SUUJI"],"suggestedReplies":["五十のテストケースのうち、四十八件が合格しました。"],"transitionText":"Sau khi mở đầu…"},{"code":"CAUSE","name":"Nêu trạng thái từng ca lỗi","next":"END","prompt":"PM hỏi nguyên nhân, mời người học nêu trạng thái từng ca lỗi.","allowedGoalCodes":["GENIN"],"suggestedReplies":["一件は修正済みです。もう一件は調査中です。"],"transitionText":"Sau khi báo số liệu…"}],"endings":{"success":{"code":"SUCCESS","title":"Báo cáo kết quả test xong","message":"分かりました。今日中に結果を共有してください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"REPORT"}', '{"grammar":[{"pattern":"〜の結果をご報告します","example":"結合テストの結果をご報告します。","explanation":"Mở đầu báo cáo kết quả."},{"pattern":"〜中です","example":"もう一件は調査中です。","explanation":"Nói trạng thái đang diễn ra."}],"vocabulary":[{"jlpt":"N2","term":"結合テスト","reading":"けつごうテスト","meaning":"kiểm thử tích hợp","example":"結合テストの結果をご報告します。"},{"jlpt":"N2","term":"合格","reading":"ごうかく","meaning":"đạt","example":"四十八件が合格しました。"},{"jlpt":"N2","term":"不合格","reading":"ふごうかく","meaning":"không đạt","example":"不合格は二件ですね。"},{"jlpt":"N2","term":"調査中","reading":"ちょうさちゅう","meaning":"đang điều tra","example":"もう一件は調査中です。"}],"exampleDialogue":[{"text":"ファムさん、結合テストの結果をご報告します。","speaker":"learner","translation":"Anh Phạm, tôi báo cáo kết quả kiểm thử tích hợp ạ."},{"text":"結果はどうでしたか。","speaker":"ai","translation":"Kết quả thế nào ạ?"},{"text":"五十のテストケースのうち、四十八件が合格しました。","speaker":"learner","translation":"Trong năm mươi ca kiểm thử, bốn mươi tám ca đạt ạ."},{"text":"不合格は二件ですね。原因は分かりましたか。","speaker":"ai","translation":"Hai ca không đạt nhỉ. Đã biết nguyên nhân chưa ạ?"},{"text":"一件は修正済みです。もう一件は調査中です。","speaker":"learner","translation":"Một ca đã sửa xong. Ca còn lại đang điều tra ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận ca kiểm thử', 'cpath-brse-19', 'Bạn nhờ khách xác nhận danh sách, hỏi hạng mục còn thiếu rồi nhận bổ sung ca màn hình lỗi.', 'N2', 'MEDIUM', 6, 'Bạn nhờ khách hàng rà soát danh sách ca kiểm thử và bổ sung hạng mục còn thiếu.', 'Văn phòng, qua điện thoại', 'Buổi chiều', '{"goals":[{"code":"KAKUNIN","type":"MISSION","title":"Nhờ xác nhận danh sách","required":true,"conditions":[{"type":"KEYWORD","value":"テストケースの一覧|確認していただけますか"}],"description":"Nhờ khách xác nhận danh sách ca kiểm thử.","displayOrder":1},{"code":"FUSOKU","type":"MISSION","title":"Hỏi hạng mục còn thiếu","required":true,"conditions":[{"type":"KEYWORD","value":"不足している項目|ありますか"}],"description":"Hỏi có hạng mục nào còn thiếu không.","displayOrder":2},{"code":"TSUIKA","type":"MISSION","title":"Nhận bổ sung ca thiếu","required":true,"conditions":[{"type":"KEYWORD","value":"追加します|そのケース"}],"description":"Nhận lời bổ sung ca còn thiếu.","displayOrder":3}],"states":[{"code":"CONFIRM","name":"Nhờ xác nhận danh sách","next":"MISSING","prompt":"Khách nhận lời xem, mời người học hỏi hạng mục còn thiếu.","allowedGoalCodes":["KAKUNIN"],"suggestedReplies":["テストケースの一覧を確認していただけますか。"]},{"code":"MISSING","name":"Hỏi hạng mục còn thiếu","next":"ADD","prompt":"Mời người học hỏi có hạng mục nào thiếu không.","allowedGoalCodes":["FUSOKU"],"suggestedReplies":["不足している項目はありますか。"],"transitionText":"Sau khi khách nhận lời xem…"},{"code":"ADD","name":"Nhận bổ sung ca thiếu","next":"END","prompt":"Khách nói thiếu ca màn hình lỗi, mời người học nhận bổ sung.","allowedGoalCodes":["TSUIKA"],"suggestedReplies":["では、そのケースを追加します。"],"transitionText":"Sau khi khách chỉ ra chỗ thiếu…"}],"endings":{"success":{"code":"SUCCESS","title":"Xác nhận ca kiểm thử xong","message":"お願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"CONFIRM"}', '{"grammar":[{"pattern":"〜を確認していただけますか","example":"テストケースの一覧を確認していただけますか。","explanation":"Nhờ đối tác rà soát tài liệu."},{"pattern":"〜はありますか","example":"不足している項目はありますか。","explanation":"Hỏi về tình trạng thiếu đủ."}],"vocabulary":[{"jlpt":"N2","term":"テストケース","reading":"テストケース","meaning":"ca kiểm thử","example":"テストケースの一覧を確認していただけますか。"},{"jlpt":"N2","term":"一覧","reading":"いちらん","meaning":"danh sách","example":"テストケースの一覧を確認します。"},{"jlpt":"N2","term":"不足","reading":"ふそく","meaning":"thiếu","example":"不足している項目はありますか。"},{"jlpt":"N2","term":"追加","reading":"ついか","meaning":"thêm","example":"そのケースを追加します。"}],"exampleDialogue":[{"text":"田中さん、テストケースの一覧を確認していただけますか。","speaker":"learner","translation":"Anh Tanaka, anh xác nhận giúp tôi danh sách ca kiểm thử được không ạ?"},{"text":"はい、拝見します。","speaker":"ai","translation":"Vâng, tôi xem ạ."},{"text":"不足している項目はありますか。","speaker":"learner","translation":"Có hạng mục nào còn thiếu không ạ?"},{"text":"エラー画面のケースが足りないようです。","speaker":"ai","translation":"Hình như ca cho màn hình lỗi còn thiếu ạ."},{"text":"では、そのケースを追加します。","speaker":"learner","translation":"Vậy tôi sẽ bổ sung ca đó ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Tiếp nhận báo lỗi từ khách hàng', 'cpath-brse-06', 'Bạn cảm ơn báo lỗi, hỏi điều kiện tái hiện, khoanh vùng rồi hẹn báo nguyên nhân trước giờ cụ thể.', 'N2', 'MEDIUM', 8, 'Khách phát hiện lỗi tìm kiếm trên môi trường staging, bạn hỏi bước tái hiện và hẹn thời gian phản hồi.', 'Phòng họp trực tuyến', 'Buổi chiều', '{"goals":[{"code":"UKETSUKE","type":"MISSION","title":"Cảm ơn và hỏi bước tái hiện","required":true,"conditions":[{"type":"KEYWORD","value":"ご報告ありがとうございます|再現手順を教えていただけますか"}],"description":"Cảm ơn báo lỗi và hỏi các bước tái hiện.","displayOrder":1},{"code":"KIRIWAKE","type":"MISSION","title":"Khoanh vùng điều kiện lỗi","required":true,"conditions":[{"type":"KEYWORD","value":"長音|正常に表示されますか"}],"description":"Nhắc lại điều kiện gây lỗi và hỏi điều kiện khác.","displayOrder":2},{"code":"YAKUSOKU","type":"MISSION","title":"Hẹn thời gian phản hồi","required":true,"conditions":[{"type":"KEYWORD","value":"調査を依頼|17時までに|ご連絡いたします"}],"description":"Hẹn báo nguyên nhân và hướng xử lý trước giờ cụ thể.","displayOrder":3}],"states":[{"code":"REPRO","name":"Hỏi bước tái hiện","next":"ISOLATE","prompt":"Khách báo lỗi, mời người học cảm ơn và hỏi bước tái hiện.","allowedGoalCodes":["UKETSUKE"],"suggestedReplies":["ご報告ありがとうございます。恐れ入りますが、再現手順を教えていただけますか。"]},{"code":"ISOLATE","name":"Khoanh vùng điều kiện lỗi","next":"COMMIT","prompt":"Khách mô tả điều kiện lỗi, mời người học khoanh vùng.","allowedGoalCodes":["KIRIWAKE"],"suggestedReplies":["長音を含む場合ですね。ほかの条件では正常に表示されますか。"],"transitionText":"Sau khi khách cho bước tái hiện…"},{"code":"COMMIT","name":"Hẹn thời gian phản hồi","next":"END","prompt":"Khách xác nhận điều kiện khác vẫn bình thường, mời người học hẹn phản hồi.","allowedGoalCodes":["YAKUSOKU"],"suggestedReplies":["すぐに開発チームに調査を依頼し、本日の17時までに原因と対応方針をご連絡いたします。"],"transitionText":"Sau khi khoanh vùng xong…"}],"endings":{"success":{"code":"SUCCESS","title":"Tiếp nhận báo lỗi xong","message":"わかりました。お願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"REPRO"}', '{"grammar":[{"pattern":"再現手順を教えていただけますか","example":"恐れ入りますが、再現手順を教えていただけますか。","explanation":"Câu đầu tiên luôn phải hỏi khi nhận báo lỗi."},{"pattern":"〜までに原因と対応方針をご連絡いたします","example":"本日の17時までに原因と対応方針をご連絡いたします。","explanation":"Luôn hẹn mốc thời gian cụ thể, không nói chung chung."}],"vocabulary":[{"jlpt":"N2","term":"再現手順","reading":"さいげんてじゅん","meaning":"các bước tái hiện lỗi","example":"再現手順を教えていただけますか。"},{"jlpt":"N2","term":"長音","reading":"ちょうおん","meaning":"trường âm","example":"長音を含むキーワードで検索すると、結果が0件になります。"},{"jlpt":"N2","term":"調査","reading":"ちょうさ","meaning":"điều tra","example":"すぐに開発チームに調査を依頼します。"},{"jlpt":"N2","term":"対応方針","reading":"たいおうほうしん","meaning":"hướng xử lý","example":"原因と対応方針をご連絡いたします。"}],"exampleDialogue":[{"text":"グエンさん、検証環境で確認していたら、検索結果が正しく表示されないんですが。","speaker":"ai","translation":"Anh Nguyễn, tôi kiểm tra trên môi trường staging thì thấy kết quả tìm kiếm hiển thị không đúng."},{"text":"ご報告ありがとうございます。恐れ入りますが、再現手順を教えていただけますか。","speaker":"learner","translation":"Cảm ơn anh đã báo. Phiền anh cho tôi biết các bước tái hiện lỗi được không ạ?"},{"text":"商品名に長音記号の「ー」を含むキーワードで検索すると、結果が0件になります。","speaker":"ai","translation":"Tìm bằng từ khóa có dấu trường âm 「ー」 trong tên sản phẩm thì kết quả ra 0."},{"text":"長音を含む場合ですね。ほかの条件では正常に表示されますか。","speaker":"learner","translation":"Trường hợp có trường âm ạ. Với điều kiện khác thì hiển thị bình thường chứ ạ?"},{"text":"はい、それ以外は問題ありません。","speaker":"ai","translation":"Vâng, ngoài trường hợp đó thì không có vấn đề gì."},{"text":"承知いたしました。すぐに開発チームに調査を依頼し、本日の17時までに原因と対応方針をご連絡いたします。","speaker":"learner","translation":"Tôi hiểu rồi. Tôi sẽ nhờ đội phát triển điều tra ngay, trước 17 giờ hôm nay sẽ báo anh nguyên nhân và hướng xử lý."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo sự cố', 'cpath-brse-20', 'Bạn báo sự cố rõ môi trường, nêu thời điểm bắt đầu, phạm vi ảnh hưởng và dự kiến khôi phục.', 'N2', 'MEDIUM', 7, 'Bạn báo sự cố production cho khách và trả lời các câu hỏi về thời điểm, phạm vi ảnh hưởng.', 'Văn phòng, qua điện thoại', 'Buổi sáng', '{"goals":[{"code":"HOUKOKU","type":"MISSION","title":"Báo sự cố","required":true,"conditions":[{"type":"KEYWORD","value":"障害が発生しました|本番環境"}],"description":"Báo sự cố xảy ra trên môi trường production.","displayOrder":1},{"code":"JIKOKU","type":"MISSION","title":"Nêu thời điểm bắt đầu","required":true,"conditions":[{"type":"KEYWORD","value":"九時ごろ|原因を調査しています"}],"description":"Nêu giờ bắt đầu và tình trạng đang điều tra.","displayOrder":2},{"code":"EIKYOU","type":"MISSION","title":"Nêu phạm vi ảnh hưởng","required":true,"conditions":[{"type":"KEYWORD","value":"ログイン機能|回避策"}],"description":"Nêu chức năng bị ảnh hưởng và biện pháp tạm thời.","displayOrder":3},{"code":"FUKKYUU","type":"MISSION","title":"Nêu dự kiến khôi phục","required":true,"conditions":[{"type":"KEYWORD","value":"明日の朝まで|復旧する予定"}],"description":"Nêu dự kiến khôi phục trước sáng mai.","displayOrder":4}],"states":[{"code":"ALERT","name":"Báo sự cố","next":"TIME","prompt":"Khách hỏi từ khi nào, mời người học nêu thời điểm bắt đầu.","allowedGoalCodes":["HOUKOKU"],"suggestedReplies":["田中さん、本番環境で障害が発生しました。"]},{"code":"TIME","name":"Nêu thời điểm bắt đầu","next":"IMPACT","prompt":"Mời người học nêu giờ bắt đầu và tình trạng điều tra.","allowedGoalCodes":["JIKOKU"],"suggestedReplies":["今朝九時ごろからです。現在、原因を調査しています。"],"transitionText":"Sau khi khách hỏi từ khi nào…"},{"code":"IMPACT","name":"Nêu phạm vi ảnh hưởng","next":"RECOVERY","prompt":"Khách hỏi phạm vi ảnh hưởng, mời người học nêu chức năng bị ảnh hưởng.","allowedGoalCodes":["EIKYOU"],"suggestedReplies":["ログイン機能に影響しています。回避策を準備します。"],"transitionText":"Sau khi nêu thời điểm…"},{"code":"RECOVERY","name":"Nêu dự kiến khôi phục","next":"END","prompt":"Khách hỏi dự kiến khôi phục, mời người học nêu thời điểm.","allowedGoalCodes":["FUKKYUU"],"suggestedReplies":["明日の朝までには復旧する予定です。"],"transitionText":"Sau khi nêu phạm vi…"}],"endings":{"success":{"code":"SUCCESS","title":"Báo cáo sự cố xong","message":"分かりました。復旧の見込みを教えてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"ALERT"}', '{"grammar":[{"pattern":"〜で障害が発生しました","example":"本番環境で障害が発生しました。","explanation":"Thông báo sự cố."},{"pattern":"〜を調査しています","example":"現在、原因を調査しています。","explanation":"Nói đang tìm nguyên nhân."}],"vocabulary":[{"jlpt":"N2","term":"障害","reading":"しょうがい","meaning":"sự cố","example":"本番環境で障害が発生しました。"},{"jlpt":"N2","term":"本番環境","reading":"ほんばんかんきょう","meaning":"môi trường production","example":"本番環境で障害が発生しました。"},{"jlpt":"N2","term":"影響","reading":"えいきょう","meaning":"ảnh hưởng","example":"ログイン機能に影響しています。"},{"jlpt":"N2","term":"復旧","reading":"ふっきゅう","meaning":"khôi phục","example":"明日の朝までには復旧する予定です。"}],"exampleDialogue":[{"text":"田中さん、本番環境で障害が発生しました。","speaker":"learner","translation":"Anh Tanaka, sự cố đã xảy ra trên môi trường chính thức ạ."},{"text":"いつからですか。","speaker":"ai","translation":"Từ khi nào ạ?"},{"text":"今朝九時ごろからです。現在、原因を調査しています。","speaker":"learner","translation":"Từ khoảng chín giờ sáng nay. Hiện chúng tôi đang điều tra nguyên nhân ạ."},{"text":"影響範囲はどのくらいですか。","speaker":"ai","translation":"Phạm vi ảnh hưởng khoảng bao nhiêu ạ?"},{"text":"ログイン機能に影響しています。回避策を準備します。","speaker":"learner","translation":"Ảnh hưởng tới chức năng đăng nhập. Chúng tôi sẽ chuẩn bị biện pháp tạm thời ạ."},{"text":"明日の朝までには復旧する予定です。","speaker":"learner","translation":"Dự kiến sẽ khôi phục trước sáng mai ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-quan-ly-du-an'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo hoàn tất sửa lỗi', 'cpath-brse-21', 'Bạn báo đã sửa xong, khẳng định không tái phát, nhận lời triển khai tối nay và báo kết quả sau.', 'N2', 'MEDIUM', 6, 'Bạn báo đã sửa xong lỗi của sự cố hôm trước và xin xác nhận triển khai.', 'Văn phòng, nói chuyện với PM', 'Buổi chiều', '{"goals":[{"code":"HOUKOKU","type":"MISSION","title":"Báo đã sửa xong","required":true,"conditions":[{"type":"KEYWORD","value":"修正が完了しました|障害"}],"description":"Nói rõ việc sửa lỗi của sự cố đã hoàn tất.","displayOrder":1},{"code":"SAIHATSU","type":"MISSION","title":"Khẳng định không tái phát","required":true,"conditions":[{"type":"KEYWORD","value":"ありません|回帰テスト|合格"}],"description":"Khẳng định không tái phát và nêu bằng chứng test.","displayOrder":2},{"code":"HANEIKI","type":"MISSION","title":"Nhận lời triển khai","required":true,"conditions":[{"type":"KEYWORD","value":"承知しました|反映します"}],"description":"Nhận lời triển khai lên production trong hôm nay.","displayOrder":3}],"states":[{"code":"DONE","name":"Báo đã sửa xong","next":"NORISK","prompt":"PM hỏi nguy cơ tái phát, mời người học khẳng định không còn.","allowedGoalCodes":["HOUKOKU"],"suggestedReplies":["ファムさん、先日の障害の修正が完了しました。"]},{"code":"NORISK","name":"Khẳng định không tái phát","next":"DEPLOY","prompt":"Mời người học khẳng định không tái phát và nêu bằng chứng test.","allowedGoalCodes":["SAIHATSU"],"suggestedReplies":["ありません。回帰テストも全て合格しました。"],"transitionText":"Sau khi báo sửa xong…"},{"code":"DEPLOY","name":"Nhận lời triển khai","next":"END","prompt":"PM giao triển khai lên production, mời người học nhận lời và nêu thời điểm.","allowedGoalCodes":["HANEIKI"],"suggestedReplies":["承知しました。今夜中に反映します。"],"transitionText":"Sau khi khẳng định không tái phát…"}],"endings":{"success":{"code":"SUCCESS","title":"Báo hoàn tất sửa lỗi xong","message":"反映後、また結果を教えてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"DONE"}', '{"grammar":[{"pattern":"〜が完了しました","example":"先日の障害の修正が完了しました。","explanation":"Báo cáo việc đã xong."},{"pattern":"〜の恐れはありますか","example":"再発の恐れはありますか。","explanation":"Hỏi về rủi ro."}],"vocabulary":[{"jlpt":"N2","term":"修正","reading":"しゅうせい","meaning":"sửa","example":"障害の修正が完了しました。"},{"jlpt":"N2","term":"再発","reading":"さいはつ","meaning":"tái phát","example":"再発の恐れはありません。"},{"jlpt":"N2","term":"回帰テスト","reading":"かいきテスト","meaning":"kiểm thử hồi quy","example":"回帰テストも全て合格しました。"},{"jlpt":"N2","term":"反映","reading":"はんえい","meaning":"triển khai, phản ánh","example":"本番環境への反映をお願いします。"}],"exampleDialogue":[{"text":"ファムさん、先日の障害の修正が完了しました。","speaker":"learner","translation":"Anh Phạm, việc sửa lỗi của sự cố hôm trước đã hoàn tất ạ."},{"text":"お疲れさまです。再発の恐れはありますか。","speaker":"ai","translation":"Vất vả rồi. Có nguy cơ tái phát không ạ?"},{"text":"ありません。回帰テストも全て合格しました。","speaker":"learner","translation":"Không ạ. Kiểm thử hồi quy cũng đạt toàn bộ rồi ạ."},{"text":"では、本番環境への反映をお願いします。","speaker":"ai","translation":"Vậy anh triển khai lên môi trường chính thức nhé."},{"text":"承知しました。今夜中に反映します。","speaker":"learner","translation":"Tôi rõ rồi ạ. Tối nay tôi sẽ triển khai."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo sơ bộ sự cố production', 'cpath-brse-13', 'Bạn báo gấp, nêu mức ảnh hưởng và giả thuyết nguyên nhân, rồi xin phê duyệt rollback trong 30 phút.', 'N2', 'HARD', 8, 'Production gặp sự cố sau đợt release buổi sáng, bạn gọi báo khách ngay và xin phê duyệt rollback.', 'Văn phòng, qua điện thoại', 'Buổi sáng', '{"goals":[{"code":"SHIKYUU","type":"MISSION","title":"Báo gấp sự cố","required":true,"conditions":[{"type":"KEYWORD","value":"至急ご報告いたします|障害が発生|決済処理"}],"description":"Báo gấp sự cố production kèm thời điểm và hiện tượng.","displayOrder":1},{"code":"EIKYOU","type":"MISSION","title":"Nêu mức ảnh hưởng","required":true,"conditions":[{"type":"KEYWORD","value":"3割|エラー|ユーザー"}],"description":"Nêu khoảng 30% lượt thanh toán bị lỗi.","displayOrder":2},{"code":"SETTEI","type":"MISSION","title":"Nêu giả thuyết nguyên nhân","required":true,"conditions":[{"type":"KEYWORD","value":"設定ファイル|可能性が高い|調査中"}],"description":"Nêu khả năng cao liên quan file cấu hình đợt release.","displayOrder":3},{"code":"SHOUNIN","type":"MISSION","title":"Xin phê duyệt rollback","required":true,"conditions":[{"type":"KEYWORD","value":"承認|30分以内|リリース前の状態"}],"description":"Xin phê duyệt đưa về trạng thái trước release trong 30 phút.","displayOrder":4}],"states":[{"code":"URGENT","name":"Báo gấp sự cố","next":"IMPACT","prompt":"Khách hỏi mức ảnh hưởng, mời người học nêu số liệu.","allowedGoalCodes":["SHIKYUU"],"suggestedReplies":["至急ご報告いたします。本日10時頃から、本番環境で決済処理がエラーになる障害が発生しております。"]},{"code":"IMPACT","name":"Nêu mức ảnh hưởng","next":"CAUSE","prompt":"Mời người học nêu mức ảnh hưởng tới người dùng.","allowedGoalCodes":["EIKYOU"],"suggestedReplies":["現時点で、決済を試みたユーザーのうち約3割がエラーになっております。"],"transitionText":"Sau khi khách hỏi ảnh hưởng…"},{"code":"CAUSE","name":"Nêu giả thuyết nguyên nhân","next":"ROLLBACK","prompt":"Mời người học nêu giả thuyết nguyên nhân khi chưa chắc chắn.","allowedGoalCodes":["SETTEI"],"suggestedReplies":["原因は調査中ですが、今朝のリリースで更新した設定ファイルが関係している可能性が高いと見ております。"],"transitionText":"Sau khi nêu mức ảnh hưởng…"},{"code":"ROLLBACK","name":"Xin phê duyệt rollback","next":"END","prompt":"Khách hỏi có quay lại ngay được không, mời người học xin phê duyệt.","allowedGoalCodes":["SHOUNIN"],"suggestedReplies":["暫定対応として、30分以内にリリース前の状態に戻す予定です。ご承認いただけますでしょうか。"],"transitionText":"Sau khi khách hỏi khả năng quay lại…"}],"endings":{"success":{"code":"SUCCESS","title":"Xin phê duyệt rollback xong","message":"お願いします。すぐに進めてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"URGENT"}', '{"grammar":[{"pattern":"至急ご報告いたします","example":"至急ご報告いたします。本番環境で決済処理がエラーになる障害が発生しております。","explanation":"Mở đầu cuộc gọi báo sự cố, đi thẳng vào việc."},{"pattern":"〜可能性が高いと見ております","example":"今朝のリリースで更新した設定ファイルが関係している可能性が高いと見ております。","explanation":"Nêu giả thuyết khi chưa chắc chắn, tránh khẳng định sai."}],"vocabulary":[{"jlpt":"N2","term":"障害","reading":"しょうがい","meaning":"sự cố","example":"決済処理がエラーになる障害が発生しております。"},{"jlpt":"N2","term":"暫定対応","reading":"ざんていたいおう","meaning":"xử lý tạm thời","example":"暫定対応として、30分以内にリリース前の状態に戻す予定です。"},{"jlpt":"N2","term":"承認","reading":"しょうにん","meaning":"phê duyệt","example":"ご承認いただけますでしょうか。"},{"jlpt":"N2","term":"設定ファイル","reading":"せっていファイル","meaning":"file cấu hình","example":"設定ファイルが関係している可能性が高いと見ております。"}],"exampleDialogue":[{"text":"田中様、至急ご報告いたします。本日10時頃から、本番環境で決済処理がエラーになる障害が発生しております。","speaker":"learner","translation":"Anh Tanaka, tôi xin báo cáo gấp. Từ khoảng 10 giờ hôm nay, môi trường production đang gặp sự cố xử lý thanh toán bị lỗi."},{"text":"えっ、ユーザーへの影響はどのくらいですか。","speaker":"ai","translation":"Hả, ảnh hưởng tới người dùng cỡ nào?"},{"text":"現時点で、決済を試みたユーザーのうち約3割がエラーになっております。","speaker":"learner","translation":"Hiện tại, khoảng 30% người dùng thực hiện thanh toán bị lỗi."},{"text":"原因は調査中ですが、今朝のリリースで更新した設定ファイルが関係している可能性が高いと見ております。","speaker":"learner","translation":"Nguyên nhân đang được điều tra, nhưng chúng tôi cho rằng khả năng cao liên quan tới file cấu hình được cập nhật trong đợt release sáng nay."},{"text":"すぐに戻せますか。","speaker":"ai","translation":"Quay lại ngay được không?"},{"text":"はい。暫定対応として、30分以内にリリース前の状態に戻す予定です。ご承認いただけますでしょうか。","speaker":"learner","translation":"Vâng. Để xử lý tạm thời, chúng tôi dự định đưa về trạng thái trước release trong vòng 30 phút. Anh có thể phê duyệt được không ạ?"}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận lần cuối trước release', 'cpath-brse-14', 'Bạn nhắc lịch release, báo thời gian dừng dịch vụ, nêu phương án rollback và hẹn báo kết quả.', 'N2', 'MEDIUM', 7, 'Trước ngày release, bạn xác nhận lịch làm, thời gian dừng dịch vụ và phương án rollback với khách.', 'Phòng họp trực tuyến', 'Buổi tối', '{"goals":[{"code":"KAKUNIN","type":"MISSION","title":"Mở đầu xác nhận cuối","required":true,"conditions":[{"type":"KEYWORD","value":"最終確認をさせていただきます|リリース"}],"description":"Mở đầu buổi xác nhận cuối cùng cho đợt release.","displayOrder":1},{"code":"TEISHI","type":"MISSION","title":"Báo thời gian dừng dịch vụ","required":true,"conditions":[{"type":"KEYWORD","value":"サービスを停止|22時|掲載"}],"description":"Báo dừng dịch vụ khoảng 1 giờ và nhờ khách thông báo người dùng.","displayOrder":2},{"code":"ROLLBACK","type":"MISSION","title":"Nêu phương án rollback","required":true,"conditions":[{"type":"KEYWORD","value":"切り戻し|元のバージョン|判断の期限"}],"description":"Nêu phương án quay về bản cũ và hạn ra quyết định.","displayOrder":3},{"code":"HOUKOKU","type":"MISSION","title":"Hẹn báo kết quả","required":true,"conditions":[{"type":"KEYWORD","value":"結果をメールでご報告"}],"description":"Hẹn báo kết quả qua email sau khi làm xong.","displayOrder":4}],"states":[{"code":"CONFIRM","name":"Mở đầu xác nhận cuối","next":"STOP","prompt":"Mời người học nhắc lịch release và khung giờ làm.","allowedGoalCodes":["KAKUNIN"],"suggestedReplies":["明日のリリースに向けて、最終確認をさせていただきます。","作業は明日の22時から24時を予定しております。"]},{"code":"STOP","name":"Báo thời gian dừng dịch vụ","next":"FALLBACK","prompt":"Khách hỏi dịch vụ có dừng không, mời người học báo thời gian dừng.","allowedGoalCodes":["TEISHI"],"suggestedReplies":["22時から約1時間、サービスを停止いたします。","停止のお知らせを、本日中にユーザーへ掲載していただけますでしょうか。"],"transitionText":"Sau khi nhắc lịch…"},{"code":"FALLBACK","name":"Nêu phương án rollback","next":"REPORT","prompt":"Mời người học nêu phương án rollback và hạn quyết định.","allowedGoalCodes":["ROLLBACK"],"suggestedReplies":["万が一問題が発生した場合は、切り戻し手順に従って元のバージョンに戻します。","判断の期限は23時30分とさせていただきます。"],"transitionText":"Sau khi khách nhận thông báo người dùng…"},{"code":"REPORT","name":"Hẹn báo kết quả","next":"END","prompt":"Khách dặn có gì cứ liên lạc, mời người học hẹn báo kết quả.","allowedGoalCodes":["HOUKOKU"],"suggestedReplies":["かしこまりました。作業完了後、結果をメールでご報告いたします。"],"transitionText":"Sau khi chốt phương án…"}],"endings":{"success":{"code":"SUCCESS","title":"Xác nhận trước release xong","message":"了解です。何かあったら、夜中でも連絡してください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"CONFIRM"}', '{"grammar":[{"pattern":"〜に向けて","example":"明日のリリースに向けて、最終確認をさせていただきます。","explanation":"Nghĩa là \'chuẩn bị cho ~\', ngữ pháp N2."},{"pattern":"万が一","example":"万が一問題が発生した場合は、切り戻し手順に従って元のバージョンに戻します。","explanation":"Dùng khi nói về rủi ro, nghe chuyên nghiệp hơn もし."}],"vocabulary":[{"jlpt":"N2","term":"リリース","reading":"リリース","meaning":"phát hành (release)","example":"明日のリリースに向けて、最終確認をさせていただきます。"},{"jlpt":"N2","term":"停止","reading":"ていし","meaning":"dừng","example":"22時から約1時間、サービスを停止いたします。"},{"jlpt":"N2","term":"切り戻し","reading":"きりもどし","meaning":"rollback, quay về bản cũ","example":"切り戻し手順に従って元のバージョンに戻します。"},{"jlpt":"N2","term":"判断の期限","reading":"はんだんのきげん","meaning":"thời hạn ra quyết định","example":"判断の期限は23時30分とさせていただきます。"}],"exampleDialogue":[{"text":"明日のリリースに向けて、最終確認をさせていただきます。","speaker":"learner","translation":"Tôi xin xác nhận lần cuối cho đợt release ngày mai."},{"text":"リリース手順書は昨日お送りしたとおりで、作業は明日の22時から24時を予定しております。","speaker":"learner","translation":"Tài liệu thao tác release như đã gửi hôm qua, dự kiến làm từ 22 giờ đến 24 giờ ngày mai."},{"text":"作業中、サービスは止まりますか。","speaker":"ai","translation":"Trong lúc làm, dịch vụ có bị dừng không?"},{"text":"はい、22時から約1時間、サービスを停止いたします。停止のお知らせを、本日中にユーザーへ掲載していただけますでしょうか。","speaker":"learner","translation":"Vâng, dịch vụ sẽ dừng khoảng 1 tiếng từ 22 giờ. Anh có thể đăng thông báo dừng dịch vụ tới người dùng trong hôm nay được không ạ?"},{"text":"万が一問題が発生した場合は、切り戻し手順に従って元のバージョンに戻します。判断の期限は23時30分とさせていただきます。","speaker":"learner","translation":"Nếu chẳng may có vấn đề, chúng tôi sẽ quay về phiên bản cũ theo quy trình rollback. Thời hạn ra quyết định là 23 giờ 30."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo phát hành', 'cpath-brse-22', 'Bạn báo phát hành xong, khẳng định hệ thống ổn định và đã sao lưu trước khi phát hành.', 'N2', 'MEDIUM', 6, 'Bạn thông báo đã phát hành phiên bản mới và xác nhận trạng thái vận hành cho khách.', 'Văn phòng, qua điện thoại', 'Buổi tối', '{"goals":[{"code":"HOUKOKU","type":"MISSION","title":"Báo phát hành xong","required":true,"conditions":[{"type":"KEYWORD","value":"リリースが完了しました|新バージョン"}],"description":"Báo phiên bản mới đã phát hành hoàn tất.","displayOrder":1},{"code":"ANZEN","type":"MISSION","title":"Khẳng định hệ thống ổn","required":true,"conditions":[{"type":"KEYWORD","value":"監視システム|異常はありません"}],"description":"Khẳng định hệ thống giám sát không có bất thường.","displayOrder":2},{"code":"BACKUP","type":"MISSION","title":"Xác nhận đã sao lưu","required":true,"conditions":[{"type":"KEYWORD","value":"バックアップ|リリース前に完了"}],"description":"Xác nhận đã sao lưu trước khi phát hành.","displayOrder":3}],"states":[{"code":"RELEASED","name":"Báo phát hành xong","next":"STABLE","prompt":"Khách hỏi vận hành có vấn đề gì không, mời người học khẳng định ổn.","allowedGoalCodes":["HOUKOKU"],"suggestedReplies":["田中さん、新バージョンのリリースが完了しました。"]},{"code":"STABLE","name":"Khẳng định hệ thống ổn","next":"BACKUP","prompt":"Mời người học khẳng định hệ thống giám sát không có bất thường.","allowedGoalCodes":["ANZEN"],"suggestedReplies":["はい、監視システムでも異常はありません。"],"transitionText":"Sau khi báo phát hành xong…"},{"code":"BACKUP","name":"Xác nhận đã sao lưu","next":"END","prompt":"Khách hỏi đã sao lưu chưa, mời người học xác nhận.","allowedGoalCodes":["BACKUP"],"suggestedReplies":["はい、リリース前に完了しています。"],"transitionText":"Sau khi khẳng định hệ thống ổn…"}],"endings":{"success":{"code":"SUCCESS","title":"Báo cáo phát hành xong","message":"安心しました。引き続きよろしくお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"RELEASED"}', '{"grammar":[{"pattern":"〜が完了しました","example":"新バージョンのリリースが完了しました。","explanation":"Báo cáo việc triển khai xong."},{"pattern":"〜は取得済みですか","example":"バックアップは取得済みですか。","explanation":"Xác nhận việc đã thực hiện."}],"vocabulary":[{"jlpt":"N2","term":"リリース","reading":"リリース","meaning":"phát hành (release)","example":"新バージョンのリリースが完了しました。"},{"jlpt":"N2","term":"監視システム","reading":"かんしシステム","meaning":"hệ thống giám sát","example":"監視システムでも異常はありません。"},{"jlpt":"N2","term":"バックアップ","reading":"バックアップ","meaning":"sao lưu","example":"バックアップは取得済みですか。"},{"jlpt":"N2","term":"異常","reading":"いじょう","meaning":"bất thường","example":"監視システムでも異常はありません。"}],"exampleDialogue":[{"text":"田中さん、新バージョンのリリースが完了しました。","speaker":"learner","translation":"Anh Tanaka, việc phát hành phiên bản mới đã hoàn tất ạ."},{"text":"ありがとうございます。動作は問題ないですか。","speaker":"ai","translation":"Cảm ơn anh. Vận hành có vấn đề gì không ạ?"},{"text":"はい、監視システムでも異常はありません。","speaker":"learner","translation":"Vâng, hệ thống giám sát cũng không có gì bất thường ạ."},{"text":"バックアップは取得済みですか。","speaker":"ai","translation":"Đã sao lưu dữ liệu chưa ạ?"},{"text":"はい、リリース前に完了しています。","speaker":"learner","translation":"Vâng, đã hoàn tất trước khi phát hành ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-khach-hang-nhat'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-brse'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Tổng hợp giao tiếp công việc BrSE', 'cpath-test-ba', 'Cuộc gọi tổng hợp đi qua nhiều chủ đề chính của mục tiêu BrSE: chào hỏi, xác nhận đặc tả, báo tiến độ, kết quả test, xử lý lỗi và xác nhận release.', 'N2', 'HARD', 14, 'Một ngày làm việc tổng hợp: bạn gặp khách hàng, xác nhận đặc tả, báo tiến độ và kết quả test, tiếp nhận báo lỗi rồi chốt kế hoạch release.', 'Phòng họp trực tuyến', 'Buổi sáng', '{"goals":[{"code":"AISATSU","type":"MISSION","title":"Chào hỏi và giới thiệu","required":true,"conditions":[{"type":"KEYWORD","value":"申します|担当いたします|ブリッジSE|初めまして"}],"description":"Chào lần đầu và nói vai trò BrSE của mình.","displayOrder":1},{"code":"SHIYOU","type":"MISSION","title":"Xác nhận điểm chưa rõ trong đặc tả","required":true,"conditions":[{"type":"KEYWORD","value":"確認させていただきたい|仕様書|ということでよろしいでしょうか"}],"description":"Chỉ rõ điểm thiếu và nhắc lại để chốt.","displayOrder":2},{"code":"SHINCHOKU","type":"MISSION","title":"Báo cáo tiến độ","required":true,"conditions":[{"type":"KEYWORD","value":"進捗をご報告|予定どおり|見込み"}],"description":"Nêu hạng mục xong và hạng mục chậm kèm dự báo.","displayOrder":3},{"code":"TESUTO","type":"MISSION","title":"Báo cáo kết quả test","required":true,"conditions":[{"type":"KEYWORD","value":"テストケース|合格|不合格"}],"description":"Báo số ca đạt/không đạt khớp nhau.","displayOrder":4},{"code":"BUG","type":"MISSION","title":"Tiếp nhận báo lỗi","required":true,"conditions":[{"type":"KEYWORD","value":"再現手順|調査|ご連絡いたします"}],"description":"Hỏi bước tái hiện và hẹn giờ phản hồi.","displayOrder":5},{"code":"RELEASE","type":"MISSION","title":"Xác nhận lần cuối trước release","required":true,"conditions":[{"type":"KEYWORD","value":"リリース|サービスを停止|切り戻し"}],"description":"Báo thời gian dừng dịch vụ và phương án rollback.","displayOrder":6}],"states":[{"code":"GREETING","name":"Chào hỏi và giới thiệu","next":"SPEC","prompt":"Chào khách và mời người học giới thiệu bản thân.","allowedGoalCodes":["AISATSU"],"suggestedReplies":["初めまして。VJソリューションズのグエンと申します。本プロジェクトでブリッジSEを担当いたします。"]},{"code":"SPEC","name":"Xác nhận đặc tả","next":"PROGRESS","prompt":"Mời người học nêu điểm cần xác nhận trong đặc tả.","allowedGoalCodes":["SHIYOU"],"suggestedReplies":["仕様書の件で一点確認させていただきたいのですが。","30分後の自動解除と、管理者による手動解除の両方を実装する、ということでよろしいでしょうか。"],"transitionText":"Sau khi chào hỏi…"},{"code":"PROGRESS","name":"Báo cáo tiến độ","next":"TEST","prompt":"Mời người học báo tiến độ tuần, gồm hạng mục xong và hạng mục chậm.","allowedGoalCodes":["SHINCHOKU"],"suggestedReplies":["今週の進捗をご報告いたします。","会員登録機能は予定どおり完了しました。","決済機能は進捗が予定の70%程度にとどまっておりますが、来週の作業で遅れを取り戻せる見込みです。"],"transitionText":"Sau khi chốt đặc tả…"},{"code":"TEST","name":"Báo cáo kết quả test","next":"BUG","prompt":"Mời người học báo số liệu kết quả kiểm thử.","allowedGoalCodes":["TESUTO"],"suggestedReplies":["テストケース全420件のうち412件を消化し、合格は398件、不合格は14件でした。"],"transitionText":"Sau khi báo tiến độ…"},{"code":"BUG","name":"Tiếp nhận báo lỗi","next":"RELEASE","prompt":"Khách báo lỗi mới, mời người học hỏi bước tái hiện và hẹn phản hồi.","allowedGoalCodes":["BUG"],"suggestedReplies":["ご報告ありがとうございます。再現手順を教えていただけますか。","本日の17時までに原因と対応方針をご連絡いたします。"],"transitionText":"Sau khi báo kết quả test…"},{"code":"RELEASE","name":"Xác nhận trước release","next":"END","prompt":"Mời người học xác nhận lịch release và phương án rollback.","allowedGoalCodes":["RELEASE"],"suggestedReplies":["明日のリリースに向けて、最終確認をさせていただきます。","22時から約1時間、サービスを停止いたします。","万が一問題が発生した場合は、切り戻し手順に従って元のバージョンに戻します。"],"transitionText":"Sau khi xử lý báo lỗi…"}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành tổng hợp công việc","message":"ありがとうございました。引き続きよろしくお願いいたします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"GREETING"}', '{"grammar":[{"pattern":"〜ということでよろしいでしょうか","example":"30分後の自動解除と、管理者による手動解除の両方を実装する、ということでよろしいでしょうか。","explanation":"Nhắc lại để chốt, kỹ năng cốt lõi của BrSE."},{"pattern":"〜可能性が高いと見ております","example":"今朝のリリースで更新した設定ファイルが関係している可能性が高いと見ております。","explanation":"Nêu giả thuyết khi chưa chắc chắn, tránh khẳng định sai."}],"vocabulary":[{"jlpt":"N2","term":"進捗","reading":"しんちょく","meaning":"tiến độ","example":"今週の進捗をご報告いたします。"},{"jlpt":"N2","term":"仕様書","reading":"しようしょ","meaning":"tài liệu đặc tả","example":"仕様書の件で確認させていただきたいのですが。"},{"jlpt":"N2","term":"合格","reading":"ごうかく","meaning":"đạt","example":"合格は398件でした。"},{"jlpt":"N2","term":"再現手順","reading":"さいげんてじゅん","meaning":"các bước tái hiện lỗi","example":"再現手順を教えていただけますか。"}],"exampleDialogue":[{"text":"初めまして。VJソリューションズのグエンと申します。本プロジェクトでブリッジSEを担当いたします。","speaker":"learner","translation":"Xin chào, tôi là Nguyễn của VJ Solutions. Tôi sẽ phụ trách vai trò BrSE cho dự án này."},{"text":"ミライテックの田中です。よろしくお願いします。","speaker":"ai","translation":"Tôi là Tanaka của Miraitech. Rất mong được hợp tác."},{"text":"仕様書の件で一点確認させていただきたいのですが、ロックの解除方法について記載がございません。30分後の自動解除と、管理者による手動解除の両方を実装する、ということでよろしいでしょうか。","speaker":"learner","translation":"Tôi muốn xác nhận một điểm trong tài liệu đặc tả: không ghi cách mở khóa. Vậy là triển khai cả tự động mở khóa sau 30 phút lẫn quản trị viên mở khóa thủ công, đúng không ạ?"},{"text":"はい、それで結構です。","speaker":"ai","translation":"Vâng, như vậy là được."},{"text":"今週の進捗をご報告いたします。会員登録機能は予定どおり完了しました。決済機能は進捗が予定の70%程度にとどまっておりますが、来週の作業で遅れを取り戻せる見込みです。","speaker":"learner","translation":"Tôi xin báo cáo tiến độ tuần. Chức năng đăng ký đã xong đúng kế hoạch. Chức năng thanh toán mới đạt khoảng 70% nhưng tuần sau sẽ bắt kịp."},{"text":"テストケース全420件のうち412件を消化し、合格は398件、不合格は14件でした。","speaker":"learner","translation":"Trong tổng số 420 test case, đã thực hiện 412 case, đạt 398 case và không đạt 14 case."},{"text":"検証環境で、検索結果が正しく表示されないんですが。","speaker":"ai","translation":"Trên môi trường staging, kết quả tìm kiếm hiển thị không đúng."},{"text":"ご報告ありがとうございます。再現手順を教えていただけますか。本日の17時までに原因と対応方針をご連絡いたします。","speaker":"learner","translation":"Cảm ơn anh đã báo. Anh cho tôi biết các bước tái hiện lỗi được không ạ? Trước 17 giờ hôm nay tôi sẽ báo nguyên nhân và hướng xử lý."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dong-nghiep'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chào buổi sáng', 'cpath-wrk-01', 'Bạn chào buổi sáng với đồng nghiệp, đáp lại lời nhận xét và nói việc mình sắp làm.', 'N3', 'MEDIUM', 6, 'Bạn vừa đến công ty và gặp đồng nghiệp ở hành lang trước giờ họp sáng.', 'Văn phòng công ty', 'Buổi sáng', '{"goals":[{"code":"GREET","type":"MISSION","title":"Chào buổi sáng","required":true,"conditions":[{"type":"KEYWORD","value":"おはようございます|おはよう"}],"description":"Chào đồng nghiệp bằng câu chào buổi sáng lịch sự.","displayOrder":1},{"code":"EARLY","type":"MISSION","title":"Đáp lại lời khen đến sớm","required":true,"conditions":[{"type":"KEYWORD","value":"はい|起きました|朝早く"}],"description":"Xác nhận mình đến sớm và giải thích ngắn gọn.","displayOrder":2},{"code":"COFFEE","type":"MISSION","title":"Nói việc sắp làm","required":true,"conditions":[{"type":"KEYWORD","value":"コーヒー|飲んできます|そうですね"}],"description":"Đồng ý và nói mình đi uống cà phê rồi quay lại.","displayOrder":3}],"states":[{"code":"OPEN","name":"Mở lời chào","next":"CHAT","prompt":"Bạn gặp đồng nghiệp đầu giờ sáng. Hãy chào buổi sáng.","allowedGoalCodes":["GREET"],"suggestedReplies":["おはようございます。"]},{"code":"CHAT","name":"Nhận xét giờ đến","next":"BEFORE","prompt":"Đồng nghiệp đáp lại và khen bạn hôm nay đến sớm.","allowedGoalCodes":["EARLY"],"suggestedReplies":["はい、朝早く起きました。"]},{"code":"BEFORE","name":"Nhắc giờ họp","next":"END","prompt":"Đồng nghiệp nhắc vẫn còn thời gian đến giờ họp sáng.","allowedGoalCodes":["COFFEE"],"suggestedReplies":["そうですね。コーヒーを飲んできます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Chào buổi sáng","message":"いってらっしゃい。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"おはようございます。","pattern":"おはようございます","explanation":"Chào buổi sáng. Câu chào buổi sáng lịch sự."},{"example":"おはようございます。今日は早いですね。","pattern":"〜は早いですね","explanation":"~ sớm nhỉ. Nhận xét về thời gian."},{"example":"そうですね。コーヒーを飲んできます。","pattern":"〜てきます","explanation":"Đi ~ rồi quay lại. Nói làm gì đó rồi quay lại."}],"vocabulary":[{"jlpt":"N3","term":"挨拶","example":"朝の挨拶をします。","meaning":"chào hỏi","reading":"あいさつ"},{"jlpt":"N3","term":"自己紹介","example":"自己紹介をお願いします。","meaning":"tự giới thiệu","reading":"じこしょうかい"},{"jlpt":"N3","term":"上司","example":"上司に挨拶します。","meaning":"cấp trên","reading":"じょうし"},{"jlpt":"N3","term":"同僚","example":"同僚と話します。","meaning":"đồng nghiệp","reading":"どうりょう"}],"exampleDialogue":[{"text":"おはようございます。","speaker":"learner","translation":"Chào buổi sáng ạ."},{"text":"おはようございます。今日は早いですね。","speaker":"ai","translation":"Chào buổi sáng. Hôm nay anh đến sớm nhỉ."},{"text":"はい、朝早く起きました。","speaker":"learner","translation":"Vâng, sáng nay tôi dậy sớm ạ."},{"text":"朝礼までまだ時間がありますね。","speaker":"ai","translation":"Còn thời gian đến giờ họp sáng nhỉ."},{"text":"そうですね。コーヒーを飲んできます。","speaker":"learner","translation":"Đúng vậy. Tôi đi uống cà phê đây ạ."},{"text":"いってらっしゃい。","speaker":"ai","translation":"Anh đi đi ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dan-anh'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Tự giới thiệu', 'cpath-wrk-02', 'Bạn tự giới thiệu bản thân, nói nơi làm cũ và cảm ơn đàn anh.', 'N3', 'MEDIUM', 6, 'Bạn là nhân viên mới được giới thiệu với đàn anh trong bộ phận.', 'Văn phòng công ty', 'Buổi sáng', '{"goals":[{"code":"INTRO","type":"MISSION","title":"Tự giới thiệu","required":true,"conditions":[{"type":"KEYWORD","value":"はじめまして|お世話になります|です"}],"description":"Chào lần đầu và giới thiệu tên mình.","displayOrder":1},{"code":"FROM","type":"MISSION","title":"Nói nơi làm cũ","required":true,"conditions":[{"type":"KEYWORD","value":"異動|営業部|から"}],"description":"Nói mình được chuyển từ bộ phận cũ sang.","displayOrder":2},{"code":"THANKS","type":"MISSION","title":"Cảm ơn và nhờ giúp đỡ","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございます|よろしくお願いします"}],"description":"Cảm ơn và gửi lời nhờ giúp đỡ.","displayOrder":3}],"states":[{"code":"OPEN","name":"Giới thiệu bản thân","next":"ASK","prompt":"Bạn gặp đàn anh lần đầu. Hãy chào và giới thiệu tên mình.","allowedGoalCodes":["INTRO"],"suggestedReplies":["はじめまして。今日からお世話になります。リンです。"]},{"code":"ASK","name":"Hỏi nơi làm cũ","next":"GUIDE","prompt":"Đàn anh chào lại và hỏi bạn trước đây ở bộ phận nào.","allowedGoalCodes":["FROM"],"suggestedReplies":["営業部から異動してきました。"]},{"code":"GUIDE","name":"Mời nhờ giúp","next":"END","prompt":"Đàn anh nói nếu có gì không rõ thì cứ hỏi.","allowedGoalCodes":["THANKS"],"suggestedReplies":["ありがとうございます。よろしくお願いします。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Tự giới thiệu","message":"こちらこそ。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"はじめまして。今日からお世話になります。リンです。","pattern":"〜からお世話になります","explanation":"Từ ~ tôi được giúp đỡ. Chào khi mới đến làm."},{"example":"営業部から異動してきました。","pattern":"〜から異動してきました","explanation":"Tôi được chuyển từ ~ sang. Nói về nơi làm cũ."},{"example":"そうですか。分からないことがあれば聞いてください。","pattern":"〜ことがあれば聞いてください","explanation":"Có gì ~ thì cứ hỏi. Mời đồng nghiệp nhờ giúp."}],"vocabulary":[{"jlpt":"N3","term":"挨拶","example":"朝の挨拶をします。","meaning":"chào hỏi","reading":"あいさつ"},{"jlpt":"N3","term":"自己紹介","example":"自己紹介をお願いします。","meaning":"tự giới thiệu","reading":"じこしょうかい"},{"jlpt":"N3","term":"上司","example":"上司に挨拶します。","meaning":"cấp trên","reading":"じょうし"},{"jlpt":"N3","term":"同僚","example":"同僚と話します。","meaning":"đồng nghiệp","reading":"どうりょう"}],"exampleDialogue":[{"text":"はじめまして。今日からお世話になります。リンです。","speaker":"learner","translation":"Rất vui được gặp anh. Từ hôm nay tôi được mọi người giúp đỡ. Tôi là Linh ạ."},{"text":"こちらこそよろしくお願いします。何部のご出身ですか。","speaker":"ai","translation":"Tôi cũng mong được hợp tác. Anh trước ở bộ phận nào ạ?"},{"text":"営業部から異動してきました。","speaker":"learner","translation":"Tôi được chuyển từ bộ phận kinh doanh sang ạ."},{"text":"そうですか。分からないことがあれば聞いてください。","speaker":"ai","translation":"Vậy à. Có gì không rõ thì cứ hỏi tôi ạ."},{"text":"ありがとうございます。よろしくお願いします。","speaker":"learner","translation":"Cảm ơn anh. Rất mong được giúp đỡ ạ."},{"text":"こちらこそ。","speaker":"ai","translation":"Tôi cũng vậy ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chào khi ra về', 'cpath-wrk-03', 'Bạn xin phép ra về trước, nhận lời dặn dò và hứa không đến muộn.', 'N3', 'MEDIUM', 6, 'Bạn xong việc và muốn ra về, ghé chào sếp trước khi rời công ty.', 'Văn phòng công ty', 'Cuối giờ làm', '{"goals":[{"code":"BYE","type":"MISSION","title":"Xin phép ra về","required":true,"conditions":[{"type":"KEYWORD","value":"お先に失礼します|失礼します"}],"description":"Chào xin phép ra về trước một cách lịch sự.","displayOrder":1},{"code":"ACCEPT","type":"MISSION","title":"Nhận lời dặn dò","required":true,"conditions":[{"type":"KEYWORD","value":"承知しました|はい|分かりました"}],"description":"Xác nhận đã rõ lời dặn của sếp.","displayOrder":2},{"code":"PROMISE","type":"MISSION","title":"Hứa không đến muộn","required":true,"conditions":[{"type":"KEYWORD","value":"分かりました|遅れない|ようにします"}],"description":"Hứa sẽ không đến muộn giờ họp sáng mai.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin phép ra về","next":"REMIND","prompt":"Bạn xong việc, định ra về. Hãy chào xin phép sếp.","allowedGoalCodes":["BYE"],"suggestedReplies":["お先に失礼します。"]},{"code":"REMIND","name":"Dặn dò tài liệu","next":"MEETING","prompt":"Sếp chào lại và dặn sáng mai xem lại tài liệu.","allowedGoalCodes":["ACCEPT"],"suggestedReplies":["はい、承知しました。"]},{"code":"MEETING","name":"Báo giờ họp","next":"END","prompt":"Sếp báo thêm cuộc họp sáng mai bắt đầu lúc chín giờ.","allowedGoalCodes":["PROMISE"],"suggestedReplies":["分かりました。遅れないようにします。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Chào khi ra về","message":"うん、気をつけて帰ってね。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"お先に失礼します。","pattern":"お先に失礼します","explanation":"Xin phép về trước. Chào khi ra về."},{"example":"お疲れさま。明日の朝、資料を確認してね。","pattern":"〜てね","explanation":"Hãy ~ nhé. Dặn dò thân mật."},{"example":"分かりました。遅れないようにします。","pattern":"〜ないようにします","explanation":"Sẽ cố không ~. Hứa cẩn thận."}],"vocabulary":[{"jlpt":"N3","term":"挨拶","example":"朝の挨拶をします。","meaning":"chào hỏi","reading":"あいさつ"},{"jlpt":"N3","term":"自己紹介","example":"自己紹介をお願いします。","meaning":"tự giới thiệu","reading":"じこしょうかい"},{"jlpt":"N3","term":"上司","example":"上司に挨拶します。","meaning":"cấp trên","reading":"じょうし"},{"jlpt":"N3","term":"同僚","example":"同僚と話します。","meaning":"đồng nghiệp","reading":"どうりょう"}],"exampleDialogue":[{"text":"お先に失礼します。","speaker":"learner","translation":"Em xin phép về trước ạ."},{"text":"お疲れさま。明日の朝、資料を確認してね。","speaker":"ai","translation":"Vất vả rồi. Sáng mai em xem lại tài liệu nhé."},{"text":"はい、承知しました。","speaker":"learner","translation":"Vâng, em đã rõ ạ."},{"text":"あと、明日の会議は九時からだよ。","speaker":"ai","translation":"À, họp ngày mai bắt đầu từ chín giờ đấy."},{"text":"分かりました。遅れないようにします。","speaker":"learner","translation":"Em hiểu rồi. Em sẽ không đến muộn ạ."},{"text":"うん、気をつけて帰ってね。","speaker":"ai","translation":"Ừ, về cẩn thận nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xin nghỉ phép', 'cpath-wrk-07', 'Bạn xin phép nghỉ, nêu lý do và hứa bàn giao công việc.', 'N3', 'MEDIUM', 6, 'Bạn cần xin sếp nghỉ phép có lương vào thứ Sáu tuần sau.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Xin nghỉ phép","required":true,"conditions":[{"type":"KEYWORD","value":"有給|てもいいですか|取って"}],"description":"Xin sếp cho nghỉ phép có lương.","displayOrder":1},{"code":"REASON","type":"MISSION","title":"Nêu lý do","required":true,"conditions":[{"type":"KEYWORD","value":"家族|用事|故郷|帰ります"}],"description":"Nói lý do về quê vì việc gia đình.","displayOrder":2},{"code":"HANDOVER","type":"MISSION","title":"Hứa bàn giao","required":true,"conditions":[{"type":"KEYWORD","value":"引き継ぎ|同僚|します"}],"description":"Hứa sẽ bàn giao công việc cho đồng nghiệp.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin nghỉ phép","next":"WHY","prompt":"Bạn cần nghỉ phép tuần sau. Hãy mở lời xin sếp.","allowedGoalCodes":["ASK"],"suggestedReplies":["部長、来週の金曜日に有給を取ってもいいですか。"]},{"code":"WHY","name":"Hỏi lý do","next":"REMIND","prompt":"Sếp hỏi bạn có việc gì.","allowedGoalCodes":["REASON"],"suggestedReplies":["家族の用事で故郷に帰ります。"]},{"code":"REMIND","name":"Dặn bàn giao","next":"END","prompt":"Sếp đồng ý và dặn bàn giao công việc trước.","allowedGoalCodes":["HANDOVER"],"suggestedReplies":["はい、同僚に引き継ぎます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xin nghỉ phép","message":"じゃ、気をつけて行ってきて。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"部長、来週の金曜日に有給を取ってもいいですか。","pattern":"〜てもいいですか","explanation":"~ được không ạ. Xin phép làm gì."},{"example":"家族の用事で故郷に帰ります。","pattern":"〜で〜ます","explanation":"Vì ~ nên ~. Nêu lý do và hành động."},{"example":"分かった。仕事の引き継ぎはしておいてね。","pattern":"〜ておいてね","explanation":"Hãy ~ trước nhé. Dặn chuẩn bị trước."}],"vocabulary":[{"jlpt":"N3","term":"有給","example":"有給を取ります。","meaning":"nghỉ có lương","reading":"ゆうきゅう"},{"jlpt":"N3","term":"早退","example":"三時に早退します。","meaning":"về sớm","reading":"そうたい"},{"jlpt":"N3","term":"病欠","example":"今日は病欠します。","meaning":"nghỉ ốm","reading":"びょうけつ"},{"jlpt":"N3","term":"引き継ぎ","example":"仕事を引き継ぎます。","meaning":"bàn giao","reading":"ひきつぎ"}],"exampleDialogue":[{"text":"部長、来週の金曜日に有給を取ってもいいですか。","speaker":"learner","translation":"Thưa trưởng phòng, thứ Sáu tuần sau em xin nghỉ phép được không ạ?"},{"text":"何か予定があるの？","speaker":"ai","translation":"Em có việc gì à?"},{"text":"家族の用事で故郷に帰ります。","speaker":"learner","translation":"Em về quê vì việc gia đình ạ."},{"text":"分かった。仕事の引き継ぎはしておいてね。","speaker":"ai","translation":"Được rồi. Em bàn giao công việc trước nhé."},{"text":"はい、同僚に引き継ぎます。","speaker":"learner","translation":"Vâng, em sẽ bàn giao cho đồng nghiệp ạ."},{"text":"じゃ、気をつけて行ってきて。","speaker":"ai","translation":"Vậy em đi cẩn thận nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xin về sớm', 'cpath-wrk-08', 'Bạn xin về sớm, nêu lý do và hứa làm nốt việc còn lại.', 'N3', 'MEDIUM', 6, 'Bạn có việc gấp và cần xin sếp về sớm lúc ba giờ chiều.', 'Văn phòng công ty', 'Buổi chiều', '{"goals":[{"code":"ASK","type":"MISSION","title":"Xin về sớm","required":true,"conditions":[{"type":"KEYWORD","value":"早退|てもいいですか|三時"}],"description":"Xin sếp cho về sớm lúc ba giờ.","displayOrder":1},{"code":"REASON","type":"MISSION","title":"Nêu lý do","required":true,"conditions":[{"type":"KEYWORD","value":"子供|熱|迎えに行きます"}],"description":"Nói con bị sốt nên phải đi đón.","displayOrder":2},{"code":"REST","type":"MISSION","title":"Hứa làm việc còn lại","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございます|残り|明日"}],"description":"Cảm ơn và hứa việc còn lại làm ngày mai.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin về sớm","next":"WHY","prompt":"Bạn có việc gấp. Hãy xin sếp về sớm.","allowedGoalCodes":["ASK"],"suggestedReplies":["部長、今日は三時に早退してもいいですか。"]},{"code":"WHY","name":"Hỏi lý do","next":"OK","prompt":"Sếp hỏi có chuyện gì.","allowedGoalCodes":["REASON"],"suggestedReplies":["子供が熱を出したので、迎えに行きます。"]},{"code":"OK","name":"Đồng ý cho về","next":"END","prompt":"Sếp thông cảm và bảo bạn về sớm.","allowedGoalCodes":["REST"],"suggestedReplies":["ありがとうございます。残りの仕事は明日やります。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xin về sớm","message":"分かった。お大事に。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"子供が熱を出したので、迎えに行きます。","pattern":"〜ので、〜ます","explanation":"Vì ~ nên ~. Nêu lý do khách quan."},{"example":"部長、今日は三時に早退してもいいですか。","pattern":"〜てもいいですか","explanation":"~ được không ạ. Xin phép."},{"example":"分かった。お大事に。","pattern":"お大事に","explanation":"Chúc mau khỏe. Lời thăm hỏi khi ai đó ốm."}],"vocabulary":[{"jlpt":"N3","term":"有給","example":"有給を取ります。","meaning":"nghỉ có lương","reading":"ゆうきゅう"},{"jlpt":"N3","term":"早退","example":"三時に早退します。","meaning":"về sớm","reading":"そうたい"},{"jlpt":"N3","term":"病欠","example":"今日は病欠します。","meaning":"nghỉ ốm","reading":"びょうけつ"},{"jlpt":"N3","term":"引き継ぎ","example":"仕事を引き継ぎます。","meaning":"bàn giao","reading":"ひきつぎ"}],"exampleDialogue":[{"text":"部長、今日は三時に早退してもいいですか。","speaker":"learner","translation":"Thưa trưởng phòng, hôm nay em xin về sớm lúc ba giờ được không ạ?"},{"text":"どうしたの？","speaker":"ai","translation":"Có chuyện gì ạ?"},{"text":"子供が熱を出したので、迎えに行きます。","speaker":"learner","translation":"Con em bị sốt nên em đi đón ạ."},{"text":"それは大変だね。早く帰りなさい。","speaker":"ai","translation":"Vậy là vất vả rồi. Em về sớm đi."},{"text":"ありがとうございます。残りの仕事は明日やります。","speaker":"learner","translation":"Cảm ơn anh. Việc còn lại em làm ngày mai ạ."},{"text":"分かった。お大事に。","speaker":"ai","translation":"Được rồi. Chúc con em mau khỏe."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo nghỉ ốm', 'cpath-wrk-09', 'Bạn xưng tên, xin nghỉ ốm và hẹn liên lạc lại.', 'N3', 'MEDIUM', 6, 'Bạn bị sốt không đi làm được, gọi điện báo sếp xin nghỉ ốm.', 'Qua điện thoại', 'Buổi sáng', '{"goals":[{"code":"NAME","type":"MISSION","title":"Xưng tên","required":true,"conditions":[{"type":"KEYWORD","value":"おはようございます|リンです|です"}],"description":"Chào và xưng tên mình khi gọi điện.","displayOrder":1},{"code":"SICK","type":"MISSION","title":"Xin nghỉ ốm","required":true,"conditions":[{"type":"KEYWORD","value":"熱|お休み|させていただけますか"}],"description":"Nói bị sốt và xin nghỉ hôm nay.","displayOrder":2},{"code":"PLAN","type":"MISSION","title":"Hẹn liên lạc lại","required":true,"conditions":[{"type":"KEYWORD","value":"行きます|午後|連絡します"}],"description":"Nói sẽ đi bệnh viện và liên lạc lại buổi chiều.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xưng tên khi gọi","next":"ASK","prompt":"Bạn gọi điện báo sếp. Hãy chào và xưng tên mình.","allowedGoalCodes":["NAME"],"suggestedReplies":["おはようございます。リンです。"]},{"code":"ASK","name":"Hỏi chuyện gì","next":"HOSPITAL","prompt":"Sếp nhận ra bạn và hỏi có chuyện gì.","allowedGoalCodes":["SICK"],"suggestedReplies":["熱があるので、今日はお休みさせていただけますか。"]},{"code":"HOSPITAL","name":"Hỏi đi viện chưa","next":"END","prompt":"Sếp đồng ý và hỏi bạn đã đi bệnh viện chưa.","allowedGoalCodes":["PLAN"],"suggestedReplies":["これから行きます。午後にまた連絡します。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Báo nghỉ ốm","message":"はい、ゆっくり休んでください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"熱があるので、今日はお休みさせていただけますか。","pattern":"お休みさせていただけますか","explanation":"Xin phép nghỉ ạ. Xin nghỉ rất lịch sự."},{"example":"分かりました。病院には行きましたか。","pattern":"〜には行きましたか","explanation":"Đã đi ~ chưa ạ. Hỏi về việc đã làm."},{"example":"これから行きます。午後にまた連絡します。","pattern":"〜にまた連絡します","explanation":"~ sẽ liên lạc lại. Hẹn phản hồi."}],"vocabulary":[{"jlpt":"N3","term":"有給","example":"有給を取ります。","meaning":"nghỉ có lương","reading":"ゆうきゅう"},{"jlpt":"N3","term":"早退","example":"三時に早退します。","meaning":"về sớm","reading":"そうたい"},{"jlpt":"N3","term":"病欠","example":"今日は病欠します。","meaning":"nghỉ ốm","reading":"びょうけつ"},{"jlpt":"N3","term":"引き継ぎ","example":"仕事を引き継ぎます。","meaning":"bàn giao","reading":"ひきつぎ"}],"exampleDialogue":[{"text":"おはようございます。リンです。","speaker":"learner","translation":"Chào buổi sáng. Em là Linh ạ."},{"text":"ああ、リンさん。どうしました？","speaker":"ai","translation":"À, Linh. Có chuyện gì ạ?"},{"text":"熱があるので、今日はお休みさせていただけますか。","speaker":"learner","translation":"Em bị sốt nên hôm nay xin phép nghỉ ạ."},{"text":"分かりました。病院には行きましたか。","speaker":"ai","translation":"Được rồi. Em đi bệnh viện chưa ạ?"},{"text":"これから行きます。午後にまた連絡します。","speaker":"learner","translation":"Em sẽ đi bây giờ. Chiều nay em liên lạc lại ạ."},{"text":"はい、ゆっくり休んでください。","speaker":"ai","translation":"Vâng, em nghỉ ngơi cho khỏe nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-doi-tac'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nhận điện thoại', 'cpath-wrk-10', 'Bạn xưng tên công ty, chuyển máy và báo đồng nghiệp vắng mặt.', 'N3', 'MEDIUM', 6, 'Điện thoại công ty reo, bạn nhận máy và đối tác muốn gặp đồng nghiệp.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"ANSWER","type":"MISSION","title":"Xưng tên công ty","required":true,"conditions":[{"type":"KEYWORD","value":"でございます|商事|はい"}],"description":"Nhấc máy và xưng tên công ty lịch sự.","displayOrder":1},{"code":"TRANSFER","type":"MISSION","title":"Chuyển máy","required":true,"conditions":[{"type":"KEYWORD","value":"かしこまりました|少々お待ちください|お願いします"}],"description":"Nhận lời và mời đối tác chờ một chút.","displayOrder":2},{"code":"ABSENT","type":"MISSION","title":"Báo vắng mặt","required":true,"conditions":[{"type":"KEYWORD","value":"席を外して|申し訳ございません|おり"}],"description":"Xin lỗi và báo đồng nghiệp đang rời khỏi chỗ.","displayOrder":3}],"states":[{"code":"OPEN","name":"Nhận điện thoại","next":"CALLER","prompt":"Điện thoại công ty reo. Hãy nhấc máy và xưng tên công ty.","allowedGoalCodes":["ANSWER"],"suggestedReplies":["はい、ミライ商事でございます。"]},{"code":"CALLER","name":"Đối tác xin gặp","next":"WAIT","prompt":"Đối tác xưng tên và xin gặp đồng nghiệp của bạn.","allowedGoalCodes":["TRANSFER"],"suggestedReplies":["かしこまりました。少々お待ちください。"]},{"code":"WAIT","name":"Đối tác cảm ơn","next":"END","prompt":"Đối tác cảm ơn khi bạn nhận chuyển máy.","allowedGoalCodes":["ABSENT"],"suggestedReplies":["申し訳ございません。田中はただいま席を外しております。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Nhận điện thoại","message":"では、折り返しお電話します。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"はい、ミライ商事でございます。","pattern":"〜でございます","explanation":"Xin nghe, (đây là) ~. Câu trả lời điện thoại công ty."},{"example":"いつもお世話になっております。山田ですが、田中さんをお願いします。","pattern":"〜さんをお願いします","explanation":"Xin gặp anh/chị ~. Yêu cầu gặp người cụ thể."},{"example":"申し訳ございません。田中はただいま席を外しております。","pattern":"〜は席を外しております","explanation":"~ đang rời khỏi chỗ. Báo người cần gặp vắng mặt."}],"vocabulary":[{"jlpt":"N3","term":"電話","example":"電話に出ます。","meaning":"điện thoại","reading":"でんわ"},{"jlpt":"N3","term":"担当","example":"担当者をお願いします。","meaning":"phụ trách","reading":"たんとう"},{"jlpt":"N3","term":"伝言","example":"伝言を承ります。","meaning":"lời nhắn","reading":"でんごん"},{"jlpt":"N3","term":"折り返し","example":"折り返し電話します。","meaning":"gọi lại","reading":"おりかえし"}],"exampleDialogue":[{"text":"はい、ミライ商事でございます。","speaker":"learner","translation":"Xin chào, công ty Mirai Shōji xin nghe ạ."},{"text":"いつもお世話になっております。山田ですが、田中さんをお願いします。","speaker":"ai","translation":"Chúng tôi luôn được quý công ty giúp đỡ. Tôi là Yamada, xin gặp anh Tanaka ạ."},{"text":"かしこまりました。少々お待ちください。","speaker":"learner","translation":"Vâng ạ. Xin ông đợi một chút."},{"text":"ありがとうございます。","speaker":"ai","translation":"Cảm ơn ạ."},{"text":"申し訳ございません。田中はただいま席を外しております。","speaker":"learner","translation":"Xin lỗi ông. Tanaka hiện đang rời khỏi chỗ ạ."},{"text":"では、折り返しお電話します。","speaker":"ai","translation":"Vậy tôi sẽ gọi lại sau ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-doi-tac'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nhận lời nhắn', 'cpath-wrk-11', 'Bạn xưng tên công ty, nhận lời nhắn và nhắc lại nội dung để xác nhận.', 'N3', 'MEDIUM', 6, 'Đối tác gọi điện nhờ bạn chuyển lời nhắn cho đồng nghiệp vắng mặt.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"ANSWER","type":"MISSION","title":"Xưng tên công ty","required":true,"conditions":[{"type":"KEYWORD","value":"でございます|商事|はい"}],"description":"Nhấc máy và xưng tên công ty.","displayOrder":1},{"code":"ACCEPT","type":"MISSION","title":"Nhận lời nhắn","required":true,"conditions":[{"type":"KEYWORD","value":"承ります|はい|お願いします"}],"description":"Nhận lời chuyển lời nhắn cho đồng nghiệp.","displayOrder":2},{"code":"REPEAT","type":"MISSION","title":"Nhắc lại nội dung","required":true,"conditions":[{"type":"KEYWORD","value":"復唱|変更|十時"}],"description":"Nhắc lại nội dung lời nhắn để xác nhận.","displayOrder":3}],"states":[{"code":"OPEN","name":"Nhận điện thoại","next":"MESSAGE","prompt":"Điện thoại công ty reo. Hãy xưng tên công ty.","allowedGoalCodes":["ANSWER"],"suggestedReplies":["はい、ミライ商事でございます。"]},{"code":"MESSAGE","name":"Đối tác nhờ nhắn","next":"CONTENT","prompt":"Đối tác xin nhờ chuyển lời nhắn cho đồng nghiệp.","allowedGoalCodes":["ACCEPT"],"suggestedReplies":["はい、承ります。"]},{"code":"CONTENT","name":"Đối tác nói nội dung","next":"END","prompt":"Đối tác nói nội dung muốn đổi giờ họp.","allowedGoalCodes":["REPEAT"],"suggestedReplies":["かしこまりました。復唱いたします。明日の会議を十時に変更ですね。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Nhận lời nhắn","message":"はい、よろしくお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"お世話になっております。佐藤ですが、田中さんに伝言をお願いできますか。","pattern":"〜をお願いできますか","explanation":"Nhờ ~ được không ạ. Nhờ chuyển lời nhắn."},{"example":"明日の会議を十時に変更したいとお伝えください。","pattern":"〜とお伝えください","explanation":"Xin nói là ~. Chuyển nội dung nhắn."},{"example":"かしこまりました。復唱いたします。明日の会議を十時に変更ですね。","pattern":"復唱いたします","explanation":"Tôi xin nhắc lại. Xác nhận lại nội dung."}],"vocabulary":[{"jlpt":"N3","term":"電話","example":"電話に出ます。","meaning":"điện thoại","reading":"でんわ"},{"jlpt":"N3","term":"担当","example":"担当者をお願いします。","meaning":"phụ trách","reading":"たんとう"},{"jlpt":"N3","term":"伝言","example":"伝言を承ります。","meaning":"lời nhắn","reading":"でんごん"},{"jlpt":"N3","term":"折り返し","example":"折り返し電話します。","meaning":"gọi lại","reading":"おりかえし"}],"exampleDialogue":[{"text":"はい、ミライ商事でございます。","speaker":"learner","translation":"Xin chào, công ty Mirai Shōji xin nghe ạ."},{"text":"お世話になっております。佐藤ですが、田中さんに伝言をお願いできますか。","speaker":"ai","translation":"Chúng tôi luôn được giúp đỡ. Tôi là Sato, nhờ chuyển lời nhắn cho anh Tanaka được không ạ?"},{"text":"はい、承ります。","speaker":"learner","translation":"Vâng, tôi xin nghe ạ."},{"text":"明日の会議を十時に変更したいとお伝えください。","speaker":"ai","translation":"Xin nói là muốn đổi cuộc họp ngày mai sang mười giờ ạ."},{"text":"かしこまりました。復唱いたします。明日の会議を十時に変更ですね。","speaker":"learner","translation":"Vâng ạ. Tôi xin nhắc lại: đổi cuộc họp ngày mai sang mười giờ ạ."},{"text":"はい、よろしくお願いします。","speaker":"ai","translation":"Vâng, nhờ anh ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-doi-tac'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Gọi điện cho khách', 'cpath-wrk-12', 'Bạn xưng tên công ty, nêu mục đích và đề nghị đổi giờ họp.', 'N3', 'MEDIUM', 6, 'Bạn gọi điện cho đối tác để xác nhận lịch hẹn.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"NAME","type":"MISSION","title":"Xưng tên công ty","required":true,"conditions":[{"type":"KEYWORD","value":"お世話になっております|リンです|商事"}],"description":"Xưng tên công ty và tên mình khi gọi.","displayOrder":1},{"code":"PURPOSE","type":"MISSION","title":"Nêu mục đích","required":true,"conditions":[{"type":"KEYWORD","value":"件で|連絡|打ち合わせ"}],"description":"Nói gọi để trao đổi về buổi họp ngày mai.","displayOrder":2},{"code":"CHANGE","type":"MISSION","title":"Đề nghị đổi giờ","required":true,"conditions":[{"type":"KEYWORD","value":"変更|十四時|していただけますか"}],"description":"Đề nghị đổi giờ họp sang mười bốn giờ.","displayOrder":3}],"states":[{"code":"OPEN","name":"Gọi điện xưng tên","next":"GREET","prompt":"Bạn gọi điện cho đối tác. Hãy xưng tên công ty và tên mình.","allowedGoalCodes":["NAME"],"suggestedReplies":["お世話になっております。ミライ商事のリンです。"]},{"code":"GREET","name":"Đối tác nhận ra","next":"ASK","prompt":"Đối tác chào lại và nhận ra bạn.","allowedGoalCodes":["PURPOSE"],"suggestedReplies":["明日の打ち合わせの件でご連絡しました。"]},{"code":"ASK","name":"Hỏi mục đích","next":"END","prompt":"Đối tác hỏi bạn gọi có việc gì.","allowedGoalCodes":["CHANGE"],"suggestedReplies":["時間を十四時に変更していただけますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Gọi điện cho khách","message":"大丈夫です。十四時に伺います。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"明日の打ち合わせの件でご連絡しました。","pattern":"〜の件でご連絡しました","explanation":"Tôi gọi để trao đổi về ~. Nêu mục đích cuộc gọi."},{"example":"時間を十四時に変更していただけますか。","pattern":"〜していただけますか","explanation":"Anh/chị làm ~ được không ạ. Nhờ đối tác một cách lịch sự."},{"example":"大丈夫です。十四時に伺います。","pattern":"〜に伺います","explanation":"Tôi sẽ đến ~. Khiêm nhường ngữ của 行きます."}],"vocabulary":[{"jlpt":"N3","term":"電話","example":"電話に出ます。","meaning":"điện thoại","reading":"でんわ"},{"jlpt":"N3","term":"担当","example":"担当者をお願いします。","meaning":"phụ trách","reading":"たんとう"},{"jlpt":"N3","term":"伝言","example":"伝言を承ります。","meaning":"lời nhắn","reading":"でんごん"},{"jlpt":"N3","term":"折り返し","example":"折り返し電話します。","meaning":"gọi lại","reading":"おりかえし"}],"exampleDialogue":[{"text":"お世話になっております。ミライ商事のリンです。","speaker":"learner","translation":"Chúng tôi luôn được quý công ty giúp đỡ. Tôi là Linh, công ty Mirai Shōji ạ."},{"text":"ああ、リンさん。こんにちは。","speaker":"ai","translation":"À, chị Linh. Chào chị."},{"text":"明日の打ち合わせの件でご連絡しました。","speaker":"learner","translation":"Tôi gọi để trao đổi về buổi họp ngày mai ạ."},{"text":"はい、何でしょうか。","speaker":"ai","translation":"Vâng, có việc gì ạ?"},{"text":"時間を十四時に変更していただけますか。","speaker":"learner","translation":"Chúng ta đổi giờ sang mười bốn giờ được không ạ?"},{"text":"大丈夫です。十四時に伺います。","speaker":"ai","translation":"Được ạ. Mười bốn giờ tôi sẽ đến."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-to-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Đeo đồ bảo hộ', 'cpath-wrk-16', 'Bạn hỏi đồ bảo hộ, hỏi thêm găng tay và xác nhận sẽ đeo ngay.', 'N3', 'MEDIUM', 6, 'Trước khi vào xưởng, bạn hỏi tổ trưởng cần chuẩn bị đồ bảo hộ gì.', 'Nhà máy sản xuất', 'Đầu ca làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi đồ bảo hộ","required":true,"conditions":[{"type":"KEYWORD","value":"必要ですか|作業場|何か"}],"description":"Hỏi tổ trưởng trước khi vào xưởng cần chuẩn bị gì.","displayOrder":1},{"code":"GLOVES","type":"MISSION","title":"Hỏi thêm găng tay","required":true,"conditions":[{"type":"KEYWORD","value":"手袋|必要ですか|も"}],"description":"Hỏi có cần đeo găng tay không.","displayOrder":2},{"code":"WEAR","type":"MISSION","title":"Xác nhận đeo ngay","required":true,"conditions":[{"type":"KEYWORD","value":"分かりました|着用します|すぐに"}],"description":"Xác nhận sẽ đeo đồ bảo hộ ngay.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi đồ bảo hộ","next":"TELL","prompt":"Trước khi vào xưởng, hãy hỏi tổ trưởng cần chuẩn bị gì.","allowedGoalCodes":["ASK"],"suggestedReplies":["主任、作業場に入る前に何か必要ですか。"]},{"code":"TELL","name":"Nhắc đeo đồ bảo hộ","next":"CONFIRM","prompt":"Tổ trưởng nhắc đeo mũ và giày bảo hộ.","allowedGoalCodes":["GLOVES"],"suggestedReplies":["手袋も必要ですか。"]},{"code":"CONFIRM","name":"Xác nhận bắt buộc","next":"END","prompt":"Tổ trưởng xác nhận trước khi làm phải đeo găng tay.","allowedGoalCodes":["WEAR"],"suggestedReplies":["分かりました。すぐに着用します。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Đeo đồ bảo hộ","message":"安全第一ですから、忘れないでください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"ヘルメットと安全靴を着用してください。","pattern":"〜を着用してください","explanation":"Hãy đeo/mặc ~ vào. Nhắc đeo đồ bảo hộ."},{"example":"手袋も必要ですか。","pattern":"〜も必要ですか","explanation":"~ có cần không ạ. Hỏi về đồ cần thiết."},{"example":"安全第一ですから、忘れないでください。","pattern":"〜ないでください","explanation":"Đừng ~. Nhắc nhở không làm gì."}],"vocabulary":[{"jlpt":"N3","term":"安全","example":"安全第一です。","meaning":"an toàn","reading":"あんぜん"},{"jlpt":"N3","term":"ヘルメット","example":"ヘルメットを着用してください。","meaning":"mũ bảo hộ","reading":"ヘルメット"},{"jlpt":"N3","term":"手袋","example":"手袋をつけます。","meaning":"găng tay","reading":"てぶくろ"},{"jlpt":"N3","term":"非常口","example":"非常口はどこですか。","meaning":"lối thoát hiểm","reading":"ひじょうぐち"}],"exampleDialogue":[{"text":"主任、作業場に入る前に何か必要ですか。","speaker":"learner","translation":"Thưa tổ trưởng, trước khi vào xưởng cần chuẩn bị gì ạ?"},{"text":"ヘルメットと安全靴を着用してください。","speaker":"ai","translation":"Hãy đội mũ bảo hộ và đi giày bảo hộ ạ."},{"text":"手袋も必要ですか。","speaker":"learner","translation":"Găng tay có cần không ạ?"},{"text":"はい、作業の前に必ずつけてください。","speaker":"ai","translation":"Có, trước khi làm việc nhất định phải đeo ạ."},{"text":"分かりました。すぐに着用します。","speaker":"learner","translation":"Em hiểu rồi. Em đeo ngay đây ạ."},{"text":"安全第一ですから、忘れないでください。","speaker":"ai","translation":"An toàn là trên hết nên đừng quên nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dan-anh'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chú ý nguồn lửa', 'cpath-wrk-17', 'Bạn hỏi xin hút thuốc, hỏi chỗ được hút và vị trí khu hút thuốc.', 'N3', 'MEDIUM', 6, 'Bạn hỏi đàn anh có được hút thuốc gần khu dễ cháy không.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Xin hút thuốc","required":true,"conditions":[{"type":"KEYWORD","value":"喫煙|てもいいですか|ここで"}],"description":"Hỏi có được hút thuốc ở đây không.","displayOrder":1},{"code":"WHERE","type":"MISSION","title":"Hỏi chỗ được hút","required":true,"conditions":[{"type":"KEYWORD","value":"どこで|吸えますか|では"}],"description":"Hỏi hút thuốc ở đâu thì được.","displayOrder":2},{"code":"LOCATION","type":"MISSION","title":"Hỏi vị trí","required":true,"conditions":[{"type":"KEYWORD","value":"喫煙所|どこですか|分かりました"}],"description":"Hỏi vị trí khu vực hút thuốc.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin hút thuốc","next":"NO","prompt":"Bạn muốn hút thuốc. Hãy hỏi đàn anh có được hút ở đây không.","allowedGoalCodes":["ASK"],"suggestedReplies":["先輩、ここで喫煙してもいいですか。"]},{"code":"NO","name":"Cấm hút ở đây","next":"SMOKING","prompt":"Đàn anh báo khu này cấm lửa.","allowedGoalCodes":["WHERE"],"suggestedReplies":["では、どこで吸えますか。"]},{"code":"SMOKING","name":"Chỉ khu hút thuốc","next":"END","prompt":"Đàn anh bảo hút ở khu vực hút thuốc.","allowedGoalCodes":["LOCATION"],"suggestedReplies":["分かりました。喫煙所はどこですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Chú ý nguồn lửa","message":"工場の裏口のそばです。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"先輩、ここで喫煙してもいいですか。","pattern":"〜てもいいですか","explanation":"~ được không ạ. Xin phép làm gì."},{"example":"分かりました。喫煙所はどこですか。","pattern":"〜はどこですか","explanation":"~ ở đâu ạ. Hỏi địa điểm."},{"example":"喫煙所でお願いします。","pattern":"〜でお願いします","explanation":"Xin làm ở ~. Chỉ dẫn nơi làm việc."}],"vocabulary":[{"jlpt":"N3","term":"安全","example":"安全第一です。","meaning":"an toàn","reading":"あんぜん"},{"jlpt":"N3","term":"ヘルメット","example":"ヘルメットを着用してください。","meaning":"mũ bảo hộ","reading":"ヘルメット"},{"jlpt":"N3","term":"手袋","example":"手袋をつけます。","meaning":"găng tay","reading":"てぶくろ"},{"jlpt":"N3","term":"非常口","example":"非常口はどこですか。","meaning":"lối thoát hiểm","reading":"ひじょうぐち"}],"exampleDialogue":[{"text":"先輩、ここで喫煙してもいいですか。","speaker":"learner","translation":"Anh ơi, hút thuốc ở đây được không ạ?"},{"text":"だめです。この辺は火気厳禁です。","speaker":"ai","translation":"Không được. Khu này cấm lửa ạ."},{"text":"では、どこで吸えますか。","speaker":"learner","translation":"Vậy hút ở đâu được ạ?"},{"text":"喫煙所でお願いします。","speaker":"ai","translation":"Hút ở khu vực hút thuốc ạ."},{"text":"分かりました。喫煙所はどこですか。","speaker":"learner","translation":"Em hiểu rồi. Khu hút thuốc ở đâu ạ?"},{"text":"工場の裏口のそばです。","speaker":"ai","translation":"Ở gần cổng sau của nhà máy ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-to-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Diễn tập sơ tán', 'cpath-wrk-18', 'Bạn hỏi giờ diễn tập, nơi tập trung và vị trí lối thoát hiểm.', 'N3', 'MEDIUM', 6, 'Bạn hỏi tổ trưởng về buổi diễn tập sơ tán hôm nay.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi diễn tập","required":true,"conditions":[{"type":"KEYWORD","value":"避難訓練|ありますか|今日"}],"description":"Hỏi hôm nay có diễn tập sơ tán không.","displayOrder":1},{"code":"PLACE","type":"MISSION","title":"Hỏi nơi tập trung","required":true,"conditions":[{"type":"KEYWORD","value":"どこに|集まりますか|集ま"}],"description":"Hỏi nơi tập trung khi sơ tán.","displayOrder":2},{"code":"EXIT","type":"MISSION","title":"Hỏi lối thoát hiểm","required":true,"conditions":[{"type":"KEYWORD","value":"非常口|どこですか|は"}],"description":"Hỏi vị trí lối thoát hiểm.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi diễn tập","next":"TIME","prompt":"Hãy hỏi tổ trưởng hôm nay có diễn tập sơ tán không.","allowedGoalCodes":["ASK"],"suggestedReplies":["主任、今日は避難訓練がありますか。"]},{"code":"TIME","name":"Báo giờ diễn tập","next":"SPOT","prompt":"Tổ trưởng cho biết diễn tập từ ba giờ chiều.","allowedGoalCodes":["PLACE"],"suggestedReplies":["どこに集まりますか。"]},{"code":"SPOT","name":"Báo chỗ tập trung","next":"END","prompt":"Tổ trưởng cho biết tập trung ở quảng trường trước nhà máy.","allowedGoalCodes":["EXIT"],"suggestedReplies":["非常口はどこですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Diễn tập sơ tán","message":"各フロアに二か所あります。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"主任、今日は避難訓練がありますか。","pattern":"〜がありますか","explanation":"Có ~ không ạ. Hỏi về sự kiện."},{"example":"どこに集まりますか。","pattern":"どこに〜ますか","explanation":"~ ở đâu ạ. Hỏi nơi thực hiện."},{"example":"非常口はどこですか。","pattern":"〜はどこですか","explanation":"~ ở đâu ạ. Hỏi địa điểm."}],"vocabulary":[{"jlpt":"N3","term":"安全","example":"安全第一です。","meaning":"an toàn","reading":"あんぜん"},{"jlpt":"N3","term":"ヘルメット","example":"ヘルメットを着用してください。","meaning":"mũ bảo hộ","reading":"ヘルメット"},{"jlpt":"N3","term":"手袋","example":"手袋をつけます。","meaning":"găng tay","reading":"てぶくろ"},{"jlpt":"N3","term":"非常口","example":"非常口はどこですか。","meaning":"lối thoát hiểm","reading":"ひじょうぐち"}],"exampleDialogue":[{"text":"主任、今日は避難訓練がありますか。","speaker":"learner","translation":"Thưa tổ trưởng, hôm nay có diễn tập sơ tán không ạ?"},{"text":"はい、午後三時からです。","speaker":"ai","translation":"Có, từ ba giờ chiều ạ."},{"text":"どこに集まりますか。","speaker":"learner","translation":"Tập trung ở đâu ạ?"},{"text":"工場の前の広場です。","speaker":"ai","translation":"Ở quảng trường trước nhà máy ạ."},{"text":"非常口はどこですか。","speaker":"learner","translation":"Lối thoát hiểm ở đâu ạ?"},{"text":"各フロアに二か所あります。","speaker":"ai","translation":"Mỗi tầng có hai chỗ ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-to-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận ca làm', 'cpath-wrk-19', 'Bạn xin xác nhận ca, hỏi giờ làm và giờ nghỉ giải lao.', 'N3', 'MEDIUM', 6, 'Bạn hỏi tổ trưởng về ca làm việc tuần tới.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"CHECK","type":"MISSION","title":"Xin xác nhận ca","required":true,"conditions":[{"type":"KEYWORD","value":"シフト|確認したい|来週"}],"description":"Nói muốn xác nhận ca làm tuần sau.","displayOrder":1},{"code":"HOURS","type":"MISSION","title":"Hỏi giờ làm","required":true,"conditions":[{"type":"KEYWORD","value":"何時から|何時まで|ですか"}],"description":"Hỏi ca làm từ mấy giờ đến mấy giờ.","displayOrder":2},{"code":"BREAK","type":"MISSION","title":"Hỏi giờ nghỉ","required":true,"conditions":[{"type":"KEYWORD","value":"休憩|ありますか|は"}],"description":"Hỏi có giờ nghỉ giải lao không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin xác nhận ca","next":"NIGHT","prompt":"Bạn muốn biết ca làm tuần sau. Hãy hỏi tổ trưởng.","allowedGoalCodes":["CHECK"],"suggestedReplies":["主任、来週のシフトを確認したいです。"]},{"code":"NIGHT","name":"Báo ca đêm","next":"TIME","prompt":"Tổ trưởng cho biết tuần sau bạn làm ca đêm.","allowedGoalCodes":["HOURS"],"suggestedReplies":["何時から何時までですか。"]},{"code":"TIME","name":"Báo giờ làm","next":"END","prompt":"Tổ trưởng cho biết làm từ mười giờ tối đến sáu giờ sáng.","allowedGoalCodes":["BREAK"],"suggestedReplies":["休憩はありますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xác nhận ca làm","message":"夜中に一時間あります。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"主任、来週のシフトを確認したいです。","pattern":"〜を確認したいです","explanation":"Muốn xác nhận ~. Nêu nhu cầu xác nhận."},{"example":"何時から何時までですか。","pattern":"〜から〜までです","explanation":"Từ ~ đến ~. Nói khoảng thời gian."},{"example":"休憩はありますか。","pattern":"〜はありますか","explanation":"Có ~ không ạ. Hỏi về sự có mặt."}],"vocabulary":[{"jlpt":"N3","term":"シフト","example":"シフトを確認したいです。","meaning":"ca làm việc","reading":"シフト"},{"jlpt":"N3","term":"夜勤","example":"来週は夜勤です。","meaning":"ca đêm","reading":"やきん"},{"jlpt":"N3","term":"残業","example":"三十分残業します。","meaning":"tăng ca","reading":"ざんぎょう"},{"jlpt":"N3","term":"休憩","example":"休憩はありますか。","meaning":"nghỉ giải lao","reading":"きゅうけい"}],"exampleDialogue":[{"text":"主任、来週のシフトを確認したいです。","speaker":"learner","translation":"Thưa tổ trưởng, em muốn xác nhận ca làm tuần sau ạ."},{"text":"リンさんは来週、夜勤です。","speaker":"ai","translation":"Tuần sau em làm ca đêm ạ."},{"text":"何時から何時までですか。","speaker":"learner","translation":"Từ mấy giờ đến mấy giờ ạ?"},{"text":"午後十時から朝六時までです。","speaker":"ai","translation":"Từ mười giờ tối đến sáu giờ sáng ạ."},{"text":"休憩はありますか。","speaker":"learner","translation":"Có giờ nghỉ giải lao không ạ?"},{"text":"夜中に一時間あります。","speaker":"ai","translation":"Có một tiếng vào giữa đêm ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dong-nghiep'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Bàn giao ca đêm', 'cpath-wrk-20', 'Bạn chào nhờ đồng nghiệp, báo máy có vấn đề và nhắc nguyên liệu sắp hết.', 'N3', 'MEDIUM', 6, 'Bạn bàn giao công việc cho đồng nghiệp làm ca đêm.', 'Nhà máy sản xuất', 'Cuối giờ làm', '{"goals":[{"code":"GREET","type":"MISSION","title":"Chào nhờ đồng nghiệp","required":true,"conditions":[{"type":"KEYWORD","value":"お疲れさま|よろしくお願いします|夜勤"}],"description":"Chào và nhờ đồng nghiệp ca đêm.","displayOrder":1},{"code":"MACHINE","type":"MISSION","title":"Báo máy có vấn đề","required":true,"conditions":[{"type":"KEYWORD","value":"調子悪い|機械|三番"}],"description":"Báo máy số ba hơi có vấn đề.","displayOrder":2},{"code":"MATERIAL","type":"MISSION","title":"Nhắc nguyên liệu","required":true,"conditions":[{"type":"KEYWORD","value":"材料|残り少ない|あと"}],"description":"Nhắc thêm nguyên liệu còn ít.","displayOrder":3}],"states":[{"code":"OPEN","name":"Chào và bàn giao","next":"ASK","prompt":"Bạn bàn giao ca đêm. Hãy chào và nhờ đồng nghiệp.","allowedGoalCodes":["GREET"],"suggestedReplies":["お疲れさまです。夜勤、よろしくお願いします。"]},{"code":"ASK","name":"Hỏi việc bàn giao","next":"OK","prompt":"Đồng nghiệp hỏi có gì cần bàn giao không.","allowedGoalCodes":["MACHINE"],"suggestedReplies":["三番の機械が少し調子悪いです。"]},{"code":"OK","name":"Ghi nhận máy","next":"END","prompt":"Đồng nghiệp ghi nhận và sẽ để ý máy số ba.","allowedGoalCodes":["MATERIAL"],"suggestedReplies":["あと、材料が残り少ないです。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Bàn giao ca đêm","message":"了解です。補充しておきます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"こちらこそ。何か引き継ぎはありますか。","pattern":"〜はありますか","explanation":"Có ~ không ạ. Hỏi về việc bàn giao."},{"example":"三番の機械が少し調子悪いです。","pattern":"〜が調子悪いです","explanation":"~ có vấn đề. Báo tình trạng máy."},{"example":"了解です。補充しておきます。","pattern":"〜ておきます","explanation":"Sẽ làm ~ trước. Hứa chuẩn bị trước."}],"vocabulary":[{"jlpt":"N3","term":"シフト","example":"シフトを確認したいです。","meaning":"ca làm việc","reading":"シフト"},{"jlpt":"N3","term":"夜勤","example":"来週は夜勤です。","meaning":"ca đêm","reading":"やきん"},{"jlpt":"N3","term":"残業","example":"三十分残業します。","meaning":"tăng ca","reading":"ざんぎょう"},{"jlpt":"N3","term":"休憩","example":"休憩はありますか。","meaning":"nghỉ giải lao","reading":"きゅうけい"}],"exampleDialogue":[{"text":"お疲れさまです。夜勤、よろしくお願いします。","speaker":"learner","translation":"Vất vả rồi. Ca đêm nhờ anh ạ."},{"text":"こちらこそ。何か引き継ぎはありますか。","speaker":"ai","translation":"Tôi cũng vậy. Có gì bàn giao không ạ?"},{"text":"三番の機械が少し調子悪いです。","speaker":"learner","translation":"Máy số ba hơi có vấn đề ạ."},{"text":"分かりました。注意して見ます。","speaker":"ai","translation":"Tôi hiểu rồi. Tôi sẽ để ý ạ."},{"text":"あと、材料が残り少ないです。","speaker":"learner","translation":"À, nguyên liệu còn ít ạ."},{"text":"了解です。補充しておきます。","speaker":"ai","translation":"Rõ rồi. Tôi sẽ bổ sung ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-quan-doc'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xin tăng ca', 'cpath-wrk-21', 'Bạn thưa lại, đồng ý tăng ca, hỏi giờ và chế độ tiền tăng ca.', 'N3', 'MEDIUM', 6, 'Quản đốc gọi bạn và đề nghị tăng ca để kịp tiến độ.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"ANSWER","type":"MISSION","title":"Thưa lại khi được gọi","required":true,"conditions":[{"type":"KEYWORD","value":"お呼びですか|工場長|はい"}],"description":"Thưa lại khi quản đốc gọi.","displayOrder":1},{"code":"AGREE","type":"MISSION","title":"Đồng ý và hỏi giờ","required":true,"conditions":[{"type":"KEYWORD","value":"分かりました|何時まで|残業"}],"description":"Đồng ý tăng ca và hỏi đến mấy giờ.","displayOrder":2},{"code":"PAY","type":"MISSION","title":"Hỏi tiền tăng ca","required":true,"conditions":[{"type":"KEYWORD","value":"残業代|出ますか|は"}],"description":"Hỏi có được trả tiền tăng ca không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Thưa khi được gọi","next":"OFFER","prompt":"Quản đốc gọi bạn. Hãy thưa lại.","allowedGoalCodes":["ANSWER"],"suggestedReplies":["工場長、お呼びですか。"]},{"code":"OFFER","name":"Đề nghị tăng ca","next":"TELL","prompt":"Quản đốc đề nghị từ hôm nay tăng ca ba mươi phút.","allowedGoalCodes":["AGREE"],"suggestedReplies":["分かりました。何時までですか。"]},{"code":"TELL","name":"Báo giờ tăng ca","next":"END","prompt":"Quản đốc cho biết tăng ca sau giờ quy định ba mươi phút.","allowedGoalCodes":["PAY"],"suggestedReplies":["残業代は出ますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xin tăng ca","message":"はい、きちんと支払います。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"リンさん、今日から三十分残業できますか。","pattern":"〜できますか","explanation":"Có thể ~ không ạ. Hỏi khả năng."},{"example":"残業代は出ますか。","pattern":"〜は出ますか","explanation":"Có trả ~ không ạ. Hỏi về chế độ."},{"example":"はい、きちんと支払います。","pattern":"きちんと〜ます","explanation":"~ đầy đủ. Cam kết thực hiện."}],"vocabulary":[{"jlpt":"N3","term":"シフト","example":"シフトを確認したいです。","meaning":"ca làm việc","reading":"シフト"},{"jlpt":"N3","term":"夜勤","example":"来週は夜勤です。","meaning":"ca đêm","reading":"やきん"},{"jlpt":"N3","term":"残業","example":"三十分残業します。","meaning":"tăng ca","reading":"ざんぎょう"},{"jlpt":"N3","term":"休憩","example":"休憩はありますか。","meaning":"nghỉ giải lao","reading":"きゅうけい"}],"exampleDialogue":[{"text":"工場長、お呼びですか。","speaker":"learner","translation":"Thưa quản đốc, ông gọi em ạ?"},{"text":"リンさん、今日から三十分残業できますか。","speaker":"ai","translation":"Linh, từ hôm nay em tăng ca ba mươi phút được không?"},{"text":"分かりました。何時までですか。","speaker":"learner","translation":"Vâng ạ. Đến mấy giờ ạ?"},{"text":"定時の後、三十分です。","speaker":"ai","translation":"Sau giờ quy định ba mươi phút ạ."},{"text":"残業代は出ますか。","speaker":"learner","translation":"Có trả tiền tăng ca không ạ?"},{"text":"はい、きちんと支払います。","speaker":"ai","translation":"Có, chúng tôi trả đầy đủ ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-to-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chỉ thị sắp xếp gọn gàng', 'cpath-wrk-28', 'Bạn hỏi việc cần làm, hỏi xử lý đồ bỏ và dọn vệ sinh.', 'N3', 'MEDIUM', 6, 'Tổ trưởng nhắc dọn dẹp sau giờ làm, bạn hỏi việc cần làm.', 'Nhà máy sản xuất', 'Cuối giờ làm', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi việc cần làm","required":true,"conditions":[{"type":"KEYWORD","value":"何をすればいい|今日|主任"}],"description":"Hỏi tổ trưởng hôm nay cần làm gì.","displayOrder":1},{"code":"TRASH","type":"MISSION","title":"Hỏi đồ bỏ đi","required":true,"conditions":[{"type":"KEYWORD","value":"不要なもの|捨てますか|は"}],"description":"Hỏi đồ không cần thì vứt đi không.","displayOrder":2},{"code":"CLEAN","type":"MISSION","title":"Hỏi dọn vệ sinh","required":true,"conditions":[{"type":"KEYWORD","value":"掃除|しますか|も"}],"description":"Hỏi có dọn vệ sinh nữa không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi việc cần làm","next":"TOOL","prompt":"Cuối giờ làm, hãy hỏi tổ trưởng cần làm gì.","allowedGoalCodes":["ASK"],"suggestedReplies":["主任、今日は何をすればいいですか。"]},{"code":"TOOL","name":"Bảo cất dụng cụ","next":"WASTE","prompt":"Tổ trưởng bảo để dụng cụ về chỗ cũ.","allowedGoalCodes":["TRASH"],"suggestedReplies":["不要なものは捨てますか。"]},{"code":"WASTE","name":"Bảo bỏ phế liệu","next":"END","prompt":"Tổ trưởng bảo bỏ đồ phế liệu vào thùng.","allowedGoalCodes":["CLEAN"],"suggestedReplies":["掃除もしますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Chỉ thị sắp xếp gọn gàng","message":"はい、床をきれいにしてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"作業が終わったら、工具を元の場所に戻してください。","pattern":"〜を元の場所に戻してください","explanation":"Hãy để ~ về chỗ cũ. Nhắc giữ gọn gàng."},{"example":"作業が終わったら、工具を元の場所に戻してください。","pattern":"〜たら、〜てください","explanation":"Sau khi ~ thì hãy ~. Chỉ trình tự dọn dẹp."},{"example":"掃除もしますか。","pattern":"〜もしますか","explanation":"Có làm ~ nữa không ạ. Hỏi thêm việc."}],"vocabulary":[{"jlpt":"N3","term":"整理","example":"工具を整理します。","meaning":"sàng lọc","reading":"せいり"},{"jlpt":"N3","term":"掃除","example":"床を掃除します。","meaning":"dọn vệ sinh","reading":"そうじ"},{"jlpt":"N3","term":"定位置","example":"工具を定位置に戻します。","meaning":"vị trí cố định","reading":"ていいち"},{"jlpt":"N3","term":"廃棄物","example":"廃棄物の箱に入れてください。","meaning":"phế liệu","reading":"はいきぶつ"}],"exampleDialogue":[{"text":"主任、今日は何をすればいいですか。","speaker":"learner","translation":"Thưa tổ trưởng, hôm nay em cần làm gì ạ?"},{"text":"作業が終わったら、工具を元の場所に戻してください。","speaker":"ai","translation":"Sau khi xong việc, hãy để dụng cụ về chỗ cũ ạ."},{"text":"不要なものは捨てますか。","speaker":"learner","translation":"Đồ không cần thì vứt đi ạ?"},{"text":"はい、廃棄物の箱に入れてください。","speaker":"ai","translation":"Vâng, bỏ vào thùng phế liệu ạ."},{"text":"掃除もしますか。","speaker":"learner","translation":"Có dọn vệ sinh không ạ?"},{"text":"はい、床をきれいにしてください。","speaker":"ai","translation":"Có, lau sạch sàn nhà ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dong-nghiep'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Trực nhật vệ sinh', 'cpath-wrk-29', 'Bạn hỏi ai trực, hỏi thời gian và khu vực phụ trách.', 'N3', 'MEDIUM', 6, 'Bạn hỏi đồng nghiệp về lịch trực vệ sinh tuần này.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"WHO","type":"MISSION","title":"Hỏi ai trực","required":true,"conditions":[{"type":"KEYWORD","value":"掃除当番|誰ですか|今週"}],"description":"Hỏi tuần này ai trực vệ sinh.","displayOrder":1},{"code":"WHEN","type":"MISSION","title":"Hỏi thời gian","required":true,"conditions":[{"type":"KEYWORD","value":"いつ|掃除しますか|は"}],"description":"Hỏi khi nào dọn vệ sinh.","displayOrder":2},{"code":"WHERE","type":"MISSION","title":"Hỏi khu vực","required":true,"conditions":[{"type":"KEYWORD","value":"担当の場所|どこですか|は"}],"description":"Hỏi khu vực phụ trách ở đâu.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi ai trực","next":"US","prompt":"Bạn muốn biết ai trực vệ sinh tuần này. Hãy hỏi đồng nghiệp.","allowedGoalCodes":["WHO"],"suggestedReplies":["今週の掃除当番は誰ですか。"]},{"code":"US","name":"Cho biết hai người","next":"TIME","prompt":"Đồng nghiệp cho biết hai người trực vệ sinh.","allowedGoalCodes":["WHEN"],"suggestedReplies":["いつ掃除しますか。"]},{"code":"TIME","name":"Báo giờ dọn","next":"END","prompt":"Đồng nghiệp cho biết mỗi ngày dọn sau giờ làm mười phút.","allowedGoalCodes":["WHERE"],"suggestedReplies":["担当の場所はどこですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Trực nhật vệ sinh","message":"三番のラインの周りです。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"今週の掃除当番は誰ですか。","pattern":"〜は誰ですか","explanation":"~ là ai ạ. Hỏi người phụ trách."},{"example":"いつ掃除しますか。","pattern":"いつ〜ますか","explanation":"Khi nào ~ ạ. Hỏi thời điểm."},{"example":"担当の場所はどこですか。","pattern":"〜はどこですか","explanation":"~ ở đâu ạ. Hỏi địa điểm."}],"vocabulary":[{"jlpt":"N3","term":"整理","example":"工具を整理します。","meaning":"sàng lọc","reading":"せいり"},{"jlpt":"N3","term":"掃除","example":"床を掃除します。","meaning":"dọn vệ sinh","reading":"そうじ"},{"jlpt":"N3","term":"定位置","example":"工具を定位置に戻します。","meaning":"vị trí cố định","reading":"ていいち"},{"jlpt":"N3","term":"廃棄物","example":"廃棄物の箱に入れてください。","meaning":"phế liệu","reading":"はいきぶつ"}],"exampleDialogue":[{"text":"今週の掃除当番は誰ですか。","speaker":"learner","translation":"Tuần này ai trực vệ sinh ạ?"},{"text":"私たち二人ですよ。","speaker":"ai","translation":"Hai chúng ta đấy ạ."},{"text":"いつ掃除しますか。","speaker":"learner","translation":"Khi nào dọn vệ sinh ạ?"},{"text":"毎日、終業後に十分間です。","speaker":"ai","translation":"Mỗi ngày mười phút sau giờ làm ạ."},{"text":"担当の場所はどこですか。","speaker":"learner","translation":"Khu vực phụ trách ở đâu ạ?"},{"text":"三番のラインの周りです。","speaker":"ai","translation":"Quanh dây chuyền số ba ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dan-anh'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Kiểm tra 5S', 'cpath-wrk-30', 'Bạn nhờ kiểm tra, xác nhận đã cất dụng cụ và lối đi sạch sẽ.', 'N3', 'MEDIUM', 6, 'Bạn nhờ đàn anh kiểm tra việc thực hiện 5S.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Nhờ kiểm tra 5S","required":true,"conditions":[{"type":"KEYWORD","value":"5S|点検|お願いします"}],"description":"Nhờ đàn anh kiểm tra 5S.","displayOrder":1},{"code":"DONE","type":"MISSION","title":"Xác nhận đã cất","required":true,"conditions":[{"type":"KEYWORD","value":"戻しました|全部|はい"}],"description":"Xác nhận dụng cụ đã để về chỗ cũ.","displayOrder":2},{"code":"CLEAN","type":"MISSION","title":"Xác nhận lối đi sạch","required":true,"conditions":[{"type":"KEYWORD","value":"置いていません|きれい|です"}],"description":"Xác nhận không để đồ trên lối đi.","displayOrder":3}],"states":[{"code":"OPEN","name":"Nhờ kiểm tra 5S","next":"TOOL","prompt":"Bạn nhờ đàn anh kiểm tra 5S.","allowedGoalCodes":["ASK"],"suggestedReplies":["先輩、5Sの点検をお願いします。"]},{"code":"TOOL","name":"Hỏi dụng cụ","next":"PATH","prompt":"Đàn anh hỏi dụng cụ đã để đúng chỗ chưa.","allowedGoalCodes":["DONE"],"suggestedReplies":["はい、全部戻しました。"]},{"code":"PATH","name":"Hỏi lối đi","next":"END","prompt":"Đàn anh hỏi có để đồ trên lối đi không.","allowedGoalCodes":["CLEAN"],"suggestedReplies":["置いていません。きれいです。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Kiểm tra 5S","message":"よくできました。この調子でお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"工具は定位置にありますか。","pattern":"〜は〜にありますか","explanation":"~ đã ở ~ chưa ạ. Kiểm tra vị trí."},{"example":"通路に物は置いていませんか。","pattern":"〜ませんか","explanation":"Có ~ không ạ. Hỏi xác nhận."},{"example":"よくできました。この調子でお願いします。","pattern":"この調子でお願いします","explanation":"Cứ duy trì như vậy ạ. Khen và động viên."}],"vocabulary":[{"jlpt":"N3","term":"整理","example":"工具を整理します。","meaning":"sàng lọc","reading":"せいり"},{"jlpt":"N3","term":"掃除","example":"床を掃除します。","meaning":"dọn vệ sinh","reading":"そうじ"},{"jlpt":"N3","term":"定位置","example":"工具を定位置に戻します。","meaning":"vị trí cố định","reading":"ていいち"},{"jlpt":"N3","term":"廃棄物","example":"廃棄物の箱に入れてください。","meaning":"phế liệu","reading":"はいきぶつ"}],"exampleDialogue":[{"text":"先輩、5Sの点検をお願いします。","speaker":"learner","translation":"Anh ơi, nhờ anh kiểm tra 5S ạ."},{"text":"工具は定位置にありますか。","speaker":"ai","translation":"Dụng cụ đã để đúng chỗ chưa ạ?"},{"text":"はい、全部戻しました。","speaker":"learner","translation":"Vâng, em đã để hết về chỗ cũ ạ."},{"text":"通路に物は置いていませんか。","speaker":"ai","translation":"Có để đồ trên lối đi không ạ?"},{"text":"置いていません。きれいです。","speaker":"learner","translation":"Không ạ. Sạch sẽ rồi ạ."},{"text":"よくできました。この調子でお願いします。","speaker":"ai","translation":"Tốt lắm. Cứ duy trì như vậy nhé ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Đón khách đến cửa hàng', 'cpath-wrk-31', 'Bạn hỏi sản phẩm gợi ý, nói nhu cầu tìm quà và xin xem thử.', 'N3', 'MEDIUM', 6, 'Bạn vào cửa hàng và muốn hỏi sản phẩm được gợi ý.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi sản phẩm gợi ý","required":true,"conditions":[{"type":"KEYWORD","value":"おすすめ|ありますか|商品"}],"description":"Hỏi nhân viên có sản phẩm gợi ý nào không.","displayOrder":1},{"code":"GIFT","type":"MISSION","title":"Nói nhu cầu","required":true,"conditions":[{"type":"KEYWORD","value":"プレゼント|探しています|を"}],"description":"Nói mình đang tìm quà tặng.","displayOrder":2},{"code":"LOOK","type":"MISSION","title":"Xin xem thử","required":true,"conditions":[{"type":"KEYWORD","value":"見てもいいですか|見|てもいい"}],"description":"Xin phép xem sản phẩm.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi sản phẩm gợi ý","next":"GREET","prompt":"Bạn vào cửa hàng. Hãy hỏi sản phẩm được gợi ý.","allowedGoalCodes":["ASK"],"suggestedReplies":["すみません、おすすめの商品はありますか。"]},{"code":"GREET","name":"Chào hỏi khách","next":"SHOW","prompt":"Nhân viên chào và hỏi bạn tìm gì.","allowedGoalCodes":["GIFT"],"suggestedReplies":["プレゼントを探しています。"]},{"code":"SHOW","name":"Giới thiệu sản phẩm","next":"END","prompt":"Nhân viên giới thiệu sản phẩm được ưa chuộng.","allowedGoalCodes":["LOOK"],"suggestedReplies":["見てもいいですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Đón khách đến cửa hàng","message":"どうぞ、ごゆっくりご覧ください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"すみません、おすすめの商品はありますか。","pattern":"〜はありますか","explanation":"Có ~ không ạ. Hỏi sự có mặt."},{"example":"プレゼントを探しています。","pattern":"〜を探しています","explanation":"Đang tìm ~. Nói nhu cầu tìm kiếm."},{"example":"見てもいいですか。","pattern":"〜てもいいですか","explanation":"~ được không ạ. Xin phép làm gì."}],"vocabulary":[{"jlpt":"N3","term":"いらっしゃいませ","example":"いらっしゃいませ。","meaning":"chào mừng quý khách","reading":"いらっしゃいませ"},{"jlpt":"N3","term":"売り場","example":"傘の売り場はどこですか。","meaning":"quầy bán","reading":"うりば"},{"jlpt":"N3","term":"試着","example":"試着したいです。","meaning":"thử đồ","reading":"しちゃく"},{"jlpt":"N3","term":"商品","example":"おすすめの商品はありますか。","meaning":"sản phẩm","reading":"しょうひん"}],"exampleDialogue":[{"text":"すみません、おすすめの商品はありますか。","speaker":"learner","translation":"Xin lỗi, có sản phẩm nào được gợi ý không ạ?"},{"text":"いらっしゃいませ。何かお探しですか。","speaker":"ai","translation":"Chào mừng quý khách. Quý khách tìm gì ạ?"},{"text":"プレゼントを探しています。","speaker":"learner","translation":"Em đang tìm quà tặng ạ."},{"text":"こちらは人気の商品です。いかがですか。","speaker":"ai","translation":"Đây là sản phẩm được ưa chuộng. Quý khách thấy sao ạ?"},{"text":"見てもいいですか。","speaker":"learner","translation":"Em xem thử được không ạ?"},{"text":"どうぞ、ごゆっくりご覧ください。","speaker":"ai","translation":"Mời quý khách cứ tự nhiên xem ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Tìm sản phẩm', 'cpath-wrk-32', 'Bạn hỏi vị trí quầy, hỏi thang cuốn và cảm ơn hướng dẫn.', 'N3', 'MEDIUM', 6, 'Bạn hỏi nhân viên vị trí quầy bán ô.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi vị trí quầy","required":true,"conditions":[{"type":"KEYWORD","value":"売り場|どこですか|傘"}],"description":"Hỏi quầy bán ô ở đâu.","displayOrder":1},{"code":"ESCALATOR","type":"MISSION","title":"Hỏi thang cuốn","required":true,"conditions":[{"type":"KEYWORD","value":"エスカレーター|ありますか|は"}],"description":"Hỏi có thang cuốn không.","displayOrder":2},{"code":"THANKS","type":"MISSION","title":"Cảm ơn hướng dẫn","required":true,"conditions":[{"type":"KEYWORD","value":"ありがとうございます|ご案内|ありがとう"}],"description":"Cảm ơn nhân viên đã hướng dẫn.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi vị trí quầy","next":"TELL","prompt":"Bạn cần tìm quầy bán ô. Hãy hỏi nhân viên.","allowedGoalCodes":["ASK"],"suggestedReplies":["すみません、傘の売り場はどこですか。"]},{"code":"TELL","name":"Chỉ vị trí","next":"YES","prompt":"Nhân viên cho biết ở phía trong tầng ba.","allowedGoalCodes":["ESCALATOR"],"suggestedReplies":["エスカレーターはありますか。"]},{"code":"YES","name":"Xác nhận thang cuốn","next":"END","prompt":"Nhân viên cho biết thang cuốn ở phía chính diện.","allowedGoalCodes":["THANKS"],"suggestedReplies":["ご案内ありがとうございます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Tìm sản phẩm","message":"どういたしまして。ごゆっくりどうぞ。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"すみません、傘の売り場はどこですか。","pattern":"〜はどこですか","explanation":"~ ở đâu ạ. Hỏi địa điểm."},{"example":"三階の奥でございます。","pattern":"〜でございます","explanation":"Là ~ (kính ngữ). Trả lời lịch sự."},{"example":"ご案内ありがとうございます。","pattern":"〜ありがとうございます","explanation":"Cảm ơn vì ~. Bày tỏ cảm ơn."}],"vocabulary":[{"jlpt":"N3","term":"いらっしゃいませ","example":"いらっしゃいませ。","meaning":"chào mừng quý khách","reading":"いらっしゃいませ"},{"jlpt":"N3","term":"売り場","example":"傘の売り場はどこですか。","meaning":"quầy bán","reading":"うりば"},{"jlpt":"N3","term":"試着","example":"試着したいです。","meaning":"thử đồ","reading":"しちゃく"},{"jlpt":"N3","term":"商品","example":"おすすめの商品はありますか。","meaning":"sản phẩm","reading":"しょうひん"}],"exampleDialogue":[{"text":"すみません、傘の売り場はどこですか。","speaker":"learner","translation":"Xin lỗi, quầy bán ô ở đâu ạ?"},{"text":"三階の奥でございます。","speaker":"ai","translation":"Ở phía trong tầng ba ạ."},{"text":"エスカレーターはありますか。","speaker":"learner","translation":"Có thang cuốn không ạ?"},{"text":"はい、正面にございます。","speaker":"ai","translation":"Vâng, có ở phía chính diện ạ."},{"text":"ご案内ありがとうございます。","speaker":"learner","translation":"Cảm ơn đã hướng dẫn ạ."},{"text":"どういたしまして。ごゆっくりどうぞ。","speaker":"ai","translation":"Không có gì ạ. Mời quý khách cứ tự nhiên."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xin thử đồ', 'cpath-wrk-33', 'Bạn xin thử đồ, hỏi đổi hàng và màu khác.', 'N3', 'MEDIUM', 6, 'Bạn muốn thử bộ quần áo và hỏi nhân viên.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"TRY","type":"MISSION","title":"Xin thử đồ","required":true,"conditions":[{"type":"KEYWORD","value":"試着したい|服|たいです"}],"description":"Nói muốn thử bộ quần áo.","displayOrder":1},{"code":"EXCHANGE","type":"MISSION","title":"Hỏi đổi hàng","required":true,"conditions":[{"type":"KEYWORD","value":"交換できますか|場合|サイズ"}],"description":"Hỏi không vừa có đổi được không.","displayOrder":2},{"code":"COLOR","type":"MISSION","title":"Hỏi màu khác","required":true,"conditions":[{"type":"KEYWORD","value":"色違い|ありますか|も"}],"description":"Hỏi có màu khác không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin thử đồ","next":"ROOM","prompt":"Bạn muốn thử bộ quần áo. Hãy nói với nhân viên.","allowedGoalCodes":["TRY"],"suggestedReplies":["この服を試着したいです。"]},{"code":"ROOM","name":"Chỉ phòng thử","next":"TAG","prompt":"Nhân viên chỉ phòng thử đồ.","allowedGoalCodes":["EXCHANGE"],"suggestedReplies":["サイズが合わない場合、交換できますか。"]},{"code":"TAG","name":"Nói điều kiện đổi","next":"END","prompt":"Nhân viên nói còn nhãn thì đổi được.","allowedGoalCodes":["COLOR"],"suggestedReplies":["色違いもありますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xin thử đồ","message":"はい、白と黒がございます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"この服を試着したいです。","pattern":"〜たいです","explanation":"Muốn ~. Nói mong muốn."},{"example":"サイズが合わない場合、交換できますか。","pattern":"〜場合、〜ますか","explanation":"Trong trường hợp ~ thì ~ ạ. Hỏi tình huống giả định."},{"example":"色違いもありますか。","pattern":"〜ば、〜ます","explanation":"Nếu ~ thì ~. Nói điều kiện."}],"vocabulary":[{"jlpt":"N3","term":"いらっしゃいませ","example":"いらっしゃいませ。","meaning":"chào mừng quý khách","reading":"いらっしゃいませ"},{"jlpt":"N3","term":"売り場","example":"傘の売り場はどこですか。","meaning":"quầy bán","reading":"うりば"},{"jlpt":"N3","term":"試着","example":"試着したいです。","meaning":"thử đồ","reading":"しちゃく"},{"jlpt":"N3","term":"商品","example":"おすすめの商品はありますか。","meaning":"sản phẩm","reading":"しょうひん"}],"exampleDialogue":[{"text":"この服を試着したいです。","speaker":"learner","translation":"Em muốn thử bộ quần áo này ạ."},{"text":"かしこまりました。試着室はあちらです。","speaker":"ai","translation":"Vâng ạ. Phòng thử đồ ở đằng kia ạ."},{"text":"サイズが合わない場合、交換できますか。","speaker":"learner","translation":"Nếu không vừa thì có đổi được không ạ?"},{"text":"はい、タグが付いていれば交換できます。","speaker":"ai","translation":"Vâng, nếu còn nhãn thì đổi được ạ."},{"text":"色違いもありますか。","speaker":"learner","translation":"Có màu khác không ạ?"},{"text":"はい、白と黒がございます。","speaker":"ai","translation":"Vâng, có màu trắng và đen ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Giới thiệu sản phẩm mới', 'cpath-wrk-34', 'Bạn hỏi sản phẩm mới, đặc điểm và cách dùng.', 'N3', 'MEDIUM', 6, 'Bạn hỏi nhân viên về sản phẩm mới.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi sản phẩm mới","required":true,"conditions":[{"type":"KEYWORD","value":"新商品|何かありますか|は"}],"description":"Hỏi có sản phẩm mới nào không.","displayOrder":1},{"code":"FEATURE","type":"MISSION","title":"Hỏi đặc điểm","required":true,"conditions":[{"type":"KEYWORD","value":"特徴|どんな|ありますか"}],"description":"Hỏi sản phẩm có đặc điểm gì.","displayOrder":2},{"code":"USE","type":"MISSION","title":"Hỏi cách dùng","required":true,"conditions":[{"type":"KEYWORD","value":"使い方|簡単|ですか"}],"description":"Hỏi cách dùng có đơn giản không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi sản phẩm mới","next":"SHOW","prompt":"Bạn muốn biết sản phẩm mới. Hãy hỏi nhân viên.","allowedGoalCodes":["ASK"],"suggestedReplies":["新商品は何かありますか。"]},{"code":"SHOW","name":"Giới thiệu sản phẩm mới","next":"TELL","prompt":"Nhân viên giới thiệu sản phẩm mới.","allowedGoalCodes":["FEATURE"],"suggestedReplies":["どんな特徴がありますか。"]},{"code":"TELL","name":"Nói đặc điểm","next":"END","prompt":"Nhân viên nói đặc điểm là nhẹ và bền.","allowedGoalCodes":["USE"],"suggestedReplies":["使い方は簡単ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Giới thiệu sản phẩm mới","message":"はい、どなたでも使えます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"新商品は何かありますか。","pattern":"〜は何かありますか","explanation":"Có ~ nào không ạ. Hỏi về sự tồn tại."},{"example":"どんな特徴がありますか。","pattern":"どんな〜がありますか","explanation":"Có ~ gì ạ. Hỏi đặc điểm."},{"example":"軽くて丈夫なのが特徴です。","pattern":"〜のが特徴です","explanation":"Đặc điểm là ~. Nêu đặc điểm."}],"vocabulary":[{"jlpt":"N3","term":"新商品","example":"新商品はありますか。","meaning":"sản phẩm mới","reading":"しんしょうひん"},{"jlpt":"N3","term":"特徴","example":"軽いのが特徴です。","meaning":"đặc điểm","reading":"とくちょう"},{"jlpt":"N3","term":"割引","example":"割引はありますか。","meaning":"giảm giá","reading":"わりびき"},{"jlpt":"N3","term":"使い方","example":"使い方を教えてください。","meaning":"cách dùng","reading":"つかいかた"}],"exampleDialogue":[{"text":"新商品は何かありますか。","speaker":"learner","translation":"Có sản phẩm mới nào không ạ?"},{"text":"こちらが新商品でございます。","speaker":"ai","translation":"Đây là sản phẩm mới ạ."},{"text":"どんな特徴がありますか。","speaker":"learner","translation":"Có đặc điểm gì ạ?"},{"text":"軽くて丈夫なのが特徴です。","speaker":"ai","translation":"Đặc điểm là nhẹ và bền ạ."},{"text":"使い方は簡単ですか。","speaker":"learner","translation":"Cách dùng có đơn giản không ạ?"},{"text":"はい、どなたでも使えます。","speaker":"ai","translation":"Vâng, ai cũng dùng được ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi giá', 'cpath-wrk-35', 'Bạn hỏi giá, hỏi giảm giá và cách làm thẻ hội viên.', 'N3', 'MEDIUM', 6, 'Bạn hỏi giá sản phẩm và chương trình giảm giá.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"PRICE","type":"MISSION","title":"Hỏi giá","required":true,"conditions":[{"type":"KEYWORD","value":"いくらですか|これ|は"}],"description":"Hỏi giá sản phẩm.","displayOrder":1},{"code":"SALE","type":"MISSION","title":"Hỏi giảm giá","required":true,"conditions":[{"type":"KEYWORD","value":"割引|ありますか|今"}],"description":"Hỏi hiện có giảm giá không.","displayOrder":2},{"code":"CARD","type":"MISSION","title":"Hỏi làm thẻ","required":true,"conditions":[{"type":"KEYWORD","value":"会員カード|どうやって|作りますか"}],"description":"Hỏi cách làm thẻ hội viên.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi giá","next":"PRICE2","prompt":"Bạn muốn biết giá. Hãy hỏi nhân viên.","allowedGoalCodes":["PRICE"],"suggestedReplies":["これはいくらですか。"]},{"code":"PRICE2","name":"Báo giá","next":"SALE2","prompt":"Nhân viên cho biết giá ba nghìn yên.","allowedGoalCodes":["SALE"],"suggestedReplies":["今、割引はありますか。"]},{"code":"SALE2","name":"Nói mức giảm","next":"END","prompt":"Nhân viên nói hội viên được giảm mười phần trăm.","allowedGoalCodes":["CARD"],"suggestedReplies":["会員カードはどうやって作りますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Hỏi giá","message":"こちらでお名前を書いてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"これはいくらですか。","pattern":"〜はいくらですか","explanation":"~ bao nhiêu tiền ạ. Hỏi giá."},{"example":"今、割引はありますか。","pattern":"〜はありますか","explanation":"Có ~ không ạ. Hỏi chương trình."},{"example":"会員カードはどうやって作りますか。","pattern":"〜はどうやって作りますか","explanation":"~ làm thế nào ạ. Hỏi cách thức."}],"vocabulary":[{"jlpt":"N3","term":"新商品","example":"新商品はありますか。","meaning":"sản phẩm mới","reading":"しんしょうひん"},{"jlpt":"N3","term":"特徴","example":"軽いのが特徴です。","meaning":"đặc điểm","reading":"とくちょう"},{"jlpt":"N3","term":"割引","example":"割引はありますか。","meaning":"giảm giá","reading":"わりびき"},{"jlpt":"N3","term":"使い方","example":"使い方を教えてください。","meaning":"cách dùng","reading":"つかいかた"}],"exampleDialogue":[{"text":"これはいくらですか。","speaker":"learner","translation":"Cái này bao nhiêu tiền ạ?"},{"text":"三千円でございます。","speaker":"ai","translation":"Ba nghìn yên ạ."},{"text":"今、割引はありますか。","speaker":"learner","translation":"Hiện có giảm giá không ạ?"},{"text":"はい、会員なら十パーセント引きです。","speaker":"ai","translation":"Vâng, hội viên được giảm mười phần trăm ạ."},{"text":"会員カードはどうやって作りますか。","speaker":"learner","translation":"Thẻ hội viên làm thế nào ạ?"},{"text":"こちらでお名前を書いてください。","speaker":"ai","translation":"Xin ghi tên vào đây ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hướng dẫn cách dùng', 'cpath-wrk-36', 'Bạn nhờ hướng dẫn, hỏi bước tiếp và sách hướng dẫn.', 'N3', 'MEDIUM', 6, 'Bạn nhờ nhân viên hướng dẫn cách dùng sản phẩm.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"ASK","type":"MISSION","title":"Nhờ hướng dẫn","required":true,"conditions":[{"type":"KEYWORD","value":"使い方|教えてください|製品"}],"description":"Nhờ nhân viên chỉ cách dùng sản phẩm.","displayOrder":1},{"code":"NEXT","type":"MISSION","title":"Hỏi bước tiếp","required":true,"conditions":[{"type":"KEYWORD","value":"その後|どうしますか|は"}],"description":"Hỏi sau đó làm gì.","displayOrder":2},{"code":"MANUAL","type":"MISSION","title":"Hỏi sách hướng dẫn","required":true,"conditions":[{"type":"KEYWORD","value":"説明書|ありますか|は"}],"description":"Hỏi có sách hướng dẫn không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Nhờ hướng dẫn","next":"STEP1","prompt":"Bạn muốn biết cách dùng. Hãy nhờ nhân viên hướng dẫn.","allowedGoalCodes":["ASK"],"suggestedReplies":["この製品の使い方を教えてください。"]},{"code":"STEP1","name":"Chỉ bước đầu","next":"STEP2","prompt":"Nhân viên bảo nhấn nút trước tiên.","allowedGoalCodes":["NEXT"],"suggestedReplies":["その後はどうしますか。"]},{"code":"STEP2","name":"Chỉ bước tiếp","next":"END","prompt":"Nhân viên bảo làm theo hướng dẫn trên màn hình.","allowedGoalCodes":["MANUAL"],"suggestedReplies":["説明書はありますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Hướng dẫn cách dùng","message":"はい、箱の中に入っています。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"この製品の使い方を教えてください。","pattern":"〜を教えてください","explanation":"Chỉ cho tôi ~. Nhờ hướng dẫn."},{"example":"まず、このボタンを押してください。","pattern":"まず、〜てください","explanation":"Trước tiên hãy ~. Hướng dẫn bước đầu."},{"example":"画面の指示に従ってください。","pattern":"〜に従ってください","explanation":"Hãy làm theo ~. Yêu cầu tuân theo."}],"vocabulary":[{"jlpt":"N3","term":"新商品","example":"新商品はありますか。","meaning":"sản phẩm mới","reading":"しんしょうひん"},{"jlpt":"N3","term":"特徴","example":"軽いのが特徴です。","meaning":"đặc điểm","reading":"とくちょう"},{"jlpt":"N3","term":"割引","example":"割引はありますか。","meaning":"giảm giá","reading":"わりびき"},{"jlpt":"N3","term":"使い方","example":"使い方を教えてください。","meaning":"cách dùng","reading":"つかいかた"}],"exampleDialogue":[{"text":"この製品の使い方を教えてください。","speaker":"learner","translation":"Chỉ cho em cách dùng sản phẩm này ạ."},{"text":"まず、このボタンを押してください。","speaker":"ai","translation":"Trước tiên, hãy nhấn nút này ạ."},{"text":"その後はどうしますか。","speaker":"learner","translation":"Sau đó làm gì ạ?"},{"text":"画面の指示に従ってください。","speaker":"ai","translation":"Làm theo hướng dẫn trên màn hình ạ."},{"text":"説明書はありますか。","speaker":"learner","translation":"Có sách hướng dẫn không ạ?"},{"text":"はい、箱の中に入っています。","speaker":"ai","translation":"Vâng, có để trong hộp ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Phương thức thanh toán', 'cpath-wrk-37', 'Bạn xin thanh toán, chọn trả thẻ và hỏi trả một lần.', 'N3', 'MEDIUM', 6, 'Bạn thanh toán và chọn phương thức trả tiền.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"PAY","type":"MISSION","title":"Xin thanh toán","required":true,"conditions":[{"type":"KEYWORD","value":"お会計|お願いします|会計"}],"description":"Nói muốn thanh toán.","displayOrder":1},{"code":"CARD","type":"MISSION","title":"Chọn trả thẻ","required":true,"conditions":[{"type":"KEYWORD","value":"カード|お願いします|で"}],"description":"Chọn trả bằng thẻ.","displayOrder":2},{"code":"LUMP","type":"MISSION","title":"Hỏi trả một lần","required":true,"conditions":[{"type":"KEYWORD","value":"一括払い|大丈夫ですか|で"}],"description":"Hỏi trả một lần có được không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin thanh toán","next":"METHOD","prompt":"Bạn muốn thanh toán. Hãy nói với nhân viên.","allowedGoalCodes":["PAY"],"suggestedReplies":["お会計をお願いします。"]},{"code":"METHOD","name":"Hỏi cách trả","next":"PIN","prompt":"Nhân viên hỏi bạn thanh toán bằng cách nào.","allowedGoalCodes":["CARD"],"suggestedReplies":["カードでお願いします。"]},{"code":"PIN","name":"Nhờ nhập mã PIN","next":"END","prompt":"Nhân viên mời nhập mã PIN vào máy.","allowedGoalCodes":["LUMP"],"suggestedReplies":["一括払いで大丈夫ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Phương thức thanh toán","message":"はい、大丈夫でございます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"カードでお願いします。","pattern":"〜でお願いします","explanation":"Cho ~ bằng ~. Chọn phương thức."},{"example":"お支払いはどうなさいますか。","pattern":"〜はどうなさいますか","explanation":"~ bằng cách nào ạ. Hỏi lịch sự."},{"example":"一括払いで大丈夫ですか。","pattern":"〜で大丈夫ですか","explanation":"~ được không ạ. Xác nhận sự phù hợp."}],"vocabulary":[{"jlpt":"N3","term":"お支払い","example":"お支払いはどうなさいますか。","meaning":"thanh toán","reading":"おしはらい"},{"jlpt":"N3","term":"現金","example":"現金でお願いします。","meaning":"tiền mặt","reading":"げんきん"},{"jlpt":"N3","term":"領収書","example":"領収書をもらえますか。","meaning":"biên lai","reading":"りょうしゅうしょ"},{"jlpt":"N3","term":"クーポン","example":"クーポンは使えますか。","meaning":"phiếu ưu đãi","reading":"クーポン"}],"exampleDialogue":[{"text":"お会計をお願いします。","speaker":"learner","translation":"Cho em thanh toán ạ."},{"text":"お支払いはどうなさいますか。","speaker":"ai","translation":"Quý khách thanh toán bằng cách nào ạ?"},{"text":"カードでお願いします。","speaker":"learner","translation":"Cho em trả bằng thẻ ạ."},{"text":"かしこまりました。こちらに暗証番号をお願いします。","speaker":"ai","translation":"Vâng ạ. Xin nhập mã PIN vào đây ạ."},{"text":"一括払いで大丈夫ですか。","speaker":"learner","translation":"Trả một lần được không ạ?"},{"text":"はい、大丈夫でございます。","speaker":"ai","translation":"Vâng, được ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xin biên lai', 'cpath-wrk-38', 'Bạn xin biên lai, ghi tên công ty và xin thêm hóa đơn.', 'N3', 'MEDIUM', 6, 'Sau khi thanh toán, bạn xin biên lai.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"RECEIPT","type":"MISSION","title":"Xin biên lai","required":true,"conditions":[{"type":"KEYWORD","value":"領収書|もらえますか|を"}],"description":"Xin nhân viên cho biên lai.","displayOrder":1},{"code":"COMPANY","type":"MISSION","title":"Ghi tên công ty","required":true,"conditions":[{"type":"KEYWORD","value":"会社の名前|お願いします|で"}],"description":"Yêu cầu ghi tên công ty trên biên lai.","displayOrder":2},{"code":"RCPT","type":"MISSION","title":"Xin thêm hóa đơn","required":true,"conditions":[{"type":"KEYWORD","value":"レシート|もらえますか|も"}],"description":"Xin thêm cả hóa đơn.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin biên lai","next":"NAME","prompt":"Bạn muốn xin biên lai. Hãy nói với nhân viên.","allowedGoalCodes":["RECEIPT"],"suggestedReplies":["領収書をもらえますか。"]},{"code":"NAME","name":"Hỏi người nhận","next":"WAIT","prompt":"Nhân viên hỏi người nhận ghi thế nào.","allowedGoalCodes":["COMPANY"],"suggestedReplies":["会社の名前でお願いします。"]},{"code":"WAIT","name":"Mời chờ","next":"END","prompt":"Nhân viên mời bạn chờ một chút.","allowedGoalCodes":["RCPT"],"suggestedReplies":["レシートももらえますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xin biên lai","message":"はい、こちらでございます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"領収書をもらえますか。","pattern":"〜をもらえますか","explanation":"Có thể nhận ~ không ạ. Yêu cầu nhận."},{"example":"はい、かしこまりました。宛名はどうしますか。","pattern":"〜はどうしますか","explanation":"~ làm thế nào ạ. Hỏi lựa chọn."},{"example":"会社の名前でお願いします。","pattern":"〜でお願いします","explanation":"Cho ~ bằng ~. Nêu yêu cầu."}],"vocabulary":[{"jlpt":"N3","term":"お支払い","example":"お支払いはどうなさいますか。","meaning":"thanh toán","reading":"おしはらい"},{"jlpt":"N3","term":"現金","example":"現金でお願いします。","meaning":"tiền mặt","reading":"げんきん"},{"jlpt":"N3","term":"領収書","example":"領収書をもらえますか。","meaning":"biên lai","reading":"りょうしゅうしょ"},{"jlpt":"N3","term":"クーポン","example":"クーポンは使えますか。","meaning":"phiếu ưu đãi","reading":"クーポン"}],"exampleDialogue":[{"text":"領収書をもらえますか。","speaker":"learner","translation":"Cho em xin biên lai được không ạ?"},{"text":"はい、かしこまりました。宛名はどうしますか。","speaker":"ai","translation":"Vâng ạ. Người nhận ghi thế nào ạ?"},{"text":"会社の名前でお願いします。","speaker":"learner","translation":"Cho em ghi tên công ty ạ."},{"text":"かしこまりました。少々お待ちください。","speaker":"ai","translation":"Vâng ạ. Xin chờ một chút ạ."},{"text":"レシートももらえますか。","speaker":"learner","translation":"Cho em cả hóa đơn được không ạ?"},{"text":"はい、こちらでございます。","speaker":"ai","translation":"Vâng, đây ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Dùng phiếu ưu đãi', 'cpath-wrk-39', 'Bạn hỏi dùng phiếu, hỏi mức giảm và dùng chung với thẻ điểm.', 'N3', 'MEDIUM', 6, 'Bạn hỏi nhân viên về phiếu ưu đãi khi thanh toán.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"USE","type":"MISSION","title":"Hỏi dùng phiếu","required":true,"conditions":[{"type":"KEYWORD","value":"クーポン|使えますか|は"}],"description":"Hỏi phiếu ưu đãi có dùng được không.","displayOrder":1},{"code":"PERCENT","type":"MISSION","title":"Hỏi mức giảm","required":true,"conditions":[{"type":"KEYWORD","value":"何パーセント|引き|になりますか"}],"description":"Hỏi được giảm bao nhiêu phần trăm.","displayOrder":2},{"code":"COMBO","type":"MISSION","title":"Hỏi dùng chung","required":true,"conditions":[{"type":"KEYWORD","value":"ポイントカード|併用できますか|も"}],"description":"Hỏi có dùng chung với thẻ điểm không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi dùng phiếu","next":"YES","prompt":"Bạn có phiếu ưu đãi. Hãy hỏi nhân viên dùng được không.","allowedGoalCodes":["USE"],"suggestedReplies":["このクーポンは使えますか。"]},{"code":"YES","name":"Xác nhận dùng được","next":"RATE","prompt":"Nhân viên xác nhận phiếu dùng được.","allowedGoalCodes":["PERCENT"],"suggestedReplies":["何パーセント引きになりますか。"]},{"code":"RATE","name":"Nói mức giảm","next":"END","prompt":"Nhân viên nói được giảm hai mươi phần trăm.","allowedGoalCodes":["COMBO"],"suggestedReplies":["ポイントカードも併用できますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Dùng phiếu ưu đãi","message":"申し訳ございません。併用はできません。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"このクーポンは使えますか。","pattern":"〜は使えますか","explanation":"~ dùng được không ạ. Hỏi tính khả dụng."},{"example":"何パーセント引きになりますか。","pattern":"〜になりますか","explanation":"Trở thành ~ ạ. Hỏi kết quả."},{"example":"申し訳ございません。併用はできません。","pattern":"〜はできません","explanation":"Không thể ~. Từ chối lịch sự."}],"vocabulary":[{"jlpt":"N3","term":"お支払い","example":"お支払いはどうなさいますか。","meaning":"thanh toán","reading":"おしはらい"},{"jlpt":"N3","term":"現金","example":"現金でお願いします。","meaning":"tiền mặt","reading":"げんきん"},{"jlpt":"N3","term":"領収書","example":"領収書をもらえますか。","meaning":"biên lai","reading":"りょうしゅうしょ"},{"jlpt":"N3","term":"クーポン","example":"クーポンは使えますか。","meaning":"phiếu ưu đãi","reading":"クーポン"}],"exampleDialogue":[{"text":"このクーポンは使えますか。","speaker":"learner","translation":"Phiếu ưu đãi này dùng được không ạ?"},{"text":"はい、お使いいただけます。","speaker":"ai","translation":"Vâng, quý khách dùng được ạ."},{"text":"何パーセント引きになりますか。","speaker":"learner","translation":"Được giảm bao nhiêu phần trăm ạ?"},{"text":"二十パーセント引きになります。","speaker":"ai","translation":"Được giảm hai mươi phần trăm ạ."},{"text":"ポイントカードも併用できますか。","speaker":"learner","translation":"Dùng chung với thẻ điểm được không ạ?"},{"text":"申し訳ございません。併用はできません。","speaker":"ai","translation":"Rất tiếc, không dùng chung được ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-le-tan-khach-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Đặt phòng', 'cpath-wrk-43', 'Bạn xin đặt phòng, nói số đêm và hỏi giá.', 'N3', 'MEDIUM', 6, 'Bạn đến quầy lễ tân để đặt phòng khách sạn.', 'Khách sạn', 'Buổi chiều', '{"goals":[{"code":"BOOK","type":"MISSION","title":"Xin đặt phòng","required":true,"conditions":[{"type":"KEYWORD","value":"予約したい|部屋|たいです"}],"description":"Nói muốn đặt phòng.","displayOrder":1},{"code":"NIGHTS","type":"MISSION","title":"Nói số đêm","required":true,"conditions":[{"type":"KEYWORD","value":"一泊|シングル|ありますか"}],"description":"Nói ở một đêm và hỏi phòng đơn.","displayOrder":2},{"code":"PRICE","type":"MISSION","title":"Hỏi giá","required":true,"conditions":[{"type":"KEYWORD","value":"いくらですか|一泊|は"}],"description":"Hỏi giá một đêm.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin đặt phòng","next":"ASK","prompt":"Bạn muốn đặt phòng. Hãy nói với lễ tân.","allowedGoalCodes":["BOOK"],"suggestedReplies":["部屋を予約したいです。"]},{"code":"ASK","name":"Hỏi số đêm","next":"ROOM","prompt":"Lễ tân hỏi bạn ở mấy đêm.","allowedGoalCodes":["NIGHTS"],"suggestedReplies":["一泊です。シングルはありますか。"]},{"code":"ROOM","name":"Báo còn phòng","next":"END","prompt":"Lễ tân cho biết còn phòng trống.","allowedGoalCodes":["PRICE"],"suggestedReplies":["一泊いくらですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Đặt phòng","message":"八千円でございます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"部屋を予約したいです。","pattern":"〜を予約したいです","explanation":"Muốn đặt ~. Nêu nhu cầu đặt."},{"example":"一泊です。シングルはありますか。","pattern":"〜はありますか","explanation":"Có ~ không ạ. Hỏi sự có mặt."},{"example":"一泊いくらですか。","pattern":"〜いくらですか","explanation":"~ bao nhiêu tiền ạ. Hỏi giá."}],"vocabulary":[{"jlpt":"N3","term":"部屋","example":"部屋を予約したいです。","meaning":"phòng","reading":"へや"},{"jlpt":"N3","term":"予約","example":"予約しています。","meaning":"đặt chỗ","reading":"よやく"},{"jlpt":"N3","term":"チェックイン","example":"チェックインをお願いします。","meaning":"nhận phòng","reading":"チェックイン"},{"jlpt":"N3","term":"料金","example":"宿泊料はいくらですか。","meaning":"phí","reading":"りょうきん"}],"exampleDialogue":[{"text":"部屋を予約したいです。","speaker":"learner","translation":"Em muốn đặt phòng ạ."},{"text":"かしこまりました。何泊ですか。","speaker":"ai","translation":"Vâng ạ. Quý khách ở mấy đêm ạ?"},{"text":"一泊です。シングルはありますか。","speaker":"learner","translation":"Một đêm ạ. Có phòng đơn không ạ?"},{"text":"はい、空室がございます。","speaker":"ai","translation":"Vâng, còn phòng trống ạ."},{"text":"一泊いくらですか。","speaker":"learner","translation":"Một đêm bao nhiêu tiền ạ?"},{"text":"八千円でございます。","speaker":"ai","translation":"Tám nghìn yên ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-le-tan-khach-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nhận phòng', 'cpath-wrk-44', 'Bạn xin nhận phòng, khai tên và hỏi chỗ nhận chìa khóa.', 'N3', 'MEDIUM', 6, 'Bạn làm thủ tục nhận phòng tại khách sạn.', 'Khách sạn', 'Buổi chiều', '{"goals":[{"code":"CHECKIN","type":"MISSION","title":"Xin nhận phòng","required":true,"conditions":[{"type":"KEYWORD","value":"チェックイン|お願いします|を"}],"description":"Nói muốn làm thủ tục nhận phòng.","displayOrder":1},{"code":"NAME","type":"MISSION","title":"Khai tên","required":true,"conditions":[{"type":"KEYWORD","value":"リンです|予約しています|です"}],"description":"Nói tên mình và đã đặt phòng.","displayOrder":2},{"code":"KEY","type":"MISSION","title":"Hỏi chìa khóa","required":true,"conditions":[{"type":"KEYWORD","value":"鍵|どこで|もらえますか"}],"description":"Hỏi nhận chìa khóa phòng ở đâu.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin nhận phòng","next":"ASK","prompt":"Bạn muốn nhận phòng. Hãy nói với lễ tân.","allowedGoalCodes":["CHECKIN"],"suggestedReplies":["チェックインをお願いします。"]},{"code":"ASK","name":"Hỏi tên","next":"CONFIRM","prompt":"Lễ tân hỏi tên bạn.","allowedGoalCodes":["NAME"],"suggestedReplies":["リンです。予約しています。"]},{"code":"CONFIRM","name":"Kiểm tra thông tin","next":"END","prompt":"Lễ tân xin kiểm tra thông tin.","allowedGoalCodes":["KEY"],"suggestedReplies":["部屋の鍵はどこでもらえますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Nhận phòng","message":"こちらでお渡しします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"チェックインをお願いします。","pattern":"〜をお願いします","explanation":"Cho ~. Yêu cầu thủ tục."},{"example":"お名前をうかがってもよろしいですか。","pattern":"〜てもよろしいですか","explanation":"~ có được không ạ. Hỏi lịch sự."},{"example":"リンです。予約しています。","pattern":"〜しています","explanation":"Đã ~. Nói trạng thái đã làm."}],"vocabulary":[{"jlpt":"N3","term":"部屋","example":"部屋を予約したいです。","meaning":"phòng","reading":"へや"},{"jlpt":"N3","term":"予約","example":"予約しています。","meaning":"đặt chỗ","reading":"よやく"},{"jlpt":"N3","term":"チェックイン","example":"チェックインをお願いします。","meaning":"nhận phòng","reading":"チェックイン"},{"jlpt":"N3","term":"料金","example":"宿泊料はいくらですか。","meaning":"phí","reading":"りょうきん"}],"exampleDialogue":[{"text":"チェックインをお願いします。","speaker":"learner","translation":"Cho em làm thủ tục nhận phòng ạ."},{"text":"お名前をうかがってもよろしいですか。","speaker":"ai","translation":"Cho tôi hỏi tên quý khách ạ?"},{"text":"リンです。予約しています。","speaker":"learner","translation":"Em tên Linh. Em đã đặt phòng ạ."},{"text":"確認いたします。少々お待ちください。","speaker":"ai","translation":"Để tôi kiểm tra ạ. Xin chờ một chút."},{"text":"部屋の鍵はどこでもらえますか。","speaker":"learner","translation":"Nhận chìa khóa phòng ở đâu ạ?"},{"text":"こちらでお渡しします。","speaker":"ai","translation":"Tôi giao ở đây ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-le-tan-khach-san'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Hỏi phí', 'cpath-wrk-45', 'Bạn hỏi phí, hỏi gồm bữa sáng và giờ trả phòng.', 'N3', 'MEDIUM', 6, 'Bạn hỏi lễ tân về phí lưu trú và các khoản kèm theo.', 'Khách sạn', 'Buổi chiều', '{"goals":[{"code":"PRICE","type":"MISSION","title":"Hỏi phí lưu trú","required":true,"conditions":[{"type":"KEYWORD","value":"宿泊料|いくらですか|は"}],"description":"Hỏi phí lưu trú bao nhiêu.","displayOrder":1},{"code":"BREAKFAST","type":"MISSION","title":"Hỏi bữa sáng","required":true,"conditions":[{"type":"KEYWORD","value":"朝食|含まれていますか|は"}],"description":"Hỏi đã gồm bữa sáng chưa.","displayOrder":2},{"code":"CHECKOUT","type":"MISSION","title":"Hỏi giờ trả phòng","required":true,"conditions":[{"type":"KEYWORD","value":"チェックアウト|何時ですか|は"}],"description":"Hỏi trả phòng lúc mấy giờ.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi phí lưu trú","next":"PRICE2","prompt":"Bạn muốn biết phí lưu trú. Hãy hỏi lễ tân.","allowedGoalCodes":["PRICE"],"suggestedReplies":["宿泊料はいくらですか。"]},{"code":"PRICE2","name":"Báo phí","next":"EXTRA","prompt":"Lễ tân cho biết một đêm mười nghìn yên.","allowedGoalCodes":["BREAKFAST"],"suggestedReplies":["朝食は含まれていますか。"]},{"code":"EXTRA","name":"Báo phí riêng","next":"END","prompt":"Lễ tân cho biết bữa sáng tính phí riêng.","allowedGoalCodes":["CHECKOUT"],"suggestedReplies":["チェックアウトは何時ですか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Hỏi phí","message":"午前十一時までです。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"宿泊料はいくらですか。","pattern":"〜はいくらですか","explanation":"~ bao nhiêu tiền ạ. Hỏi giá."},{"example":"朝食は含まれていますか。","pattern":"〜は含まれていますか","explanation":"Đã gồm ~ chưa ạ. Hỏi nội dung gồm."},{"example":"チェックアウトは何時ですか。","pattern":"〜は何時ですか","explanation":"~ lúc mấy giờ ạ. Hỏi thời gian."}],"vocabulary":[{"jlpt":"N3","term":"部屋","example":"部屋を予約したいです。","meaning":"phòng","reading":"へや"},{"jlpt":"N3","term":"予約","example":"予約しています。","meaning":"đặt chỗ","reading":"よやく"},{"jlpt":"N3","term":"チェックイン","example":"チェックインをお願いします。","meaning":"nhận phòng","reading":"チェックイン"},{"jlpt":"N3","term":"料金","example":"宿泊料はいくらですか。","meaning":"phí","reading":"りょうきん"}],"exampleDialogue":[{"text":"宿泊料はいくらですか。","speaker":"learner","translation":"Phí lưu trú bao nhiêu ạ?"},{"text":"一泊一万円でございます。","speaker":"ai","translation":"Một đêm mười nghìn yên ạ."},{"text":"朝食は含まれていますか。","speaker":"learner","translation":"Đã gồm bữa sáng chưa ạ?"},{"text":"いいえ、別料金です。","speaker":"ai","translation":"Không ạ, tính phí riêng ạ."},{"text":"チェックアウトは何時ですか。","speaker":"learner","translation":"Trả phòng lúc mấy giờ ạ?"},{"text":"午前十一時までです。","speaker":"ai","translation":"Đến mười một giờ sáng ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo tiến độ', 'cpath-wrk-04', 'Bạn mở đầu báo cáo, nêu mức hoàn thành và cam kết thời hạn nộp.', 'N2', 'HARD', 8, 'Bạn cần báo cáo tiến độ công việc đang làm cho sếp.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"REPORT","type":"MISSION","title":"Mở đầu báo cáo","required":true,"conditions":[{"type":"KEYWORD","value":"報告します|進捗|ご報告"}],"description":"Mở lời xin báo cáo tiến độ hiện tại.","displayOrder":1},{"code":"PROGRESS","type":"MISSION","title":"Nêu mức hoàn thành","required":true,"conditions":[{"type":"KEYWORD","value":"七割|完了|作成"}],"description":"Báo công việc đã hoàn thành đến bảy mươi phần trăm.","displayOrder":2},{"code":"DEADLINE","type":"MISSION","title":"Cam kết thời hạn","required":true,"conditions":[{"type":"KEYWORD","value":"明日中|提出|間に合う"}],"description":"Cam kết sẽ nộp trong ngày mai.","displayOrder":3}],"states":[{"code":"OPEN","name":"Mở đầu báo cáo","next":"ASK","prompt":"Bạn cần báo cáo tiến độ cho sếp. Hãy mở lời xin báo cáo.","allowedGoalCodes":["REPORT"],"suggestedReplies":["部長、現在の進捗をご報告します。"]},{"code":"ASK","name":"Mời báo cáo","next":"CHECK","prompt":"Sếp mời bạn báo cáo.","allowedGoalCodes":["PROGRESS"],"suggestedReplies":["資料作成は七割まで完了しました。"]},{"code":"CHECK","name":"Hỏi về hạn nộp","next":"END","prompt":"Sếp hỏi bạn có kịp hạn nộp không.","allowedGoalCodes":["DEADLINE"],"suggestedReplies":["はい、明日中に提出します。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Báo cáo tiến độ","message":"分かりました。よろしくお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"部長、現在の進捗をご報告します。","pattern":"〜をご報告します","explanation":"Xin báo cáo ~. Mở đầu báo cáo."},{"example":"資料作成は七割まで完了しました。","pattern":"〜割まで完了しました","explanation":"Đã hoàn tất ~ phần trăm. Báo mức độ hoàn thành."},{"example":"締め切りに間に合いますか。","pattern":"〜に間に合いますか","explanation":"Có kịp ~ không ạ. Hỏi về hạn."}],"vocabulary":[{"jlpt":"N2","term":"報告","example":"部長に進捗を報告します。","meaning":"báo cáo","reading":"ほうこく"},{"jlpt":"N2","term":"進捗","example":"進捗を確認してください。","meaning":"tiến độ","reading":"しんちょく"},{"jlpt":"N2","term":"完了","example":"作業が完了しました。","meaning":"hoàn tất","reading":"かんりょう"},{"jlpt":"N2","term":"提出","example":"明日までに提出します。","meaning":"nộp","reading":"ていしゅつ"}],"exampleDialogue":[{"text":"部長、現在の進捗をご報告します。","speaker":"learner","translation":"Thưa trưởng phòng, tôi xin báo cáo tiến độ hiện tại ạ."},{"text":"お願いします。","speaker":"ai","translation":"Em báo cáo đi."},{"text":"資料作成は七割まで完了しました。","speaker":"learner","translation":"Việc làm tài liệu đã hoàn tất bảy mươi phần trăm ạ."},{"text":"締め切りに間に合いますか。","speaker":"ai","translation":"Có kịp hạn không ạ?"},{"text":"はい、明日中に提出します。","speaker":"learner","translation":"Vâng, ngày mai tôi sẽ nộp ạ."},{"text":"分かりました。よろしくお願いします。","speaker":"ai","translation":"Được rồi. Nhờ em nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo sự cố', 'cpath-wrk-05', 'Bạn xin báo cáo, nêu sự cố bị chậm và giải thích nguyên nhân.', 'N2', 'HARD', 8, 'Công việc gặp trục trặc, bạn cần báo cáo sự cố cho sếp.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"NOTICE","type":"MISSION","title":"Xin báo cáo","required":true,"conditions":[{"type":"KEYWORD","value":"報告があります|ご報告|部長"}],"description":"Mở lời xin báo cáo sự việc.","displayOrder":1},{"code":"ISSUE","type":"MISSION","title":"Nêu sự cố","required":true,"conditions":[{"type":"KEYWORD","value":"遅れています|返事|取引先"}],"description":"Nói phản hồi từ đối tác đang bị chậm.","displayOrder":2},{"code":"CAUSE","type":"MISSION","title":"Giải thích nguyên nhân","required":true,"conditions":[{"type":"KEYWORD","value":"担当者|出張|不在|のようです"}],"description":"Giải thích người phụ trách đi công tác nên vắng mặt.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin báo cáo","next":"ASK","prompt":"Có sự cố trong công việc. Hãy mở lời xin báo cáo với sếp.","allowedGoalCodes":["NOTICE"],"suggestedReplies":["部長、ご報告があります。"]},{"code":"ASK","name":"Hỏi sự việc","next":"WHY","prompt":"Sếp hỏi có chuyện gì.","allowedGoalCodes":["ISSUE"],"suggestedReplies":["取引先からの返事が遅れています。"]},{"code":"WHY","name":"Hỏi nguyên nhân","next":"END","prompt":"Sếp hỏi nguyên nhân của sự chậm trễ.","allowedGoalCodes":["CAUSE"],"suggestedReplies":["担当者が急な出張で不在のようです。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Báo cáo sự cố","message":"では、今日中に電話で確認してください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"取引先からの返事が遅れています。","pattern":"〜が遅れています","explanation":"~ đang bị chậm. Báo tình trạng chậm trễ."},{"example":"担当者が急な出張で不在のようです。","pattern":"〜のようです","explanation":"Có vẻ là ~. Nêu phỏng đoán."},{"example":"では、今日中に電話で確認してください。","pattern":"〜で確認してください","explanation":"Hãy xác nhận bằng ~. Chỉ cách xác nhận."}],"vocabulary":[{"jlpt":"N2","term":"報告","example":"部長に進捗を報告します。","meaning":"báo cáo","reading":"ほうこく"},{"jlpt":"N2","term":"進捗","example":"進捗を確認してください。","meaning":"tiến độ","reading":"しんちょく"},{"jlpt":"N2","term":"完了","example":"作業が完了しました。","meaning":"hoàn tất","reading":"かんりょう"},{"jlpt":"N2","term":"提出","example":"明日までに提出します。","meaning":"nộp","reading":"ていしゅつ"}],"exampleDialogue":[{"text":"部長、ご報告があります。","speaker":"learner","translation":"Thưa trưởng phòng, em có việc cần báo cáo ạ."},{"text":"どうしましたか。","speaker":"ai","translation":"Có chuyện gì ạ?"},{"text":"取引先からの返事が遅れています。","speaker":"learner","translation":"Phản hồi từ phía đối tác đang bị chậm ạ."},{"text":"原因は何ですか。","speaker":"ai","translation":"Nguyên nhân là gì ạ?"},{"text":"担当者が急な出張で不在のようです。","speaker":"learner","translation":"Có vẻ người phụ trách đang đi công tác đột xuất nên không có mặt ạ."},{"text":"では、今日中に電話で確認してください。","speaker":"ai","translation":"Vậy hôm nay em gọi điện xác nhận nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo cáo kết quả', 'cpath-wrk-06', 'Bạn báo công việc đã xong, đưa báo cáo và xác nhận đã kiểm tra kỹ.', 'N2', 'HARD', 8, 'Bạn hoàn thành việc được giao và báo cáo kết quả cho sếp.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"DONE","type":"MISSION","title":"Báo việc đã xong","required":true,"conditions":[{"type":"KEYWORD","value":"完了しました|作業|依頼"}],"description":"Báo công việc được giao đã hoàn tất.","displayOrder":1},{"code":"RESULT","type":"MISSION","title":"Nêu kết quả","required":true,"conditions":[{"type":"KEYWORD","value":"問題なく|終わりました|報告書"}],"description":"Khẳng định hoàn thành ổn và đưa báo cáo.","displayOrder":2},{"code":"CHECK","type":"MISSION","title":"Xác nhận đã kiểm tra","required":true,"conditions":[{"type":"KEYWORD","value":"二回|確認しました|はい"}],"description":"Xác nhận đã kiểm tra lại cẩn thận.","displayOrder":3}],"states":[{"code":"OPEN","name":"Báo cáo hoàn tất","next":"ASK","prompt":"Bạn đã xong việc được giao. Hãy báo cáo với sếp.","allowedGoalCodes":["DONE"],"suggestedReplies":["部長、昨日依頼された作業が完了しました。"]},{"code":"ASK","name":"Hỏi kết quả","next":"PRAISE","prompt":"Sếp khen nhanh và hỏi kết quả thế nào.","allowedGoalCodes":["RESULT"],"suggestedReplies":["問題なく終わりました。こちらが報告書です。"]},{"code":"PRAISE","name":"Khen số liệu","next":"END","prompt":"Sếp cảm ơn và nhận xét số liệu khớp.","allowedGoalCodes":["CHECK"],"suggestedReplies":["はい、二回確認しました。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Báo cáo kết quả","message":"ご苦労さま。次の仕事もお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"部長、昨日依頼された作業が完了しました。","pattern":"〜が完了しました","explanation":"~ đã hoàn tất. Báo việc đã xong."},{"example":"問題なく終わりました。こちらが報告書です。","pattern":"〜なく終わりました","explanation":"Hoàn thành mà không ~. Báo kết quả thuận lợi."},{"example":"はい、二回確認しました。","pattern":"〜確認しました","explanation":"Đã kiểm tra ~. Nói đã rà soát."}],"vocabulary":[{"jlpt":"N2","term":"報告","example":"部長に進捗を報告します。","meaning":"báo cáo","reading":"ほうこく"},{"jlpt":"N2","term":"進捗","example":"進捗を確認してください。","meaning":"tiến độ","reading":"しんちょく"},{"jlpt":"N2","term":"完了","example":"作業が完了しました。","meaning":"hoàn tất","reading":"かんりょう"},{"jlpt":"N2","term":"提出","example":"明日までに提出します。","meaning":"nộp","reading":"ていしゅつ"}],"exampleDialogue":[{"text":"部長、昨日依頼された作業が完了しました。","speaker":"learner","translation":"Thưa trưởng phòng, việc hôm qua được giao đã hoàn tất ạ."},{"text":"早いですね。結果はどうでしたか。","speaker":"ai","translation":"Nhanh nhỉ. Kết quả thế nào ạ?"},{"text":"問題なく終わりました。こちらが報告書です。","speaker":"learner","translation":"Hoàn thành không có vấn đề gì ạ. Đây là báo cáo."},{"text":"ありがとう。数字も合っていますね。","speaker":"ai","translation":"Cảm ơn em. Số liệu cũng khớp nhỉ."},{"text":"はい、二回確認しました。","speaker":"learner","translation":"Vâng, em đã kiểm tra hai lần ạ."},{"text":"ご苦労さま。次の仕事もお願いします。","speaker":"ai","translation":"Vất vả rồi. Việc tiếp theo cũng nhờ em nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Chuẩn bị họp', 'cpath-wrk-13', 'Bạn báo đã chuẩn bị xong, in đủ tài liệu và xác nhận máy chiếu hoạt động.', 'N2', 'HARD', 8, 'Bạn chuẩn bị xong phòng họp và báo cáo với sếp.', 'Phòng họp', 'Trước giờ họp', '{"goals":[{"code":"READY","type":"MISSION","title":"Báo chuẩn bị xong","required":true,"conditions":[{"type":"KEYWORD","value":"準備ができました|会議|でき"}],"description":"Báo việc chuẩn bị họp đã xong.","displayOrder":1},{"code":"COPIES","type":"MISSION","title":"Báo số tài liệu","required":true,"conditions":[{"type":"KEYWORD","value":"十部|印刷|はい"}],"description":"Xác nhận đã in đủ mười bộ tài liệu.","displayOrder":2},{"code":"OK","type":"MISSION","title":"Xác nhận máy chiếu","required":true,"conditions":[{"type":"KEYWORD","value":"問題ありません|はい|確認"}],"description":"Xác nhận máy chiếu hoạt động bình thường.","displayOrder":3}],"states":[{"code":"OPEN","name":"Báo chuẩn bị xong","next":"CHECK","prompt":"Bạn chuẩn bị xong phòng họp. Hãy báo với sếp.","allowedGoalCodes":["READY"],"suggestedReplies":["部長、会議の準備ができました。"]},{"code":"CHECK","name":"Hỏi tài liệu","next":"PROJECTOR","prompt":"Sếp hỏi tài liệu có đủ số người không.","allowedGoalCodes":["COPIES"],"suggestedReplies":["はい、十部印刷しました。"]},{"code":"PROJECTOR","name":"Hỏi máy chiếu","next":"END","prompt":"Sếp hỏi đã kiểm tra máy chiếu chưa.","allowedGoalCodes":["OK"],"suggestedReplies":["はい、問題ありません。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Chuẩn bị họp","message":"では、十分間後に始めましょう。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"部長、会議の準備ができました。","pattern":"〜の準備ができました","explanation":"~ đã chuẩn bị xong. Báo đã chuẩn bị xong."},{"example":"資料は人数分ありますか。","pattern":"〜は〜分ありますか","explanation":"~ có đủ ~ phần không ạ. Hỏi số lượng."},{"example":"はい、問題ありません。","pattern":"〜後(ご)に始めましょう","explanation":"~ phút nữa bắt đầu. Thông báo giờ bắt đầu."}],"vocabulary":[{"jlpt":"N2","term":"会議","example":"会議の準備をします。","meaning":"cuộc họp","reading":"かいぎ"},{"jlpt":"N2","term":"議事録","example":"議事録を作成しました。","meaning":"biên bản họp","reading":"ぎじろく"},{"jlpt":"N2","term":"意見","example":"意見を申し上げます。","meaning":"ý kiến","reading":"いけん"},{"jlpt":"N2","term":"検討","example":"予算を検討しましょう。","meaning":"xem xét","reading":"けんとう"}],"exampleDialogue":[{"text":"部長、会議の準備ができました。","speaker":"learner","translation":"Thưa trưởng phòng, việc chuẩn bị họp đã xong ạ."},{"text":"資料は人数分ありますか。","speaker":"ai","translation":"Tài liệu có đủ số người không ạ?"},{"text":"はい、十部印刷しました。","speaker":"learner","translation":"Vâng, em đã in mười bộ ạ."},{"text":"プロジェクターの動作は確認しましたか。","speaker":"ai","translation":"Đã kiểm tra máy chiếu hoạt động chưa ạ?"},{"text":"はい、問題ありません。","speaker":"learner","translation":"Vâng, không có vấn đề gì ạ."},{"text":"では、十分間後に始めましょう。","speaker":"ai","translation":"Vậy mười phút nữa bắt đầu nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-cap-tren'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Phát biểu trong họp', 'cpath-wrk-14', 'Bạn xin phát biểu, nêu vấn đề ngân sách thiếu và đưa con số cụ thể.', 'N2', 'HARD', 8, 'Trong cuộc họp, bạn xin phép nêu ý kiến về kế hoạch.', 'Phòng họp', 'Trong giờ làm việc', '{"goals":[{"code":"SPEAK","type":"MISSION","title":"Xin phát biểu","required":true,"conditions":[{"type":"KEYWORD","value":"意見|申し上げます|計画"}],"description":"Xin phép nêu ý kiến về kế hoạch.","displayOrder":1},{"code":"OPINION","type":"MISSION","title":"Nêu ý kiến","required":true,"conditions":[{"type":"KEYWORD","value":"予算|不足|と思います"}],"description":"Nói ngân sách đang hơi thiếu.","displayOrder":2},{"code":"AMOUNT","type":"MISSION","title":"Đưa con số cụ thể","required":true,"conditions":[{"type":"KEYWORD","value":"十万円|追加|必要"}],"description":"Nêu số tiền cần bổ sung thêm.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin phát biểu","next":"GO","prompt":"Trong cuộc họp, hãy xin phép nêu ý kiến.","allowedGoalCodes":["SPEAK"],"suggestedReplies":["この計画について、意見を申し上げます。"]},{"code":"GO","name":"Sếp mời nói","next":"HOWMUCH","prompt":"Sếp mời bạn phát biểu.","allowedGoalCodes":["OPINION"],"suggestedReplies":["予算が少し不足していると思います。"]},{"code":"HOWMUCH","name":"Hỏi con số","next":"END","prompt":"Sếp hỏi cụ thể cần bao nhiêu.","allowedGoalCodes":["AMOUNT"],"suggestedReplies":["十万円ほど追加が必要です。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Phát biểu trong họp","message":"なるほど。検討しましょう。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"この計画について、意見を申し上げます。","pattern":"〜について、意見を申し上げます","explanation":"Về ~, xin nêu ý kiến. Mở đầu phát biểu."},{"example":"予算が少し不足していると思います。","pattern":"〜と思います","explanation":"Tôi nghĩ là ~. Nêu ý kiến mềm mỏng."},{"example":"十万円ほど追加が必要です。","pattern":"〜が必要です","explanation":"Cần ~. Nêu điều cần thiết."}],"vocabulary":[{"jlpt":"N2","term":"会議","example":"会議の準備をします。","meaning":"cuộc họp","reading":"かいぎ"},{"jlpt":"N2","term":"議事録","example":"議事録を作成しました。","meaning":"biên bản họp","reading":"ぎじろく"},{"jlpt":"N2","term":"意見","example":"意見を申し上げます。","meaning":"ý kiến","reading":"いけん"},{"jlpt":"N2","term":"検討","example":"予算を検討しましょう。","meaning":"xem xét","reading":"けんとう"}],"exampleDialogue":[{"text":"この計画について、意見を申し上げます。","speaker":"learner","translation":"Về kế hoạch này, em xin phép nêu ý kiến ạ."},{"text":"どうぞ。","speaker":"ai","translation":"Mời em."},{"text":"予算が少し不足していると思います。","speaker":"learner","translation":"Em nghĩ ngân sách hơi thiếu ạ."},{"text":"具体的にはどのくらいですか。","speaker":"ai","translation":"Cụ thể là khoảng bao nhiêu ạ?"},{"text":"十万円ほど追加が必要です。","speaker":"learner","translation":"Cần bổ sung thêm khoảng một trăm nghìn yên ạ."},{"text":"なるほど。検討しましょう。","speaker":"ai","translation":"Ra vậy. Chúng ta xem xét nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dong-nghiep'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận biên bản họp', 'cpath-wrk-15', 'Bạn báo đã soạn xong, nhờ kiểm tra và nhận góp ý để viết lại.', 'N2', 'HARD', 8, 'Bạn soạn xong biên bản họp và nhờ đồng nghiệp kiểm tra.', 'Văn phòng công ty', 'Trong giờ làm việc', '{"goals":[{"code":"DONE","type":"MISSION","title":"Báo đã soạn xong","required":true,"conditions":[{"type":"KEYWORD","value":"議事録|作成しました|会議"}],"description":"Nói đã soạn xong biên bản cuộc họp.","displayOrder":1},{"code":"CHECK","type":"MISSION","title":"Nhờ kiểm tra","required":true,"conditions":[{"type":"KEYWORD","value":"お願いします|誤字|教えてください"}],"description":"Đồng ý cho kiểm tra và nhờ báo lỗi chính tả.","displayOrder":2},{"code":"REWRITE","type":"MISSION","title":"Hứa viết lại","required":true,"conditions":[{"type":"KEYWORD","value":"書き直して|共有します|では"}],"description":"Nhận góp ý và hứa viết lại rồi chia sẻ.","displayOrder":3}],"states":[{"code":"OPEN","name":"Báo đã soạn xong","next":"REVIEW","prompt":"Bạn soạn xong biên bản họp. Hãy báo với đồng nghiệp.","allowedGoalCodes":["DONE"],"suggestedReplies":["昨日の会議の議事録を作成しました。"]},{"code":"REVIEW","name":"Đồng nghiệp muốn xem","next":"NOTE","prompt":"Đồng nghiệp khen và hỏi có xem được không.","allowedGoalCodes":["CHECK"],"suggestedReplies":["はい、お願いします。誤字があったら教えてください。"]},{"code":"NOTE","name":"Góp ý cách ghi","next":"END","prompt":"Đồng nghiệp góp ý một mục ghi hơi khó hiểu.","allowedGoalCodes":["REWRITE"],"suggestedReplies":["では、書き直して共有します。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xác nhận biên bản họp","message":"お願い。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"昨日の会議の議事録を作成しました。","pattern":"〜を作成しました","explanation":"Đã soạn xong ~. Báo đã làm xong tài liệu."},{"example":"はい、お願いします。誤字があったら教えてください。","pattern":"〜があったら教えてください","explanation":"Có ~ thì báo giúp. Nhờ phản hồi."},{"example":"では、書き直して共有します。","pattern":"〜て共有します","explanation":"~ rồi chia sẻ. Hẹn gửi lại."}],"vocabulary":[{"jlpt":"N2","term":"会議","example":"会議の準備をします。","meaning":"cuộc họp","reading":"かいぎ"},{"jlpt":"N2","term":"議事録","example":"議事録を作成しました。","meaning":"biên bản họp","reading":"ぎじろく"},{"jlpt":"N2","term":"意見","example":"意見を申し上げます。","meaning":"ý kiến","reading":"いけん"},{"jlpt":"N2","term":"検討","example":"予算を検討しましょう。","meaning":"xem xét","reading":"けんとう"}],"exampleDialogue":[{"text":"昨日の会議の議事録を作成しました。","speaker":"learner","translation":"Em đã soạn xong biên bản cuộc họp hôm qua ạ."},{"text":"お疲れさま。確認してもいい？","speaker":"ai","translation":"Vất vả rồi. Tôi xem được không?"},{"text":"はい、お願いします。誤字があったら教えてください。","speaker":"learner","translation":"Vâng, nhờ anh. Có lỗi chính tả thì báo em ạ."},{"text":"この決定事項の書き方が少し分かりにくいね。","speaker":"ai","translation":"Cách ghi mục quyết định này hơi khó hiểu nhỉ."},{"text":"では、書き直して共有します。","speaker":"learner","translation":"Vậy em viết lại rồi chia sẻ ạ."},{"text":"お願い。","speaker":"ai","translation":"Nhờ em."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dan-anh'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận quy trình', 'cpath-wrk-22', 'Bạn nhờ hướng dẫn, hỏi bước tiếp theo và bước kiểm tra cuối.', 'N2', 'HARD', 8, 'Bạn nhờ đàn anh chỉ quy trình lắp ráp linh kiện.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Nhờ hướng dẫn","required":true,"conditions":[{"type":"KEYWORD","value":"教えてください|手順|組立"}],"description":"Nhờ đàn anh chỉ quy trình lắp ráp.","displayOrder":1},{"code":"NEXT","type":"MISSION","title":"Hỏi bước tiếp","required":true,"conditions":[{"type":"KEYWORD","value":"その後|どうすればいい|は"}],"description":"Hỏi sau đó phải làm gì.","displayOrder":2},{"code":"TEST","type":"MISSION","title":"Hỏi bước kiểm tra","required":true,"conditions":[{"type":"KEYWORD","value":"検査|最後に|しますか"}],"description":"Hỏi cuối cùng có kiểm tra không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Nhờ hướng dẫn","next":"STEP1","prompt":"Bạn cần học quy trình lắp ráp. Hãy nhờ đàn anh chỉ dẫn.","allowedGoalCodes":["ASK"],"suggestedReplies":["先輩、この部品の組立手順を教えてください。"]},{"code":"STEP1","name":"Chỉ bước một","next":"STEP2","prompt":"Đàn anh hướng dẫn lắp hai linh kiện vào nhau.","allowedGoalCodes":["NEXT"],"suggestedReplies":["その後、どうすればいいですか。"]},{"code":"STEP2","name":"Chỉ bước vặn ốc","next":"END","prompt":"Đàn anh bảo vặn ba con ốc vít vào.","allowedGoalCodes":["TEST"],"suggestedReplies":["最後に検査をしますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xác nhận quy trình","message":"はい、必ず確認してください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"先輩、この部品の組立手順を教えてください。","pattern":"〜を教えてください","explanation":"Chỉ cho tôi ~. Nhờ hướng dẫn."},{"example":"まず、この二つの部品をはめます。","pattern":"まず、〜ます","explanation":"Trước tiên, ~. Bắt đầu hướng dẫn bước một."},{"example":"先輩、この部品の組立手順を教えてください。","pattern":"〜てください","explanation":"Hãy ~. Yêu cầu thao tác."}],"vocabulary":[{"jlpt":"N2","term":"作業","example":"作業指示をお願いします。","meaning":"công việc","reading":"さぎょう"},{"jlpt":"N2","term":"手順","example":"組立手順を教えてください。","meaning":"quy trình","reading":"てじゅん"},{"jlpt":"N2","term":"部品","example":"部品を百個加工します。","meaning":"linh kiện","reading":"ぶひん"},{"jlpt":"N2","term":"検査","example":"最後に検査します。","meaning":"kiểm tra","reading":"けんさ"}],"exampleDialogue":[{"text":"先輩、この部品の組立手順を教えてください。","speaker":"learner","translation":"Anh ơi, chỉ em quy trình lắp ráp linh kiện này với ạ."},{"text":"まず、この二つの部品をはめます。","speaker":"ai","translation":"Trước tiên, lắp hai linh kiện này vào nhau ạ."},{"text":"その後、どうすればいいですか。","speaker":"learner","translation":"Sau đó thì làm gì ạ?"},{"text":"ネジを三本締めてください。","speaker":"ai","translation":"Vặn ba con ốc vít vào ạ."},{"text":"最後に検査をしますか。","speaker":"learner","translation":"Cuối cùng có kiểm tra không ạ?"},{"text":"はい、必ず確認してください。","speaker":"ai","translation":"Có, nhất định phải kiểm tra ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-to-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Nghe chỉ thị', 'cpath-wrk-23', 'Bạn xin nhận việc, hỏi tiêu chuẩn và hạn hoàn thành.', 'N2', 'HARD', 8, 'Tổ trưởng giao việc cho bạn trong ca hôm nay.', 'Nhà máy sản xuất', 'Đầu ca làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Xin giao việc","required":true,"conditions":[{"type":"KEYWORD","value":"作業指示|お願いします|今日"}],"description":"Xin tổ trưởng giao việc hôm nay.","displayOrder":1},{"code":"STANDARD","type":"MISSION","title":"Hỏi tiêu chuẩn","required":true,"conditions":[{"type":"KEYWORD","value":"基準|同じ|いつも"}],"description":"Hỏi tiêu chuẩn có như mọi khi không.","displayOrder":2},{"code":"DEADLINE","type":"MISSION","title":"Hỏi hạn hoàn thành","required":true,"conditions":[{"type":"KEYWORD","value":"何時まで|終わらせますか|までに"}],"description":"Hỏi phải xong trước mấy giờ.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin giao việc","next":"TASK","prompt":"Đầu ca làm việc, hãy xin tổ trưởng giao việc.","allowedGoalCodes":["ASK"],"suggestedReplies":["主任、今日の作業指示をお願いします。"]},{"code":"TASK","name":"Giao việc và số lượng","next":"MANUAL","prompt":"Tổ trưởng giao gia công một trăm linh kiện.","allowedGoalCodes":["STANDARD"],"suggestedReplies":["基準はいつもと同じですか。"]},{"code":"MANUAL","name":"Bảo làm theo chỉ thị","next":"END","prompt":"Tổ trưởng bảo làm theo phiếu chỉ thị.","allowedGoalCodes":["DEADLINE"],"suggestedReplies":["何時までに終わらせますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Nghe chỉ thị","message":"午後五時までにお願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"主任、今日の作業指示をお願いします。","pattern":"〜をお願いします","explanation":"Xin giao ~. Yêu cầu nhận việc."},{"example":"はい、指示書の通りにお願いします。","pattern":"〜の通りに","explanation":"Theo đúng ~. Nhấn mạnh làm đúng chuẩn."},{"example":"何時までに終わらせますか。","pattern":"〜までに終わらせますか","explanation":"Phải xong trước ~ ạ. Hỏi hạn hoàn thành."}],"vocabulary":[{"jlpt":"N2","term":"作業","example":"作業指示をお願いします。","meaning":"công việc","reading":"さぎょう"},{"jlpt":"N2","term":"手順","example":"組立手順を教えてください。","meaning":"quy trình","reading":"てじゅん"},{"jlpt":"N2","term":"部品","example":"部品を百個加工します。","meaning":"linh kiện","reading":"ぶひん"},{"jlpt":"N2","term":"検査","example":"最後に検査します。","meaning":"kiểm tra","reading":"けんさ"}],"exampleDialogue":[{"text":"主任、今日の作業指示をお願いします。","speaker":"learner","translation":"Thưa tổ trưởng, xin giao việc hôm nay ạ."},{"text":"この部品を百個加工してください。","speaker":"ai","translation":"Em gia công một trăm cái linh kiện này ạ."},{"text":"基準はいつもと同じですか。","speaker":"learner","translation":"Tiêu chuẩn có như mọi khi không ạ?"},{"text":"はい、指示書の通りにお願いします。","speaker":"ai","translation":"Vâng, làm theo phiếu chỉ thị ạ."},{"text":"何時までに終わらせますか。","speaker":"learner","translation":"Phải xong trước mấy giờ ạ?"},{"text":"午後五時までにお願いします。","speaker":"ai","translation":"Trước năm giờ chiều ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dan-anh'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xác nhận số lượng', 'cpath-wrk-24', 'Bạn hỏi số lượng, hỏi số cái mỗi hộp và xác nhận tổng số hộp.', 'N2', 'HARD', 8, 'Bạn hỏi đàn anh số lượng hàng cần giao hôm nay.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi số lượng","required":true,"conditions":[{"type":"KEYWORD","value":"納入数量|いくつ|今日"}],"description":"Hỏi hôm nay phải giao bao nhiêu cái.","displayOrder":1},{"code":"PERBOX","type":"MISSION","title":"Hỏi số mỗi hộp","required":true,"conditions":[{"type":"KEYWORD","value":"一箱|何個|入りますか"}],"description":"Hỏi một hộp đựng bao nhiêu cái.","displayOrder":2},{"code":"CONFIRM","type":"MISSION","title":"Xác nhận tổng số","required":true,"conditions":[{"type":"KEYWORD","value":"十箱|確認してきます|では"}],"description":"Xác nhận tổng cộng mười hộp và đi kiểm tra.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi số lượng","next":"TOTAL","prompt":"Bạn cần biết số lượng giao hôm nay. Hãy hỏi đàn anh.","allowedGoalCodes":["ASK"],"suggestedReplies":["先輩、今日の納入数量はいくつですか。"]},{"code":"TOTAL","name":"Báo tổng số","next":"BOX","prompt":"Đàn anh cho biết hai trăm cái, tính theo hộp.","allowedGoalCodes":["PERBOX"],"suggestedReplies":["一箱に何個入りますか。"]},{"code":"BOX","name":"Báo số mỗi hộp","next":"END","prompt":"Đàn anh cho biết mỗi hộp hai mươi cái.","allowedGoalCodes":["CONFIRM"],"suggestedReplies":["では、十箱ですね。確認してきます。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xác nhận số lượng","message":"お願いします。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"先輩、今日の納入数量はいくつですか。","pattern":"〜はいくつですか","explanation":"~ là bao nhiêu ạ. Hỏi số lượng."},{"example":"二百個です。単位は箱で数えます。","pattern":"〜で数えます","explanation":"Tính theo ~. Nói cách đếm."},{"example":"では、十箱ですね。確認してきます。","pattern":"〜てきます","explanation":"Đi ~ rồi quay lại. Nói làm gì rồi về."}],"vocabulary":[{"jlpt":"N2","term":"作業","example":"作業指示をお願いします。","meaning":"công việc","reading":"さぎょう"},{"jlpt":"N2","term":"手順","example":"組立手順を教えてください。","meaning":"quy trình","reading":"てじゅん"},{"jlpt":"N2","term":"部品","example":"部品を百個加工します。","meaning":"linh kiện","reading":"ぶひん"},{"jlpt":"N2","term":"検査","example":"最後に検査します。","meaning":"kiểm tra","reading":"けんさ"}],"exampleDialogue":[{"text":"先輩、今日の納入数量はいくつですか。","speaker":"learner","translation":"Anh ơi, hôm nay phải giao bao nhiêu cái ạ?"},{"text":"二百個です。単位は箱で数えます。","speaker":"ai","translation":"Hai trăm cái. Tính theo đơn vị hộp ạ."},{"text":"一箱に何個入りますか。","speaker":"learner","translation":"Một hộp đựng bao nhiêu cái ạ?"},{"text":"一箱に二十個です。","speaker":"ai","translation":"Một hộp hai mươi cái ạ."},{"text":"では、十箱ですね。確認してきます。","speaker":"learner","translation":"Vậy là mười hộp nhỉ. Em đi kiểm tra ạ."},{"text":"お願いします。","speaker":"ai","translation":"Nhờ em ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-to-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo máy hỏng', 'cpath-wrk-25', 'Bạn báo máy dừng, miêu tả đèn báo và hỏi gọi thợ sửa.', 'N2', 'HARD', 8, 'Máy số ba đột ngột dừng, bạn báo cho tổ trưởng.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"STOP","type":"MISSION","title":"Báo máy dừng","required":true,"conditions":[{"type":"KEYWORD","value":"止まりました|機械|突然"}],"description":"Báo máy số ba tự nhiên dừng lại.","displayOrder":1},{"code":"LAMP","type":"MISSION","title":"Miêu tả đèn báo","required":true,"conditions":[{"type":"KEYWORD","value":"赤い|点滅|ランプ"}],"description":"Nói đèn đỏ đang nhấp nháy.","displayOrder":2},{"code":"REPAIR","type":"MISSION","title":"Hỏi gọi thợ sửa","required":true,"conditions":[{"type":"KEYWORD","value":"修理|呼びますか|分かりました"}],"description":"Hỏi có cần gọi thợ sửa không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Báo máy hỏng","next":"ASK","prompt":"Máy số ba dừng đột ngột. Hãy báo tổ trưởng.","allowedGoalCodes":["STOP"],"suggestedReplies":["主任、三番の機械が突然止まりました。"]},{"code":"ASK","name":"Hỏi đèn báo","next":"SIGN","prompt":"Tổ trưởng hỏi đèn báo có sáng không.","allowedGoalCodes":["LAMP"],"suggestedReplies":["赤いランプが点滅しています。"]},{"code":"SIGN","name":"Chỉ nhấn nút dừng","next":"END","prompt":"Tổ trưởng bảo đó là dấu hiệu hỏng, nhấn nút dừng.","allowedGoalCodes":["REPAIR"],"suggestedReplies":["分かりました。修理を呼びますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Báo máy hỏng","message":"はい、すぐにメーカーに連絡します。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"主任、三番の機械が突然止まりました。","pattern":"〜が止まりました","explanation":"~ đã dừng lại. Báo sự cố dừng máy."},{"example":"ランプは点いていますか。","pattern":"〜ています","explanation":"Đang ~. Miêu tả trạng thái."},{"example":"それは故障のサインです。停止ボタンを押してください。","pattern":"〜を押してください","explanation":"Hãy nhấn ~. Chỉ thao tác khẩn cấp."}],"vocabulary":[{"jlpt":"N2","term":"故障","example":"機械が故障しました。","meaning":"hỏng hóc","reading":"こしょう"},{"jlpt":"N2","term":"異常","example":"異常な音がします。","meaning":"bất thường","reading":"いじょう"},{"jlpt":"N2","term":"停止","example":"機械を停止してください。","meaning":"dừng lại","reading":"ていし"},{"jlpt":"N2","term":"修理","example":"修理を呼びます。","meaning":"sửa chữa","reading":"しゅうり"}],"exampleDialogue":[{"text":"主任、三番の機械が突然止まりました。","speaker":"learner","translation":"Thưa tổ trưởng, máy số ba tự nhiên dừng lại ạ."},{"text":"ランプは点いていますか。","speaker":"ai","translation":"Đèn báo có sáng không ạ?"},{"text":"赤いランプが点滅しています。","speaker":"learner","translation":"Đèn đỏ đang nhấp nháy ạ."},{"text":"それは故障のサインです。停止ボタンを押してください。","speaker":"ai","translation":"Đó là dấu hiệu hỏng hóc. Em nhấn nút dừng đi ạ."},{"text":"分かりました。修理を呼びますか。","speaker":"learner","translation":"Em hiểu rồi. Có gọi thợ sửa không ạ?"},{"text":"はい、すぐにメーカーに連絡します。","speaker":"ai","translation":"Có, tôi liên lạc nhà sản xuất ngay ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dan-anh'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Báo tiếng kêu lạ', 'cpath-wrk-26', 'Bạn báo tiếng lạ, miêu tả âm thanh và xác nhận dừng máy kiểm tra.', 'N2', 'HARD', 8, 'Bạn nghe tiếng kêu lạ từ máy và báo cho đàn anh.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"SOUND","type":"MISSION","title":"Báo tiếng kêu lạ","required":true,"conditions":[{"type":"KEYWORD","value":"変な音|音がします|機械"}],"description":"Báo máy phát ra tiếng kêu lạ.","displayOrder":1},{"code":"DESCRIBE","type":"MISSION","title":"Miêu tả âm thanh","required":true,"conditions":[{"type":"KEYWORD","value":"ガラガラ|音です|という"}],"description":"Miêu tả tiếng lạch cạch.","displayOrder":2},{"code":"CHECK","type":"MISSION","title":"Xác nhận dừng máy","required":true,"conditions":[{"type":"KEYWORD","value":"止めて|点検しますか|から"}],"description":"Xác nhận dừng máy rồi kiểm tra.","displayOrder":3}],"states":[{"code":"OPEN","name":"Báo tiếng kêu lạ","next":"ASK","prompt":"Máy phát ra tiếng lạ. Hãy báo đàn anh.","allowedGoalCodes":["SOUND"],"suggestedReplies":["先輩、機械から変な音がします。"]},{"code":"ASK","name":"Hỏi tiếng gì","next":"STOP","prompt":"Đàn anh hỏi tiếng như thế nào.","allowedGoalCodes":["DESCRIBE"],"suggestedReplies":["ガラガラという音です。"]},{"code":"STOP","name":"Đề nghị dừng máy","next":"END","prompt":"Đàn anh bảo nguy hiểm, tạm dừng máy.","allowedGoalCodes":["CHECK"],"suggestedReplies":["止めてから点検しますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Báo tiếng kêu lạ","message":"はい、一緒に確認しましょう。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"先輩、機械から変な音がします。","pattern":"〜から音がします","explanation":"Phát ra tiếng từ ~. Báo âm thanh bất thường."},{"example":"危険なので、一度機械を止めましょう。","pattern":"〜ので、〜ましょう","explanation":"Vì ~ nên hãy ~. Đề xuất xử lý."},{"example":"止めてから点検しますか。","pattern":"〜てから〜ますか","explanation":"Làm ~ rồi ~ ạ. Xác nhận trình tự."}],"vocabulary":[{"jlpt":"N2","term":"故障","example":"機械が故障しました。","meaning":"hỏng hóc","reading":"こしょう"},{"jlpt":"N2","term":"異常","example":"異常な音がします。","meaning":"bất thường","reading":"いじょう"},{"jlpt":"N2","term":"停止","example":"機械を停止してください。","meaning":"dừng lại","reading":"ていし"},{"jlpt":"N2","term":"修理","example":"修理を呼びます。","meaning":"sửa chữa","reading":"しゅうり"}],"exampleDialogue":[{"text":"先輩、機械から変な音がします。","speaker":"learner","translation":"Anh ơi, máy phát ra tiếng kêu lạ ạ."},{"text":"どんな音ですか。","speaker":"ai","translation":"Tiếng như thế nào ạ?"},{"text":"ガラガラという音です。","speaker":"learner","translation":"Tiếng lạch cạch ạ."},{"text":"危険なので、一度機械を止めましょう。","speaker":"ai","translation":"Nguy hiểm đấy, tạm dừng máy một lần nhé."},{"text":"止めてから点検しますか。","speaker":"learner","translation":"Dừng máy rồi kiểm tra ạ?"},{"text":"はい、一緒に確認しましょう。","speaker":"ai","translation":"Vâng, cùng kiểm tra nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-to-truong'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-cong-nhan-nha-may'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xử lý tạm thời', 'cpath-wrk-27', 'Bạn báo rò dầu, hỏi cách xử lý và xác nhận sẽ báo cáo sau.', 'N2', 'HARD', 8, 'Bạn phát hiện rò rỉ dầu và báo cho tổ trưởng.', 'Nhà máy sản xuất', 'Trong giờ làm việc', '{"goals":[{"code":"FIND","type":"MISSION","title":"Báo rò dầu","required":true,"conditions":[{"type":"KEYWORD","value":"油漏れ|発見しました|主任"}],"description":"Báo phát hiện rò rỉ dầu.","displayOrder":1},{"code":"FIX","type":"MISSION","title":"Hỏi cách xử lý","required":true,"conditions":[{"type":"KEYWORD","value":"応急処置|どうすればいい|は"}],"description":"Hỏi cách xử lý tạm thời.","displayOrder":2},{"code":"REPORT","type":"MISSION","title":"Xác nhận báo cáo","required":true,"conditions":[{"type":"KEYWORD","value":"報告しますか|その後|はい"}],"description":"Xác nhận sau khi xử lý sẽ báo cáo.","displayOrder":3}],"states":[{"code":"OPEN","name":"Báo rò dầu","next":"STOP","prompt":"Bạn phát hiện rò rỉ dầu. Hãy báo tổ trưởng.","allowedGoalCodes":["FIND"],"suggestedReplies":["主任、油漏れを発見しました。"]},{"code":"STOP","name":"Bảo dừng máy","next":"WIPE","prompt":"Tổ trưởng bảo dừng máy ngay lập tức.","allowedGoalCodes":["FIX"],"suggestedReplies":["応急処置はどうすればいいですか。"]},{"code":"WIPE","name":"Hướng dẫn lau dầu","next":"END","prompt":"Tổ trưởng bảo lau sạch dầu bị rò.","allowedGoalCodes":["REPORT"],"suggestedReplies":["その後、報告しますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xử lý tạm thời","message":"はい、すぐに知らせてください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"主任、油漏れを発見しました。","pattern":"〜を発見しました","explanation":"Đã phát hiện ~. Báo phát hiện sự cố."},{"example":"応急処置はどうすればいいですか。","pattern":"〜はどうすればいいですか","explanation":"~ thì phải làm thế nào ạ. Hỏi cách xử lý."},{"example":"まず、漏れた油を拭き取ってください。","pattern":"まず、〜てください","explanation":"Trước tiên hãy ~. Hướng dẫn bước đầu."}],"vocabulary":[{"jlpt":"N2","term":"故障","example":"機械が故障しました。","meaning":"hỏng hóc","reading":"こしょう"},{"jlpt":"N2","term":"異常","example":"異常な音がします。","meaning":"bất thường","reading":"いじょう"},{"jlpt":"N2","term":"停止","example":"機械を停止してください。","meaning":"dừng lại","reading":"ていし"},{"jlpt":"N2","term":"修理","example":"修理を呼びます。","meaning":"sửa chữa","reading":"しゅうり"}],"exampleDialogue":[{"text":"主任、油漏れを発見しました。","speaker":"learner","translation":"Thưa tổ trưởng, em phát hiện rò rỉ dầu ạ."},{"text":"すぐに機械を停止してください。","speaker":"ai","translation":"Hãy dừng máy ngay lập tức ạ."},{"text":"応急処置はどうすればいいですか。","speaker":"learner","translation":"Xử lý tạm thời thế nào ạ?"},{"text":"まず、漏れた油を拭き取ってください。","speaker":"ai","translation":"Trước tiên, lau sạch dầu bị rò ạ."},{"text":"その後、報告しますか。","speaker":"learner","translation":"Sau đó em báo cáo ạ?"},{"text":"はい、すぐに知らせてください。","speaker":"ai","translation":"Vâng, báo ngay cho tôi ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Phàn nàn hàng lỗi', 'cpath-wrk-40', 'Bạn báo sản phẩm lỗi, nói rõ vết xước có từ lúc mở và hỏi hoàn tiền.', 'N2', 'HARD', 8, 'Bạn phát hiện sản phẩm mua về bị xước và đến phàn nàn.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"COMPLAINT","type":"MISSION","title":"Báo sản phẩm lỗi","required":true,"conditions":[{"type":"KEYWORD","value":"傷があります|商品|買った"}],"description":"Báo sản phẩm mua về bị xước.","displayOrder":1},{"code":"WHEN","type":"MISSION","title":"Nói rõ thời điểm","required":true,"conditions":[{"type":"KEYWORD","value":"開けた時|傷|から"}],"description":"Nói vết xước có từ lúc mở ra.","displayOrder":2},{"code":"REFUND","type":"MISSION","title":"Hỏi hoàn tiền","required":true,"conditions":[{"type":"KEYWORD","value":"返金|できますか|も"}],"description":"Hỏi có thể hoàn tiền được không.","displayOrder":3}],"states":[{"code":"OPEN","name":"Báo sản phẩm lỗi","next":"SORRY","prompt":"Sản phẩm mua về bị xước. Hãy báo với nhân viên.","allowedGoalCodes":["COMPLAINT"],"suggestedReplies":["すみません、買った商品に傷があります。"]},{"code":"SORRY","name":"Xin lỗi và kiểm tra","next":"OFFER","prompt":"Nhân viên xin lỗi và xin kiểm tra.","allowedGoalCodes":["WHEN"],"suggestedReplies":["開けた時から傷がありました。"]},{"code":"OFFER","name":"Đề nghị đổi mới","next":"END","prompt":"Nhân viên đề nghị đổi sản phẩm mới.","allowedGoalCodes":["REFUND"],"suggestedReplies":["返金もできますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Phàn nàn hàng lỗi","message":"はい、ご希望に応じます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"すみません、買った商品に傷があります。","pattern":"〜があります","explanation":"Có ~. Báo tình trạng."},{"example":"申し訳ございません。確認させてください。","pattern":"〜させてください","explanation":"Cho tôi ~. Xin phép kiểm tra."},{"example":"返金もできますか。","pattern":"〜にお応じします","explanation":"Đáp ứng theo ~. Hứa xử lý linh hoạt."}],"vocabulary":[{"jlpt":"N2","term":"苦情","example":"苦情を伝えます。","meaning":"phàn nàn","reading":"くじょう"},{"jlpt":"N2","term":"返金","example":"返金をお願いします。","meaning":"hoàn tiền","reading":"へんきん"},{"jlpt":"N2","term":"不良品","example":"商品が初期不良でした。","meaning":"hàng lỗi","reading":"ふりょうひん"},{"jlpt":"N2","term":"対応","example":"今後の対応を確認します。","meaning":"xử lý","reading":"たいおう"}],"exampleDialogue":[{"text":"すみません、買った商品に傷があります。","speaker":"learner","translation":"Xin lỗi, sản phẩm em mua bị xước ạ."},{"text":"申し訳ございません。確認させてください。","speaker":"ai","translation":"Thành thật xin lỗi quý khách. Cho tôi kiểm tra ạ."},{"text":"開けた時から傷がありました。","speaker":"learner","translation":"Từ lúc mở ra đã có vết xước rồi ạ."},{"text":"かしこまりました。新しいものとお取り替えします。","speaker":"ai","translation":"Vâng ạ. Tôi đổi cho quý khách sản phẩm mới ạ."},{"text":"返金もできますか。","speaker":"learner","translation":"Có thể hoàn tiền được không ạ?"},{"text":"はい、ご希望に応じます。","speaker":"ai","translation":"Vâng, chúng tôi đáp ứng theo mong muốn của quý khách ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-quan-ly-cua-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Yêu cầu hoàn tiền', 'cpath-wrk-41', 'Bạn xin hoàn tiền, nêu lý do hàng lỗi và xin lời xin lỗi.', 'N2', 'HARD', 8, 'Bạn yêu cầu hoàn tiền với quản lý cửa hàng.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"REFUND","type":"MISSION","title":"Xin hoàn tiền","required":true,"conditions":[{"type":"KEYWORD","value":"返金|お願いしたい|店長"}],"description":"Yêu cầu quản lý cho hoàn tiền.","displayOrder":1},{"code":"REASON","type":"MISSION","title":"Nêu lý do","required":true,"conditions":[{"type":"KEYWORD","value":"初期不良|商品|買った"}],"description":"Nói sản phẩm bị lỗi ban đầu.","displayOrder":2},{"code":"APOLOGY","type":"MISSION","title":"Xin lời xin lỗi","required":true,"conditions":[{"type":"KEYWORD","value":"お詫び|いただけますか|言葉"}],"description":"Xin nhận lời xin lỗi.","displayOrder":3}],"states":[{"code":"OPEN","name":"Xin hoàn tiền","next":"HEAR","prompt":"Bạn muốn yêu cầu hoàn tiền. Hãy nói với quản lý.","allowedGoalCodes":["REFUND"],"suggestedReplies":["店長さん、返金をお願いしたいです。"]},{"code":"HEAR","name":"Xin nghe trình bày","next":"SORRY","prompt":"Quản lý xin nghe diễn biến sự việc.","allowedGoalCodes":["REASON"],"suggestedReplies":["買った商品が初期不良でした。"]},{"code":"SORRY","name":"Xin lỗi và hoàn tiền","next":"END","prompt":"Quản lý xin lỗi và hoàn tiền ngay.","allowedGoalCodes":["APOLOGY"],"suggestedReplies":["お詫びの言葉もいただけますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Yêu cầu hoàn tiền","message":"はい、心よりお詫び申し上げます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"店長さん、返金をお願いしたいです。","pattern":"〜をお願いしたいです","explanation":"Muốn yêu cầu ~. Nêu yêu cầu."},{"example":"経緯をお聞かせいただけますか。","pattern":"〜をお聞かせいただけますか","explanation":"Cho tôi nghe ~ ạ. Xin nghe trình bày."},{"example":"大変申し訳ございません。すぐに返金いたします。","pattern":"〜いたします","explanation":"Tôi sẽ ~ (khiêm nhường). Cam kết thực hiện."}],"vocabulary":[{"jlpt":"N2","term":"苦情","example":"苦情を伝えます。","meaning":"phàn nàn","reading":"くじょう"},{"jlpt":"N2","term":"返金","example":"返金をお願いします。","meaning":"hoàn tiền","reading":"へんきん"},{"jlpt":"N2","term":"不良品","example":"商品が初期不良でした。","meaning":"hàng lỗi","reading":"ふりょうひん"},{"jlpt":"N2","term":"対応","example":"今後の対応を確認します。","meaning":"xử lý","reading":"たいおう"}],"exampleDialogue":[{"text":"店長さん、返金をお願いしたいです。","speaker":"learner","translation":"Quản lý ơi, em muốn yêu cầu hoàn tiền ạ."},{"text":"経緯をお聞かせいただけますか。","speaker":"ai","translation":"Cho tôi nghe diễn biến sự việc ạ."},{"text":"買った商品が初期不良でした。","speaker":"learner","translation":"Sản phẩm em mua bị lỗi ban đầu ạ."},{"text":"大変申し訳ございません。すぐに返金いたします。","speaker":"ai","translation":"Thành thật xin lỗi. Tôi hoàn tiền ngay ạ."},{"text":"お詫びの言葉もいただけますか。","speaker":"learner","translation":"Em có thể nhận lời xin lỗi không ạ?"},{"text":"はい、心よりお詫び申し上げます。","speaker":"ai","translation":"Vâng, tôi chân thành xin lỗi quý khách ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-nhan-vien-ban-hang'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-khach-hang'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Xin lỗi và xử lý', 'cpath-wrk-42', 'Bạn hỏi tiến triển, nguyên nhân và cách xử lý sau này.', 'N2', 'HARD', 8, 'Bạn quay lại hỏi tiến triển của khiếu nại lần trước.', 'Cửa hàng', 'Ban ngày', '{"goals":[{"code":"ASK","type":"MISSION","title":"Hỏi tiến triển","required":true,"conditions":[{"type":"KEYWORD","value":"どうなりましたか|クレーム|件"}],"description":"Hỏi chuyện khiếu nại lần trước thế nào.","displayOrder":1},{"code":"CAUSE","type":"MISSION","title":"Hỏi nguyên nhân","required":true,"conditions":[{"type":"KEYWORD","value":"原因|分かりましたか|は"}],"description":"Hỏi đã biết nguyên nhân chưa.","displayOrder":2},{"code":"FUTURE","type":"MISSION","title":"Hỏi cách xử lý","required":true,"conditions":[{"type":"KEYWORD","value":"今後の対応|どうなりますか|は"}],"description":"Hỏi cách xử lý sau này.","displayOrder":3}],"states":[{"code":"OPEN","name":"Hỏi tiến triển","next":"SORRY","prompt":"Bạn quay lại hỏi tiến triển khiếu nại.","allowedGoalCodes":["ASK"],"suggestedReplies":["この前のクレームの件はどうなりましたか。"]},{"code":"SORRY","name":"Xin lỗi","next":"RESULT","prompt":"Nhân viên xin lỗi vì đã làm phiền.","allowedGoalCodes":["CAUSE"],"suggestedReplies":["原因は分かりましたか。"]},{"code":"RESULT","name":"Báo nguyên nhân","next":"END","prompt":"Nhân viên cho biết kết quả là lỗi ban đầu.","allowedGoalCodes":["FUTURE"],"suggestedReplies":["今後の対応はどうなりますか。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành: Xin lỗi và xử lý","message":"再発防止に努めます。ご指摘ありがとうございます。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"OPEN"}', '{"grammar":[{"example":"この前のクレームの件はどうなりましたか。","pattern":"〜はどうなりましたか","explanation":"~ thế nào rồi ạ. Hỏi tiến triển."},{"example":"ご迷惑をおかけして申し訳ございません。","pattern":"〜て申し訳ございません","explanation":"Xin lỗi vì ~. Bày tỏ xin lỗi."},{"example":"再発防止に努めます。ご指摘ありがとうございます。","pattern":"〜に努めます","explanation":"Cố gắng ~. Cam kết cải thiện."}],"vocabulary":[{"jlpt":"N2","term":"苦情","example":"苦情を伝えます。","meaning":"phàn nàn","reading":"くじょう"},{"jlpt":"N2","term":"返金","example":"返金をお願いします。","meaning":"hoàn tiền","reading":"へんきん"},{"jlpt":"N2","term":"不良品","example":"商品が初期不良でした。","meaning":"hàng lỗi","reading":"ふりょうひん"},{"jlpt":"N2","term":"対応","example":"今後の対応を確認します。","meaning":"xử lý","reading":"たいおう"}],"exampleDialogue":[{"text":"この前のクレームの件はどうなりましたか。","speaker":"learner","translation":"Chuyện khiếu nại lần trước thế nào rồi ạ?"},{"text":"ご迷惑をおかけして申し訳ございません。","speaker":"ai","translation":"Chúng tôi thành thật xin lỗi vì đã làm phiền quý khách ạ."},{"text":"原因は分かりましたか。","speaker":"learner","translation":"Đã biết nguyên nhân chưa ạ?"},{"text":"はい、調査の結果、初期不良でした。","speaker":"ai","translation":"Vâng, kết quả điều tra cho thấy là lỗi ban đầu ạ."},{"text":"今後の対応はどうなりますか。","speaker":"learner","translation":"Cách xử lý sau này thế nào ạ?"},{"text":"再発防止に努めます。ご指摘ありがとうございます。","speaker":"ai","translation":"Chúng tôi sẽ cố gắng ngăn tái diễn. Cảm ơn góp ý của quý khách ạ."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT INTO scenario (category_id, ai_role_id, learner_role_id, prompt_template_id, title, slug, description, jlpt_level, difficulty, estimated_minutes, background, location, time_of_day, flow_json, learning_content_json, thumbnail_url, is_active) VALUES ((SELECT id FROM category WHERE code = 'introduction'), (SELECT id FROM scenario_role WHERE role_kind = 'AI' AND code = 'cpath-dan-anh'), (SELECT id FROM scenario_role WHERE role_kind = 'LEARNER' AND code = 'cpath-nhan-vien-cong-ty'), (SELECT id FROM prompt_template WHERE code = 'scenario_practical_v2'), 'Một ngày làm việc tổng hợp', 'cpath-test-work', 'Một cuộc gọi tổng hợp đi qua các chủ đề chính của Tiếng Nhật công việc: chào hỏi, giới thiệu, báo cáo, phát biểu và xin phép.', 'N2', 'HARD', 15, 'Bạn trải qua một ngày làm việc tổng hợp tại văn phòng: chào hỏi, tự giới thiệu, báo cáo, họp hành và xin về sớm.', 'Văn phòng công ty', 'Cả ngày làm việc', '{"goals":[{"code":"GREET","type":"MISSION","title":"Chào buổi sáng","required":true,"conditions":[{"type":"KEYWORD","value":"おはようございます|おはよう"}],"description":"Chào đồng nghiệp đầu ngày làm việc.","displayOrder":1},{"code":"INTRO","type":"MISSION","title":"Tự giới thiệu bản thân","required":true,"conditions":[{"type":"KEYWORD","value":"はじめまして|お世話になります|リンです"}],"description":"Giới thiệu tên và nói từ hôm nay được mọi người giúp đỡ.","displayOrder":2},{"code":"REPORT","type":"MISSION","title":"Báo cáo tiến độ công việc","required":true,"conditions":[{"type":"KEYWORD","value":"報告|進捗|完了|七割"}],"description":"Báo cáo tiến độ công việc đã hoàn thành đến đâu.","displayOrder":3},{"code":"OPINION","type":"MISSION","title":"Nêu ý kiến trong cuộc họp","required":true,"conditions":[{"type":"KEYWORD","value":"と思います|意見|不足|必要"}],"description":"Nêu ý kiến về kế hoạch trong cuộc họp.","displayOrder":4},{"code":"LEAVE","type":"MISSION","title":"Xin về sớm","required":true,"conditions":[{"type":"KEYWORD","value":"早退|有給|てもいいですか"}],"description":"Xin phép về sớm hoặc xin nghỉ phép lịch sự.","displayOrder":5},{"code":"BYE","type":"MISSION","title":"Chào khi ra về","required":true,"conditions":[{"type":"KEYWORD","value":"お先に失礼します|失礼します|ありがとうございました"}],"description":"Chào xin phép ra về trước khi kết thúc ngày làm.","displayOrder":6}],"states":[{"code":"START","name":"Mở đầu ngày làm","next":"INTRO2","prompt":"Bạn đến công ty buổi sáng. Đồng nghiệp đứng ở cửa chào bạn.","allowedGoalCodes":["GREET"],"suggestedReplies":["おはようございます。"]},{"code":"INTRO2","name":"Làm quen","next":"REPORT","prompt":"Đồng nghiệp hỏi bạn là người mới và mời giới thiệu bản thân.","allowedGoalCodes":["INTRO"],"suggestedReplies":["はじめまして。今日からお世話になります。リンです。"]},{"code":"REPORT","name":"Báo cáo tiến độ","next":"OPINION","prompt":"Đồng nghiệp hỏi tiến độ công việc bạn được giao.","allowedGoalCodes":["REPORT"],"suggestedReplies":["資料作成は七割まで完了しました。"]},{"code":"OPINION","name":"Phát biểu trong họp","next":"LEAVE","prompt":"Trong cuộc họp, đồng nghiệp mời bạn nêu ý kiến về kế hoạch.","allowedGoalCodes":["OPINION"],"suggestedReplies":["予算が少し不足していると思います。"]},{"code":"LEAVE","name":"Xin về sớm","next":"BYE","prompt":"Buổi chiều bạn có việc gấp. Đồng nghiệp hỏi bạn cần gì.","allowedGoalCodes":["LEAVE"],"suggestedReplies":["今日は三時に早退してもいいですか。"]},{"code":"BYE","name":"Chào ra về","next":"END","prompt":"Kết thúc ngày làm, đồng nghiệp chờ bạn chào trước khi ra về.","allowedGoalCodes":["BYE"],"suggestedReplies":["お先に失礼します。"]}],"endings":{"success":{"code":"SUCCESS","title":"Hoàn thành ngày làm việc","message":"お疲れさまでした。気をつけて帰ってください。","condition":"all_objectives","nextAction":"SHOW_RESULT"}},"version":1,"initialState":"START"}', '{"grammar":[{"example":"予算が少し不足していると思います。","pattern":"〜と思います","explanation":"Nêu ý kiến một cách mềm mỏng."},{"example":"今日は三時に早退してもいいですか。","pattern":"〜てもいいですか","explanation":"Xin phép làm gì một cách lịch sự."},{"example":"資料作成は七割まで完了しました。","pattern":"〜まで完了しました","explanation":"Báo mức độ hoàn thành công việc."}],"vocabulary":[{"jlpt":"N3","term":"挨拶","example":"朝の挨拶をします。","meaning":"chào hỏi","reading":"あいさつ"},{"jlpt":"N2","term":"進捗","example":"進捗を報告します。","meaning":"tiến độ","reading":"しんちょく"},{"jlpt":"N3","term":"早退","example":"三時に早退します。","meaning":"về sớm","reading":"そうたい"},{"jlpt":"N2","term":"会議","example":"会議で意見を言います。","meaning":"cuộc họp","reading":"かいぎ"}],"exampleDialogue":[{"text":"おはようございます。","speaker":"learner","translation":"Chào buổi sáng ạ."},{"text":"おはようございます。今日は早いですね。","speaker":"ai","translation":"Chào buổi sáng. Hôm nay đến sớm nhỉ."},{"text":"資料作成は七割まで完了しました。","speaker":"learner","translation":"Việc làm tài liệu đã hoàn thành bảy mươi phần trăm ạ."},{"text":"締め切りに間に合いますか。","speaker":"ai","translation":"Có kịp hạn không ạ?"},{"text":"お先に失礼します。","speaker":"learner","translation":"Em xin phép về trước ạ."},{"text":"お疲れさまでした。気をつけて帰ってください。","speaker":"ai","translation":"Vất vả rồi. Về cẩn thận nhé."}]}', NULL, 1) AS n ON DUPLICATE KEY UPDATE category_id = n.category_id, ai_role_id = n.ai_role_id, learner_role_id = n.learner_role_id, prompt_template_id = n.prompt_template_id, title = n.title, description = n.description, jlpt_level = n.jlpt_level, difficulty = n.difficulty, estimated_minutes = n.estimated_minutes, background = n.background, location = n.location, time_of_day = n.time_of_day, flow_json = n.flow_json, learning_content_json = n.learning_content_json, thumbnail_url = n.thumbnail_url, is_active = n.is_active;
INSERT IGNORE INTO scenario_evaluation_rule (scenario_id, rule_id)
