-- =============================================================================
-- [JLAS-W0108] Communication path content + AI-call scenarios (generated seed).
-- Generated by tools/comm-path/build_comm_seed.mjs. Do not edit by hand.
--
-- Content: cpath_goal x4, cpath_topic x35, cpath_situation x106,
--          cpath_line x722, cpath_item x1185 (880 WORD + 305 PHRASE).
-- Kaiwa:    scenario_role x57, scenario x110 (only cpath-* codes/slugs).
--
-- seed_version per goal (first 12 chars of SHA-256 of the compiled <GOAL>.json):
--   TRAVEL     5f7a09dc7a13
--   DAILY_LIFE d2c4b91916be
--   BA         80cfde997abf
--   WORK       7a8f7e1bcd88
--
-- Idempotent: ON DUPLICATE KEY UPDATE / INSERT IGNORE only. Safe to re-run.
-- Requires the base kaiwa seed (jlas_seed_all.sql) and sql/seeds/ai_call_scoring_rules.sql to be loaded first
-- (category / scenario_role / prompt_template / evaluation_rule rows are referenced by code, never by id).
-- =============================================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- =============================================================================
-- BEGIN GENERATED cpath
-- =============================================================================
AS n ON DUPLICATE KEY UPDATE name_vi = n.name_vi, sort_order = n.sort_order, fields_json = n.fields_json, test_scenario_slug = n.test_scenario_slug, seed_version = n.seed_version;

AS n ON DUPLICATE KEY UPDATE goal_code = n.goal_code, sort_order = n.sort_order, level = n.level, name_ja = n.name_ja, name_vi = n.name_vi, seed_version = n.seed_version;

AS n ON DUPLICATE KEY UPDATE topic_code = n.topic_code, sort_order = n.sort_order, level = n.level, title_ja = n.title_ja, title_vi = n.title_vi, situation_vi = n.situation_vi, challenge_json = n.challenge_json, scenario_slug = n.scenario_slug, seed_version = n.seed_version;

AS n ON DUPLICATE KEY UPDATE speaker = n.speaker, learner = n.learner, ja = n.ja, furigana = n.furigana, vi = n.vi, audio_path = n.audio_path, seed_version = n.seed_version;

AS n ON DUPLICATE KEY UPDATE kind = n.kind, topic_code = n.topic_code, situation_code = n.situation_code, sort_order = n.sort_order, ja = n.ja, reading = n.reading, vi = n.vi, note_vi = n.note_vi, audio_path = n.audio_path, seed_version = n.seed_version;

-- END GENERATED cpath

-- =============================================================================
-- BEGIN GENERATED cpath-aicall
-- =============================================================================
-- Roles (only cpath-* codes). Same code across goals is inserted once.

-- Scenarios (only cpath-* slugs). category / roles / prompt_template resolved by code.

-- Link cpath scenarios to the 4 scoring rules (grammar/vocab/mission/natural), idempotent.
SELECT s.id, r.id FROM scenario s
JOIN evaluation_rule r ON r.code IN ('grammar_accuracy', 'vocabulary_usage', 'mission_completion', 'naturalness')
WHERE s.slug LIKE 'cpath-%';

-- END GENERATED cpath-aicall

COMMIT;
